values ('02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', 'DA PAM 611-21', 'Military Occupational Classification and Structure — enlisted MOS specifications (chapter 10c)', 'Chapter 10c', 'All Army enlisted MOS', 'Military Personnel Structure & Plans Division (DAPE-PRP), HQDA ODCS G-1', 'https://api.army.mil/e2/c/downloads/2025/12/04/20612de5/chapter-10c-enlisted-mos-specifications.pdf',
