values
  ('d074e125-cd9b-5df5-822b-12fc8e5e6c16', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00D', 'Position Special Reporting Code (SRC) 00D—Special Duty Assignment', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'This code (00D) will be used to identify approved special duty assignment positions in organizational requirements and authorization documents, and to report the duty MOS for Soldiers assigned to these positions. Refer to chapter 14 for specifications, applications and restrictions.', '400c7114e64fb96378dc9d8257d7df5d4cdfa312cc6d852b29b257a28610ebdd', 2, 2, null, 0, null, null, false, null),
  ('e71dab8d-3846-50c9-99cd-e8ac1ca10531', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00F', 'Position Special Reporting Code (SRC) 00F—MOS Immaterial NGB', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'This code (00F) will be used to identify approved MOS immaterial positions in Army National Guard Table of Distribution and Allowance (TDA) organizational authorization documents, and to report the duty MOS for Soldiers assigned to theses positions. Refer to chapter 14 for specifications, applications and restrictions.', '0b7b8bdcaba8aa74c322fb819ab0b840a770d07aae5ca83d01bf77be3fcfb6aa', 3, 3, null, 1, null, null, false, null),
  ('803ca76d-3575-56eb-99d5-f4ce37c71d6f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00G', 'Position Special Reporting Code (SRC) 00G—MOS Immaterial USAR', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'This code (00G) will be used to identify approved MOS immaterial positions in Army Reserve Table of Distribution and Allowance (TDA) organizational authorization documents and to report the duty MOS for Soldiers assigned to these positions. Refer to chapter 14 for specifications, applications and restrictions.', '666045c227bf6a6e8b5b61ff2473a1ff85676a2b7e230f812183a5a88d690ddd', 4, 4, null, 2, null, null, false, null),
  ('8a7878c5-c139-526d-955a-6d5c402291e0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00J', 'Position Special Reporting Code (SRC) 00J— Command Sergeant Major (CSM) Engineer/Signal/Military Police/Milita', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'This code (00J) will be used to identify approved command sergeant major duty positions in organizational authorization documents that are interchangeable between career management fields (CMF) 12 (Engineer), 25 (Signal), 31 (Military Police) and CMF 35 (Military Intelligence) and to report the duty MOS for Soldiers assigned to these positions. Authorization documents will not be identified with SRC 00J prior to approval by HQDA, ODCS G-1 (DAPE- PRP-CSB)(see table 14-2).. Refer to chapter 14 for specifications, applications and restrictions.', '8f1bcdd6e169a530b00b0fe65e96a4f34b380ad95945f8816189ce4a5e47ef3a', 5, 5, null, 3, null, null, false, null),
  ('f20ad462-7227-5360-9078-933ced2db481', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00K', 'Position Special Reporting Code (SRC) 00K— Command Sergeant Major (CSM) Maneuver Support (MS)/Logistics', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'This code (00K) will be used to identify approved command sergeant major duty positions in organizational authorization documents that are interchangeable between maneuver support career management fields (CMF) 12 (Engineer), 31 (Military Police), 74 (Chemical, Biological, Radiological and Nuclear (CBRN)), and logistics CMF 88 (Transportation), 91 (Ordnance) and 92 (Quartermaster), 94 (Electronic Maintenance and Calibrations) and to report the duty MOS for Soldiers assigned to these positions. Authorization documents will not be identified with SRC 00K prior to approval by HQDA, ODCS G-1 (DAPE-PRP-CSB) (see table 14- 2). Refer to chapter 14 for specifications, applications and restrictions.', '7630220b5a59dbbc565a4a5b6e98895c75e3b8aa1e93fbcf00826e5d736a6a56', 6, 6, null, 4, null, null, false, null),
  ('eb4c08e7-f196-532c-8a5f-72eae07376a3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00L', 'Position Special Reporting Code (SRC) 00L— Command Sergeant Major (CSM) Logistics', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'This code (00L) will be used to identify approved command sergeant major and sergeant major duty positions in organizational authorization documents that are interchangeable between logistics career management fields 88 (Transportation), 89 (Ammunition), 91 (Ordnance) and 92 (Quartermaster), 94 (Electronic Maintenance and Calibrations) and to report the duty MOS for Soldiers assigned to these positions. Authorization documents will not be identified with SRC 00L prior to approval by HQDA, ODCS G-1 (DAPE- PRP) Refer to chapter 14 for specifications, applications and restrictions.', '423d7a7687b7a9235bbc357484ef03a161dfb19aef41c7562747d11d85fd3ca9', 7, 7, null, 5, null, null, false, null),
  ('5468f97b-cd3a-5333-824c-50b55466c7ab', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00M', 'Position Special Reporting Code (SRC) 00M—MOS Grade Immaterial', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'This code (00M) will be used to identify approved MOS immaterial positions and grades in Army Future Command (AFC) Table of Distribution and Allowance (TDA) organizational authorization documents, Refer to chapter 14 for specifications, applications and restrictions.', '1ec2e0b525f5ab6284a90e4f08688db82793794a022211ef80fda896dbcc0c7d', 8, 8, null, 6, null, null, false, null),
  ('dc38b243-752f-5330-a359-24f742955733', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00P', 'Position Special Reporting Code (SRC) 00P— Command Sergeant Major (CSM) Force Sustainment', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'This code (00P) will be used to identify approved command sergeant major duty positions in organizational authorization documents that are interchangeable between force sustainment career management fields (CMF) 27 (Paralegal), 36 (Financial Management), 42 (Adjutant General), 56 (Religious Support), 68 (Medical), 79 (Recruitment and Reenlistment), 88 (Transportation), 89 (Ammunition), 91 (Ordnance), 92 (Quartermaster) and 94 (Electronic Maintenance and Calibrations) and to report the duty MOS for Soldiers assigned to these positions. Authorization documents will not be identified with SRC 00P prior to approval by HQDA, ODCS G-1 (DAPE-PRP-CSB) (see table 14-2). Refer to chapter 14 for specifications, applications and restrictions.', '6d79c5e707398db11083e54630dc6c02a5e797d9258cffe1b0fa5aae6db09ec9', 9, 9, null, 7, null, null, false, null),
  ('2ddd70d9-4787-57f4-8a8c-bf9d21a887f5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00R', 'Position Special Reporting Code (SRC) 00R— Command Sergeant Major (CSM) Infantry/Armor Immaterial', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'This code (00R) will be used to identify approved command sergeant major duty positions in organizational authorization documents that are interchangeable between Infantry and Armor skills of career management field (CMF) 11 (Infantry) and 19 (Armor), and to report the duty MOS for Soldiers assigned to these positions. Authorization documents will not be identified with SRC 00R prior to approval by HQDA, ODCS G-1 (DAPE-PRP-CSB) (see table 14- 2). Refer to chapter 14 for specifications, applications and restrictions.', 'ceced7546d68b743e36a9894e434257925cf0f5978dabbf2118b3a0020192808', 10, 10, null, 8, null, null, false, null),
  ('7333104b-dc8c-5794-a2f5-2fa38c6a3ab9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00T', 'Position Special Reporting Code (SRC) 00T— Command Sergeant Major (CSM) Infantry/Armor/Field Artillery/Combat ', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'This code (00T) will be used to identify approved command sergeant major duty positions in organizational authorization documents that are interchangeable between Infantry, Armor, Field Artillery and Combat Engineer skills of career management field (CMF) 11 (Infantry), 12 (Engineer (Combat Engineer Senior Sergeant only), 13 (Field Artillery) and 19 (Armor), and to report the duty MOS for Soldiers assigned to these positions. Authorization documents will not be identified with SRC 00T prior to approval by HQDA, ODCS G-1 (DAPE- PRP-CSB) (see table 14-2). Refer to chapter 14 for specifications, applications and restrictions.', '4891f5c6f2a15bdc87bfd48d077941ed61d34f68e2933a791e13e44cbd9fc32f', 11, 11, null, 9, null, null, false, null),
  ('040f70f6-8c90-51c8-8ee2-490647d1a05a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00X', 'Position Special Reporting Code (SRC) 00X— Command Sergeant Major (CSM)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'MOS Immaterial, CMF 00
a. Major duties. This code (00X) will be used to identify approved command sergeant major duty positions in organizational authorization documents that are not directly associated with the skills of a specific career management field (CMF) or MOS, and to report the duty MOS for Soldiers assigned to these positions. Authorization documents will not be identified with SRC 00X prior to approval by HQDA, ODCS G-1 (DAPE-PRP-CSB). (see table 14-2). Refer to chapter 14 for specifications, applications and restrictions.', '79a81bc8f9521ebc7844e4517031f1fdd270cf6620708136db42b4d8875bbb16', 12, 12, null, 10, null, null, false, null),
  ('911e3170-d6b0-5d75-bb2b-ca45c5cc6e52', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '00Z', 'Nominative Command Sergeant Major/Sergeant Major (CSM/SGM)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'MOS 00Z identifies positions and personnel in grade E9 (CSM & SGM) where the incumbents are Sergeants Major of organizations commanded by General Officers. Additionally, Sergeants Major that serve as the principal Staff Sergeant Major at the HQDA may also be considered Nominative. Certain other Sergeants Major positions may be considered as Nominative at the direction of the Sergeant Major of the Army. A Nominative Command Sergeant Major or Sergeant Major is a senior leader who serves as the Senior Enlisted Leader for their command or agency. Nominative positions generally have direct oversight on a large number of Soldiers and civilians, typically at the strategic level. The Sergeant Major is expected to be above reproach, the standard bearer in all things, including fitness and appearance. They embrace the Army Professional Ethic. They are the senior enlisted trainer and spokesperson that enforces established policies and standards for enlisted soldiers pertaining to performance, care, conduct, appearance, effective personnel utilization and management and training; and ensures that subordinate leaders do the same. Duties for MOS 00Z are:
a. Major duties.
(1) Serves as the senior enlisted person for the command.
(2) Serves as the standard bearer in all things in the command including fitness and appearance.
(3) Provides guidance and expertise to the command on the Army’s Professional Ethic.
(4) Serves as the expert on Army and organizational history, traditions, customs and courtesies.
(5) Leads all enlisted talent management within the command.
(6) Serves as the principal enlisted advisor to the Commanding General.
(7) Provides advice and makes recommendations to senior leaders and staff on all matters pertaining to enlisted soldiers and their families.
(8) Manages enlisted professional development across the command.).
(9) Serves as the lead agent in the development of subordinate personnel.
(10) Disseminates information, command/organization policies, objectives and guidance to subordinate NCO Support Chain to ensure successful completion of missions.
(11) Develops and recommends courses of action for policy development and critical senior leader decisions.
(12) Provides guidance to create efficiencies and streamline processes.
(13) Develops methods to improve readiness.
(14) Performs other duties prescribed by their senior leader.', '93a577db2c47682d840130b11f2b5dbd65b978fa406a300b084f300fd0155b1b', 13, 13, null, 11, null, null, false, null),
  ('88a1df2e-7418-54ab-9b9a-266b5f9f1b53', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '08H', 'Army Equestrian', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Army equestrian supervises or performs ceremonial and related support functions with military working equids (MWEs) in support of specialized ceremonial detachments and other similar organizations, activities and units; and advises the commander, the staff, and unit Soldiers on equestrian matters. Ceremonial equestrian activities support state funerals, military funerals, color guard functions, historical reenactments, outreach and other activities in support of the Army mission. The Army equestrian performs all functions in support of the husbandry, training, transportation, recruitment and disposition of MWEs.', '7fc4bb80fadb27468a9f55628c6814556f055194e7fc28a2b39063d182c31242', 14, 14, null, 12, '2026-03-01', null, false, null),
  ('52370fed-7d00-54ce-875f-8ebd38248287', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '08H', 'Army Equestrian', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform care of MWEs to include feeding, watering, grooming, leading, tacking and untacking, bathing, clipping, health checks, and basic first aid. Perform facilities maintenance to include stall cleaning and bedding, aisle cleaning, manure removal, resupply of hay, bedding, and feeds, minor repairs, mowing, and weed removal. Perform maintenance and cleaning of all MWE tack, equipment, and conveyances. Ride MWEs individually and in postilion in ceremonial military style. Lead MWEs in ceremonial military style. Maintain fitness of MWEs as directed.', '6ec23afe229fcd3804c4f16af645cdd03f81107f21f04a5d2bd93df5de4a81f2', 14, 14, null, 13, '2026-03-01', null, false, 2),
  ('a772a6c3-83cd-5ced-ad95-6eddc24edfd9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '08H', 'Army Equestrian', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at preceding skill level and provides technical guidance to subordinate Soldiers in accomplishment of these duties. Acts as squad leader with all typical and ceremonial responsibilities associated with this position. Drives MWEs in harness. Performs training of MWEs as directed and under supervision. Transports horses via trailer.', '44aecb2379850f7a8d96a6ba966b1db9009e4e589c0868f032c70a49f4aa7352', 14, 14, null, 14, '2026-03-01', null, true, 3),
  ('7d333101-3fbf-5697-9461-68ab3c1440f2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '08H', 'Army Equestrian', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties of and supervises the functions of the preceding skill levels. Trains MWEs and equestrians directly and through supervision of subordinates. Ensures fitness of MWEs. Performs staff functions to execute ceremonial missions, support MWEs and Soldiers, and maintain the organization and its property. Perform platoon sergeant functions with all typical and ceremonial responsibilities associated with this position.', '4f4a606325432a45d0a392c5042fe607f897cb8cc04a8554d898fa80b21e950f', 14, 14, null, 15, '2026-03-01', null, true, 4),
  ('f62ef716-0e62-5ff1-99cc-6d4b579d9b75', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '08H', 'Army Equestrian', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform first sergeant functions with all typical and ceremonial responsibilities associated with this position. Custodian of ceremonial standards and traditions. Advise the commander, staff, and subordinates on MWE training, fitness, husbandry, and welfare.', '89bb344449ee1a8026e0509046ce7606642aea9ac8fbb43764672639e492b610', 14, 14, null, 16, '2026-03-01', null, false, 5),
  ('a17fc458-4f96-5a8e-ac4a-6859c61f093d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '08H', 'Army Equestrian', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise duties at the preceding skill levels. Serves as the senior enlisted equestrian in the Army and senior advisor to the Chief of Army Horses. Ensures MWE welfare and ceremonial standards are maintained throughout the Army equine enterprise. The SGM ensures the health of organizations, and development and growth of the future enlisted leaders of Army equestrians. Provides direct mentorship to Soldiers, provides training oversight to units, and maintains external relationships, provides readiness oversight.', '0da6e548ae569ffe60698c9221891e67b117c75a09d1135310f7826420525964', 14, 14, null, 17, '2026-03-01', null, true, 6),
  ('b677dfaf-06fc-53ca-9276-0685a7c6ec80', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '09U', 'Personnel Special Reporting Code (SRC) 09U— Unqualified in Authorized Army', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'MOS (09U) CMF 09
a. Major duties. This code (09U) will be used in place of a Primary MOS (PMOS) to report enlisted Soldiers who lose their MOS qualifications and cannot be or are not qualified to be classified in any MOS contained in DA Pam 611-21. Refer to chapter 14 for specifications, applications and restrictions.', 'd90d545c6df1939dd109574848f55e2cd7cbd0b8847cad9458c1de74962d5f74', 16, 16, null, 18, null, null, false, null),
  ('f935225c-453d-501f-9ba3-4040d494cddd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11B', 'Infantryman', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The infantryman supervises, leads, or serves as a member of an infantry activity that employs individual small arms weapons or heavy anti-armor crew served weapons, either vehicle or dismounted in support of offensive and defensive combat operations.', '57f5269cd1d1aa4fc8658a72148fde55a49b4fdc9dbc132d32c92652c2903906', 17, 17, null, 19, null, null, false, null),
  ('7fa0faf5-249f-5268-9882-e286742bba6a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11B', 'Infantryman', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates both mounted and dismounted to close with and destroy the enemy. Employs, operates, and maintains assigned weapons and equipment. Assist in the performance of reconnaissance operations. Employs, fires, and recovers anti-personnel and anti-tank mines. Locates and neutralizes mines. Perform self-extraction from a mine field. Orients a map. Operates, mounts/dismounts, zeros, and engages targets using night vision sights. Operates and maintains communications equipment, enter, and operates in a radio net. Operate in a NBC contaminated area. Constructs and camouflages individual/crew served weapons/vehicle firing/fighting positions. Assist in the construction of fortification and barriers, including minefields and obstacles. Assist in the breaching of minefields and obstacles. Constructs field expedient firing aids for infantry weapons. Recognizes friendly and threat armored vehicles. Perform\ as a member of a fire team during a movement to contact, reconnaissance, and security, an attack, defense, situational training exercises and all infantry dismounted battle drills. Process prisoners of war and captured documents. Operate IFV over diverse terrain in varies visibility. Assist in target detection, identification, and round sensing.', '02282daff835ceebd6d71d1771c32739b8eff259298eefefe7bf005071fc8960', 17, 17, null, 20, null, null, false, 1),
  ('4a97a2b8-e4d9-5126-9c42-6b0247e4a47e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11B', 'Infantryman', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding level of skill. Perform duties as IFV gunner or team leader of the infantry rifle squad. The Infantryman will prepare sector sketches of vehicle or infantry rifle team positions and sectors. As gunner, detects, acquires, identifies, and engages targets. Maintain the turret weapons systems of the IFV. Lead an infantry team/heavy anti-armor squad in combat operations, providing tactical and technical guidance to subordinates and professional support to both superiors and subordinates in the accomplishment of their duties. Leads, supervises, and trains subordinate personnel. Calls for and adjusts indirect fire. Evaluates terrain and selects weapon emplacement. Control organic fires. Installs and recovers anti-handling devices on anti-tank mines and electrical and non-electrical demolition charges. Supervise construction of hasty fortifications and receipt, storage, and issue of ammunition. Record operational information on maps. Indicate location, strength, tactical deployment, and emplacement of enemy and friendly units. Receives and implements combat orders, directs deployment of personnel in offensive, defensive, and retrograde operations. Requests, observes, and adjusts direct supporting fire. Conducts battle damage assessment and repair. Evaluates terrain and supervises the emplacement of sighting and firing all assigned weapons. Uses maps and map overlays, performs intersection and resection, and determines elevation and grid azimuths. Know threat formations and tactics through battalion size elements. Prepares, operates, and maintains secure communications equipment. Leads a fire team during a movement to contact, reconnaissance and security, an attack, defense, situational training exercises, and all infantry dismounted battle drills.', '88dd2b2d5efee1dcc6ecbd0e19fac30a0461bf43506378f4b5afd6d0c200997f', 17, 17, null, 21, null, null, true, 2),
  ('ff0dcc78-5d76-53b4-8c95-6399b09e8c0a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11B', 'Infantryman', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding level of skill. Lead an infantry squad, heavy anti-armor weapons section, and/or a reconnaissance (scout) team or IFV section during combat operations. Supervise tactical deployment of assigned element/weapon system in offensive, defensive, and retrograde operations. Provide tactical and technical guidance to subordinates and professional support to both subordinates and superiors in the accomplishment of their duties. Receives and issues orders. Coordinates action of the element with adjacent and support elements and organic and supporting firepower. Ensure collection and proper reporting of intelligence data to unit. Adjust aerial fire support. Analyze terrain. Conduct tactical operations for a squad, heavy anti-armor section, operations of a patrol base, and NBC operations. Maintain operational security. Prepares, operates, and maintains secure communications equipment. Prepare an anti-armor section sketch. Leads a squad, heavy anti-armor section, during movement to contact, reconnaissance and security, an attack, defense situational training exercises, and all infantry mounted and dismounted battle drills.', '3e1b4b18c8890331e81d85627394190e98fe718f9da9683c6082fa6738342185', 17, 17, null, 22, null, null, true, 3),
  ('2b346ffb-c9f0-5fbe-8940-ec91c717d350', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11B', 'Infantryman', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding level of skill. Performs duties as an infantry, reconnaissance (scout), heavy anti-armor weapon platoon Sergeant, or Operations Sergeant in combat operations. Receives, issues and implements orders. Assists platoon leader in controlling platoon in mounted and dismounted operations. Assist in dissemination of intelligence information to unit and staff sections. Assist in planning, organizing, directing, supervising, training, coordinating, and reporting activities of subordinate elements. Provide tactical and technical guidance to subordinates and professional support to both subordinates and superiors in the accomplishment of their duties. Supervise the occupation of an assembly area. Employ NBC defensive teams. Plans for, supervises preparation of, and conducts NBC operations. Perform battle damage assessment. Supervises platoon maintenance activities. Supervise receipt, storage, and distribution of ammunition, supplies, equipment, and rations to subordinate elements. Develop a platoon training plan. Assist in production and administration of staff journals, files, records, and reports. Assist in coordination and implementation of combat operations, training programs, and administrative and communications procedures. Assist in organization and operation of the tactical operations center. Know threat organization and tactics through regiment level. Plans for, coordinates resources for, and sets up a multipurpose range complex for qualification exercises.', 'a07717d3d3ddc3f894ddfabbaf0af33d77bcd7975cb9535ed639f7dc75b478f5', 17, 18, null, 23, null, null, true, 4),
  ('4dca3963-5ab9-5a23-a2dc-89f84c9491c0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11C', 'Indirect Fire Infantryman (Indrct Fire Infmn)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The indirect fire infantryman serves as a supervisor or as a member of a mortar squad, section, or platoon. Employs crew and individual weapons in offensive, defensive and retrograde ground combat tactical operations.', '35cf17333770901f91d962d2c45ecacd74c1bf565a402491896117cb98972203', 20, 20, null, 24, null, null, false, null),
  ('419c64f7-6ca8-5290-a613-62d9a8458714', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11C', 'Indirect Fire Infantryman (Indrct Fire Infmn)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Employs, fires and recovers anti-personnel and anti-tank mines. Perform self extraction from a mine field. Locates and neutralizes mines. Navigate from one point on the ground to another. Orients a map. Operates and maintains communications equipment and operates in a radio net. Operate in a NBC contaminated area. Emplace and recover early warning devises. Constructs and camouflages individual/crew served weapons firing position. Constructs and camouflages a mortar firing position. Maintain mortars and fire control equipment. Perform safety checks on mortars. Perform as a member of a mortar squad providing indirect fire support.', '85df35ee6760762450c0432f40a3e720319c18697d2286901c938fc9e494fdca', 20, 20, null, 25, null, null, false, 1),
  ('88c2e0a4-52b7-583b-96d4-ccdc64c1941c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11C', 'Indirect Fire Infantryman (Indrct Fire Infmn)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding level skill. Leads and controls mortar squads. Supervises and trains subordinate personnel. Provide tactical and technical guidance to subordinates and professional support to subordinates and superiors in the accomplishment of their duties. Supervise the construction of mortar positions. Record operational information on maps. Receives and implements combat orders; directs deployment of personnel in offensive, defensive, and retrograde operations. Requests, observes, and adjusts indirect supporting fire. Supervise subordinate personnel in all phases of individual and mortar equipment maintenance. Uses map and map overlays, performs intersection and resection, and determines elevations and grid azimuth. Prepare fire plans, target lists and overlays. Prepares and computes firing data using below pivot point and grid method. Reciprocally lay mortars. Prepare mortar ballistic computer for operation.', 'cb4eb8362556aa89cc9a34e03d8772ba3ed8d3dbdb18b2edfa68d9a23c8dc62f', 20, 20, null, 26, null, null, true, 2),
  ('1bfb3c0c-791d-5d31-86c1-bb0566e3e8c7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11C', 'Indirect Fire Infantryman (Indrct Fire Infmn)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding level of skill. Lead a mortar section. Provide tactical and technical guidance to subordinates and professional support to both subordinates and superiors in the accomplishment of their duties. Receives and issues orders. Coordinate indirect fire support for the mortar. Ensure collection and proper reporting of intelligence data to unit. Supervise a firing section and various work details. Analyze terrain. Conduct tactical operations for a squad and NBC operations. Maintain operational security. Prepares, operates, and maintains secure communications equipment. Reciprocally lay mortars. Consolidates and re organizes a mortar squad. Supervise fire direction center personnel.', 'f6566fb68b4e1a4ba63988b629ba2efc98e98bebf591d456e846ff5fa7c80d53', 20, 20, null, 27, null, null, true, 3),
  ('811c6dc1-4450-5a04-b074-d4deb9ac9255', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11C', 'Indirect Fire Infantryman (Indrct Fire Infmn)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding level of skill. Leads mortar or infantry weapons platoon. Assist in planning (to include fire planning), organizing, directing, supervising, training, coordinating and reporting activities of subordinate mortar sections and squads. Provide tactical and technical guidance to subordinates and professional support to subordinates and superiors in the accomplishment of their duties. Supervise occupation of an assembly area. Employ NBC defensive team. Plans for, supervises preparation of, and conducts NBC operations. Perform battle damage assessment. Develop a platoon training plan. Conduct graphic resection and hasty surveys.', 'd7ba0f8fc995d426d3f90103aa8334d13a676507fa296a2921455ea57e1849f3', 20, 20, null, 28, null, null, true, 4),
  ('0a380670-c227-5ec7-af47-e6e72d51f066', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11Z', 'Infantry Senior Sergeant (Inf Sr SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Infantry Senior Sergeant supervises, leads, or serves as a member of an infantry activity that employs individual small arms weapons or heavy anti-armor crew served weapons, either vehicle or dismounted in support of offensive and defensive combat operations.', '6418723006a41075f9ae5a08fdb3289d2d5480616a65ea9452134e1688ec68ba', 22, 22, null, 29, null, null, false, null),
  ('a370eff5-5939-5a9f-95aa-7a996e106df1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11Z', 'Infantry Senior Sergeant (Inf Sr SGT)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Infantry Senior Sergeant serves as the principal NCO in an infantry dismounted reconnaissance, mechanized, or weapons company, operations or intelligence sections of an infantry or combined arms battalion or infantry brigades and higher level organizations. Provides tactical and technical guidance and professional support to subordinates and makes recommendations to superiors in the accomplishment of their duties. The key developmental position for MOS 11Z5O is a First Sergeant.', '6cff62bedda205de07160458247213ac169eefd0eeb526691d7f2ecef0b4eeec', 22, 22, null, 30, null, null, false, 5),
  ('b48b1129-ab56-504c-b468-ddad14611866', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '11Z', 'Infantry Senior Sergeant (Inf Sr SGT)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', '(a) SGM: Serve as principal noncommissioned officer in an infantry battalion or higher to supervise the processing of operations and intelligence information in an Infantry brigade or higher level unit. Provide tactical and technical guidance to subordinates and professional support to both subordinates and superiors in accomplishment of their duties. Plans, coordinates and supervises activities pertaining to organization, training and combat operations. Edits and prepares tactical plans and training material. Coordinate implementation of operations, training programs and communications activities.
(b) CSM: Serves as the principle advisor to the Commander (Battalion and higher level unit) on all enlisted issues and is primarily focused on the training, maintaining, caring, and leading of the unit''s Soldiers, facilities and equipment. Assists the Commander in the implementation of command policies and establishes and enforces standards related to the appearance and conduct of all Soldiers within the command. Develops and executes NCO Professional Development Programs within the command and advises/counsels Soldiers on issues related to training, education, and professional development. Responsible for the unit’s individual skills training program for all CMF’s. (Battalion and higher level unit).', 'bb55ac0f1f13775cea304007c32252754fc2bf57c33e3a4fd611d18fdef2125c', 22, 22, null, 31, null, null, false, 6),
  ('d6d891e7-09c9-5882-aeba-2e51f4c5c1ec', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12A', '12A Engineer Senior Sergeant', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The engineer senior sergeant inspects and advises on bridging, rafting, and river crossing operations. Supervises general engineering activities related to all construction and utility operations. Formulates and maintains construction schedules. Assist in supervision of troops in assault operations. Perform ground and aerial reconnaissance. Advises engineer staff section personnel in matters involving combat engineer operations. Assist engineering officer in construction planning, scheduling, and material estimating. Assist in the preparation of operation orders, standing operating procedures, and contingency plans. Coordinates with staff agencies for engineer operational and tactical support. Coordinates employment of engineer elements operating with infantry and armored units. Inspects construction sites and enforces job specification and safety standards. Collects, interprets, analyzes, evaluates, and disseminates intelligence data. Provides staff supervision and principal noncommissioned officer direction to units engaged in performing engineering missions. Inspects construction and training activities. Supervises performance of combat engineering missions.', '57f161613cd40c3060932db1f57bf445852b8f57d013664b298550c9ebae580c', 24, 24, null, 32, null, null, false, null),
  ('9a696d7a-4099-58b9-b7bb-d95327e4a257', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12B', 'Combat Engineer', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Combat engineers supervise, or serve, as a member of a team, squad, section, or platoon. They are engaged in providing mobility, counter-mobility and survivability support to combat forces.', 'be7af11aeeb3a7e07243009c6087a743a56ce03345318a81063d37636e796141', 25, 25, null, 33, null, null, false, null),
  ('3ff9d5f2-5dd2-5218-9ac0-157df11d4868', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12B', 'Combat Engineer', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform basic demolition, mine warfare and combat construction operations. Operates various light and heavy engineer wheeled and tracked vehicles. Prepares, installs and primes firing systems for demolition and explosives. Arms, disarms and installs U.S. anti-personnel and anti-tank mines. Locate mines and booby traps by visual, manual, mechanical, electronic, other means or through the use of a mine detection dog. Recognize booby traps, friendly and threat mines and firing devices. Installs wire obstacle material.', '11a565de3b4da6212fd2cb1289d9c817b1871b99eda231bb77aee5377e3d3bde', 25, 25, null, 34, null, null, false, 1),
  ('4c4e6a00-e88f-5792-854a-3913b4656989', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12B', 'Combat Engineer', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises lower grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Directs and assists in the operation of engineer wheeled or tracked vehicles. Direct the construction of fighting positions and wire entanglements. Controls fire team movements. Directs the placement of explosives and clears misfires. Direct a mine-clearing line charge loading team. Direct the installation and removal of U.S. anti-handling devices on anti-tank mines. Direct minefield marking party and dispensing operation of mine scattering systems. Conducts reconnaissance operations, determines limiting slopes, curves, stream velocity, and gap widths.', 'f2a6635e0ab0134825214271c3123b2061aea6793fe10cf2efa0755dfcbc19bc', 25, 25, null, 35, null, null, true, 2),
  ('dcac7090-f6cd-5f3a-abf8-f458848a36e4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12B', 'Combat Engineer', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises lower grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Supervise squad and section personnel. Direct utilization and maintenance of vehicles and equipment. Supervise the employment of unit and job site security. Prepares and issues an oral squad operation order. Conduct the maneuver of a squad in a patrol. Directs minefield installation, removal, and submits minefield reports. Supervise breaching operations. Collects data and calculates the requirement for explosives and related material. Direct construction of combat bunkers, shelters and non-explosive anti-vehicular obstacles. Conducts ground reconnaissance for roads, routes, bridges, tunnels, fords, rivers and ferries. Prepare a demolition and reconnaissance report. Directs assembly of military fixed bridges.', '61a5259e101ccaa357aa9769111e7018a302069cde4adcfc1d9e7065e3d50b68', 25, 25, null, 36, null, null, true, 3),
  ('33aa2486-b022-513a-9587-9b6989a7e714', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12B', 'Combat Engineer', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises lower grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Assign tasks to subordinate elements and personnel. Account for Soldiers, material, and equipment. Supervise in mine warfare, demolition’s and combat construction operations. Calculate logistical requirements for minefields, bunkers, shelters, obstacles and wire entanglements. Enforce safety standards, field sanitation, communication procedures, security, and job specifications. Provides support for construction and tactical movements. Supervises platoon reconnaissance missions and determines the Rapid Field classification of fixed bridges. Direct employment of Assault Breacher Vehicle (ABV), Joint Assault Bridge (JAB), Armored Vehicle Launched Bridge (AVLB) and the Armored Combat Earthmover (ACE) in support of maneuver forces.', '92789efe91a9bef0f2961c51279b38cfe3fd260b7091c4a52bfae69ebf064713', 25, 25, null, 37, null, null, true, 4),
  ('b32434b1-b1ec-592d-932b-9eef09f5d163', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12C', 'Bridge Crewmember', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Bridge crewmembers supervise or serve as a member of a squad, section or platoon. They provide conventional and powered bridge and rafting support for wet and dry gap crossing operations.', '8a03c19afa192a4afe0f88c648fac999b653f7dcb2c92a2abc6ee3ab1e8fda7c', 27, 27, null, 38, null, null, false, null),
  ('62ce6d1d-3c94-5b2d-8dd4-786a1ea01d05', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12C', 'Bridge Crewmember', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operate bridge truck and light vehicles. Operate, launches, retrieves and performs duties as a deck hand on the bridge erection boat. Assists in the preparations of a bridge site, handles shore lines, assists in rafting and bridging operations. Assist in the installation of the overhead anchorage system. Installs kedge anchorage systems. Launches and retrieves ribbon bridge bays. Launches and retrieves the Rapidly Emplaced Bridge. Assists in the assembly and maintenance of military fixed and float bridges. Prepares ribbon bridge equipment for air transport. Operate the crane on the Dry Support Bridge (DSB). Operates, maintains and employs a variety of U.S. weapons including pistols, shotguns, rifles, carbines, machine guns, launchers and grenades- including the use of electronic or remote weapons platforms. Operates and maintains communications equipment, enters and operates in radio net. Assist in the performance of reconnaissance operations. Detect and recognize U.S. and Foreign mines and bobby traps through visual, mechanical, manual, and electronic/robotic means. Constructs, installs and primes firing systems for use in demolition and explosives. Employs U.S. scatterable mines. Installs wire mine obstacle material.', 'f54a8be4d099abbc87c2f7ea8e02f544b5871680f2b430255f08624868820bb1', 27, 27, null, 39, null, null, false, 1),
  ('f3567d70-a613-5cff-9b47-0148fa5a205e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12C', 'Bridge Crewmember', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill level. Supervises lower grade soldiers and provides technical guidance in the accomplishment of their mission. Performs as Team Leader and directs deployment of personnel in offensive, defensive, and stability operations. Provide professional development to subordinate Soldiers through oral and written counseling. Direct construction of fighting positions and wire entanglements. Determine limiting slopes, curves, stream velocities, and gap width. Conducts engineer reconnaissance. Directs crew in the assembly and maintenance of military fixed and float bridges. Operate an Engineer Regulating Point (ERP). Direct crew in the installation of fixed bridge anchorage, shore guys, kedge anchorage system and the overhead anchorage systems. Selects crossing site and directs emplacement of the Rapidly Emplaced Bridge. Operates and or supervises the use of bridge erection boats. Conducts and supervises maintenance, battle damage assessment and repair. Receives and implements combat orders providing brief backs and debriefings. Records operational information on maps indicating location, strength, and tactical employment of friendly and enemy units. Performs and teaches the operation, maintenance, and employment of a variety of U.S. weapons including pistols, shotguns, rifles, carbines, machine guns, launchers and grenades- including the use of electronic or remote weapon platforms. Directs the placement of explosives, determines safe distances, constructs field expedient demolitions, and clears demolition misfires.', '4a3c6c698749db66a1c1fa6c48dce79efd7794f60c434968ed55c3f09329fbb9', 27, 27, null, 40, null, null, true, 2),
  ('91c05446-a7dc-5da9-8fa7-04171dcb2de1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12C', 'Bridge Crewmember', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and maintains proficiency in all major duties of previous skill levels. Supervises subordinate Soldiers and provides technical and tactical guidance in the accomplishment of their duties. Receives and issues orders providing brief back and debriefing. Plans, prepares, and conducts oral operations orders. Coordinates action of the element with adjacent and support elements and organic/ supporting firepower. Collects data and calculates the demolition requirement for explosives and related materials. Conducts road, tunnel, ford, river, ferry and bridge reconnaissance. Direct the utilization and maintenance of vehicles and equipment. Direct the employment of unit and job site security. Directs the off-loading and assembly of float and fixed bridges. Performs float and fixed bridge site layout. Supervise installation of an overhead cable anchorage system, kedge anchorage system, shore guys and fixed bridge anchorage. Supervises maintenance of fixed and float bridges. Direct rafting operations. Directs fixed and float bridge construction. Supervise preparation of ribbon bridge equipment for air transport. Determine requirements for Engineer Equipment Park (EEP) and Engineer Regulating Point (ERP). Direct construction of bunkers, shelters and fortifications. Ensure collection and proper reporting of intelligence data to unit. Collects and disseminates engineer intelligence data. Collects data and calculates the requirement for explosives and related material. Prepare a demolition and reconnaissance report. Conducts ground reconnaissance for roads, routes, bridges, tunnels, fords, rivers and ferries. Direct the construction of wire entanglements, and construction of field and urban fighting positions. Determine logistical requirements for wire entanglements. Operate the chest pack for the Dry Support Bridge (DSB).', 'bd95c18c97178fa55a7e71577c6800d2405afdc9f8743f55246e2a26dee94f29', 27, 28, null, 41, null, null, true, 3),
  ('62d5025c-c435-53df-ac0b-f427337e77eb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12C', 'Bridge Crewmember', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and maintains proficiency in all major duties of previous skill levels. Supervises subordinate Soldiers and provides technical and tactical guidance in the accomplishment of their duties. Provide professional development to subordinate Soldiers through oral and written counseling. Assist in the planning, organizing, directing, supervising, training, coordinating and reporting of subordinate squads. Develops platoon training plan and enforce safety standards. Assist in the coordination and implementation of combat operations, training programs, and administrative and communication procedures. Assist in organization and operation of tactical operations center. Supervises platoon maintenance activities. Supervise receipt, storage, and distribution of ammunition, demolition, supplies, equipment, and rations to subordinate elements. Determines logistical requirements for military fixed and float bridges. Determines anchorage requirements for fixed and float bridges. Calculate area requirements for airlift operations. Inspects fixed and float bridges. Determine requirements for float bridge protective devices. Supervise mine clearing and demolition missions. Determines logistical requirements for bunkers and supervises the construction of a defensive perimeter. Conducts platoon reconnaissance missions and calculates the Rapid Field Classification of fixed bridges. Coordinate a passage of lines.', '67a5798204b65d5d2d01a1784f0a590fd041bb076f615cb439580c60988f483c', 28, 28, null, 42, null, null, true, 4),
  ('27e5b65e-3956-53a1-b4db-a871924dfdce', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12D', 'Diver', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The diver performs or supervises SCUBA or Surface-Supplied diving operations for underwater reconnaissance, demolition, port construction and rehabilitation, harbor clearance, ship’s husbandry, river crossing, hydrographic survey, and salvage operations to a depth of 190FSW. Conducts Soldiers common tasks outlined in STP 21-1 SMCT and STP 21-24 SMCT.', '8d45e0a29ab15b21ac72cb997d9b4a1f3bf249eee18892d9a899f8c1ae0e80d5', 29, 29, null, 43, null, null, false, null),
  ('9c4f1ddb-a14a-5232-a85c-fea8b9cebfe0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12D', 'Diver', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform underwater work as directed from the Diving Supervisor or Lead Diver. Perform operator through intermediate levels of maintenance on diving life support equipment. Operates power support equipment, emplaces demolitions, and performs as secondary air systems operator during diving and recompression chamber operations.', 'a66a1d4ef481ec025f8e29e7b3980d854ef58dec6d91e381e278d28be8ad9907', 29, 29, null, 44, null, null, false, 1),
  ('add99e64-fb51-5968-867e-bdc23651f57e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12D', 'Diver', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform as the Lead Diver during underwater work as directed from the Diving Supervisor. Perform operator through intermediate levels of maintenance on diving life support equipment. Assist the Diving Supervisor for preparing all equipment for SCUBA and Surface-Supplied diving operations. Construct and fabricate all patches for vessel salvage. Prepare rigging and lifting devices for salvage of submerged objects. Prepare explosives for placement. Perform as primary operator on air systems and underwater support equipment during diving and recompression chamber operations.', '30cbfcea4429143cedb4dc6249ce289308d170aabf233f1ad45010ba072426d8', 29, 29, null, 45, null, null, false, 2),
  ('a6839253-dc0b-530f-ba74-a2b92eb5ca70', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12D', 'Diver', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise all non-decompression SCUBA and Surface-Supplied diving operations. Supervise operator through intermediate levels of maintenance on diving life support equipment. Direct preparation and operation of diving equipment for all underwater work. Supervise calculation, training, and use of explosives. Supervise use of underwater hydraulic and electric power equipment and other special underwater tools. Supervises recompression chamber and life support equipment during diving and emergency operations.', '3b7ba77760c0029a0df2b5e95bf233e35d0a246dbb68ff0ef2ca58802b19b5d5', 29, 29, null, 46, null, null, false, 3),
  ('103ff0ab-df78-5beb-9c38-eca29bbdf85f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12D', 'Diver', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise decompression and high-risk dives for SCUBA and Surface- Supplied and Chamber diving operations. Assist the Platoon Leader during planning, scheduling, and execution of diving missions. Supervise operator through intermediate levels of maintenance on diving life support equipment. Perform as a qualified Master Diver for diving teams. Supervise recompression therapy for diving injuries and coordinates medical support. Prepare detailed plans and reports for complex diving operations. Supervise use, training, and safety during demolitions missions.', 'bf2b9e573ff377769c8fbe769e5f6e72bde028d2a1ceb13ea6446b81393ca2d4', 29, 29, null, 47, null, null, false, 4),
  ('e031d1e0-8f2b-5f3d-8222-3921f9728719', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12D', 'Diver', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise decompression and high-risk dives for SCUBA and Surface- Supplied and Chamber diving operations. Assist the commander in planning, scheduling, and executing training for all operational dive missions. Supervise operator through intermediate levels of maintenance on diving life support equipment. Perform as a qualified Master Diver for diving teams. Accountable for the unit dive safety and inspection program. Formulates demolition plan for operational and training missions. Provide expertise to staff planners and diving teams. Writes and develops doctrinal, regulatory, training, and safety material related to the accomplishment of diving missions.', '906d0bf0ad415016b479340204d54b7023f77fd3db571ee47d180c213f60295a', 29, 29, null, 48, null, null, false, 5),
  ('8c84c7ba-6f85-5808-be20-e99fa4e619ce', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12G', 'Quarrying Specialist (National Guard Only)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The quarrying specialist supervises or operates electric, pneumatic, and internal combustion powered machines used in drilling, crushing, grading, and washing gravel aggregate for construction projects.. Detonates explosives to blast rock in quarries and construction sites.', '81bdad184be011eca11c193b84d3006a8906c575599a12ab6d44cd0ce4881bda', 31, 31, null, 49, null, null, false, null),
  ('34f9a96d-582c-55a0-bd08-740e79c3a27f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12G', 'Quarrying Specialist (National Guard Only)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs Preventive Maintenance Checks and Services (PMCS), assembles, adjust, and operates the Crushing, Screening, Washing Plant (CSWP). Performs PMCS and operates rock drills. Loads boreholes with explosives and assembles nonelectrical firing circuits.', '7d86193018d008962709783b1cd605a35cb4da48252af65e3fc9db0a8e9fdf66', 31, 31, null, 50, null, null, false, 1),
  ('e6ca9260-ff37-508a-b8c3-dd3f44a4f58f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12G', 'Quarrying Specialist (National Guard Only)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises PMCS of CSWP and rock drills. Supervises assembly, adjustment, calibration, and operation of CSWP in the production of aggregate for construction projects. Supervises drilling of blast patterns and loading of boreholes. Detonates explosives to excavate quarry rock.', 'f56229408cd3ad87fb2288ea52972657aba66b2b85939b8d359694796d286267', 31, 31, null, 51, null, null, false, 2),
  ('a65d89a5-83b8-504e-a8de-8037c140c3b6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12G', 'Quarrying Specialist (National Guard Only)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises rock production operations. Directs the production of crushed, washed, and graded aggregate. Designs, plans, and conducts subsurface demolitions operations. Plans and directs the quarry layout and plant setup.', '6d7042ecaa6b5c17e431aecaf8da3b4e1a913a7f63204ae926620c2efb51d2a7', 31, 31, null, 52, null, null, false, 3),
  ('93dbd57e-dc3b-52d5-aa0b-a06e487e8856', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12H', 'Construction Engineering Supervisor (Const Engr Supv)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The construction engineering supervisor supervises construction, repair, and utility services of buildings, warehouses, fixed bridges, port facilities, and petroleum pipelines, tanks, and related equipment.', 'e1c8b39a0798797fdf1939d6c8277d72b0cba4592c7ec260165b12ab8699e0aa', 32, 32, null, 53, null, null, false, null),
  ('c395390f-bea3-58de-9681-450c529b3bc4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12H', 'Construction Engineering Supervisor (Const Engr Supv)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and maintains proficiency in all major duties of previous skill levels in MOS 12W, 12K, or 12R. Supervises subordinate Soldiers and provides technical and tactical guidance in the accomplishment of their duties. Supervises the construction of forms, wood frame structures, concrete structures, masonry structures, installation of plumbing systems, erection of pre-engineered buildings, installation of electrical systems, installation of suspended ceilings, building layout, generator operations, and construction of steel frames. Designs column forms and wall forms. Prepares a bill of material, schedules work, reads and annotates construction prints. Directs operator maintenance on assigned equipment, inspects work for proper installation in accordance with local codes and ordinances, and ensures employment of proper safety procedures. Implement Quality Control (QC) plan. Implement construction site safety and environmental plans.', '0f4fcf768fb4de45241d55780f7926617c1dafcd296027fba5fc5d08372514b4', 32, 32, null, 54, null, null, true, 3),
  ('e912f22e-2f08-548b-8ae7-260b991533d5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12H', 'Construction Engineering Supervisor (Const Engr Supv)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Designs utilities job plans, timber trestle bridges, and manages construction projects. Devises project management plans, including work breakdown structure and network flow diagrams such as the critical path method or utilizing project management software, and coordinates work activities of supporting units. Provide supervision over all structural and utility construction projects. Inspect subordinate elements to ensure compliance with directives, construction drawings, and specifications. Advises Battalion commanders on all construction projects. Supervises Quality Control (QC), construction site safety and environmental plans. Supervises subordinate personnel.', 'c45d52641dc9600864db088bb0841a3599a04ffc4f1d8417ae46dc88ef98ed8b', 32, 32, null, 55, null, null, false, 4),
  ('46bef4bb-2f14-5982-b97b-5f859757142e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12K', 'Plumber', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The plumber installs and repairs pipe systems and fixtures, and petroleum pipeline systems.', '1ef51e98b8066a5284a4799f8762cd1427d547e62123ba634d90c7b8fbe580f8', 33, 33, null, 56, null, null, false, null),
  ('316cdea6-a590-5391-9812-efb5587a40ea', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12K', 'Plumber', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Installs steel, plastic, and copper pipes, water closet with tank, urinals, water heaters, shower systems, water systems, waste systems, lavatories, and cross linked polyethylene (PEX) pipes. Repairs valves and fixtures control devices, steel, plastic, and copper pipes, cast iron pipes, and PEX pipes. Maintains plumbing tools, grades sewer lines, tests waste and water systems, clears waste systems stoppages, identifies plumbing materials, winterizes water systems, interprets plumbing prints and drawings, prepares a material takeoff list, and rescues an electrical shock victim.', '508f10d1d1a4c8d6588c00e84afcaac57633e13489c71dd14acd388c7ef9f50d', 33, 33, null, 57, null, null, false, 1),
  ('4d88217b-275c-50f1-b9ee-4587ab3220ec', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12K', 'Plumber', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Installs cast iron pipes and draws a plumbing job plan. Coordinates construction planning and advises on plumbing construction. Inspect plumbing systems/components for proper installation and ensures employment of proper safety procedures.', '899e8ced6b28f10bdf76b23eab73742a56963478b040a9552820f64334a77095', 33, 33, null, 58, null, null, false, 2),
  ('6959859a-51ff-5e9d-a4ad-e25e5d7f625e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12M', 'Firefighter', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The firefighter supervises or provides fire prevention and protection, firefighting, technical rescue, urban search and rescue and hazardous materials response capabilities to prevent or minimize injury, loss of life, and property and the environment throughout a range of military operations.', '465fbb2c19fcc8325c60ed73615adda9cc79b7ce02d87981b279ee2df2c92602', 34, 34, null, 59, null, '2025-10-01', false, null),
  ('3b93b22b-06ca-5fe6-ab66-9dc4f1b88e33', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12M', 'Firefighter', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Firefighter performs Fire and Emergency Services (F&ES) tasks under the direction of the Lead Firefighter and Station Chief. Their duties include Performing rescue and firefighting operations during structural fires, aircraft firefighting (ARFF) emergencies, vehicle emergencies and wildland fires; performing emergency response duties during hazardous materials incidents to include ordnance; performing urban search and rescue and technical rescue duties. The Fire Truck Driver/Operator performs as the Driver/Operator of an engineer F&ES vehicle. They maintain firefighting equipment and vehicles during emergency and non-emergency operations. They must be licensed both through Army drivers training and the specific driver requirements outlined in DoDM 6055.06 to operate F&ES vehicles assigned to the team. Driver/Operators must be certified to the level of Driver Operator- Pumper and Driver Operator-ARFF prior to performing duties in the Driver/Operator positions on the Tactical Firefighting Truck (TFFT). To perform duties as the Driver/Operator for the Heavy Expanded Mobility Tactical Truck Based Water Tender (HEWATT), the Driver/Operator must be certified to the Mobile Water Supply (MWS) Apparatus level. Both Fire Apparatuses require the Driver/Operator to be Heavy Expanded Mobility Tactical Truck (HEMTT) driver qualified.', 'd5a6282517d9456f667a0e28d74ae705c04ea8c4da2c56f6bd82fcde8b2661a1', 34, 34, null, 60, null, '2025-10-01', false, 1),
  ('763b2309-fd33-5131-93d9-4a9deae83d24', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12M', 'Firefighter', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Lead Firefighter leads team personnel at the scene of an emergency and conducts and records team level training as directed by the Station Chief. Their duties include Directing rescue and firefighting operations during structural fires, ARFF emergencies, vehicle emergencies, and wildland fires; directing emergency response crews during hazardous materials incidents to include ordnance; and directing urban search and rescue and technical rescue operations as directed by the Fire Chief or Fire Marshal.', 'f45cc4281b07bed2c822b95b2bcdcdaf70564d7fb5a962bfc5e767990ebaf370', 34, 34, null, 61, null, '2025-10-01', false, 2),
  ('88cd7500-ceed-5949-8821-0d284a11f9a4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12M', 'Firefighter', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Station Chief/Fire Team Chief duties include Supervising the team in all F&ES missions. Acting as Senior Fire Officer during initial response to an emergency. In the absence of a supporting headquarters, they assume responsibilities of Fire Chief. The Fire Inspector provides fire inspection and prevention capability in support of activities in a base camp. The fire inspector provides expeditionary fire inspections and limited fire prevention functions including hazard assessments, public fire safety education and facilities plans reviews. Additional duties include maintaining the status of the F&ES team equipment and supplies for 24-hour continuous missions and resupply after each mission. Duties may also include coordinating for recharging and servicing of SCBA and firefighting agents for mission vehicles. In addition, provide resupply for fire extinguishers that are unserviceable for live areas and structures via contract with local vendors.', '88b614bc42d4e1b26c0b7dd1026ba0d88575bd90fa2ab11d2981d42ee58d096b', 34, 34, null, 62, null, '2025-10-01', false, 3),
  ('3ef9c478-d793-5772-92b9-c383e163b553', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12M', 'Firefighter', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Fire Chief is both the Noncommissioned Officer in charge (NCOIC) and Senior Fire Officer (SFO) for all F&ES at the Army, Corps, Division, and Brigade level for an area of operations (AO). Their duties consist of: Advising the Fire Marshal, Fire Inspector, mayor cell, forward engineer support team, and commander of force protection issues relating to F&ES; establishing and direct F&ES planning and coordination, working with the fire marshal in establishing and directing a Fire Alarm Communications Center (FACC); providing F&ES management oversight, establishing a fire prevention and inspection program to include training; providing senior leadership advice on vital information for minimizing loss of life, property damage, life safety, and limiting damage from fire that would seriously degrade mission capability. The Fire Chief is designated as incident commander during F&ES incidents and is the operations section chief or branch director (fire protection) when not employed as the incident commander in the National Incident Management System (NIMS) hierarchy of incident command.', 'b0dda6dd4b58a0f56de1eca66bcc9194bfb1ab98b929e321dbe33e9c6884eb63', 34, 34, null, 63, null, '2025-10-01', false, 4),
  ('08fa288e-bdd9-5ecf-8a7c-efad06b19569', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12N', 'Horizontal Construction Engineer (Horiz Const Engineer)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The horizontal construction engineer supervises or serves as a member of a squad, team, section, or platoon. Duties start with operating heavy equipment at an intern level and progress to senior equipment operator level with supervisory responsibilities for personnel, construction projects, obstacle emplacement, and counter-obstacle operations involving construction equipment.', 'd2d16e6d229f24ca1b98a1a1de077a19c756b34adc7f0bb24a17ba3a5a579a67', 37, 37, null, 64, null, null, false, null),
  ('130396f5-1438-58c2-9bd7-e56d89d4d7d7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12N', 'Horizontal Construction Engineer (Horiz Const Engineer)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serve as an intern level equipment operator with basic level training for interpreting basic grade stakes, , and identifying basic soil properties Performs basic crawler tractor operating tasks of clearing; , grubbing, stripping, excavating, backfilling, constructing ditches, stockpiling and push loading scrapers Performs basic motorized scraper operating tasks of excavating and spreading fill material Performs basic scoop loader operating tasks of stockpiling, backfilling, and loading haul units. Perform basic motorized grader operating tasks of scarifying, spreading, leveling and constructing V ditches. Performs basic hydraulic excavator operating tasks of excavating, stockpiling, backfilling, constructing ditches and loading haul units Performs basic backhoe loader operating tasks of excavating, stockpiling, backfilling, constructing ditches, and loading haul units. Performs basic dump truck operating tasks of driving, spreading, and dumping material Performs basic water distributor operating tasks of driving, loading, and spraying water. Performs basic roller operating tasks of compacting material utilizing a sheep’s foot roller, smooth drum roller, and a vibratory roller. Performs basic tractor trailer operating tasks of transporting heavy construction equipment.', '84acd6218bcf05f0611a1e4d10f30a81775739d3cde71e41b03e2a05532ad93c', 37, 37, null, 65, null, null, false, 1),
  ('43a623c6-6440-56dc-b34e-47755db7483b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12N', 'Horizontal Construction Engineer (Horiz Const Engineer)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as a Horizontal Construction Sergeant with limited supervision of construction equipment and personnel activities. Soldiers are senior and become primary operators for all finishing work and complex operating situations on horizontal construction projects. Provides guidance to less experienced equipment operators on operating techniques, procedures, and operator maintenance.', 'a3d07ef93be1f57a4becf4cc5c8646df024eec0a528a0ff4be1ae86685059924', 37, 37, null, 66, null, null, false, 2),
  ('d88d86f0-dc2b-588f-82fe-ac81cbae353c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12N', 'Horizontal Construction Engineer (Horiz Const Engineer)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as a Horizontal Construction Supervisor, Section Sergeant. Supervises activities related to the utilization of heavy construction and lifting equipment in support of construction project operations. Calculates equipment and operator requirements to assist in the development of construction project estimates. Organizes and direct mobility and counter-mobility missions.', 'ce79069ec87936abcd25c97556c00284bae80c71b59d5dc0c03c1b6661d22277', 37, 37, null, 67, null, null, false, 3),
  ('50ac052b-ced7-5143-83d2-0f672a8bec6e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12N', 'Horizontal Construction Engineer (Horiz Const Engineer)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as a Senior Horizontal Construction Supervisor, or Platoon Sergeant. Organizes the overall construction workload. Utilizes project management techniques in the development and execution of construction projects and coordinates work activities of supporting units. Plans, organizes, and supervises all engineer construction equipment operations, including mobility and counter-mobility missions. Develops and executes a quality control plan and standard operating procedures.', 'fb398d4f96230b65fcf31795aed971a30653eeefb9c09dfc885ad7500fd3bf8f', 37, 37, null, 68, null, null, false, 4),
  ('b473d852-be38-5e6c-bb37-b8a31e185a11', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12P', 'Prime Power Production Specialist (PPPS)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The prime power production specialist performs electrical assessments, facilities maintenance, QA/QC operations: supervises, operates, installs, and performs DS/GS level maintenance on electric power plants, consisting of prime power generator sets of 500 KW and higher; and associated auxiliary systems and equipment. Other duties include LNO and technical advisor to FEMA and other federal organizations.', 'b2c3a16031f9b0753479e00b8bc3b4eacc3ebc1373d40a0121f369d4b60a3bbf', 39, 39, null, 69, null, null, false, null),
  ('c8be7d99-75c9-50e7-8b3b-f229a0f779de', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12P', 'Prime Power Production Specialist (PPPS)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists with the operation and maintenance of electrical power plants. Performs mechanical, electrical and instrumentation functions as necessary during the installation and preparation of power station equipment during initial startup. Assists with the assessments of electrical distribution systems and facilities. Troubleshoots and repairs power generating equipment and associated systems components.', 'fa2e03e6558880cbbd9f6090bd88450272525ad45f62b95950347d91c0ac94a3', 39, 39, null, 70, null, null, false, 1),
  ('908a7381-4470-5663-aff1-d40fc7e62485', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12P', 'Prime Power Production Specialist (PPPS)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises the operation and maintenance of electrical power plants. Performs mechanical, electrical and instrumentation functions necessary to install and prepare power station equipment for initial startup. Analyze plant equipment and system operating characteristics to determine operational condition. Supervises and performs electrical assessments of electrical distribution systems and facilities. Repair or overhauls generating equipment and associated systems components.', 'c6ad77411645fd9d39a3ca3161ca863a0f940c2345de2c9fd56a70a510e037a8', 39, 39, null, 71, null, null, false, 2),
  ('25787a1f-9fff-5fdc-ae03-9a1631b7cd09', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12P', 'Prime Power Production Specialist (PPPS)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise the installation, operation, or maintenance of prime power plants, associated systems, equipment, and Soldiers. Direct preparation of power plant equipment for movement, storage, and installation. Serve as technical inspector to determine faulty operation/maintenance practices. Determines and isolates complex malfunctions, utilizing diagnostic tests, and troubleshooting techniques. Supervise electrical assessments of electrical distribution systems and facilities. Assist in QA/QC operations for electrical projects, equipment, and contract personnel. Determines repair/overhaul required, cost effectiveness and method of accomplishment for power plant equipment, and associated systems.', '92c95d55f4947d317ce8b3d1347002d55bf49c0609c573900ed378301e276cba', 39, 39, null, 72, null, null, false, 3),
  ('33f6d7f3-78f6-520a-aa11-305431e30568', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12P', 'Prime Power Production Specialist (PPPS)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise personnel and the installation, operation, unit level and direct support maintenance of electrical power plants. Coordinates, plans, and schedules team activities. Plans for the use, movement, and siting of electrical power plants. Estimate manpower, equipment, and material necessary to accomplish installation of power station and construction of associated systems. Advise subordinate personnel on prime power equipment use, siting, operation, and maintenance. Manages electrical projects, devises, and implements safety programs and serves as LNO for echelons above Corps. Supervise QA/QC operations for electrical projects, equipment, and contract personnel.', 'b492cf3bddceb46b1b8dedc6f2587a72b4e1270ee4f0a20b4bff4e76ecf51209', 39, 39, null, 73, null, null, false, 4),
  ('1700a4ad-638c-50cc-8135-f2e3cb9459fd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Q', 'Powerline Distribution Specialist (Reserve Components) (Powerline Dist Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The powerline distribution specialist supervises or installs and maintains electrical distribution systems; performs duties as a member of a transmission and distribution team.', '61ba73930272961338daffc48d290e58b96663956cb47086ae7a867f87a9d34b', 41, 41, null, 74, null, null, false, null),
  ('29d3821f-8f6c-5ffd-88f6-d9e0350a5f48', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Q', 'Powerline Distribution Specialist (Reserve Components) (Powerline Dist Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assist in installation of electrical transmission and distribution systems and exterior services. Assists in the erection of utility poles; and, installs guys, anchors, crossarms, conductors, insulators, and other hardware. Installs and connects service drops and conduits on de-energized systems.', '49b056d7ed13df68f5f695a947423e62020348e8a311a378de2c54794ebfa4b3', 41, 41, null, 75, null, null, false, 1),
  ('1778e785-0397-5721-a023-645ff1f86a00', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Q', 'Powerline Distribution Specialist (Reserve Components) (Powerline Dist Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Installs and maintains electrical transmission and distribution systems. Tests circuits and components to isolate malfunction and repair defects. Perform scheduled and emergency inspections and repairs of distribution systems and equipment. Assist in maintenance, repair, calibration, and tests of internal substation equipment.', '033165abf1f19c8bab614f08f662614f8cb83055fb5f82ab9c5dd8dd9ce4adf1', 41, 41, null, 76, null, null, false, 2),
  ('8867a635-679f-5233-8712-629de4d75aa2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Q', 'Powerline Distribution Specialist (Reserve Components) (Powerline Dist Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise installation of underground and overhead electrical distribution systems. Supervise staging of material and construction and maintenance equipment. Maintains and uses special purpose safety equipment and tools employed for electrical construction and maintenance. Ensures proper safety and clearance procedures are followed.', 'd2fc742cbbe71585a6255f377815273ad99e3fb888205e03e0668b79821f2788', 41, 41, null, 77, null, null, false, 3),
  ('9f24fd50-ff7c-568c-88af-dea7d5e36e2e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Q', 'Powerline Distribution Specialist (Reserve Components) (Powerline Dist Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans and supervises construction and maintenance of electrical transmission and distribution systems. Estimate manpower, equipment, and material requirements for electrical construction. Advise on electrical construction and maintenance procedures and capabilities.', 'a9aaef3fdf72ec4fc69acf76dc53bbd0c93b5560eca4d472bccadad8fb5fa00b', 41, 41, null, 78, null, null, false, 4),
  ('a213cff8-6b38-59a7-af02-dbe7081fe220', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12R', 'Interior Electrician', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The interior electrician supervises or performs installation and maintenance of interior electrical systems and equipment.', '1fd48a048b4ed289e103fa61406e281a86b49c97dfaac664b5cc1a6691db0918', 42, 42, null, 79, null, null, false, null),
  ('32e58235-493b-5a67-bea4-5432ecf6493f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12R', 'Interior Electrician', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Installs and maintains interior electrical systems up to 600 volts. Installs service entrance systems, electrical boxes, conduit systems, cable systems, switches, receptacles, fixtures, service panels, grounding systems, and 240-50Hz International Electrical systems. Interprets electrical prints, schematics, and drawings and International codes and standards. Maintains electrical tools, troubleshoots malfunctions in electrical circuits, performs generator operations, prepares a material takeoff list, and recues an electrical shock victim.', 'a240b9f6945b3941927596fb6723314e02ef62f247c68a62c163fbc9cfee0ce2', 42, 42, null, 80, null, null, false, 1),
  ('e978b5d3-97c7-5701-b1a2-a0a4e67077a9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12R', 'Interior Electrician', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise installation and maintenance of interior electrical systems. Coordinates construction planning and advises on electrical construction. Uses test equipment to isolate malfunctions and repairs defects in systems and components. Inspect interior electrical systems/components for proper installation in accordance with National Electrical Code and local ordinances and ensures employment of proper safety procedures.', '075327b4ba5a2ae6649ad31394d466f6dccc14f47742189b7000c2b663143682', 42, 42, null, 81, null, null, false, 2),
  ('f118db58-357d-5278-be16-6cbcb85ca25f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12T', 'Technical Engineer (Tech Engr)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The technical engineer supervises or participates in construction and airfield site development, establishing permanent survey control stations, producing construction plans, performing quality control inspections, and performing field and laboratory testing on construction materials.', '2b459cb1b22ae302af341cbc40bff4a07c2ad9d6a7f4ec04944c5534ca89e960', 43, 43, null, 82, null, null, false, null),
  ('00f28db3-1d4d-5824-846f-f2aaaf691310', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12T', 'Technical Engineer (Tech Engr)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs construction surveying, geodetic surveying, computer aided drafting, testing on construction materials, and quality control inspections. Processes and adjust Global Positioning System (GPS) survey data.', '6ff53c8cdb60d92fe9ab605a08b6aac76a5f631e7a59b5ccd4919ad7e9ee0d31', 43, 43, null, 83, null, null, false, 1),
  ('c691a2f1-d721-5a71-b47c-b538a4af64f6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12T', 'Technical Engineer (Tech Engr)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises construction surveying, geodetic surveying, computer aided drafting, testing on construction materials and quality control inspections. Corrects and validates Global Positioning System (GPS) survey data.', 'e4a7e66230e33ae1f6cae4733aa2c7fb397a210d19258fe4c55c460a4ee67458', 43, 43, null, 84, null, null, false, 2),
  ('e4e2ef0d-0b62-5364-9f45-ef1ae741d24a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12T', 'Technical Engineer (Tech Engr)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Directs and inspects construction surveying, geodetic surveying, computer aided drafting, testing on construction materials, quality control inspections, Global Positioning System (GPS) survey data. Reconnoiters and plans construction surveys to determine special requirements. Determines soils stabilization methods for military construction. Designs concrete and asphalt mixtures. Prepares project progress reports and conducts project briefings.', 'cc6f91d0e3e99c65eaf16abb32c9911203112a60a2e4d3a0669746247fa4b1cf', 43, 43, null, 85, null, null, false, 3),
  ('581bee14-57ec-5e71-b54b-009d591c44f8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12T', 'Technical Engineer (Tech Engr)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Manages a Survey and Design Detachment. Analyzes and interprets field and laboratory tests on construction materials, construction and geodetic surveys, and drafting for military construction. Plans airfield, signal and intelligence surveys and quality control assurance check procedures. Prepares design specifications for construction projects.', 'c8f6104f6c2514ff3235bef59dae2f83eba081a89968904ca969ee871b6239da', 43, 43, null, 86, null, null, false, 4),
  ('dda3153e-815a-51f9-8b89-3b6a568263cf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12W', 'Carpentry and Masonry Specialist (Carpentry & Masonry Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The carpentry and masonry specialist performs general heavy carpentry and masonry duties..', '19551d4b2ace04f3d81dd2b416f04174eef0ff7e47e1d779d3d52554b03afc77', 44, 44, null, 87, null, null, false, null),
  ('c6b02d62-78f7-5036-a69c-e30bd560f3f2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12W', 'Carpentry and Masonry Specialist (Carpentry & Masonry Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Employ basic carpentry and masonry skills. Constructs floor systems, stairs, roof systems, wall systems, masonry walls, concrete wall forms, and concrete slab forms. Installs batter boards, suspended ceilings, exterior finishes, interior coverings, floor and wall tiles, and doors and windows. Places concrete, applies roof coverings, fabricates joints and splices, erects pre-engineered buildings, prepares material takeoff lists, applies interior trim, identifies building materials, maintains carpentry and masonry tools, and rescues an electrical shock victim.', '44189261dfa236e4e063f1ca3b0d1dc7d2f690a051c0947399ec2615ec1be5a4', 44, 44, null, 88, null, null, false, 1),
  ('b9e94984-c087-5b16-a437-253a5e8f4c11', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12W', 'Carpentry and Masonry Specialist (Carpentry & Masonry Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Constructs foundations, constructs overhead forms, and performs slump tests. Coordinates construction planning and advises on carpentry and masonry construction. Directs operational maintenance on assigned equipment. Inspects carpentry and masonry components for proper installation in accordance and ensures employment of proper safety procedures.', 'a7fa6456159a51f153175dd7404dbab1321aaae581d3ec5e4c53e9046d05c642', 44, 44, null, 89, null, null, false, 2),
  ('07f90e0d-5d80-52bb-8b4c-fbaef1e80b4a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12X', 'General Engineering Supervisor (Gen Engr Supv)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'at skill level 5. The general engineering supervisor supervises general engineering activities related to all construction and utility operations. Assist engineering officer in construction planning, scheduling, and material estimating. Assist in the preparation of operation orders, standing operating procedures, and contingency plans. Provides staff supervision and principal noncommissioned officer direction to units engaged in performing general engineering missions. Inspect construction and training activities. Supervise performance of combat engineering missions.', '5011708efeac06269a2b33d9e0a837ec2c2261ae763d03eab143d031c1245340', 45, 45, null, 90, null, null, false, null),
  ('01065362-245b-5216-99c7-64c5b227e632', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Y', 'Geospatial Engineer', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Geospatial engineers manage the enterprise geospatial database; compiled from all sources including the National Geospatial Intelligence Agency, the Army Geospatial Center and other services, international partners as well as exploiting new collection and production from deployed Soldiers and sensors. Geospatial engineers manage the geospatial foundation of the Common Operational Picture (COP), synchronizing hard and soft copy products and are a necessary component of all military operations. Finish compilation of geospatial data i methods include web-enabled geospatial services, digital geospatial information on removable media, hard copy map production, and sharing geospatial knowledge through written and oral communication.', '52341f25eb382f7c34f62e6f9c6e932c767146697e136cc90fba7c8b104dc67a', 46, 46, null, 91, '2024-09-01', null, false, null),
  ('43b3497b-ed56-5db2-bfac-f3a87c843afb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Y', 'Geospatial Engineer', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Extract geospatial data from remote sensed imagery, field reconnaissance, digital data, existing Geospatial products, and other collateral data sources. Records data extraction/analysis results in a standard military geospatial data base. Digitizes and scans cultural, topographic, hydrographic, and/or other features in digital formats. Perform digital manipulation of geospatial information by querying, viewing, evaluating, and analyzing digital data. Finish compilation of geospatial data into printable map/products and/or digital display of geospatial information.', '006544f9257fbf44c16e6a7661b1dbf8b2be68acbadb6e3155437c4ff9cabaef', 46, 46, null, 92, '2024-09-01', null, false, 1),
  ('666229ce-3091-5b55-91b8-476aaa2e6ea1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Y', 'Geospatial Engineer', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in the preceding skill level, supervise lower grade Soldiers and provides technical guidance to the Soldiers in accomplishment of their duties. Analyze collected military geographic information to produce geospatial decision aids. Predict terrain and weather effects as applied to all Army operations, Perform data base management for the storage of aerial photographs, maps, digital data bases and collateral source materials. Perform quality assurance during all stages of geospatial operations to include finish compilation of geospatial data into printable map/products and/or digital display of geospatial information.', '6d333021c712af0597c0a871f23b2b957d6365b8dbb7ed9bb7941df43c2dc83c', 46, 46, null, 93, '2024-09-01', null, true, 2),
  ('7bff381a-b2e5-5d60-b750-5231cb1ca08f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Y', 'Geospatial Engineer', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties of preceding skill level, supervises lower grade Soldiers, and provides technical guidance to Soldiers in the accomplishment of their duties. Supervise Geospatial Engineers at Division, Corps and EAC Geospatial units to include maintenance of assigned equipment. Evaluate source materials for military geographic information analysis. Supervise quality assurance during all stages of geospatial operations to include finish compilation of geospatial data into printable and digital map/products. Ensures required administrative, intelligence, source data and reference files are maintained. Advise command and staff officers on all aspects of geospatial operations and doctrine.', '9ad87409a107de69cf371bda31e87890840aa37a90e86914f6de4214174e69b0', 46, 46, null, 94, '2024-09-01', null, true, 3),
  ('633f6a12-a05a-56f3-8eee-5bfd77976dfe', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Y', 'Geospatial Engineer', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties of preceding skill level, supervises lower grade Soldiers, and provides technical guidance to Soldiers in the accomplishment of their duties. Supervise Geospatial analysis activities at all levels. Coordinates and validates data generation requirements. Supervise quality assurance program for all Geospatial operations to include finish compilation of geospatial data into printable map/products and printing of hardcopy geospatial information. Plans and coordinates activities pertaining to the organization, training and the tactical and technical operation of the assigned unit. Advise command and staff officers on all aspects of Geospatial operations and doctrine. Coordinate the planning and production of military geographic information.', '3bdfa04ada4ec0a41e3ced67f375e0dca84218c544d1582ac6a57929e5897700', 46, 46, null, 95, '2024-09-01', null, true, 4),
  ('de760476-2506-57f8-b884-ea382ed073c5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Y', 'Geospatial Engineer', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assist in geospatial planning and control activities. Assist in determining foundation geospatial map and data requirements and providing technical supervision of geospatial mapping and other military geographic intelligence programs. Assist in command supervision and coordination of map reproduction and geospatial dissemination programs. Provides staff supervision and principal noncommissioned officer direction to units engaged in performing geospatial engineering missions.', '6a993e1198ac15f2299bc657f14976b8581d874877cc4b590972079076b109f6', 46, 46, null, 96, '2024-09-01', null, false, 5),
  ('ed86eaba-437f-52c6-9a3c-ffba50e80e22', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '12Z', 'Combat Engineering Senior Sergeant (Combat Engr Sr SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'at skill level 5. The combat engineering senior sergeant inspects and advises on bridging, rafting, and river crossing operations. Formulates and maintains construction schedules. Assist in supervision of troops in assault operations. Perform ground and aerial reconnaissance. Advises engineer staff section personnel in matters involving combat engineer operations. Coordinate with staff agencies for engineer operational and tactical support. Coordinate employment of engineer elements operating with infantry and armored units. Inspects construction sites and enforces job specification and safety standards. Collects, interprets, analyzes, evaluates, and disseminates intelligence data.', 'd03cf62f15ec84254f12e123d109e26806069cdcec0f31b9b53ff0fe825f3148', 48, 48, null, 97, null, null, false, null),
  ('a616f6e0-e7f6-5548-82fd-8780b5575382', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13B', 'Cannon Crewmember', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The cannon crewmember supervises or serves as a member of field artillery cannon section or ammunition section.', '9380c1b16d7e30dc8b9bbb885a3924d105d3d8a214cf81130a752e86f8ad8ffc', 49, 49, null, 98, null, null, false, null),
  ('ebbd269f-cc11-5d96-9eb6-9fc77fb3c1f3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13B', 'Cannon Crewmember', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Integral member of a crew that operates high technology cannon artillery weapon systems. Load and fire howitzers. Sets fuse and charge on a variety of munitions, including high explosive artillery rounds, laser guided projectiles, scatterable mines, and rocket assisted projectiles. Uses computer generated fire direction data to set elevation of cannon tube for loading and firing. Employ rifles, machine guns, and grenade and rocket launchers in offensive and defensive operations. Drives and operates heavy and light wheeled trucks and tracked vehicles. Transports and manages artillery ammunition. Participate in reconnaissance operations to include security operations and position preparation. Operate in reduced visibility environments with infrared and starlight enhancing night vision devices and other equipment. Coordinate movement into position. Camouflages position area. Communicate using voice and digital wire and radio equipment. Use critical combat survival skills to operate in a hostile environment. Maintain operational readiness of vehicles and equipment.', '32ff0da6fb7f70cdf2a414a79e3941905049637f76d5ce841538a027b9c0467f', 49, 49, null, 99, null, null, false, 1),
  ('f98a9522-c3fa-596a-ad82-6c7c85bb57c5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13B', 'Cannon Crewmember', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise handling, transportation, accountability, and distribution of ammunition. Assists section chief in supervision of howitzer operations, maintenance, and training. Lays weapon for direction, conducts bore sighting and basic periodic tests. Supervise the operation, loading, and maintenance of the Field Artillery Ammunition Support Vehicle.', 'c2843736ce0b2a8535bbb26e2843aa38abc68621346cacd8f93bfd9ba8ab3ea5', 49, 49, null, 100, null, null, false, 2),
  ('0639ef23-8cbb-5e0b-ab3c-8617e071f600', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13B', 'Cannon Crewmember', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Directs and supervises movement emplacement of the howitzer section. Supervises and directs the construction, camouflage, and defense of the section position. Trains, instructs, and supervises section personnel in cannon gunnery procedures and firing. Responsible for the verification of safe firing data. Supervises the handling, storage, accountability, and distribution of ammunition. Supervises the performance of operator, crew, and organizational maintenance on section vehicles.', 'c359b36ca4f80c255177b9f3b05fd6619c15f02b8bec30697251f2bc7d6cb4dc', 49, 49, null, 101, null, null, false, 3),
  ('3b922fa3-af46-56ca-befd-9032e021d2ce', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13B', 'Cannon Crewmember', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists platoon leader in the planning, preparation, and execution of collective training activities of the platoon. Conduct battery/platoon reconnaissance, selection, occupation, and defense of position areas. Supervise firing battery personnel engaged in firing battery operations, maintenance, and training. Lays the unit for direction of fire and verifies safe operations before and during firing. Supervises battalion ammunition trains operations. Reviews, consolidates, and prepares technical, personnel, and administrative reports covering firing battery element activities.', '5099cdd7a99626720da804e3e24a98f0685c8dfd9ed38d139ba73eb667f7bdd5', 49, 49, null, 102, null, null, false, 4),
  ('f409fe48-911a-5c41-b43b-10c9c27e3788', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13F', 'Joint Fire Support Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Joint Fire Support Specialist (JFSS) is an integrator of joint fire support and executor of tactical indirect fires across all maneuver formations from Armor, Mechanized Infantry, Light Infantry, and Special Operations units in support of Unified Land Operations (ULO). The JFS is an integral part of the targeting process. The JFSS is the eyes and ears of the combined arms team and employs a suite of tactical vehicles, digital devices, precision targeting tools, precision munitions, employment tactics and procedures to provide surface to surface fires, close combat attack, and close air support, The JFSS reports battlefield intelligence, recommends targets for inclusion into the fire support plan, establishes and maintains digital and voice communication, provides target refinement data and advice to the combined arms team on the limitations and capabilities of all fire support assets. The JFS provides fire support planning, coordination, integration, and management of tactical battlefield information through a network of automated Mission Command systems. The JFS performs operator and unit level maintenance on all section equipment.', '3ca69c749516ff7c7f009f56939ee51c5bf98c3486756ac667ced135bbe65df2', 51, 51, null, 103, null, null, false, null),
  ('548df8e7-6829-5415-af6b-0ef5b3122283', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13F', 'Joint Fire Support Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Primarily assists in providing indirect fires support in all maneuver formations from Armor and Mechanized Infantry to light infantry units in support of unified land operations (ULO). The JFSS, 13F10, supports the employment of all digital devices, precision targeting tools, fire support tactics, techniques, and procedures in order to accomplish the mission in support of ULO with indirect fires. Entry level JFSS is qualified in the employment of surface to surface fires and is familiar with executing and integrating Joint Fires, employing precision targeting tools and precision munitions. Performs operator and unit level maintenance on all section equipment.', 'e9253c3a4d8de4ebf61455a85651ab373aa161e07f4651f44e52f2acb4828149', 51, 51, null, 104, null, null, false, 1),
  ('519b5383-cfb1-5ef4-a190-718010348493', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13F', 'Joint Fire Support Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Primary enabler and executor of indirect fires and fire support at the maneuver platoon level across all maneuver formations in support of Unified Land Operations (ULO). Initiates and facilitates the integration of all fires in support of maneuver platoon operations, employs a suite of digital devices, fire support command and control systems, precision targeting tools, conventional and precision munitions, employment tactics techniques and procedures in order to provide artillery and mortar surface to surface fires, close combat attack, close air support, and Naval Surface Fire Support (NSFS). Assists in training subordinates in fire support tactics, techniques and procedures, supervision of section operations, maintenance, and training, prepares and refines target lists and assists in developing Joint fire support plans. Reports battlefield intelligence, submits key targets for Troop/Company fire plans, establishes and maintains digital and voice communication, advises the platoon leader on limitations and capabilities of all fires support assets, provides target refinement data, provides targeting data for close combat attack and facilitates the execution of close air support by conducting Terminal Guidance Operations. Performs operator and unit level maintenance on all section equipment, to include calibrating and bore sighting precision automated systems.', '4d30023eeb870736291bcb7c129c591eea1714360d4d7ae9ea50a9f1bb2be1fe', 51, 51, null, 105, null, null, false, 2),
  ('20937639-e9f4-5e67-af78-a4be814c3ddb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13F', 'Joint Fire Support Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Primary integrator and executor of indirect fires and fire support at the maneuver Troop/Company level across all maneuver formations; prepares target lists and assists the Company Fire Support Officer in developing Company/Troop fire support plans in support of ULO. Initiates calls for fire on targets of opportunity, develops and executes planned targets and integrates fires with the scheme of maneuver. Employs a suite of digital devices and precision targeting tools, provides target mensuration and target refinement, submits targets for Squadron/Battalion fire plans, establishes and maintains digital and voice communication, reports battlefield intelligence, employs fire support command and control systems, advises the Fire Support Officer and Commander on capabilities and limitations of all fire support assets, provides targeting data for close combat attack and close air support Leads section training and preparation for combat operations. Advises, trains and evaluates personnel on the employment of precision and joint fire support tactics, techniques, and procedures. Keeps key personnel informed of pertinent information. Supervises the operation and maintenance of all fire support equipment, to include calibrating and bore sighting precision automated systems.', 'c68afd1b81337fbd96dc70006ebbe2a23773194f5866040b0f1e4490fe3ac4fd', 51, 51, null, 106, null, null, false, 3),
  ('b1cbf535-1009-5456-95ad-72a2532731cb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13F', 'Joint Fire Support Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads and trains the Fire Support Personnel within Battalion, Brigade, Field Artillery Brigade and higher echelon Tactical Operations Centers. Advises and assists with planning, integration and coordination of all Fire Support assets. Provides recommendations throughout the targeting process to facilitate the integration of all fire support assets into the scheme of maneuver, assists the Fire Support Officer with the integration of the fire support plan and fire support tasks with the Battalion/Squadron operations order. Provides technical oversight during fire support technical rehearsals, trains fire support personnel, processes and assists with ground and air space clearance in support of calls for fire on targets of opportunity, facilitates the execution of planned targets and counter-fire missions, prepares and disseminates the fire support plan, execution matrix, target list worksheet, and fire support overlay to key personnel, advises the Fire Support Officer and Commander on the positioning, capabilities and limitations of all fire support assets. Certified as JFO-evaluator (JFO-E), provides training, unit certification program management and expertise in close combat attack and close air support, and provides oversight and recommendations for the employment of fire support personnel and equipment. Advises and evaluates fire support personnel on the employment of fire support tactics, techniques, and procedures. Supervises the operation and maintenance of all fire support equipment and keeps key personnel informed of pertinent information. Assists the Targeting Warrant officer in the process, development and submission of Target mensuration, CDE calls and Weaponeering.', '2c5cc9a4fb9f7add5c61d1fdd9d1676f5910926b82c00e1bd37dc56a1ab4088e', 51, 52, null, 107, null, null, false, 4),
  ('946826da-0218-5ffd-ba87-6041a8a2d42f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13J', 'Fire Control Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Fire Control Specialist employs automated computer based systems used in all U.S. Army echelons across multiple weapon systems and formations in order to facilitate the delivery and integration of joint fires in support of combat operations. The Fire Control Specialist integrates and processes tactical battlefield information from multiple users and sensors through a network of Army and JOINT automated battle command systems. The Fire Control Specialist employs automated systems in order to process technical firing solutions, apply gunnery fundamentals critical to the 5 Requirements for Accurate Fires, process precision tactical fire missions, control tactical fires, conduct Joint sensor management, integrate fire support coordination measures, integrate maneuver control measures, manage and process meteorological data and troubleshoot technical firing solutions. The Fire Control Specialist performs operator and unit level maintenance on all automated tools and section equipment.', '03cc0c9564a09fcb0dfdddd4cc530a866fbfff7c176ccedd6103ceabf35cd6cf', 54, 54, null, 108, null, null, false, null),
  ('48c97e9c-c195-5ea6-8fe1-6e29be75bc7d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13J', 'Fire Control Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as a member of a Fire Control/Fire Support section across multiple weapon systems and formations. Major duties include primary tactical data system operations, basic communications, data base management, fire mission processing, gunnery fundamentals critical to the 5 Requirements for Accurate Fires, meteorological data processing, establish and maintain fire support coordination measures, establish and maintain maneuver coordination measures, perform operator and unit level maintenance on primary automation tools and section equipment.', 'c2279827e2f912af43063118cd20f68bd62b89b0f5989e1b789f1df52968001a', 54, 54, null, 109, null, null, false, 1),
  ('b1925075-8f7e-5c49-bfa5-09ac542214eb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13J', 'Fire Control Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves within a Fire Control/Fire Support section across multiple weapon systems and formations. Major duties include executing automated precision fires in support of combat operations, tactical data system operations oversight, troubleshoot technical firing solutions, meteorological data management, integration and management of tactical data, and Joint sensor management. A Fire Control SGT assists in training management, section maintenance, mission execution, personnel development, personnel management and supervision of section.', 'dac6ccad7eb79592e879738ecbff075f9e292a15418fb22425d044f83caba7cd', 54, 54, null, 110, null, null, false, 2),
  ('218a6220-88ba-5189-bcda-4442d4cfc1ab', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13J', 'Fire Control Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves within a Fire Control/Fire Support section across multiple weapon systems and formations. Major duties include execution and management of automated fires in support of Combat Operations, troubleshooting technical gunnery solutions on primary and secondary equipment, applying gunnery fundamentals critical to the 5 Requirements for Accurate Fires, tactical data system operations, battlefield information management, Joint sensor management and met operations, integrating fire support coordination measures, integrating maneuver control measures and conducting. Performs technical fire control rehearsals at Battery level and supervises fire control operations and rehearsals at lower unit levels. A Fire Control NCO is responsible for training management, section supervision, mission execution, maintenance of section equipment, meteorological data management, personnel development and personnel management.', '996ef1b4cd23661ea23063b963ddcd395a11a6d86a963fced22125707594a53d', 54, 54, null, 111, null, null, false, 3),
  ('714405d3-fd4f-5ca4-b078-9af0a612a5d1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13J', 'Fire Control Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves in all Field Artillery HQs formations from a Battalion through CORPS. Major duties include fire control management, software database management, fire support execution, tactical information management, integrating fire plans, integrating fire support coordination measures, air space coordinating measures and maneuver control measures, trouble shooting, gunnery fundamentals critical to the 5 Requirements for Accurate Fires, manages met operations, conducts joint sensor management. Performs technical fire control rehearsals from Battalion through CORPS and supervises fire control operations and rehearsals at lower unit levels. Manages, prepares and conducts individual and collective training and assists in unit certification training. Develops meteorology plans to support combat operations. Is responsible for crew and organizational maintenance of vehicles and equipment.', '05c87b9e1ef8cd70ba51ea82ff6332f264d28c28bb3959dc9bc3788cf0b59915', 54, 54, null, 112, null, null, false, 4),
  ('5d062384-2fb8-5607-bbfc-7133b438dda8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13M', 'Multiple Launch Rocket System (MLRS)/High Mobility Artillery Rocket System (HIMARS) Crewmember (MLRS/HIMARS)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The MLRS/HIMARS crewmember supervises or serves as a member of a launcher crew or section.', '56e5aad8b34914073e86392901c2ce2ae5469faa7d6f651eb337c7256f83515c', 56, 56, null, 113, null, null, false, null),
  ('b67073e9-9fd6-51d6-8ea3-6ef09f4c1b24', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13M', 'Multiple Launch Rocket System (MLRS)/High Mobility Artillery Rocket System (HIMARS) Crewmember (MLRS/HIMARS)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Drive the M270, M270A1 (MLRS) or the M142 (HIMARS) Self- Propelled Loader Launcher (SPLL) and the ammunition resupply vehicle and trailer. Perform operator/crew maintenance on the SPLL and ammunition resupply vehicle and trailer. Perform operator/crew maintenance on the SPLL and ammunition resupply vehicle. Perform ammunition reload operations on the launcher and resupply vehicle. Tests, removes, and replaces fire control system components as needed on the M270, M270A1 or HIMARS launcher and the launch pod/container trainer. Mounts radio sets in vehicles, cables communication components in M270, M270A1 or M142 launcher, and operates and performs operator maintenance on communications equipment. Replace or repair track on an M270, and M270A1 as necessary. Change a flat tire (301 LBS) on an M142.', 'dda99b9cdca1f9d5fecbc7bc296ce01c26f5080147ee88ef1f5c82684a953a03', 56, 56, null, 114, null, null, false, 1),
  ('69b4f746-fb5a-50c9-a7e0-45ab097e2d1c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13M', 'Multiple Launch Rocket System (MLRS)/High Mobility Artillery Rocket System (HIMARS) Crewmember (MLRS/HIMARS)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists section chief in supervision of operations, maintenance, and training. Leads and instructs the reconnaissance team in combat operations. Assist the ammunition section chief in supervision of the section during ammunition resupply operations, maintenance, and training. Performs start-up of fire control system, and operates MLRS/HIMARS fire control system in all modes of operation. Makes manual fire control entries and enters meteorological data into the fire control system. Fires weapon on command. Perform fire control system diagnostic test using built-in test equipment. Prepare launcher-loader module for reload and performs maintenance operations. Conduct reconnaissance to determine routes and precise firing location sites.', '9f8a579e7d53c7812f80b7ce900ffb5b01345d57837fc8e27b05dd2192190e2b', 56, 56, null, 115, null, null, false, 2),
  ('5587ef38-7f69-5af8-9a15-e2f7633af275', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13M', 'Multiple Launch Rocket System (MLRS)/High Mobility Artillery Rocket System (HIMARS) Crewmember (MLRS/HIMARS)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads and trains firing section or ammunition section. Supervise crewmembers during fire mission processing and ammunition reload operations. Supervise the performance of operator, crew, and organizational maintenance on section vehicles. Plan movement routes to and from firing areas and selects sites for launcher emplacement. Checks site to crest mask at firing positions. Coordinate requirements for organizational maintenance. Enforce OPSEC procedures and adherence to safety procedures involving launcher firing.', 'd0e4c50fa2c6203dec2342651de6b75a76c89ddd1105f2e14a5da26edcc010b0', 56, 56, null, 116, null, null, false, 3),
  ('e9b4e575-c378-5d20-97a3-553bbf41d1d1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13M', 'Multiple Launch Rocket System (MLRS)/High Mobility Artillery Rocket System (HIMARS) Crewmember (MLRS/HIMARS)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists platoon leader in the planning, preparation, and execution of collective training activities of the platoon. Conduct reconnaissance of platoon positions, reload points, and platoon area survey points. Supervise operator and organizational maintenance of equipment, vehicles, weapons, and communication and speech secure equipment. Lead in the operation of the PLDMD. Supervise the emplacement and march-order of platoon elements. Supervises and directs convoy movement of ammunition resupply vehicles. Responsible for the receipt, accountability, distribution, and storage of ammunition. Develops and maintains external and internal SOPs. Organizes platoon defense. Present briefings on current platoon operations and situation. Supervises platoon headquarters personnel including assignment of duties. Assume duties of platoon leader in his absence. Maintains and processes operations and intelligence information to include situation maps. Plans and selects reload points, launch areas, and ammunition cache sites. Monitors platoon fire missions, launcher status, and logistic requirements. Coordinates positioning of platoon elements with maneuver and support elements. Conducts reconnaissance and selects routes between the Ammunition Transfer Point and Ammunition Supply Point. Coordinate with ammunition officer for location of transfer points, amount, and mix of ammunition. Supervise the preparation and distribution of maps, operational information, and status reports.', '11ac103d6344c7f0bdb102ab03609785956a5cc9a3a71ca89427b2ca96aff7b6', 56, 56, null, 117, null, null, false, 4),
  ('4c5f8ebe-4aae-5200-a6fb-d3679fb8620c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13R', 'Field Artillery (FA) Weapons Locating Radar (WLR) Specialist (FA WLR Spc)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The WLR specialist supports unified land operations (offensive, defensive, stability, and defense support of civil authorities) thru the tactical employment of Field Artillery heavy and light WLR within the Target Acquisition Platoon (TAP) in support of Field Artillery Brigades, DIVARTY, and Brigade Combat Teams (BCT). The WLR specialist’s primary mission is to track surface to surface munitions, report the point of origin (POO), and determine a prediction of the point of impact (POI) in support of counterfire operations and the identification of land based hostile indirect fire weapons. The WLR specialist’s secondary mission is to provide calibration and registration support to friendly indirect fire systems. The WLR specialist is critical in protecting friendly forces from surface to surface indirect fire attacks by providing early warning and distributing timely and accurate target information thru intelligence operations as a member of the Counterfire Cell and Target Processing Sections.', '7ea982df299c8bf2ac3e36a79845748a9f75516d164a42c2cac921476ce3c7ce', 58, 58, null, 118, null, null, false, null),
  ('0dea3253-1700-5694-becc-70626968262c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13R', 'Field Artillery (FA) Weapons Locating Radar (WLR) Specialist (FA WLR Spc)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs critical duties associated with the identification of hostile weapons locations in support of counter fire operations, and precision fire weapon registrations. Establishes and maintains radio communications; prepares for operation operates and maintains WLR and associated equipment. Construct fortifications, bunkers, and crew-served weapons emplacements. Operates and performs operator maintenance on prime movers, radar system, and associated equipment.', '19d215dc6edff631139f3ac493aeaf0417d8d28775136160f42ac210d22ae950', 58, 58, null, 119, null, null, false, 1),
  ('a81dfde6-2689-5948-83cc-2c64ed3032dd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13R', 'Field Artillery (FA) Weapons Locating Radar (WLR) Specialist (FA WLR Spc)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads and supervises Radar Teams in combat operations. Supervises the preparation for operations; operates and maintains WLR. Assists section chief in the management of section personnel and equipment. Provides technical guidance and instruction on common and critical tasks to subordinate Soldiers. Assists in site improvement of the WLR systems. Supervises and advises scheduling of operational maintenance on radar and associated equipment. In the absence of the section chief, assumes the duties of the section chief.', '27ab499a24b1eeea3f3df6a04b54884a5adaca08477680b713b0c548d60d580d', 58, 58, null, 120, null, null, false, 2),
  ('86080a52-ed85-5119-b039-ccae13c857b4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13R', 'Field Artillery (FA) Weapons Locating Radar (WLR) Specialist (FA WLR Spc)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads and supervises the tactical employment of WLR Sections and associated equipment. Leads, trains, and supervises Soldiers in operations and maintenance of WLR and associated equipment. Provides leadership and training for integrated Target Acquisition (TA) operations. Instruct Soldiers in radar operations, tactics, techniques, and procedures. Conducts preliminary organizational maintainer duties of WLRs. Leads and manages upkeep on section associated equipment. Evaluates, processes, and reports target information to Brigade/DIVARTY. Recommends positioning of WLR assets, sectors of search, Common Sensory Boundaries (CSB), and radar zone positioning. Recommends cueing guidance to Brigade/DIVARTY counter-fire officer for WLR.', '27f42e3144687011e8d8eabef7f171834f71d387e302356c1b8685826b6b1882', 58, 58, null, 121, null, null, false, 3),
  ('12b70ec1-4886-5136-aaf2-d8287313c9c4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13R', 'Field Artillery (FA) Weapons Locating Radar (WLR) Specialist (FA WLR Spc)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads and supervises all aspects of WLR in a TAP. Conducts map and ground reconnaissance of general position areas for relocation of a WLR. Ensures radar visibility diagrams are constructed correctly for posting on battery capabilities chart. Conducts, coordinates, and evaluates platoon training. Supervises, coordinates, and conducts IPADS-G operations. Computes survey data, plots geographic/UTM grid coordinates and performs azimuth transfer with IPADS-G. Operates IPADS-G systems, collects, evaluates, and disseminates IPADS-G survey data. Assists in preparing the Survey Tab of the FA Support Plan. Responsible for assisting the S-3 in formulating and executing the IPADS-G survey plan to establish common survey control (Common Gird) throughout the units Area of Operation (AO). Advises the commander, S-3, FSO, and staff on all matters pertaining to IPADS-G Survey requirements, techniques, capabilities, and problem areas. Leads, supervises, and trains the targeting element in a Tactical Operations Center (TOC) in conjunction with the Fire Support Element (FSE). Collects and disseminates intelligence information and applies these products to the tactical employment of TA assets and counterfire operations. Assist in monitoring TA assets operations, status, and current and proposed locations. Recommends TA coverage to include command and control relationships of organic and attached TA assets. Provides input to associated S- 2/Counter-Fire Officer (CFO) for consolidation into the TA Tab of the Field Artillery support plan positioning of TA assets, sector of search, CSB, and radar zone positioning and frequency management input for WLR assets. Prepare Radar Deployment Orders (RDO) as required. Assist in maintaining the artillery Order-of-Battle (OB) Data Base and target file. Recommend cueing guidance to the Targeting Officer/CFO for all TA assets. Assist in preparing the TA Tab of the FA Support Plan. Coordinates logistic requirements and prepares reports summarizing data obtained from radar sections on troop strengths, logistics, surveillance techniques, and tactical operations.', 'cc5984db2988b520f9c011c58a29c1eb906dd3f6d10a9995647ad466596a3f35', 58, 59, null, 122, null, null, false, 4),
  ('0402420d-0968-582b-8958-7a44fea53cb9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13Z', 'Field Artillery Senior Sergeant (FA Sr Sgt)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Field Artillery Senior Sergeant duties include Command Sergeant Major (CSM), Operations Sergeant Major (SGM), First Sergeant (1SG), Detachment Sergeant and Operations Sergeant. The Field Artillery Senior Sergeant is assigned and performs duties in Theater, Corps, Divisions, Brigade Combat Teams, Fires Brigades, Battlefield Coordination Detachments, Batteries and Companies. They assist commanders and/or their staff officers in the coordination of advanced battle command systems that support the integration of Army indirect fires, fire support operations, joint operations and target acquisition.', 'b9c9c97ebb69c016dbc76b8b09f4d370546fc59807726bb49dd56bafca151534', 60, 60, null, 123, null, null, false, null),
  ('9c05dc14-cf9b-525d-9653-432c41de2fed', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13Z', 'Field Artillery Senior Sergeant (FA Sr Sgt)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', '(a) Command Sergeant Major 7C (O6 level CDR) or 6C (O5 level CDR)): Serves as the principal advisor to the commander on all enlisted issues at the Brigade level or below. The CSM is primarily focused on training, maintaining, caring and leading of the unit’s Soldiers, facilities and equipment. Assists the Commander in the implementation of command policies, Establishes and enforces standards related to the appearance and conduct of all Soldiers within the command. Develops and executes noncommissioned officer (NCO) professional development programs within the command and advises, counsels Soldiers on issues related to training, education and professional development. The CSM is primarily responsible for the unit’s individual soldier training programs.
(b) Sergeant Major 7S (O6 level Officer) or 6S (O5 level Staff Officer)): Serves as the principal Field Artillery enlisted advisor within Army, Corps, Division, Brigade, Battalion and Battlefield Coordination Detachment staffs on operational, fire support and target acquisition issues. Provides technical and tactical expertise in the use of advanced battle command systems to leaders and subordinates in the accomplishment of their duties. Plans, edits and prepares tactical plans and courses of action for the commander. Selects position locations for the tactical operations center and provides defensive position planning for its security. Monitors the professional development for all enlisted Soldiers under their direct supervision. Assumes the duties of the CSM in their absence.', 'bf89a9af276f472e44054cb4c287764136e9ba92f032e7a62808419ba731c42e', 60, 60, null, 124, null, null, false, 6),
  ('6a5212f5-cbd9-5fba-98f1-dd772917e794', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '13Z', 'Field Artillery Senior Sergeant (FA Sr Sgt)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', '(a) First Sergeant: Serves as the principal advisor to the commander on all enlisted issues at the Battery and Detachment level. The 1SG is primarily focused on training, maintaining, caring and leading of the unit’s Soldiers, facilities and equipment. Assists the Commander in the implementation of command policies, establishes and enforces standards related to the appearance and conduct of all Soldiers within the command. Develops and executes noncommissioned officer (NCO) professional development programs within the command and advises and counsels Soldiers on issues related to training, education and professional development. The 1SG is primarily responsible for the unit’s individual soldier training programs in the areas of combat readiness and physical fitness. The 1SG also performs duties as the unit defensive planner and chief logistician.
(b) Operations Sergeant: Serves as the principal Field Artillery enlisted advisor within Army, Corps, Division, Brigade, Battalion and Battlefield Coordination Detachment staffs on operational, fire support and target acquisition issues. Provides technical and tactical expertise in the use of advanced battle command systems to leaders and subordinates in the accomplishment of their duties. Plans, edits and prepares tactical plans and courses of action for the commander. Selects position locations for the tactical operations center and provides defensive position planning for its security. Supervises the professional development for all enlisted Soldiers under their direct control. Assumes the duties of the 1SG in their absence.', '3ba8e63257848b2fa6ebed3d47ea64247c708014fe8e23bdf80e3ab86c803567', 60, 60, null, 125, null, null, false, 5),
  ('8a3407e1-bdd9-5730-b453-4e5a8a3fbe01', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14E', 'Patriot Fire Control Enhanced Operator/Maintainer (PATRIOT Fire Ctrl Enh Opr/Maint)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Patriot fire control enhanced operator/maintainer supervises or serves in an air defense unit or as a member of an air defense activity engaged in operations or intelligence functions of liaison units. Responsible for system emplacement, initialization, and operator/organizational level system maintenance and services, (limited to the ability to detect improper equipment operation or malfunction by use of the senses, embedded diagnostic aids; e.g., BIT/BITE and/or on-board test equipment, Test Measurement and Diagnostic Equipment (TMDE) (e.g., multimeter to perform low voltage and continuity checks), technical references, technical inspections, adjustments, removal and replacement of battery replaceable units/line- replaceable units (BRUs/LRUs), and other tasks authorized in the maintenance allocation chart (MAC), and preventive maintenance checks and services (PMCS) required to sustain or return the Patriot Fire Control Section (FCS), Fire Direction Section (FDS), and associated equipment to its operational readiness condition. Perform Battle Damage Assessment Repair (BDAR), near- real time status reporting, report generation, and system deployment. Evaluates target data and identifies and engages targets.', 'ee5e407daec72878806ee035b45ea733f932f34dfe632537551342e06ef2fb7e', 62, 62, null, 126, null, null, false, null),
  ('8e249cc7-ad55-5d88-8d8b-ad53d8a6a790', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14E', 'Patriot Fire Control Enhanced Operator/Maintainer (PATRIOT Fire Ctrl Enh Opr/Maint)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs march orders and emplacement of the FCS, FDS, and associated equipment. Initialize and operates the Information and Coordination Central (ICC), Engagement Control Station (ECS), radar set, Identification Friend or Foe (IFF) Interrogator, Antenna Mast Group (AMG), and remotely located Communications Relay Group (CRG). Perform organizational level system maintenance and PMCS on FCS and FDS equipment. Evaluates target data and identifies and engages targets. Performs operation and intelligence duties, operates/performs PMCS on Patriot system prime movers and power units, establishes, and maintains radio and wire communications.', '43b3281678c5dc59134db11eeb1b3086b333ffe5b49dc806476121623923be87', 62, 62, null, 127, null, null, false, 1),
  ('78692451-3e26-5b78-8dc1-6ebdff43b641', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14E', 'Patriot Fire Control Enhanced Operator/Maintainer (PATRIOT Fire Ctrl Enh Opr/Maint)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level and provides technical guidance to lower grade personnel. Supervises and performs organizational level system maintenance and PMCS on FCS and FDS equipment. Supervises march order and emplacement of FCS, FDS and associated equipment.', 'eadad1ed13f2675d3054aa7333c6f6645c9ce1cc99e1001d15450fe9ff39f42d', 62, 62, null, 128, null, null, true, 2),
  ('52a3c4ae-cd4c-5115-a7cd-f0b11585909c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14E', 'Patriot Fire Control Enhanced Operator/Maintainer (PATRIOT Fire Ctrl Enh Opr/Maint)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level and supervises the operations and organizational level system maintenance and PMCS on FCS and FDS equipment. Enforce safety procedures and standards. Supervise the operation tactical communications. Supervises and participates in unit level training and training management. Performs operations and intelligence duties and serves as unit liaison.', 'b234aa966393be235eee732f4fda3e4856d6656130328bdb46ef422e34075ca2', 62, 62, null, 129, null, null, true, 3),
  ('f50c1ed7-03eb-5881-b975-46774571fc4c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14E', 'Patriot Fire Control Enhanced Operator/Maintainer (PATRIOT Fire Ctrl Enh Opr/Maint)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level and monitors the operations and operator maintenance of the FCS and FDS platoons. Provide technical training and guidance to subordinate personnel. Assist in supervising operations and intelligence functions.', '4282c299f05ff40569df03f6309849b32d95913096a97fa6af8eace9d4402ced', 62, 62, null, 130, null, null, true, 4),
  ('56cc73c5-d8bf-5df9-9f60-b420eb6f986b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14G', 'Air Defense (AD) Battle Management System Operator', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Battle Management System Operator supervises or serves in an Army Air and Missile Defense Command (AAMDC), Air Defense Brigade, Maneuver Battalion, Air Defense Airspace Management (ADAM) cell in conjunction with a Brigade Aviation Element (BAE) as an Air/Ground integrator/manager responsible for planning, coordinating, and establishing connectivity with Joint, Interagency, Intergovernmental, and Multinational (JIIM) sensors and command, control, communications, computers, and intelligence (C4I)/controller networks and airspace users; provides Situational Awareness (SA) of airspace and early warning; conducts current and future operations planning and execution of airspace management requirements for the supported echelon; and conducts Air and Missile Defense (AMD) and Aviation planning and coordination to determine AMD and Aviation requirements across the full spectrum of operations. Responsible for ADAM Cell equipment march order, emplacement, initialization and operator/organizational level system maintenance (limited to the ability to detect improper equipment operation or malfunction by use of the senses, embedded diagnostic aids; e.g. BIT/BITE and/or on-board test equipment, Test Measurement and Diagnostic Equipment (TMDE) (example, multimeter to perform low voltage and continuity checks), technical references, technical inspections, adjustments, removal and replacement of battery replaceable units/line replaceable units (BRUs/LRUs), and other tasks authorized in the maintenance allocation chart (MAC) and preventive maintenance checks and services (PMCS) required to sustain or return the ADAM Cell to its operational readiness condition.', '6780e61f955bfc6b601376eee792876d6b60066e3397c021dc1391849ab3fe0c', 64, 64, null, 131, null, null, false, null),
  ('c19d32ab-5184-5b0b-aa5d-a83fff002425', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14G', 'Air Defense (AD) Battle Management System Operator', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs march order, emplacement, initialization, operator/organizational level system maintenance and PMCS on the Sentinel Radar and ADAM Cell equipment including the Air and Missile Defense Warning System (AMDWS), the Air Defense Systems Integrator (ADSI), the Tactical Airspace Integration System (TAIS), and the Forward Area Air Defense System Engagement Operations (FAAD-EO) system as well as operating the Sentinel Radar. Evaluates tactical electronic intelligence data for force/engagement operations in JIIM networks. Performs operations and intelligence duties, monitors SA of the airspace and provides early warning, conducts planning and execution of airspace management requirements for the supported echelon, and operates/performs operator PMCS on vehicles/system prime power units. Performs data connectivity between AD communications equipment, Tri-Services Tactical Communications (TRITAC) network, Mobile Subscriber Equipment (MSE), and Link- 11/Link-16 with Army, Air Force, Navy, Marine Corps and Multi-National. Performs on-line/off-line Common Hardware-Software diagnostics and fault isolation programs. Emplaces, initializes, operates and march orders LAN, WAN, and remote video displays.', '617fc9eb6f62a6c37884e4d95e304595b822cb88b5654390648acdf0d733b52c', 64, 64, null, 132, null, null, false, 1),
  ('1414c7f6-79bd-55b2-8f9f-bc899c1000d9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14G', 'Air Defense (AD) Battle Management System Operator', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, serves as a Senior Early Warning System (EWS) operator in Air Defense Command and Control (C2) nodes or ADAM Cells at brigade level or higher. Supervises and provides technical guidance to subordinate Soldiers. May serve as a team leader in brigade level and above staff sections.', '7f79d85476dbdc7f396489a6bddf0b63fb34239047ca873dbeb2ad1123dd6fbc', 64, 64, null, 133, null, null, true, 2),
  ('1a8de7e3-4d77-5e6b-b837-318d02e727fc', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14G', 'Air Defense (AD) Battle Management System Operator', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels. Establishes, supervises and participates in unit level training for crew certification programs and Air Defense exercises. Performs operations and intelligence duties and may serve as air defense liaison noncommissioned officer (NCO). May serve as a section sergeant, assistant operations NCO or operations NCO in brigade level and above staff sections.', '7a1826b2771dba58ec77000524637ac43a94114be27393cf9e4dc162b108e7b0', 64, 64, null, 134, null, null, true, 3),
  ('5755db18-118b-51eb-b604-b0ba1f058ec5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14G', 'Air Defense (AD) Battle Management System Operator', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels. Provides technical guidance to subordinate Soldiers. Performs operations and intelligence duties at brigade and higher levels. May serve as an operations NCO, systems evaluator, or battle manager in brigade level and above staff sections. Directs, instructs and evaluates tactical operating procedures. Monitors unit equipment readiness and prepares monthly unit readiness reports (URR).', 'f5542202198fcba49515f043dbbbb58c75fbe1ad18fdb63c806f4d89d7670774', 64, 64, null, 135, null, null, true, 4),
  ('9fd4c18f-0a46-5e91-a330-22e01ae718d0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14H', 'Air Defense (AD) Enhanced Early Warning System Operator', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Enhanced Early Warning Operator supervises or serves in a Patriot air defense unit or as a member of an air defense activity engaged in operations or intelligence functions of liaison units. Responsible for air defense C4I system march order, emplacement, initialization and operator/organizational level system maintenance (limited to the ability to detect improper equipment operation or malfunction by use of the senses, embedded diagnostic aids; e.g. BIT/BITE and/or on-board test equipment, Test Measurement and Diagnostic Equipment (TMDE) (example, multimeter to perform low voltage and continuity checks), technical references, technical inspections, adjustments, removal and replacement of battery replaceable units/lines replaceable units (BRUs/LRUs), and other tasks authorized in the maintenance allocation chart (MAC) and preventive maintenance checks and services (PMCS) required to sustain or return the AD C4I system to its operational readiness condition.', 'f51ddb4c5115345dcd3adc5a686ab2a0bd26a56768c7cd52c77e7d36cb2c5ebe', 66, 66, null, 136, null, null, false, null),
  ('51dec884-5b48-52fa-b3b6-1cdfbefc738c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14H', 'Air Defense (AD) Enhanced Early Warning System Operator', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs march order, emplacement, initialization, and operator/organizational level system maintenance and PMCS on Air and Missile Defense Planning Control Systems (AMDPCS). Evaluate tactical electronic intelligence data for force/engagement operations in a joint service network. Perform operations and intelligence duties and operates/performs operator PMCS on vehicles/system prime power units. Perform data connectivity between air defense communications equipment, Tri- Services Tactical Communications (TRITAC) network, Mobile Subscriber Equipment (MSE), and Link- 11/16 with the Navy, Marine Corps, and Multi-National forces. Perform on-line/off-line Common Hardware-Software diagnostics and fault isolation programs. Emplace, initialize, operates and march orders LAN, WAN, JTAGS and remote video displays.', '4bc4d6e1f6a6113013e81dafd19c062ccadc21e9d3f9794d794ef08a97bc29b9', 66, 66, null, 137, null, null, false, 1),
  ('16431b16-42d9-594e-a7ac-635e078db6e5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14H', 'Air Defense (AD) Enhanced Early Warning System Operator', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels and serves as a crew chief in Air Defense Command and Control (C2) nodes or sensor section. Supervises soldiers and provides technical guidance to subordinate Soldiers. Perform data connectivity between Air Defense communications equipment, TRITAC, MSE and Link-11 with Army, Air Force, Navy, Marine Corps and Allied Nations. Perform online/offline Common Hardware-Software diagnostics and fault isolation programs. Emplaces, operates and maintains LAN, WAN and remote video displays. Responsible for the emplacement, operation and maintenance of JTAGS.', 'dc5435e0a3e3d3ffb66288386b4523400b6d18e7d54f3cc27eeadc82d74f6af1', 66, 66, null, 138, null, null, true, 2),
  ('945a7377-f354-5405-ad39-41c39cf4df20', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14H', 'Air Defense (AD) Enhanced Early Warning System Operator', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises the operation and organizational maintenance for AD C4I systems. Establishes, supervises and participates in unit level training for crew certification programs and Air Defense exercises. Performs intelligence duties and serves as unit liaison.', 'df49e173410531557dfd21c88561bf13d83779c152864bd2191033001d6ee601', 66, 66, null, 139, null, null, true, 3),
  ('91b583bd-4e07-5ed0-9904-98ec961fb29a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14H', 'Air Defense (AD) Enhanced Early Warning System Operator', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill levels. Supervise operations, and organizational maintenance for all AD C4I systems. Provide technical guidance to subordinate Soldiers. Perform operations and intelligence duties at battalion and higher level. Directs, instructs and evaluates tactical operating procedures. Monitors unit equipment readiness and prepares monthly unit readiness reports (URRs). Trains, evaluates, and certifies AD C4I systems personnel at the unit/battalion level. Assist in supervising maintenance records and maintaining supportive stockage procedures. Assist in designing and implementing the maintenance program.', '6aa4e49ff8d4684744380db2b2437dc0f0fc1af04f2569cbb75e0e6d56617234', 66, 66, null, 140, null, null, true, 4),
  ('7531a298-5b45-5619-8f8c-8f49c0813471', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14P', 'Air and Missile Defense (AMD) Crewmember', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The air and missile defense crewmember supervises, operates or serves as a member of a lightweight, highly mobile, air defense weapons systems.', '7a3c957fbd8f56428a0e15cff3a484862158018a938ed69ae19510857d101e5a', 68, 68, null, 141, '2025-10-01', null, false, null),
  ('7bb012de-bffe-57c5-bf19-e4aaeda5efeb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14P', 'Air and Missile Defense (AMD) Crewmember', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Prepares, operates and fires the Avenger weapon system and Man Portable Air Defense System (MANPADS) in degraded operations as required while assigned to the Avenger System. Establishes and maintains radio and wire communications. Assists in maintaining range card. Performs target engagement evaluation. Applies infrared (IR) techniques to detect and engage targets Resupplies ammunition and prepares systems for firing. Perform emergency procedures for weapon systems. Maintains sight alignment on systems. Operates and maintains system carriers.', '47aecfc02f98525489c4c8000901725340b7608c0f14b3625df6b933cdaade5b', 68, 68, null, 142, '2025-10-01', null, false, 1),
  ('e271ea88-b28e-5847-848e-f0833f4efdc4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14P', 'Air and Missile Defense (AMD) Crewmember', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises and assists the preparation and firing of the Avenger weapons systems. Collects and consolidates intelligence information. Processes special and periodic reports. Prepares and maintains range card. Designates fighting positions. Transmits alert status and readiness changes over secured network. Receives air early warning and tracks incoming targets over the Pony PCU.', '5466a5d7918a6fef22f09d08366795a98d115313e9b18956ecba14e73e8da21d', 68, 68, null, 143, '2025-10-01', null, true, 2),
  ('a0189c7a-9a67-53b8-aa76-6ff6e43b4244', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14P', 'Air and Missile Defense (AMD) Crewmember', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises the Avenger team/squad. Prepares for and supervises section movement. Supervises radio and wire communications. Plans for and supervises ammunition resupply. Deploys section to provide air defense coverage. Coordinates operations and intelligence data.. Supervise dissemination of air and ground early warning information to subordinate fire units over the Pony Portable Computer Unit (PCU). Assists update of Operation Order (OPORD), range cards and overlays. Employs weapon systems. Supervises Preventive Maintenance Checks and Services (PMCS).', '3e5d6329ec586a889c9e1cb69b550783d8a61723d052f4f925fe1df03e580897', 68, 68, null, 144, '2025-10-01', null, true, 3),
  ('78dab333-674d-59e1-b06a-280cb8bc795c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14P', 'Air and Missile Defense (AMD) Crewmember', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises Avenger platoon operations. Performs or supervises ADA operations and intelligence duties. Assists platoon leader in planning, management and training activities of subordinate sections. Conducts platoon reconnaissance, selection and occupation of position (RSOP). Coordinates platoon and section logistical activities.', 'f0f53dede30162a637c4acc8244278b3a747b6152fbb8c8753abfe64ae7b54c3', 68, 68, null, 145, '2025-10-01', null, true, 4),
  ('19699c14-c56d-5cee-bc71-043ea4e0520c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14T', 'Patriot Launching Station Enhanced Operator/Maintainer (Patriot LS Enh Opr/Maint)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Patriot launching station enhanced operator/maintainer supervises or serves in an air defense unit or as a member of an air defense activity engaged in operations or intelligence functions of liaison units. Responsible for system emplacement, initialization, operator/organizational level system maintenance (limited to the ability to detect improper equipment operation or malfunction by use of the senses, embedded diagnostic aids; e.g., BIT/BITE and/or board test equipment, Test Measurement and Diagnostic Equipment (TMDE) (example, multi-meter to perform low voltage and continuity checks), technical references, technical inspections, adjustments, removal and replacement of battery replaceable units/line replaceable units (BRUs/LRUs), and other tasks authorized in the maintenance allocation chart (MAC) and preventive maintenance checks and services (PMCS) required to sustain or return the Patriot Launching Station (LS), Enhanced Launcher Electronic System (ELES), Patriot guided missile round, and associated equipment to its operational readiness condition. Perform Battle Damage Assessment Repair (BDAR) and system deployment, and missile resupply/reload functions.', '7856a544de547c7bdce616111347d7ddd62a48f628c706a93de79ddaf6e7c03b', 70, 70, null, 146, null, null, false, null),
  ('ecad4dce-b64e-5e0d-99a0-142d24749e4e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14T', 'Patriot Launching Station Enhanced Operator/Maintainer (Patriot LS Enh Opr/Maint)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs march-order and emplacement of LS and associated equipment. Initializes, operates and performs organizational level system maintenance and PMCS on the LS, ELES, and associated equipment. Operates and performs Launching Test Set (LSTS) and Patriot Missile Round organizational level maintenance and PMCS. Perform missile resupply/reload functions. Perform operations and intelligence duties, operates and performs PMCS on Patriot Prime Movers and Prime Power Units. Establishes and maintains radio and wire communications.', '5a403d915ebc57e29f6392d5901d5451140f562bb96f0de269ba14479264a012', 70, 70, null, 147, null, null, false, 1),
  ('e01c1e41-37aa-5290-b1cf-57df987dc79e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14T', 'Patriot Launching Station Enhanced Operator/Maintainer (Patriot LS Enh Opr/Maint)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises and provides technical guidance to subordinate soldiers. Supervise organizational level maintenance and PMCS on LS, ELES, LSTS, and Patriot Missile Round.', '5671e529caf672943e38c44d21960f8a2187ceee58017d8e81a2e9c6c0daf515', 70, 70, null, 148, null, null, true, 2),
  ('9c36c5ee-99c6-5d27-8feb-068969532d5f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14T', 'Patriot Launching Station Enhanced Operator/Maintainer (Patriot LS Enh Opr/Maint)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill levels. Supervise the operations and organizational level system maintenance on the LS, ELES, LSTS, and Patriot Missile Round and associated equipment. Enforce safety procedures and standards. Supervise and participates in unit level training and training management. Performs operations and intelligence duties and serves as unit liaison. Supervise operations of tactical communications.', '15c99deb0cc9b4e7a24ff851924d12e77b8188c636a624bd1dacad628a6f78a1', 70, 70, null, 149, null, null, true, 3),
  ('e86a7012-7953-5981-a3a9-709deb3c8e15', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14T', 'Patriot Launching Station Enhanced Operator/Maintainer (Patriot LS Enh Opr/Maint)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels and monitors installation, operations and organizational level maintenance on the LS Platoon equipment. Provide technical training and guidance to subordinate personnel. Directs, instructs and evaluates tactical operating procedures. Supervise operations and intelligence functions. Trains, evaluates and certifies Patriot LS Crews in AD table training crew drills at unit/battalion level. Supervise operations and intelligence functions. Assists in supervising maintenance records and demand supported/diagnostics repair parts stockage procedures. Assist in designing and implementing the unit maintenance program.', '1d8615378c1634ae855275f6a9324f224ee62945a677e35538d709d71a4eae04', 70, 70, null, 150, null, null, true, 4),
  ('d26dc2ae-b040-5e6c-bee2-962f770f33f4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '14Z', 'Air Defense Artillery Senior Sergeant', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The ADA senior sergeant supervises, plans, coordinates, and directs the emplacement, operation, unit level maintenance and management of air defense artillery weapon systems in support of ADA units at all levels. Supervises and provides technical guidance to subordinate Soldiers in the accomplishment of their duties. Supervises training, evaluations and certification of AD crews in AD table training crew-drills. Monitors unit equipment readiness and prepares monthly readiness reports. Performs inspections on maintenance records and demand supported/diagnostics repair parts stockage procedures. Designs and implements the unit maintenance programs. Coordinates with maintenance and logistical support activities. Performs organizational planning, operations and training.', '413291a02c40341fb05994025d9c7186e1b2f7dfeb5205a124ce62c8d0488845', 72, 72, null, 151, null, null, false, null),
  ('93c03212-5a41-536d-a904-7adde7131914', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15B', 'Aircraft Powerplant Repairer (Acft Powerplant Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The aircraft powerplant repairer performs and/or supervises inspections, testing, cleaning, repairs, maintenance and storage according to drawings, blueprints, directives, technical manuals, and safety procedures of aircraft powerplant subsystems, assemblies, and components. Requisitions and maintains shop and bench stock for repair of aircraft powerplant equipment. Prepares aircraft related maintenance forms and records. Typically assigned to Aviation Field or Sustainment maintenance units.', 'd5b1487598a488c46b673533cb29a9f9989f49cc0fb622e2959a74ad15fd41c2', 73, 73, null, 152, null, null, false, null),
  ('c31e8208-7187-56ad-a1d6-d402c3b2f205', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15B', 'Aircraft Powerplant Repairer (Acft Powerplant Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Removes, replaces, services, prepares, preserves, cleans and stores engine assemblies or components. Disassembles, repairs, reassembles, adjusts, diagnostically test turbine engine systems, subsystems and components according to drawings, blueprints, directives, technical manuals. Assists in troubleshooting engines and rigging engine controls. Performs limited maintenance operational checks. Uses and performs operator maintenance on ground support equipment common and special tools. Maintains facilities for storage of flammable and hazardous materials. Requisitions and maintains shop and bench stock for repair of aircraft engines. Prepares requests for turn-ins and repair parts and engine components. Prepares forms and records related to MOS.', 'f75d5c84fe5f3669733aae2ec0e49b783aa347ca50b73bf79781a2b35bda585e', 73, 73, null, 153, null, null, false, 1),
  ('7f102b10-654e-52af-885a-f3bee9d40ab1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15B', 'Aircraft Powerplant Repairer (Acft Powerplant Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Diagnoses and troubleshoots malfunctions in aircraft engines and their components. Participates in maintenance test flights as required. Monitors hazardous material control and storage.', 'cb0c0e5ef4f9593dbd5b9bf216b488c30a6e6a6159881273e61cf7375fa6902e', 73, 73, null, 154, null, null, true, 2),
  ('2039928f-a6f0-5435-8875-eb2bbad404d4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15B', 'Aircraft Powerplant Repairer (Acft Powerplant Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2) and evaluates the technical training program. Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures, and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles, and procedures to aircraft engine maintenance and shop operations. Instructs personnel and conducts technical training in aircraft engine system maintenance, supply and safety techniques. Monitors requisition of parts, tools, and supplies.', '42a6658a56013a6b2e733c370f1b5eb01670b46c50c745d3510cd7ba3f156528', 73, 73, null, 155, null, null, true, 3),
  ('04ccfe9c-98da-503c-b99e-f343239a0071', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15C', 'MQ-1 Operator', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'A Soldier in MOS 15C engages in operating and remotely piloting of the UAS. Perform pre-flight, in-flight, post-flight checks and procedures. Conducts site selection, emplacement and deployment of the air vehicles and ground equipment of the UAS. Participates in launch/recovery ground crew operations. Performs mission commander duties to include planning, analyzing and execution of reconnaissance surveillance, targeting and acquisition (RSTA) missions. Applies and assists in the military intelligence collection process and acts as a liaison to supported units. Operates, troubleshoots and performs limited unit-level maintenance on communication equipment, power sources, light and heavy wheeled vehicles.', 'c3e83561fd13a3425b06b43d0e55dc4da0e01f6d1fbf2ed635473e78c7ff946e', 75, 75, null, 156, null, null, false, null),
  ('f7ee03f2-b77b-568d-bed5-c3482d0c7650', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15C', 'MQ-1 Operator', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Prepares and conducts air RSTA missions. Plans and analyzes flight missions. Deploys and redeploys the UAS ground and air system. Launches and recovers the air vehicle, performs pre-flight, in flight and post-flight checks and procedures. Uses and performs operator maintenance and crew procedures performed on UAS air and ground equipment. Prepares forms and records related to UAS air and ground support equipment maintenance. Participates in the UAS site setup. Assists in maintaining facilities for storage of flammable and hazardous materials.', '7310f14755ba7b60012c37db4c91548fe5e79f6826661b1f8226f8f936da85b0', 75, 75, null, 157, null, null, false, 1),
  ('bd58bc5d-5ab2-5c47-bd1a-fecfe7258b45', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15C', 'MQ-1 Operator', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2). Perform operational checks and scheduled inspections. Supervise site setup. Participates in mission planning using maps, terrain studies, and intelligence reports. Participates in and supervise operator maintenance and crew procedures performed on UAS air and ground equipment. Conducts flight and academic instruction in accordance with Aircrew Training Program (ATP). Monitor hazardous material control and storage.', '3e6dcc18586c44d8f914145db1dc5d4449fc7a1fc86460fb265c5cb1087645f1', 75, 75, null, 158, null, null, true, 2),
  ('dcbca5aa-f299-55c8-9ac8-e1b0e1f57c14', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15C', 'MQ-1 Operator', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1 and 2). Performs, supervises and provides technical guidance to subordinate personnel performing UAS operations, maintenance and crew procedures. Performs site selection and supervises site setup of UAS ground equipment using maps, aerial photographs, terrain studies, and intelligence reports. Assist in intelligence collection and dissemination. Coordinate methods of employment to higher and adjacent units. Creates and maintains a mission and operational data base. Conducts flight and academic instruction in accordance with Aircrew Training Program (ATP).', '52bfc5e4aed34e2efafbf911a5e2452dd04818ff286c6217bf870f4b134ca211', 75, 75, null, 159, null, null, true, 3),
  ('5e0623d5-8afd-5902-b4ba-ccb013b49f46', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15C', 'MQ-1 Operator', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels and provides guidance to subordinate Soldiers. Supervise operations and activities of the platoon. Applies the military intelligence collection process and surveillance planning to UAS operations. Conducts flight and academic instruction in accordance with Aircrew Training Program (ATP) for designated instructor positions.', 'd9106c6e7a36e8a0d4f287e4e442940eca593ed9f64214da2a7870e0a307a5b1', 75, 75, null, 160, null, null, true, 4),
  ('f89ba73a-fa50-5446-960f-95f7aa76cf71', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15D', 'Aircraft Powertrain Repairer (Acft Powertrain Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The aircraft powertrain repairer performs and/or supervises inspections, repairs and maintenance according to drawings, blueprints, directives, technical manuals, and safety procedures on aircraft powertrain systems to include the lubrication of required components and the removal and installation of aircraft subsystems such as main and tail rotor hub assemblies. Prepares aircraft related maintenance forms and records. Typically assigned to Aviation Field or Sustainment maintenance units.', 'b03a672adcb70e78456bf6ae629fd5ffde84f2090fffbd437839766449a90ecf', 77, 77, null, 161, null, null, false, null),
  ('39f77172-256a-5e30-b74b-7faa733dbd69', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15D', 'Aircraft Powertrain Repairer (Acft Powertrain Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Removes and replaces powertrain quills, transmissions adapting parts, rotary wing hub and tanks. Disassembles friction dampers and hanger assemblies. Disassembles, repairs, reassembles, adjusts, balances and aligns powertrain components, systems and subsystems to include main and tail rotor hub assemblies according to drawings, blueprints, directives, technical manuals. Applies corrosion preventative procedures. Cleans, preserves and stores powertrain components. Performs nondestructive inspections on aircraft components and related items. Uses and performs operator maintenance on ground support equipment, common and special tools. Maintains facilities for storage of flammable and hazardous materials. Requisitions and maintains shop and bench stock for repair of aircraft powertrain systems and subsystems. Prepares request for turn-ins and repair parts for powertrain components. Prepares forms and records related to aircraft maintenance.', '5c53c52f3ec6175d1c39dcc5807cf125626b27bfc11dc115fde2d34b3cdf5e3b', 77, 77, null, 162, null, null, false, 1),
  ('2aa02fe2-da69-5500-8971-945f3ac51c19', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15D', 'Aircraft Powertrain Repairer (Acft Powertrain Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Diagnoses and troubleshoots malfunctions in aircraft powertrain components and their subcomponents. Participates in maintenance test flights as required. Monitors hazardous material control and storage.', 'c9f4049c6fe1aceb17d446dee7a6d4e302e4f718170709da411f811c887d9633', 77, 77, null, 163, null, null, true, 2),
  ('33ff194d-5cce-56e4-a363-4f1fb83a1ab5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15D', 'Aircraft Powertrain Repairer (Acft Powertrain Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2) and evaluates the technical training program. Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures to aircraft powertrain system maintenance, nondestructive inspection and shop operations. Instructs personnel and conducts technical training in aircraft powertrain system maintenance, nondestructive inspection, supply and safety techniques. Monitors requisition of parts, tools, and supplies.', '4f6994341952ea401c447f4f560e9e70ab00a0a32c304efe2518fc4cec10bd29', 77, 77, null, 164, null, null, true, 3),
  ('80bcbc45-c2c8-57a7-8857-af22f5932634', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15E', 'Tactical Unmanned Aircraft System (TUAS) Repairer', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Tactical Unmanned Aircraft System (TUAS) Repairer performs, inspects, and supervises TUAS field and sustainment maintenance. Troubleshoots and repairs the aircraft electrical, avionics, communications, propulsion, fuel system, and takeoff and landing systems. Removes and replaces payload and weapons systems to include electrical and mechanical components. Troubleshoots and repairs the ground control and support equipment to include electronic and communication systems. Prepares TUAS related maintenance forms and records.', 'd82ba5187232321c0ab1a9c062abe6c42e077200dd55184ced5e0e5035cfc24e', 79, 79, null, 165, '2025-10-01', null, false, null),
  ('cb6112a3-d22e-50e5-8feb-186edc76834f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15E', 'Tactical Unmanned Aircraft System (TUAS) Repairer', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Troubleshoots and repairs TUAS electrical, avionics, communications, propulsion, fuel system, and takeoff and landing systems according to applicable manuals, directives, and safety procedures. Removes and installs tactical unmanned aircraft system subassemblies. Performs inspections and periodic maintenance on the aircraft, ground control equipment, associated ground support equipment, and takeoff and landing systems. Performs aircraft fueling/de-fueling and arming/de- arming operations. Serves as a crewmember performing launch and recovery operations. Performs alignments and calibrations on tactical unmanned aircraft systems. Maintains facilities for storage of flammable and hazardous materials. Requisitions and maintains shop and bench stock for repair of aircraft systems and equipment. Uses and performs operator maintenance on tools, special tools and aircraft ground support equipment. Prepares forms and records related to aircraft maintenance.', '4fc31f467f34567cc047b44e11a22b8661e6e0f5d98fb0fa030eec8dd2052dd7', 79, 79, null, 166, '2025-10-01', null, false, 1),
  ('059dc21e-a8fe-5ca8-87c8-6be5502d3a0f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15E', 'Tactical Unmanned Aircraft System (TUAS) Repairer', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph a.(1), supervises, and provides technical guidance to subordinate personnel while performing quality control duties. Monitors flammable and hazardous material control and storage. Schedules maintenance on test, measurement and diagnostic equipment (TMDE). Alters or modifies material according to approved modification work orders.', '66bcce416476caaf9c1c81d1df4804b427f652ee1cc783aabb6262c4d410da7b', 79, 79, null, 167, '2025-10-01', null, true, 2),
  ('9f5a73ae-cc6b-5829-ad6c-ffd5dd438a90', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15E', 'Tactical Unmanned Aircraft System (TUAS) Repairer', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs a(1) and a(2) and evaluates the aviation maintenance training program (AMTP). Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures, and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures. Computes weight and balance and ensures compliance with aircraft configuration control, Army Oil Analysis Program, and TMDE calibration. Instructs personnel and conducts technical training in TUAS electrical, avionic, communications, propulsion, fuel, payload and weapon systems repair procedures, and shop and flightline safety. Monitors requisition of parts, tools, and supplies.', 'e8a204f011c0b69c8061b66ba7bd60d4c27c830883323a0001e4b6891ff0e4f2', 79, 79, null, 168, '2025-10-01', null, true, 3),
  ('8cc36ac3-4d0f-51e4-9427-fc866768768b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15E', 'Tactical Unmanned Aircraft System (TUAS) Repairer', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Manages and provides technical guidance to subordinate personnel performing duties described in paragraphs a(1), a(2), and a(3) and manages and evaluates the AMTP. Manages TUAS maintenance and production control activities. Determines man-hours, personnel, parts, and facility requirements to repair TUAS and associated equipment. Coordinates maintenance areas, component repair, technical inspection techniques, and procedures according to directives, technical manuals, work standards, and operational policies. Manages supply economy and discipline. Manages the TUAS quality control training program. Prepares evaluations, special reports and records pertaining to TUAS maintenance and related activities.', '21a9a205b2b376d090e87d9edd9e2e8ab892572d292a1a6106504054f39bd0c1', 79, 79, null, 169, '2025-10-01', null, true, 4),
  ('c3a7ccc3-edae-5a85-b0f2-d335fb547233', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15E', 'Tactical Unmanned Aircraft System (TUAS) Repairer', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Tactical Unmanned Aircraft System (TUAS) Repairer performs, inspects, and supervises TUAS field and sustainment maintenance. Troubleshoots and repairs the aircraft electrical, avionics, communications, propulsion, fuel system, and takeoff and landing systems. Removes and replaces payload and weapons systems to include electrical and mechanical components. Troubleshoots and repairs the ground control and support equipment to include electronic and communication systems. Prepares TUAS related maintenance forms and records.', 'd82ba5187232321c0ab1a9c062abe6c42e077200dd55184ced5e0e5035cfc24e', 81, 81, null, 170, null, '2025-10-01', false, null),
  ('bc78c526-ee0c-5997-8e28-e6231a4ce209', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15E', 'Tactical Unmanned Aircraft System (TUAS) Repairer', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Troubleshoots and repairs TUAS electrical, avionics, communications, propulsion, fuel system, and takeoff and landing systems according to applicable manuals, directives, and safety procedures. Removes and installs tactical unmanned aircraft system subassemblies. Performs inspections and periodic maintenance on the aircraft, ground control equipment, associated ground support equipment, and takeoff and landing systems. Performs aircraft fueling/de-fueling and arming/de- arming operations. Serves as a crewmember performing launch and recovery operations. Performs alignments and calibrations on tactical unmanned aircraft systems. Maintains facilities for storage of flammable and hazardous materials. Requisitions and maintains shop and bench stock for repair of aircraft systems and equipment. Uses and performs operator maintenance on tools, special tools and aircraft ground support equipment. Prepares forms and records related to aircraft maintenance.', '4fc31f467f34567cc047b44e11a22b8661e6e0f5d98fb0fa030eec8dd2052dd7', 81, 81, null, 171, null, '2025-10-01', false, 1),
  ('4ed438a2-d3fe-5997-9891-c20a21560061', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15E', 'Tactical Unmanned Aircraft System (TUAS) Repairer', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph a.(1), supervises, and provides technical guidance to subordinate personnel while performing quality control duties. Monitors flammable and hazardous material control and storage. Schedules maintenance on test, measurement and diagnostic equipment (TMDE). Alters or modifies material according to approved modification work orders.', '66bcce416476caaf9c1c81d1df4804b427f652ee1cc783aabb6262c4d410da7b', 81, 81, null, 172, null, '2025-10-01', true, 2),
  ('2c218b31-2c63-5139-9655-5f92dedeb773', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15E', 'Tactical Unmanned Aircraft System (TUAS) Repairer', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs a(1) and a(2) and evaluates the aviation maintenance training program (AMTP). Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures, and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures. Computes weight and balance and ensures compliance with aircraft configuration control, Army Oil Analysis Program, and TMDE calibration. Instructs personnel and conducts technical training in TUAS electrical, avionic, communications, propulsion, fuel, payload and weapon systems repair procedures, and shop and flightline safety. Monitors requisition of parts, tools, and supplies.', 'e8a204f011c0b69c8061b66ba7bd60d4c27c830883323a0001e4b6891ff0e4f2', 81, 81, null, 173, null, '2025-10-01', true, 3),
  ('4c4fc011-ae21-553a-9a20-49800794ff46', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15E', 'Tactical Unmanned Aircraft System (TUAS) Repairer', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Manages and provides technical guidance to subordinate personnel performing duties described in paragraphs a(1), a(2), and a(3) and manages and evaluates the AMTP. Manages TUAS maintenance and production control activities. Determines man-hours, personnel, parts, and facility requirements to repair TUAS and associated equipment. Coordinates maintenance areas, component repair, technical inspection techniques, and procedures according to directives, technical manuals, work standards, and operational policies. Manages supply economy and discipline. Manages the TUAS quality control training program. Prepares evaluations, special reports and records pertaining to TUAS maintenance and related activities.', '21a9a205b2b376d090e87d9edd9e2e8ab892572d292a1a6106504054f39bd0c1', 81, 81, null, 174, null, '2025-10-01', true, 4),
  ('33b1b975-27bf-5def-a05a-05619959a381', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15F', 'Aircraft Electrician (Acft Elec)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The aircraft electrician performs and/or supervises inspections, repairs, maintenance and testing according to drawings, blueprints, directives, technical manuals, and safety procedures of aircraft electrical systems and electronic components to include associated subsystems by applying the principles of electricity/electronics, hydrostatic motion, pneumatics, and hydraulics. Prepares aircraft related maintenance forms and records. Typically assigned to Aviation Field or Sustainment maintenance units.', '3e8ecd43ea83c2134d2aa58b9088a9f30ee5de8fe499f98965022af82555ca64', 83, 83, null, 175, null, null, false, null),
  ('8e615665-a04a-5e33-b604-0433990dabb8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15F', 'Aircraft Electrician (Acft Elec)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Diagnoses and troubleshoots malfunctions in electrical and electronic components, including solid state and transistorized subsystems. Repairs aircraft instrument systems. Applies principles of electricity/electronics, hydrostatic motion, pneumatics and hydraulics applicable to repair aircraft instrument systems. Removes, installs, repairs, adjusts and tests electrical/electronic elements of assemblies and components according to technical manuals, directives and safety procedures. Clean, preserve and store electrical/electronic components and aircraft instruments. Removes, repairs, services, installs, and troubleshoots nickel-cadmium batteries. Uses and performs operator maintenance on ground support equipment, common and special tools. Maintains facilities for storage of flammable and hazardous materials. Requisitions and maintains shop and bench stock for repair of aircraft electrical systems and subsystems. Prepares request for turn-ins and repair parts for electrical components. Prepares forms and records related to aircraft maintenance.', '2a86dda87ee5c7993a008a5e5d7a1bd0c2e0da4d4b702ed06dbdb57cb7b62990', 83, 83, null, 176, null, null, false, 1),
  ('965426ce-58de-5cba-af35-fa18b04525d4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15F', 'Aircraft Electrician (Acft Elec)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Diagnoses and troubleshoots malfunctions in aircraft electrical components and their subcomponents. Participate in maintenance test flights as required. Monitors hazardous material control and storage.', 'aad9a053ef0bca7916be3b8cb804bec1eb2d25b29f3c6e64f9b67d2bf4555c9f', 83, 83, null, 177, null, null, true, 2),
  ('d4c2a402-7a04-5160-b8c4-524822ab381f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15F', 'Aircraft Electrician (Acft Elec)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2) and evaluates the technical training program. Evaluate maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures to aircraft electrical system maintenance, nondestructive inspections and shop operations. Instructs personnel and conducts technical training in aircraft electrical systems maintenance, nondestructive inspections, supply and safety techniques. Monitors requisition of parts, tools, and supplies.', 'b3dce45f75f096f47e97d6838fb589d308314cf0465d8808a27634190f3b51ed', 83, 83, null, 178, null, null, true, 3),
  ('4ccb81c4-d724-5243-9ff8-3f43b064cc30', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15G', 'Aircraft Structural Repairer (Acft Structural Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The aircraft structural repairer performs and/or supervises inspections, fabrication, repairs and maintenance on aircraft structures according to drawings, blueprints, directives, technical manuals, and safety procedures. Uses and performs operator maintenance on common and special tools. Requisitions and maintains shop and bench stock for repair of aircraft structures and maintain facilities for storage of flammable and hazardous materials. Prepares aircraft related maintenance forms and records. Typically assigned to Aviation Field or Sustainment maintenance units.', '8f99eb8316a6e3849b595325141396c3607568a92fb4de9e786d30ec04e29505', 85, 85, null, 179, null, null, false, null),
  ('a9cf5a3b-3036-540a-b60a-a795380c6347', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15G', 'Aircraft Structural Repairer (Acft Structural Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Repairs and replaces aircraft structural components to include stingers, longerons, bulkheads, beams and aircraft skin according to drawings, blueprints, directives, technical manuals and safety procedures. Fabricate structural parts, forming blocks, and shapes metal using stretching, shrinking, and other metal forming techniques. Mixes and applies fiberglass materials. Makes emergency and permanent repairs to transparent plastic windows and enclosures. Uses common measuring tools, precision measuring gages, and alignment fixtures to perform structural repairs. Balances fixed-wing aircraft controls such as flags and ailerons. Mixes and applies primers and paints to aircraft surfaces. Apply corrosion control treatment to aircraft metals. Maintains facilities for storage of flammable and hazardous materials. Requisitions and maintains shop and bench stock for repair of aircraft structures. Prepares forms and records related to aircraft maintenance.', 'b5e10470b5b9ebb21f24e038035c5a05e58da9c10e0945869f846591fe8041ec', 85, 85, null, 180, null, null, false, 1),
  ('bdfea98a-6738-543b-b378-a9ef85fa0fae', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15G', 'Aircraft Structural Repairer (Acft Structural Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Diagnoses airframe structural integrity IAW drawings, blueprints, directives, technical manuals and manufacturing engineers. Monitors hazardous material control and storage.', '66427abbc2bda951f5ad6bfc2e0288b93a1143d1e00828a683200c2d9897540e', 85, 85, null, 181, null, null, true, 2),
  ('ed49ce91-c103-544c-8bb0-111f30ae65ef', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15G', 'Aircraft Structural Repairer (Acft Structural Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2) and evaluates the technical training program. Evaluate maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures to aircraft electrical system maintenance, nondestructive inspections and shop operations. Instructs personnel and conducts technical training in aircraft structural repair, nondestructive inspections, supply and safety techniques. Monitors requisition of parts, tools, and supplies.', '6478e5c0d626135249a99eb220f9ea8c2f2d3714f52bd698e833a4cecd4b2469', 85, 85, null, 182, null, null, true, 3),
  ('41a551aa-db2f-5ca9-9ecc-4edadcb9c676', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15H', 'Aircraft Pneudraulics Repairer (Acft Pneudraulics Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The aircraft pneudraulics repairer performs and/or supervises inspections, fabrication, repairs and maintenance on aircraft pneudraulic subsystems, assemblies, and components according to drawings, blueprints, directives, technical manuals, and safety procedures. Uses and performs operator maintenance on common and special tools. Requisitions and maintains shop and bench stock for repair of aircraft structures and maintain facilities for storage of flammable and hazardous materials. Prepares aircraft related maintenance forms and records. Typically assigned to Aviation Field or Sustainment maintenance units.', '08ec1cf7a8251d544d4bad4d57979b14a9931b0ea6da5f96f649a1f67c6d2309', 87, 87, null, 183, null, null, false, null),
  ('f0303c4c-b212-5a76-b2e6-9316c1bd96dc', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15H', 'Aircraft Pneudraulics Repairer (Acft Pneudraulics Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Removes, repairs, replaces, adjusts and tests pneudraulic systems, subsystems, assemblies, and components according to drawings, blueprints, directives, technical manuals, and safety procedures. Fabricates tubes and hoses. Diagnoses and troubleshoots malfunctions to pneudraulic systems and subsystems or components. Maintain facilities for storage of flammable and hazardous materials. Requisitions and maintains shop and bench stock for repair of aircraft structures. Prepares forms and records related to aircraft maintenance.', '196a6a1e70d68ba7c53de2f3e404cf3e7683d9ceaa92646f1d24e8aebe420d5a', 87, 87, null, 184, null, null, false, 1),
  ('959c0209-ce14-5124-8fca-6ca124389be3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15H', 'Aircraft Pneudraulics Repairer (Acft Pneudraulics Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Monitors hazardous material control and storage.', '50430368a23b3c9cb0778dd07b7b2797e8495ebbe98f9960c2502446aa396915', 87, 87, null, 185, null, null, true, 2),
  ('528669ea-ffab-553f-a3d9-00cc02f29a8c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15H', 'Aircraft Pneudraulics Repairer (Acft Pneudraulics Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2) and evaluates the technical training program. Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures to aircraft pneudraulics maintenance, nondestructive inspections and shop operations. Instructs personnel and conducts technical training in aircraft pneudraulics repair, nondestructive inspections, supply and safety techniques. Monitors requisition of parts, tools, and supplies.', '7a3e89861431b36fb86ae7d6014bf925f106d58b719db40644407da40485e421', 87, 87, null, 186, null, null, true, 3),
  ('77066b4e-3869-53bd-a5e9-036d33835930', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15K', 'Aircraft Components Repair Supervisor (Acft Comp Repair Supv)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The aircraft component repair supervisor must be knowledgeable of the duties performed by personnel in MOSs 15B, 15D, 15G, and 15H. Performs administrative duties such as planning aircraft maintenance areas, component and avionics repair shops/facilities as well as determining man-hours, personnel management, parts and facility requirements while maintaining supply economy and discipline. Prepares evaluations, special reports, records and recommends and/or administers plans and policies pertaining to aircraft component repair. Instructs and supervises maintenance, repairs and inspections of aircraft components and other systems according to drawings, blueprints, directives, technical manuals, and safety procedures. Typically assigned to Aviation Field or Sustainment maintenance units.', 'bb8d4fe662b0d9290ff0d25b78d74419765411d199a42a054ca86583ac4e64a0', 89, 89, null, 187, null, null, false, null),
  ('193033ec-d26f-5c4e-bfa5-19a782d40c21', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15L', 'Armament/Electrical/Avionics Repair Supervisor (Arm/Elect/Avionics Rep Supv)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The aircraft component repair supervisor must be knowledgeable of the duties performed by personnel in MOSs 15F, 15N, and 15Y. Performs administrative duties such as planning aircraft maintenance, and avionics repair shops/facilities as well as determining man-hours, personnel management, parts and facility requirements while maintaining supply economy and discipline. Prepares evaluations, special reports, records and recommends and/or administers plans and policies pertaining to aircraft component repair. Instructs and supervises maintenance, repairs and inspections of aircraft armament, aviation communications and other electronic/electrical systems according to drawings, blueprints, directives, technical manuals, and safety procedures. Typically assigned to Aviation Field or Sustainment maintenance units.', '39636d00503a29296849baa33ea9c9ebab5a255ea3e9f7b3a2ebe1b89fbcca46', 90, 90, null, 188, null, null, false, null),
  ('e081f54d-8e0e-5f1c-9531-b4b208acd8bf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15M', 'MQ-1 Repairer', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Unmanned Aircraft Systems Repairer supervises, inspects and performs UAS field and sustainment maintenance. Repairs the aircraft electrical, avionics, radio frequency, propulsion, fuel, removes and replaces optical payload, and weapons systems to include the electrical, electronic, and mechanical systems associated with those systems; the Ground Control Station electrical and electronic systems; the Ground Data Terminal electrical, electronic, and radio frequency systems; takeoff and landing systems; and associated ground support equipment. Prepares UAS related maintenance forms and records.', '506d2b75f19e9091f3bdcf549be923cf3fd17406e9e6525e8c52d2fe1b960f33', 91, 91, null, 189, null, null, false, null),
  ('9f98d7a5-0e5b-538f-beef-5e59f10402a2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15M', 'MQ-1 Repairer', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Diagnoses, troubleshoots and repairs malfunctions in Unmanned Aircraft Systems electrical, avionics, radio frequency, propulsion, fuel, optical payload, and weapon systems components including solid state and transistorized subsystems according to pertinent technical manuals, directives and safety procedures. Remove and install unmanned aircraft system subassemblies. Performs inspections and periodic maintenance on the aircraft, ground control station, ground data terminal, takeoff and landing systems, and associated ground support equipment. Performs aircraft fueling/defueling operations. Serves as crewmember performing launch and recovery operations. Performs maintenance and authorized modifications on unmanned aircraft systems components. Repairs, replaces and performs operational and preventive checks and alignments on aircraft flight controls, stabilization systems, avionics and controlled cryptographic equipment. Troubleshoots equipment wiring harnesses, electrical components, and radio frequency paths using technical manuals and schematic drawings to diagnose, isolate faults, and effect repairs. Uses test sets and diagnostic equipment. Maintain records on all system equipment. Uses common and special tools. Maintains facilities for storage of flammable and hazardous materials. Prepares forms and records related to MOS.', '62a233c0daf3ac34402dace3441f833c0932062a5f511bff5a09bafb1ad007ff', 91, 91, null, 190, null, null, false, 1),
  ('a4b553ab-9a73-5357-a020-9dc984ad471a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15M', 'MQ-1 Repairer', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Serves as a crew chief for launch and recovery operations. Monitors hazardous material control and storage. Schedules maintenance on test, measurement and diagnostic equipment (TMDE). Alters or modifies material according to DA approved modification work orders.', 'aa005b63bb5f536662def77b834663638be01b305d9496f35764df12bb8227e5', 91, 91, null, 191, null, null, true, 2),
  ('34338b38-b07e-5f61-bb85-4323b3d64b1d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15M', 'MQ-1 Repairer', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2) and evaluates the technical training program. Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures. Computes basic weight and balance and ensures compliance with aircraft configuration control, Army Oil Analysis Program, and Test. Measurement, and Diagnostic Equipment calibration. Performs technical inspections. Instructs personnel and conducts technical training in unmanned aircraft systems electrical, avionic, radio frequency, propulsion, fuel, optical payload, and weapon systems repair procedures and shop and flight line safety. Monitors requisition of parts, tools and supplies.', 'b7738cd887d14a19b33d44913dfb51442f34bf8d7d94526f934f66e32bf1012e', 91, 91, null, 192, null, null, true, 3),
  ('4bbe2f64-fbda-560c-b757-7ec7ff17d52e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15M', 'MQ-1 Repairer', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises unmanned aircraft systems maintenance and technical inspection activities. Determines man-hours, personnel, parts and facility requirements to repair unmanned aircraft systems and associated equipment. Plans maintenance areas, component repair, technical inspection techniques, and procedures, according to directives, technical manuals, work standards, and operational policies. Maintains supply economy and discipline. Supervise the unmanned aircraft systems technical training program. Prepares evaluations, special reports, and records pertaining to unmanned aircraft systems maintenance and related activities. Recommends and administers plans and policies.', '09ccdb7a5519a1418c4efe6b56ff7aae32a4eab32f9485a2908d9c50b9abfd94', 91, 91, null, 193, null, null, false, 4),
  ('1a33f6d9-7c4c-561e-a68f-d6ea26dbf79b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15N', 'Avionic Mechanic', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The avionic mechanic conducts inspections and/or maintenance according to drawings, blueprints, directives, technical manuals, and safety procedures on aircraft flight controls, stabilization systems, avionics and controlled cryptographic equipment such as Identification friend or foe (IFF). Tests, troubleshoots, and repairs test sets and diagnostic equipment. Maintains facilities for storage of flammable and hazardous materials. Uses and performs operator maintenance on common and special tools. Requisitions and maintains shop and bench stock for repair of aircraft avionics equipment. Prepares aircraft related maintenance forms and records. Typically assigned to Aviation Field or Sustainment maintenance units.', '613f289ed4809e503f501dbd3427a39cf9294d788e3654e11bcc69d727061d8e', 93, 93, null, 194, null, null, false, null),
  ('0524023d-887a-5c87-b185-376c95d0208f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15N', 'Avionic Mechanic', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Repairs, replaces, and performs operational and preventive checks and alignments on aircraft flight controls, stabilization systems, avionics and controlled cryptographic equipment. Troubleshoots equipment and traces avionic and cryptographic equipment wiring harnesses using technical manuals and schematic drawings to diagnose and isolate faults and effect repairs. Performs unit maintenance on special and common hand tools and test, measurement, and diagnostic equipment. Requisitions and maintains shop and bench stock for repair of aircraft avionics equipment. Maintains facilities for storage of flammable and hazardous materials. Prepares forms and records related to aircraft maintenance.', '1cf0e7995267d96a6732f36742113da54fc467e0cedbe0a59d90be1905c0bccd', 93, 93, null, 195, null, null, false, 1),
  ('e0a5ab58-1500-5203-8e43-346792f7cfab', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15N', 'Avionic Mechanic', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Schedules maintenance on test measurement and diagnostic equipment (TMDE). Alters or modifies material according to DA approved modification work orders. Monitors hazardous material control and storage.', '8b317b33e4c42ad2c535094b51ae0f720a366762792a9629e69bf92a913c88b5', 93, 93, null, 196, null, null, true, 2),
  ('d33bf9c8-42ce-5a58-8ae3-d09a02933349', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15N', 'Avionic Mechanic', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2). Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures to armament, electrical and avionics maintenance, nondestructive inspections, and shop operations. Instructs personnel and conducts technical training in avionic, COMSEC, flight control and stabilization equipment maintenance, repair, nondestructive inspections, supply, and safety techniques. Evaluates the technical training program. Monitors requisition of parts, tools, and supplies.', 'b5592d34b3cb146f55724a2d99dd724406e4a4c2ba8a64eec65d9bc98649758a', 93, 93, null, 197, null, null, true, 3),
  ('caaf5be3-a491-5dd9-9298-2e339042967a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15P', 'Aviation Operations Specialist (Aviation Ops Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'A Soldier in MOS 15P supervises and/or conducts operation and maintenance of flight operations equipment. Performs duties such as conducting aircraft mission planning and maintaining individual aircrew flight records and assists in development of operation, warning, and fragmentary orders, prepares and updates appropriate maps, overlays, and charts, current DOD flight publications, encodes, decodes, and posts notices to airman (NOTAMS). Provides air traffic advisory services and interprets teletype weather reports.', 'b9595df1a6eca2a1425152f7d686ffc81374707385f306a072a6098b098722a1', 95, 95, null, 198, null, null, false, null),
  ('35ec3d1d-1abe-5798-b62e-facc061f6ec3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15P', 'Aviation Operations Specialist (Aviation Ops Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Processes cross-country and local flight clearances, including examination for conformance with flight rules and regulations. Prepares and maintains cross country kits. Checks accuracy of flight plans. Coordinates flight plans with all related agencies. Maintains flight information on inbound and outbound flights. Monitors, with the proper agencies, overdue flights. Alerts crash crew for emergencies. Maintains current file on aircraft flying regulations and navigation information such as Army, DoD and FAA regulations, DoD flight information publications (FLIPS) and aeronautical charts. Safeguards classified material. Knows terminology used in air navigation and is aware of air traffic control advisory radio procedures. Encodes, decodes and posts notices to airmen (NOTAMS). Interprets and posts teletype weather reports. Maintain individual flight records and functional files. Maintain flight operations equipment in a tactical environment. Prepare, submit operator meaconing, intrusion, jamming and interference reports. Participates in maintaining situation map.', '28219299c923a5a65548b830548f99fab3be1209365dbdecb3c5f751cf9b1d24', 95, 95, null, 199, null, null, false, 1),
  ('74fbca72-86bc-5a2a-9390-45fc4a93f076', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15P', 'Aviation Operations Specialist (Aviation Ops Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and instructs subordinates in proper work techniques and procedures. Reviews, consolidates and prepares technical reports. Knows procedures for reporting flight violations. Prepares situation map. Supervises receipt and transfer of classified material. Participates in the development of a tactical crash rescue system.', '171487dd533e9c294586ba62a5f0b70d173bdaf7e802a8fa209ff881a7356d07', 95, 95, null, 200, null, null, false, 2),
  ('50b0c8cc-3140-59c2-8ba8-30f3d1eb1e7b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15P', 'Aviation Operations Specialist (Aviation Ops Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2). Supervises the preparation of the situation map. Assists in preparation of operations estimates and orders. Supervises airfield services and administration. Applies operational and administrative techniques in movement of military personnel and supplies by air. Perform administrative duties in aircraft accident investigations. Prepares operations letters.', '72b6748d601975383d92c6dd7c6fb27940f2f63ebfb19f5d79ffe64d069b4f57', 95, 95, null, 201, null, null, true, 3),
  ('2d722e92-5fdb-5b42-ab71-f347e0e4c0df', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15P', 'Aviation Operations Specialist (Aviation Ops Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provides tactical and technical expertise to subordinates and superiors in aviation operations. Plans, coordinates and supervises activities pertaining to organization, training, combat operations and combat intelligence. Coordinates implementation of operations, training programs and communications activities. As an Aviation Operation Sergeant at Brigade Aviation Element (BAE) provide technical and doctrinal advice to the Chief of Operations (CHOPS). Receives and distributes relevant data from the Airspace Control Order (ACO) and Airspace Tasking Order (ATO). Ensures operation and maintenance requirements are met for section Air and Missile Defense Workstation (AMDWS, Forward Area Air Defense (FAAD), and Tactical Airspace Integration System (TAIS) equipment. As a platoon sergeant, coordinates the logistical, personnel and administrative support for all platoon elements.', 'b9e838c07dc005a69ebde70c85b0f735dd22f07194f5606bc7f889a8b5332516', 95, 95, null, 202, null, null, false, 4),
  ('caaddf00-d6a2-5d59-a16e-a3975418dab2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Q', 'Air Traffic Control (ATC) Operator', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'A Soldier in MOS 15Q supervises and/or conducts Air Traffic Services (ATS) following Federal Aviation Administration (FAA) and DoD policy procedures. Issues flight instructions and clearances via Visual Flight Rules (VFR), Instrument Flight Rules (IFR), and Special Visual Flight Rules (SVFR), Formulates data for Terminal Instrument Procedures (TERPS). Assists Air Control Authority (ACA) with the Army Airspace Command and Control (A2C2) system using Airspace Control Measures (ACM). Operates various facilities to include Air Traffic Control Towers (ATCT), Ground Controlled Approach (GCA) Radars, and Airspace Information Centers (AIC). Maintains United States Air Force certification as limited weather observer; compiles, controls information and conducts emergency notification and assistance in the event of aviation accidents or incidents.', '0c16ea11c2cdbcbbb9109d7d7b3b6d0320135ed8d31342117b072327045b2706', 97, 97, null, 203, null, null, false, null),
  ('0bbe8edb-6928-52ac-aaae-bcf0ad99ae60', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Q', 'Air Traffic Control (ATC) Operator', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates fixed and tactical ATC towers, Ground Control Approach GCA radars and airspace information centers (AICs). Operates and maintains vehicles, tactical/fixed base ATC equipment and navigational aids (NAVAIDs). Assist in the installation and relocation of tactical ATC facilities. Applies air traffic control rules, procedures and regulations. Processes flight plan data. Formulates and issues ATC clearances, advisories and control information. Maintains logs, records, files and recordings of voice communications. Interprets and relays Notices to Airmen (NOTAM) information. Reads and interprets DoD Flight Information Publications (FLIPS) and aeronautical charts. Analyzes air traffic to identify and resolve potential conflicts. Controls airborne and ground traffic on and in the vicinity of the airport. Updates Automated Terminal Information Service (ATIS) and performs radarscope alignments. Coordinates terminal/enroute control. Provides approach control services, conducts precision radar instrument approaches, provide (AIC) services and control tower services. As a qualified member of a tactical air control team (TACT), establishes and controls landing zones (LZs), helicopter landing zones (HLZs), drop zones (DZs) and pick-up zones (PZs).', '5dd06afa59948e49240a7bd58a6a18f3627d727572ab0464e182147033b2f44a', 97, 97, null, 204, null, null, false, 1),
  ('7aedb99e-7f02-50d2-af42-790a129e1b10', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Q', 'Air Traffic Control (ATC) Operator', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts ATC facility training. Briefs shift personnel on runway utilization, airfield conditions and weather/ground activities. Prepares and updates flight following maps. Supervises a shift in a tactical or fixed tower, radar, or AIC. Services as a tactical air control team (TACT) leader in a tactical terminal control system (TTCS), deploys team as advance party to remote areas to secure and set up forward area refueling and rearming points (FARPS), LZs, HLZs, DZs and PZs. Maintains current DoD and DOT/FAA publications, ATC facility logs, forms, records and situation maps. Prepares, briefs and disseminates Aviator’s Procedures Guide (APG) to supported aviation units. Assist in the preparation of TERPS.', '82b4df968b5e2a22d37d41f0f4d95a1b64cf6c21425ce4fd8922e6009a7e6d1e', 97, 97, null, 205, null, null, false, 2),
  ('c626b702-f87e-52a6-8ff2-6bb6bf293bfd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Q', 'Air Traffic Control (ATC) Operator', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2). Serves as facility chief at low-density towers, radar or airspace information centers. Serve as facility chief in tactical towers, GCA radars and AICs. Administer ATC facility. Formulates and coordinates letters of agreement, operations letters and facility memorandums. Prepares duty rosters and assigns duties to personnel. Ensures facility flight check requirements are met for navigational aids, radar and radio communications equipment. Plans and organizes ATC activities for tower, GCA radar, airspace information centers and verifies facility compliance with Army and FAA standards. Evaluates ATC operations and work performance. Reviews and prepares reports. Coordinate ATC activities with other facilities. Prepares and updates situation maps. Assists in the preparation of Standard Instrument Approach/Enroute/Departure Procedures (TERPS) for assigned facility/NAVAID.', 'e67638b1a540bd9e4a6915b25102dfcd76eb4f5176c7b0ad08e4b3644cacb387', 97, 97, null, 206, null, null, true, 3),
  ('d24fdd2c-5f75-52f3-9e79-d3f99495158c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Q', 'Air Traffic Control (ATC) Operator', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as facility chief in high density and designated remotely located fixed base towers, GCA radar, or AICs. Plans, organizes and supervises ATC facilities. Establishes and supervises the facility training and rating program. Advises in the preparation of TERPS. Ensure proper utilization and coordination of maintenance support. Prepares and interprets orders and reports. As an A2C2 liaison at division and echelons above corps (EAC) assists in the development and execution of the Airspace Control Order (ACO) and Airspace Tasking Order (ATO). Coordinates, deconflicts and integrates all airspace control measures for division, corps, or EAC commanders. As a platoon sergeant, coordinates the logistical, personnel and administrative support for all platoon elements and deploys platoon to remote locations in support of forward aviation assets. Prepares and coordinates TERPS data with the appropriate FAA Department of the Army regional representative. Conduct briefings for senior commanders on the current tactical airspace situation.', 'b8694e60cfbee1a279bcb5c77116e12e920c5cd46b2b39613f82d39153f95282', 97, 97, null, 207, null, null, false, 4),
  ('2d990e21-027c-577d-820a-d0e85d0a43c8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15R', 'AH-64 Attack Helicopter Repairer (AH-64 Attack Hel Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'A Soldier in MOS 15R performs and/or supervises inspections, maintenance and modifications according to drawings, blueprints, directives, technical manuals, and safety procedures on the AH-64A/D armament, electrical and avionics systems and cryptographic equipment to include the electrical, electronic, mechanical, and pneudraulics systems associated with AH-64A/D Armament/Missile Fire Control Systems. Tests, troubleshoots and repairs test sets and diagnostic equipment. Maintains records on weapons and subsystems. Uses and performs operator maintenance on common and special tools. Prepares aircraft related maintenance forms and records. Typically assigned to Aviation Field or Sustainment maintenance units.', 'fc74faeef756fea44ed181682b7473bd7641375106a3919e66ef767e49243de4', 100, 100, null, 208, null, null, false, null),
  ('7572ce2b-8e13-5011-b833-0a6a2a415577', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15R', 'AH-64 Attack Helicopter Repairer (AH-64 Attack Hel Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Removes and installs aircraft subsystem assemblies such as engines, rotors, gearboxes, transmissions, mechanical flight controls and their components. Services and lubricates aircraft and subsystems. Prepares aircraft for inspections and maintenance checks. Performs scheduled inspections and assists in performing special inspections. Performs limited maintenance operational checks and assists in diagnosing and troubleshooting aircraft subsystems using special tools and equipment as required. Maintains facilities for storage of flammable and hazardous materials. Requisitions and maintains shop and bench stock for repair of aircraft systems and equipment. Uses and performs operator maintenance on tools, special tools and aircraft ground support equipment. Prepares forms and records related to aircraft maintenance.', 'b4b196d253bef544319438eab0a767509d1ba654d79cffa7e77ca6848c11e84c', 100, 100, null, 209, null, null, false, 1),
  ('be9ac9cb-b876-59ef-8186-15aa9e9920ab', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15R', 'AH-64 Attack Helicopter Repairer (AH-64 Attack Hel Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Performs operational checks and scheduled inspections. Diagnoses and troubleshoots malfunctions in aircraft subsystems. Monitor hazardous material control and storage.', '4bc30c72b39a0aa1e169ab5724f62d277a32fd81741794b9a40c118fe33f8438', 100, 100, null, 210, null, null, true, 2),
  ('f431b693-c96d-5b0c-90be-751e772c9b3b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15R', 'AH-64 Attack Helicopter Repairer (AH-64 Attack Hel Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2) and evaluates the technical training program. Evaluate maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures to airplane maintenance operations. Plans, conducts and supervises aircraft technical inspections. Compute basic weight and balance records. Participate in maintenance test flights. Ensure compliance with aircraft configuration control, Army Oil Analysis Program and test measuring diagnostic calibration.', 'dec4a651219550401295edf6cb6c54a6e96b62e9716f06b9476af702dd499413', 100, 100, null, 211, null, null, true, 3),
  ('55efef1c-c189-528e-bf48-c120cfb1b191', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15R', 'AH-64 Attack Helicopter Repairer (AH-64 Attack Hel Rep)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises aircraft maintenance and technical inspection activities. Determine man-hours, personnel, parts and facility requirements to repair aircraft and associated equipment. Plans aircraft maintenance areas, component repair shops and facilities. Instructs subordinates in aircraft repair and technical inspection techniques and procedures according to directives, technical manuals, work standards and operational policies. Maintains supply economy and discipline. Supervises the technical training program. Prepares evaluations, special reports and records pertaining to aircraft maintenance repair and related activities. Recommends and administers plans and policies.', 'aea6b4b8609bac782c53265d790835b8db546230d252f983ae6ba1b9b7cafa71', 100, 100, null, 212, null, null, false, 4),
  ('88582a2e-53d7-52f6-8b6e-f975c8c573fd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15T', 'UH-60 Helicopter Repairer /Aircrew Member (UH-60 Hel Rep/ACM)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'A Soldier in MOS 15T performs and/or supervises inspections, repairs and maintenance according to drawings, blueprints, directives, technical manuals, and safety procedures (excluding repair of armament, avionics, electrical and cryptographic equipment/system components) Duties also include the lubrication of required components and the removal and installation of aircraft subsystems, using special tools and equipment as required. Prepares aircraft related maintenance forms and records. Soldiers may be required (if able) to perform non-rated crewmember duties involving frequent and regular participation in aerial flight as a Crew Chief on the aircraft that are essential to its operation and or specific flight mission. Typically assigned to Aviation Field or Sustainment maintenance units.', 'b4d9ec25d05bb35b0336050b91268f338de59648173fea6787b6881e3398381e', 102, 102, null, 213, null, null, false, null),
  ('6e5e0260-3321-5b7f-9220-728d212f57c3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15T', 'UH-60 Helicopter Repairer /Aircrew Member (UH-60 Hel Rep/ACM)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and installs aircraft subsystem assemblies such as engines, rotors, gearboxes, transmissions, mechanical flight controls and their components. Services and lubricates aircraft and subsystems. Prepare aircraft for inspections and maintenance checks. Performs scheduled inspections and assists in performing special inspections. Performs limited maintenance operational checks and assists in diagnosing and troubleshooting aircraft subsystems using special tools and equipment as required. Requisitions and maintains shop and bench stock for repair of aircraft systems and equipment. Maintains facilities for storage of flammable and hazardous materials. Uses and performs operator maintenance on tools, special tools and aircraft ground support equipment. Prepares forms and records related to aircraft maintenance. Performs non-rated crewmember duties.', '5b3398d9cd996062c7b214e77b0b07953ac420bc9ebb89329247c8ed19fd4104', 102, 102, null, 214, null, null, false, 1),
  ('ae3cbef3-6c33-53e0-81c5-b3e748c95e7d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15T', 'UH-60 Helicopter Repairer /Aircrew Member (UH-60 Hel Rep/ACM)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Performs operational checks and scheduled inspections. Diagnoses and troubleshoots malfunctions in aircraft subsystems. Conducts flight and academic instruction in accordance with Aircrew Training Program (ATP). Monitor hazardous material control and storage.', '0fb42f9ee41f6e742fad8cb2129a9b7b76d8da777321e74b25c8851711083d7f', 102, 102, null, 215, null, null, true, 2),
  ('d709185f-7db6-587b-8e70-c3a60815cfe2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15T', 'UH-60 Helicopter Repairer /Aircrew Member (UH-60 Hel Rep/ACM)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2) and evaluates the technical training program. Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures, and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures to airplane maintenance operations. Plans, conducts and supervises aircraft technical inspections. Computes basic weight and balance records. Participates in maintenance test flights. Ensure compliance with aircraft configuration control, Army Oil Analysis Program, and test measuring diagnostic calibration. Conducts flight and academic instruction in accordance with Aircrew Training Program (ATP).', '51843d3fa30f473758fba1320116d6ac3693ac7bd518d4a11609396db429bd29', 102, 102, null, 216, null, null, true, 3),
  ('4df78513-dd80-5a57-b5f3-9d6b66b7c193', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15T', 'UH-60 Helicopter Repairer /Aircrew Member (UH-60 Hel Rep/ACM)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises aircraft maintenance and technical inspection activities. Determines man hours, personnel, parts and facility requirements to repair aircraft and associated equipment. Plans aircraft maintenance areas, component repair, shops and facilities. Instructs subordinates in aircraft repair and technical inspection techniques and procedures according to directives, technical manuals, work standards, and operational policies. Maintains supply economy and discipline. Supervises the technical training program. Prepares evaluations, special reports, and records pertaining to aircraft maintenance repair and related activities. Recommends and administers plans and policies.', '454deb17ee4d88c6f609d47b2bc355e7af36576f5c4138d10a3ff8c99fca3a0c', 102, 102, null, 217, null, null, false, 4),
  ('4479ea0f-df24-5940-9b3f-2aebc55715ef', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15U', 'CH-47 Helicopter Repairer/Aircrew Member (CH-47 Hel Rep/ACM)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'A Soldier in MOS 15U performs and/or supervises inspections, repairs and maintenance according to drawings, blueprints, directives, technical manuals, and safety procedures (excluding repair of armament, avionic, electrical and cryptographic equipment/system components). Duties also include the lubrication of required components and the removal and installation of aircraft subsystems, using special tools and equipment as required. Prepares aircraft related maintenance forms and records. Soldiers may be required (if able) to perform non-rated crewmember duties involving frequent and regular participation in aerial flight as a Crew Chief on the aircraft that are essential to its operation and or specific flight mission. Typically assigned to Aviation Field or Sustainment maintenance units.', '7e4b848a1191ccc76d9d56e9b6fffa3204e3ef43d525d59c1b5e931394166b01', 104, 104, null, 218, null, null, false, null),
  ('41079165-ed68-54f9-a211-587333e5c231', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15U', 'CH-47 Helicopter Repairer/Aircrew Member (CH-47 Hel Rep/ACM)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Removes and installs aircraft subsystem assemblies such as engines, rotors, gearboxes, transmissions, mechanical flight control, and their components. Services and lubricates aircraft and subsystems. Prepares aircraft for inspections and maintenance checks. Performs scheduled inspections and assists in performing special inspections. Performs limited maintenance operational checks and assists in diagnosing and troubleshooting aircraft subsystems using special tools and equipment as required. Maintains facilities for storage of flammable and hazardous materials. Uses and performs operator maintenance on tools, special tools and aircraft ground support equipment. Prepares forms and records related to aircraft maintenance. Performs non-rated crewmember duties.', '9d2865a1cb5b269e8f7cc4484207e6e7da354f4e5322f700417651bd117ab7d4', 104, 104, null, 219, null, null, false, 1),
  ('77a1b097-b78c-54bd-9253-daa669f773fe', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15U', 'CH-47 Helicopter Repairer/Aircrew Member (CH-47 Hel Rep/ACM)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Performs operational checks and scheduled inspections. Diagnoses and troubleshoots malfunctions in aircraft subsystems. Conducts flight and academic instruction in accordance with the Aircrew Training Program (ATP). Monitors hazardous material control and storage.', '49ebaa5e236747f463306f0fd0756aa89a18bb67edf0da2b1a2075c16e1d0c66', 104, 104, null, 220, null, null, true, 2),
  ('5799c07f-6225-5f66-8594-da5d9a7a0eb0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15U', 'CH-47 Helicopter Repairer/Aircrew Member (CH-47 Hel Rep/ACM)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2) and evaluates the technical training program. Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures, and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures to aircraft maintenance operations. Plans, conducts, and supervises aircraft technical inspections. Computes basic weight and balance records. Participates in maintenance test flights. Ensures compliance with aircraft configuration control, Army Oil Analysis Program and test measuring diagnostic calibration. Conducts flight and academic instruction in accordance with the ATP.', '8d5485da16614aab2e808b1fc329895dd4c7823a34a829b184498268166dd4c7', 104, 104, null, 221, null, null, true, 3),
  ('64704839-2e20-5734-b929-bff2941cb126', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15U', 'CH-47 Helicopter Repairer/Aircrew Member (CH-47 Hel Rep/ACM)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises aircraft maintenance and technical inspection activities. Determines man-hours, personnel, parts and facility requirements to repair aircraft and associated equipment. Plans aircraft maintenance areas, component repair shops and facilities. Instructs subordinates in aircraft repair and technical inspection techniques and procedures according to directives, technical manuals, work standards and operational policies. Maintains supply economy and discipline. Supervises the technical training program. Prepares evaluations, special reports, and records pertaining to aircraft maintenance repair and related activities. Recommends and administers plans and policies. Conducts flight and academic instruction in accordance with the ATP.', '686274695359cc8d5a84ff553b3618e8e29bd7e5f92ae98db501aad886e9f6d0', 104, 104, null, 222, null, null, false, 4),
  ('28c5e4e3-c291-5d19-9d33-4fbd760e9e8f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15W', 'Tactical Unmanned Aircraft System (TUAS) Operator', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'A Soldier in MOS 15W engages in operating and remotely piloting the TUAS. Performs pre-flight, in-flight, and post-flight checks and procedures. Conducts site selection, emplacement, and deployment of the air vehicles and ground equipment of the TUAS. Participates in launch/recovery ground crew operations. Performs aircraft commander (AC) duties to include planning, analysis, and execution of reconnaissance and security missions in support of targeting and information collection. Operates, troubleshoots, and performs limited unit-level maintenance on communication equipment, power sources, and wheeled vehicles.', 'e99df3f32eefb125894045aa88e14f484d09dc945fdd887502af1089198b351a', 106, 106, null, 223, null, '2025-10-01', false, null),
  ('1c108c24-cf8c-51b3-9025-af91414ffefc', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15W', 'Tactical Unmanned Aircraft System (TUAS) Operator', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Executes reconnaissance and security missions. Plans and analyzes flight missions. Deploys and redeploys the TUAS ground and air system. Launches and recovers the air vehicle, performs pre-flight, in-flight, and post-flight checks and procedures. Performs operator maintenance and crew procedures on TUAS air and ground equipment. Prepares forms and records related to TUAS air and ground support equipment maintenance. Participates in the TUAS site setup and breakdown. Assists in proper handling and storage of flammable and hazardous materials.', '9cc2a5bb3bc11b57902f9d0b7526950af676a8a8b3994b7fd27d0f44c77c7f35', 106, 106, null, 224, null, '2025-10-01', false, 1),
  ('83b19997-29c2-5d8a-8a2a-ca5ed6f7601e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15W', 'Tactical Unmanned Aircraft System (TUAS) Operator', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs a.1 and a.2. Performs operational checks and scheduled inspections. Supervises and assists site setup and breakdown. Participates in mission planning including terrain, threat, and current situation analysis. Participates in and supervises operator maintenance and crew procedures performed on TUAS air and ground equipment. Serves as primary trainer of readiness level (RL) 1 operators as the AC. Monitors proper handling and storage of flammable and hazardous materials.', '06de1dc4810c8a9b119ca5a2d557215a59fa77591d6c5f7288929b845a2f7c22', 106, 106, null, 225, null, '2025-10-01', true, 2),
  ('760a3560-87de-58af-ba37-b7d11106bb2b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15W', 'Tactical Unmanned Aircraft System (TUAS) Operator', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph a.1 and a.2. Performs, supervises, and provides technical guidance to subordinate personnel performing TUAS operations, maintenance, and crew procedures. Performs site selection using maps, aerial photographs, terrain analysis, and information reports. Supervises site setup and breakdown. Coordinates with adjacent, higher, and supported units. Conducts pre-combat checks and inspections. Supervises the conduct of after-action reviews (AAR).', 'c349b2ed51b5f97a21efb293fe1fa4b2a2979fd48c92a3936f5916027a905125', 106, 106, null, 226, null, '2025-10-01', true, 3),
  ('bf24418c-1d18-5079-b4ae-9c31284c6698', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15W', 'Tactical Unmanned Aircraft System (TUAS) Operator', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels (SL) and provides guidance to subordinate Soldiers. Supervise operations and activities of the platoon. Applies the military information collection and targeting process, reconnaissance, and security planning to TUAS operations. Conducts and assists the development of the unit training plan.', 'e5a4404e6f0d7ba2ef2c73f8218b36113d85c82929c9d872ee752dcc4a8e2a89', 106, 106, null, 227, null, '2025-10-01', true, 4),
  ('622aa622-b9dc-51b7-a086-a5e83aa8ef5f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15W', 'Tactical Unmanned Aircraft System (TUAS) Operator', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'A Soldier in MOS 15W engages in operating and remotely piloting the TUAS. Performs pre-flight, in-flight, and post-flight checks and procedures. Conducts site selection, emplacement, and deployment of the air vehicles and ground equipment of the TUAS. Participates in launch/recovery ground crew operations. Performs aircraft commander (AC) duties to include planning, analysis, and execution of reconnaissance and security missions in support of targeting and information collection. Operates, troubleshoots, and performs limited unit-level maintenance on communication equipment, power sources, and wheeled vehicles.', 'e99df3f32eefb125894045aa88e14f484d09dc945fdd887502af1089198b351a', 108, 108, null, 228, '2025-10-01', null, false, null),
  ('75983d95-51c5-5320-85a7-e325127e8af5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15W', 'Tactical Unmanned Aircraft System (TUAS) Operator', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Executes reconnaissance and security missions. Plans and analyzes flight missions. Deploys and redeploys the TUAS ground and air system. Launches and recovers the air vehicle, performs pre-flight, in-flight, and post-flight checks and procedures. Performs operator maintenance and crew procedures on TUAS air and ground equipment. Prepares forms and records related to TUAS air and ground support equipment maintenance. Participates in the TUAS site setup and breakdown. Assists in proper handling and storage of flammable and hazardous materials.', '9cc2a5bb3bc11b57902f9d0b7526950af676a8a8b3994b7fd27d0f44c77c7f35', 108, 108, null, 229, '2025-10-01', null, false, 1),
  ('79cf02f2-537d-5bfd-b6e3-b2165ef873d7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15W', 'Tactical Unmanned Aircraft System (TUAS) Operator', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs a.1 and a.2. Performs operational checks and scheduled inspections. Supervises and assists site setup and breakdown. Participates in mission planning including terrain, threat, and current situation analysis. Participates in and supervises operator maintenance and crew procedures performed on TUAS air and ground equipment. Serves as primary trainer of readiness level (RL) 1 operators as the AC. Monitors proper handling and storage of flammable and hazardous materials.', '06de1dc4810c8a9b119ca5a2d557215a59fa77591d6c5f7288929b845a2f7c22', 108, 108, null, 230, '2025-10-01', null, true, 2),
  ('7c10513d-1054-56cb-8bed-4914dcb51a0a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15W', 'Tactical Unmanned Aircraft System (TUAS) Operator', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph a.1 and a.2. Performs, supervises, and provides technical guidance to subordinate personnel performing TUAS operations, maintenance, and crew procedures. Performs site selection using maps, aerial photographs, terrain analysis, and information reports. Supervises site setup and breakdown. Coordinates with adjacent, higher, and supported units. Conducts pre-combat checks and inspections. Supervises the conduct of after-action reviews (AAR).', 'c349b2ed51b5f97a21efb293fe1fa4b2a2979fd48c92a3936f5916027a905125', 108, 108, null, 231, '2025-10-01', null, true, 3),
  ('c3114a4a-6a3f-5207-b146-3004cea47859', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15W', 'Tactical Unmanned Aircraft System (TUAS) Operator', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels (SL) and provides guidance to subordinate Soldiers. Supervise operations and activities of the platoon. Applies the military information collection and targeting process, reconnaissance, and security planning to TUAS operations. Conducts and assists the development of the unit training plan.', 'e5a4404e6f0d7ba2ef2c73f8218b36113d85c82929c9d872ee752dcc4a8e2a89', 108, 108, null, 232, '2025-10-01', null, true, 4),
  ('2f850976-ef12-560f-9706-b66c0e5a7009', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15X', 'Tactical Unmanned Aircraft System (TUAS) Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The TUAS Specialist employs, operates, trains, repairs, services, modifies, fabricates, and inspects unmanned aircraft systems (UAS) and associated ground equipment for UAS groups one through three at brigade and below. Integrates into maneuver formations to conduct, assist, and train UAS operations in contact. Performs planning, analysis, and execution of aerial reconnaissance and tailors lethal and non-lethal UAS payloads to fit the mission''s targeting objectives. Conducts site selection, emplacement, cover, concealment, and deployment of aircraft and ground equipment. Performs pre-flight, in-flight, and post-flight checks and procedures. Executes launch/recovery ground crew operations. Exercises electromagnetic spectrum discipline and adjusts UAS control and video frequencies to counter electronic warfare threats.', '7933bd3a413400ebfcaff275f43aefcf2951d3e39c18e136a7ea743a621f788d', 110, 110, null, 233, '2026-10-01', null, false, null),
  ('20079dd4-1dd2-58a7-8c38-3a1f93f3f8d9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15X', 'Tactical Unmanned Aircraft System (TUAS) Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Executes UAS reconnaissance, security, target acquisition, and attack missions. Plans and analyzes flight missions. Designs, fabricates, configures, and tests UAS and associated payloads, ground control stations, and communication systems. Prepares UAS for deployment, shipment, and storage. Launches, controls, and recovers aircraft, performing pre-flight, in-flight, and post-flight inspections and operational checks. Conducts scheduled and unscheduled maintenance on airframes, payloads, and ground support equipment. Manages fuel, battery, and munitions systems, including transport, storage, and recovery. Operates mission planning systems, flight simulators, and tactical communication networks. Troubleshoots and repairs electrical components, flight controllers, and radio frequency systems using diagnostic tools. Maintains technical records and participates in site setup, breakdown, and after-action reviews. Ensures proper handling of hazardous materials and compliance with operational safety standards.', '2e2b94bf007dda59f009640db380898415ad451f1cbddf4a6660ef0dd037127d', 110, 110, null, 234, '2026-10-01', null, false, 1),
  ('ba5a7f36-27a4-56f0-b891-f50e532645a4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15X', 'Tactical Unmanned Aircraft System (TUAS) Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels and provides guidance to subordinate Soldiers. Integrates emerging UAS capabilities and assists development of the operator and gunnery training program. Executes training of UAS Operators across formations on UAS assembly, operation, employment, and gunnery. Supervises and assists site setup and breakdown. Participates in mission planning including terrain, threat, and current situation analysis. Participates in and supervises operator maintenance and crew procedures performed on UAS air and ground equipment. Serves as the primary trainer of TUAS Specialists as a unit trainer. Monitors proper handling and storage of flammable, explosive, and hazardous materials. Schedules maintenance on test, measurement and diagnostic equipment (TMDE).', 'a0a213b1d522a41a0d1d4af2bfcced9206a4c709d54a16e0ea0443f1120b56aa', 110, 110, null, 235, '2026-10-01', null, true, 2),
  ('2b006268-99d9-5b2a-83e1-d12c5fda9fd5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15X', 'Tactical Unmanned Aircraft System (TUAS) Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels and provides guidance to subordinate Soldiers. Advises commanders on optimal UAS integration and employment techniques, tactics, and procedures to include payload capability, payload employment, airspace management, and electromagnetic spectrum survivability. Manages the UAS training, gunnery, standardization and safety programs. Synchronizes UAS frequency management against threat EW. Performs, supervises, and provides technical guidance to subordinate personnel performing UAS operations, maintenance, and crew procedures. Performs site selection using maps, photographs, terrain analysis, and information reports. Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures and operational policies. Performs technical inspections. Applies production control, quality control and other maintenance management principles and procedures. Computes basic weight and balance and ensures compliance with aircraft configuration control, Army Oil Analysis Program, and TMDE calibration. Supervises site setup and breakdown. Coordinates with adjacent, higher, and supported units. Conducts pre-combat checks and inspections. Supervises the conduct of after-action reviews (AAR). Monitors requisition of parts, tools and supplies.', '2a9b036d9b2c5a77aad80b4cd2259409f29c03917ea5a96824f385736fe286a2', 110, 110, null, 236, '2026-10-01', null, true, 3),
  ('3b0db7df-9e8d-505b-bdf6-a300a7cae8bc', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15X', 'Tactical Unmanned Aircraft System (TUAS) Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels and provides guidance to subordinate Soldiers. Supervises operations and activities of the platoon. Applies military intelligence collection, targeting processes, and security planning to UAS operations. Conducts and assists development of the unit training plan. Determines man-hours, personnel, parts and facility requirements to repair UAS and associated equipment. Plans maintenance areas, component repair, technical inspection techniques, and procedures, according to directives, technical manuals, work standards, and operational policies. Maintains supply economy and discipline. Supervises the unmanned aircraft systems technical training program. Prepares evaluations, special reports, and records pertaining to unmanned aircraft systems maintenance and related activities. Recommends and administers plans and policies.', '755e12011fb4ae53b9e57806fc87dac498d75c1ce9312d5322007f6c004eb140', 110, 110, null, 237, '2026-10-01', null, true, 4),
  ('c61ce79c-1052-571d-b78d-84fb48186669', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Y', 'AH-64 Armament/Electrical/Avionics Systems Repairer (AH-64 Arm/Elect/Avionics Sys Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'A Soldier in MOS 15Y performs and/or supervises inspections, maintenance and modifications according to drawings, blueprints, directives, technical manuals, and safety procedures on the AH-64D armament, electrical and avionics systems and cryptographic equipment to include the electrical, electronic, mechanical, and pneudraulics systems associated with AH-64D Armament/Missile Fire Control Systems. Tests, troubleshoots and repairs test sets and diagnostic equipment. Maintains records on weapons and subsystems. Uses and performs operator maintenance on common and special tools. Prepares aircraft related maintenance forms and records. Typically assigned to Aviation Field or Sustainment maintenance units.', '5bc17afc4f7428484b5b41b6ae1927dc40eed0939721bc467d942018beb41cf0', 112, 112, null, 238, null, null, false, null),
  ('679a8b6c-7630-50bc-8bff-047e1838893a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Y', 'AH-64 Armament/Electrical/Avionics Systems Repairer (AH-64 Arm/Elect/Avionics Sys Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Diagnoses, troubleshoots, and repairs malfunctions in AH-64D armament, electrical, and avionics systems and components including solid state and transistorized subsystems according to pertinent technical manuals, directives and safety procedures. Perform maintenance, authorized modifications and alignment on aircraft weapons components, fire control units, and sighting elements, electronic and mechanical devices. Repairs, replaces and performs operational and preventive checks and alignment on aircraft flight controls, stabilization systems, avionics and controlled cryptographic equipment. Uses and performs operator maintenance on tools, special tools and aircraft ground support equipment. Requisitions and maintains shop and bench stock for repair of aircraft systems and equipment. Maintains facilities for storage of flammable and hazardous materials. Prepares forms and records related to aircraft maintenance. Participates in the setup of the Forward Arming and Refueling Point (FARP).', '74ff42697699db97c9a634051a42c9b7355e02d74e74511b25772244006add91', 112, 112, null, 239, null, null, false, 1),
  ('2d13ce49-fea3-5868-bca3-196590022a16', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Y', 'AH-64 Armament/Electrical/Avionics Systems Repairer (AH-64 Arm/Elect/Avionics Sys Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties described in paragraph (1) and provides technical guidance to subordinate personnel. Performs operational checks and scheduled inspections. Diagnoses and troubleshoots malfunctions in aircraft subsystems. Alters or modifies material according to DA approved modification work orders. Monitors hazardous material control and storage.', '0ccfdd34ac91531a51b2ca62565b366784075122787364a94ddfef38154a1f2d', 112, 112, null, 240, null, null, true, 2),
  ('32a83005-68f4-5233-8eb9-6c1ec7855059', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Y', 'AH-64 Armament/Electrical/Avionics Systems Repairer (AH-64 Arm/Elect/Avionics Sys Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate personnel performing duties described in paragraphs (1, 2) and evaluates the technical training program. Evaluates maintenance operations and facilities for compliance with directives, technical manuals, work standards, safety procedures, and operational policies. Performs maintenance trend analysis and applies production control, quality control and other maintenance management principles and procedures to airplane maintenance operations. Plans, conducts, and supervises aircraft technical inspections. Compute basic weight and balance records. Participate in maintenance test flights. Ensure compliance with aircraft configuration control, Army Oil Analysis Program and test measuring diagnostic calibration. Supervise the establishment of the FARP.', '3f76fa122c08f0597951f6ede2ce6952a2403dc4683ef58687f2615f568e4912', 112, 112, null, 241, null, null, true, 3),
  ('1389d7cd-be82-5ce1-86a1-05dbf9cf0d06', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Z', 'Aviation Senior Sergeant (Avn Sr SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises personnel performing duties of CMF 15 Aviation as described below:', 'ce2c1a4868073fb061bf461627e906428851b5ec0dd34accad13dab208978530', 114, 114, null, 242, null, null, false, null),
  ('5287720f-ac48-5dbb-8e73-d14ee5a1d69a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Z', 'Aviation Senior Sergeant (Avn Sr SGT)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The aviation senior sergeant supervises aviation activities in a maintenance company/troop, aviation support company/troop and depot maintenance having a mix of aircraft maintenance and/or component repair MOS. Prepares studies, evaluations, special reports, and records pertaining to aircraft maintenance, component repair, and related activities. Plans aircraft maintenance areas, components repair shops, and facilities. Apply production control, quality control and other maintenance management principles and procedures to aircraft maintenance and shop operations. Supervise the verification and validation of technical manuals, training devices and contractor furnished training material pertaining to new aircraft and/or component fielding. Supervise research and development projects in aviation and related areas. Assist in the development of maintenance procedures for prototype aircraft and components. Supervise the development and instruction of training programs. Recommend and establish plans, policies, and procedures for aircraft maintenance operations. Maintains supply economy and discipline. Principal NCO in the operations (S3) section of an Aviation Battalion. Responsible for the synchronization of all staff functions for the commander. Knowledge of all ABCS systems and understands their deployment on the battlefield. Supervises and instructs subordinates in proper work techniques and procedures. Reviews, consolidates and prepares technical reports. Provides and oversight of a flight operations section that is responsible for the reporting of flight violations, preparing of situation maps, receiving and transferring classified information and participates in the crash rescue system.', '2fe137addb7c78dc444c00c264a65b4dca34f4a84fbf260d646213c5a78baf8c', 114, 114, null, 243, null, null, false, 5),
  ('e53005b5-1f56-56ad-bf9c-1105be4162a1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '15Z', 'Aviation Senior Sergeant (Avn Sr SGT)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Aviation Senior Sergeant serves as the principal NCO in a Combat Aviation Brigade (CAB) or higher organizations. Provides tactical and technical guidance and professional support to subordinates and makes recommendations to supervisors in the accomplishment of their duties. Supervises activities pertaining to operations (S3) in a CAB. Plans, coordinates, and supervises activities pertaining to organization, training combat operations.', 'e49447e2971f9cbc69217208fc767054e9853c68aeb53edd6e6f5f10139c07b1', 114, 114, null, 244, null, null, false, 6),
  ('802bd748-f053-551f-9ebd-fbb5388f52c8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17C', 'Cyber Operations Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Cyber Operations Specialist executes effects in support of cyberspace operations and multidomain operations by employing devices, computer programs or techniques including combinations of software, firmware, and hardware intended to project power in and through cyberspace, targeting enemy and hostile adversary activities and capabilities. As an integral part of the national cyberspace workforce, Cyber Operations Specialists are generally aligned under standardized cyberspace work roles defined by the DoD Cyberspace Workforce Framework, U.S. Cyber Command (USCYBERCOM), and Army Cyber Command (ARCYBER). The primary functions relevant to the Cyber Operations Specialist are planning, analysis, development and remote/expeditionary operations.', 'cbe9191c96de301fae15f4776ba7e899763c7597f8b69b899412a3ce101f4407', 116, 116, null, 245, '2025-10-01', null, false, null),
  ('169eea11-e40e-5ac6-8607-4c50752b6e99', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17C', 'Cyber Operations Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conduct cyber effects, cyber operational preparation of the environment, and cyber intelligence, surveillance, and reconnaissance actions on specified systems and networks. Conduct network terrain audits, penetration testing, basic digital forensics data analysis, and software threat analysis. React to cyberspace events, employ cyberspace defense infrastructure capabilities, collect basic digital forensics data, provide incident response impact assessments, and produce network security posture assessments. Analyze computer system and network architectures, as well as determine and implement exploitation methods.', '94c95fbd0e7191fdcd8c2f30b3c8324c236f150e52ccac033509198924016292', 116, 116, null, 246, '2025-10-01', null, false, 1),
  ('717e7fbd-06cf-5162-894b-250f0479c682', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17C', 'Cyber Operations Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill level and provide guidance to subordinate Soldiers. Lead Soldiers in performing activities in support of offensive and defensive cyberspace operations. Validate critical infrastructure configurations, network alerts, and network security posture assessments. Review, write, edit, evaluate and publish both offensive and defensive cyberspace operations products and reports.', '79ae7ea8a7c883fd82a0784902553612e683065ab115002c0955539f1c42b2d8', 116, 116, null, 247, '2025-10-01', null, true, 2),
  ('786257d1-89df-584f-aca1-e2d0cc6dd0c6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17C', 'Cyber Operations Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill levels and provide guidance to subordinate Soldiers. Lead operational teams in support of offensive and defensive cyberspace operations. Conduct cyberspace operations risk assessments, post-incident analysis and intermediate software analysis. Collect and analyze intermediate forensics data. Validate architectural analysis, administer penetration testing, and coordinate response actions.', '2f75a08b2a4ef595929ca7a1d9af74d2edc5c4abb6194ff4a21cb8a1969a45f3', 116, 116, null, 248, '2025-10-01', null, true, 3),
  ('d187d5cd-03a0-517e-a98c-61c8ee9a3ddc', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17C', 'Cyber Operations Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill levels and provide guidance to subordinate Soldiers. Supervise operational teams in support of offensive and defensive cyberspace operations. Direct network terrain audits, digital forensics processes, and exploitation missions. Evaluate cyber defense requirements and participate in the joint targeting process.', 'da755e914cb5f9983f66e3c0317b184a8ca1b457b63fc690c442ed13f66854e4', 116, 116, null, 249, '2025-10-01', null, true, 4),
  ('5e88e951-3df0-5e8b-a290-f54d2b3e8827', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17C', 'Cyber Operations Specialist', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill levels and provide guidance to subordinate Soldiers. Perform mission management functions for cyberspace operations. Develop crisis plans to directly support cyberspace operations planning and targeting. Serve as Subject Matter Experts (SME) of the technical integration of cyberspace attack; defense; Intelligence, Surveillance, and Reconnaissance; Operation Preparation of the Environment in support of unified land operations. MSGs are also assigned as First Sergeants and Operations Sergeants at battalion and higher level. These assignments rely heavily on leadership experience and technical expertise to synchronize effects within the Joint operational and targeting planning process and operational framework.', '1f6ba6510b2abd9e27599fe83a365d3a1243fa4c136801d35a2df0919e8df337', 116, 116, null, 250, '2025-10-01', null, true, 5),
  ('58c89ead-8ab7-57fc-afd2-94655c1c8da2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17E', 'Electronic Warfare Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Electronic Warfare Specialists are subject matter experts on the manipulation, control, and dominance of the electromagnetic spectrum. They advise and assist the commander or command Electronic Warfare Officer (EWO), as applicable, to defeat the enemy through planning, coordination, integration, and execution of Electronic Attack (EA), protect and harden friendly systems, processes, and personnel by developing, training, and executing Electronic Protection (EP), and support current and future operations by planning and performing Electronic Warfare Support (ES). Electronic Warfare Specialists plan for and coordinate the integration of electronic warfare into military operations through every step of the military descision making process (MDMP).', 'b52dead7d8d06b82041bf04540d2b6aedc7aea65a569c52d713447867270d2a4', 118, 118, null, 251, null, null, false, null),
  ('23d55f6a-2d97-531c-b201-aaa0734757ca', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17E', 'Electronic Warfare Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates and maintains electronic warfare (EW) equipment to include Special Purpose Electronic Attack (SPEA) systems, Direction Finding (DF) systems, modeling and simulation tools, EW test equipment, and counter radio-controlled improvised explosive device electronic warfare (CREW) systems. Evaluates technical electronic intelligence data for force engagement operations in a joint service network, assisting in generating Enemy Electronic Order of Battle and EW threat briefs and maintaining the common operating picture. Assists in preparing and evaluating interference reports and EA requests. Operates and performs operator PMCS on EW system equipped vehicles/system prime power units. Conducts EA in support of ground maneuver, tactical deception, or in support of information operations. Conducts ES in support of an information collection plan to answer PIR, provide early warning to ground maneuver units, or to assist in the assessment of unit EP measures. Conducts EP activities to harden communications against intentional or unintentional electromagnetic interference, minimize emission signature of friendly unit communication and non-communication emitters, and avoid spectrum interference by adjacent units.', '7e16796fd46a857e0794acce3cfb42079c73397899138620c96b0c503ac9a76b', 118, 118, null, 252, null, null, false, 1),
  ('de3028ed-5b17-50bf-b5de-ca79932ae1bb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17E', 'Electronic Warfare Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and supervises duties shown in preceding skill level as an Electronic Warfare Team Chief or Battalion to Brigade level Staff NCO. Responsible for execution and coordination of cyber electromagnetic operations to include EA, EP, and ES activities; operate test measurement and diagnostic equipment (TMDE); maintain and troubleshoot assigned equipment; resolves interoperability issues at unit level; prepares and maintains EW running estimates; assists company CREW specialists to ensure an effective CREW electronic counter measure (ECM) force protection (FP) program.', '3c4b75afa7661f58b083a93ae6eaeac24fd92505b3cbe673b985328fb1afdf39', 118, 118, null, 253, null, null, true, 2),
  ('c0a2fb9e-a52d-574d-8de2-d3daaa43ae8e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17E', 'Electronic Warfare Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. Serves as Electronic Warfare Platoon Senior Team Chief or Brigade Combat Team Staff NCO. Demonstrates proficiency in orders process, Military Decision Making Process (MDMP), and the targeting process; manages employment of EW air and ground systems; reviews, processes, and forwards effects packets to higher; ensures timely dissemination of information to and from higher headquarters; identifies risks, vulnerabilities, courses of action and potential countermeasures. Understands the cyberspace domain and coordinates EW actions and effects with offensive and defensive cyberspace operations.', 'b91b40e25d69651ff15fb4394fa2949c2eb5bbc6f83c3122517367af7c8c86fe', 118, 118, null, 254, null, null, true, 3),
  ('5b2d0246-cca3-50ac-8f39-a17523dee20e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17E', 'Electronic Warfare Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. Serves as Electronic Warfare Platoon Sergeantor as staff NCO at echelons above Brigade. Primary planner of Cyberspace Electromagnetic Activities (CEMA) for CEMA section at echelons Division and above; ensures support to subordinate units; manages equipment and resource issues with and between higher, adjacent and subordinate units; prioritizes allocation of Army EW air and ground assets; reviews and processes effects packets; coordinates integration and execution of cyberspace joint EW operations.', '4130242ea8c5763b3af6324bb7b411f5f4a76ee2e3362ccc3f54a301faf30f16', 118, 118, null, 255, null, null, true, 4),
  ('e7d8c4ba-6783-5d6b-bf89-4e0fdf41a22f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17E', 'Electronic Warfare Specialist', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. Serves as Company 1SG or Brigade or higher staff NCO. Primary enlisted EW advisor of the EW element at the Brigade or Division echelons; primary planner of CEMA for EW Platoon elements; significant combined operations emphasis; prioritization of Army, joint and multi-national EW assets between adjacent and subordinate commands, as applicable; allocation of EW equipment and resources; develops tactical level guidance from strategic guidance pushed down from higher.', '8048306e0666d9943b457ab80f24f696a62cd2c4ef759c27373664f0ef783a58', 118, 118, null, 256, null, null, true, 5),
  ('0ee46dac-4ee8-5efb-b708-081ce74368f7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '17Z', 'Cyberspace and Electromagnetic Activities (CEMA) Senior Sergeant (CEMA Sr SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The CEMA senior sergeant provides senior level technical and tactical advice to command and staff on all aspects of offensive and defensive cyberspace and electronic warfare operations matters. Mentors command leadership and subordinate personnel on CEMA functions and capabilities. Facilitates and synchronizes joint CEMA functions and capabilities in support of Large Scale Combat Operations (LSCO) at the corps, theater, ASCC, and inter-service level focusing on: decisional aspects; prioritization, allocation, and coordination of all CEMA assets and operations; development of strategic concepts and operations; direct involvement with HQDA, Army Commands, Army Service Component Commands, and National Agencies. Negotiates, establishes, and maintains liaison within the Army, other services, national, allied, and coalition nations on all CEMA functions and capabilities. Serves on national strategic panels, committees, work groups, and advises international, national, military and civil organizations. Responsible for development, preparation and/or analysis of strategic CEMA guidance for use by subordinate commands.', '33454f0ccfcd4f462a74094c1307b77f8e6435e7695274a1fcf7e233c099dc3b', 120, 120, null, 257, null, null, false, null),
  ('680f5c34-fe3e-5948-9075-dc9a2125f279', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18B', 'Special Forces Weapons Sergeant (SF Wpns SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Special Forces Weapons Sergeant employs U.S. and foreign small arms, light and heavy crew served weapons, anti-aircraft and anti-armor weapons. Controls emplacement and supervises employment during tactical offensive and defensive combat operations; reads, interprets, and prepares combat orders; coordinates organic and supporting fire power, performs standard and non-standard air delivery, airborne operations, and air-ground operations; ensures collection and proper reporting of intelligence data to unit and staff sections.', 'dcb8e5660d300b5ff07ceb7589da4543e0dd51335d7b74c5ce2702fadac7cf12', 121, 121, null, 258, null, null, false, null),
  ('699f0c0c-5971-50d7-aec1-4ccb810de24c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18B', 'Special Forces Weapons Sergeant (SF Wpns SGT)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Trains and maintains proficiency in all major duties. Employ highly demanding conventional and high-risk unconventional warfare tactics and techniques in the employment of U.S. and foreign small arms, light and heavy crew served weapons, anti-aircraft and anti-armor weapons. Supervises and controls execution of tactical conventional and unconventional operational employment and emplacement of all types of U.S. light weapons (up to and including 50 cal MG and 106mm RR), man-portable air defense weapons and U.S. anti-armor weapons (including anti-tank missile systems), to perform tactical operations. Maintain proficiency with the employment and functions of all foreign high-density light and heavy weapons, man-portable air defense and anti-armor weapons. Evaluates terrain, selects weapons emplacements, sites, and assigns targets and areas of fire. Reads, interprets, and prepares combat orders.', '8052711c1006481d43722a459fd32d30692d559cedd13d0cea863a348c4e0f70', 121, 121, null, 259, null, null, false, 3),
  ('2aac7f1d-9930-5f22-ad81-327a0be98eb3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18B', 'Special Forces Weapons Sergeant (SF Wpns SGT)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs all duties of preceding skill level and coordinates organic and supporting fire power, performs standard and non-standard air delivery, airborne operations, and air-ground operations. Participates in special missions and operations as detachment member. Ensures collection and proper reporting of intelligence data to unit and staff sections. Reads and interprets maps and aerial photos and assists in area studies preparation. Plans, prepares and conducts briefings, brief backs, and debriefings. Acts in supervisor capacity when conducting split-detachment operations and missions. Conducts security and training when task organized in preparation (isolation) for missions and during operations.', 'f24a49ff8f149d2221a364693bea0a35016a68b8ad60858cd4292b7e2077ec4e', 121, 121, null, 260, null, null, true, 4),
  ('ca60d0e2-a0c4-571d-ada7-9d46d3b92004', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18C', 'Special Forces Engineer Sergeant (SF Engr SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Special Forces Engineer Sergeant employs offensive/defensive combat engineer capabilities; performs and instructs in demolitions, explosives, improvised munitions, U.S. and foreign landmines, mine/countermine operations, construction, field fortification, bridging, rigging, electrical wiring, reconnaissance, target analysis and civil action projects; instructs and performs land and water navigation duties by interpreting maps, overlays, photos, charts and using standard and nonstandard navigational techniques and equipment; proficient in sabotage operations with standard, nonstandard, and improvised munitions and explosives; plans, prepares and conducts the target analysis portion of the area study; collects and disseminates engineer intelligence data; prepares and reviews target folders; prepares and reviews target analysis folders.', '8f79d7426817c9ab9882f7a26555af8f77ba3bb245d0bfd05af1750623b59716', 123, 123, null, 261, null, null, false, null),
  ('ff33fc4c-f16d-530b-b208-1ac75d69be8c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18C', 'Special Forces Engineer Sergeant (SF Engr SGT)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and maintains proficiency in all major duties. Performs and teaches tasks in demolitions, explosives, improvised munitions, U.S. and foreign landmines, mine/countermine operations, construction, field fortification, bridging, rigging, electrical wiring, reconnaissance, target analysis and civil action projects. Instructs and performs land and water navigation duties by interpreting maps, overlays, photos, charts and using standard and nonstandard navigational techniques and equipment. Plans, teaches and performs sabotage operations with standard, nonstandard and improvised munitions and explosives. Plans, prepares and conducts the target portion of the area study and conducts briefings, briefbacks and debriefings. Collects and disseminates engineer intelligence data. Prepares and reviews target folders. Supervises combat engineering functions when conducting split-detachment operations and missions.', 'ccf1a67783910dd6b5c27e3519774c69e9a7351c325d167dc6c341550ecaf97d', 123, 123, null, 262, null, null, false, 3),
  ('dc6f1f00-9ec0-5fd7-bf09-4042bc6e7ddd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18C', 'Special Forces Engineer Sergeant (SF Engr SGT)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform all duties of preceding skill level. Provide tactical and technical guidance to the Detachment Commander, indigenous and allied personnel. Plans, organizes, trains, advises, assists and supervises indigenous and allied personnel on employment of engineer assets in defensive/offensive operations and in support of operations through battalion level. Responsible for the planning, execution and supervision of cross training of detachment members in Special Forces engineer skills. When directed, conducts operational and intelligence planning, preparation, and execution of detachment missions.', '09a08c946831fd6a8679046be8b5a8801eec91a94bd700e1d5dfccdbbc5cd9b6', 123, 123, null, 263, null, null, true, 4),
  ('582d8e26-6adf-5a3a-b822-d8598f6da4cf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18D', 'Special Forces Medical Sergeant, (SF Med SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Special Forces Medical Sergeant ensures detachment medical readiness; establishes and supervises temporary, fixed and unconventional warfare medical/dental facilities to support conventional or unconventional operations with emergency, routine, and long term medical care; provides initial medical/dental screening and evaluation of allied and indigenous personnel; manages detachment, allied, or indigenous patients, administration, admission and discharge, care, laboratory and pharmacological requirements and the initiation, maintenance and transfer of records; orders, stores, catalogs, safeguards and distributes medical/dental supplies, equipment and pharmaceuticals; supervises medical care and treatment during split detachment missions; operates combat laboratory and treats emergency and trauma patients in accordance with established surgical principles; diagnoses and treats various medical/veterinary dermatological, pediatric, infectious and obstetric conditions using appropriate medications, intravenous fluid support and physical measures; manages and supervise all aspects of deployed preventive medicine; develops and provides medical intelligence as required; in unconventional warfare environment, instructs medical personnel, manages guerilla hospital, and field evacuation nets; coordinates the operation, interaction and activities of medical/dental facilities within an area of operation; manages battalion size troop medical/dental clinic and its administrative and logistical support; establishes a base stock of medical supplies and equipment, internal or external procurement, storage, security and distribution of those items; coordinates veterinary training and support for area requiring animal transportation or use; provides guidance and training of medical personnel and preventive medicine specialists.', 'fb326d402bf220daad1789dc37cd90764577ce1449add577d7963bfffc3ec67d', 125, 125, null, 264, null, null, false, null),
  ('25a1e7d3-a95b-5958-9246-4468435aee7d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18D', 'Special Forces Medical Sergeant, (SF Med SGT)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and maintains proficiency in all major duties in accordance with the medical skills sustainment program outlined in USASOC Regulation 350-1 (ARSOF Active Component and Reserve Component Training) and 1st Special Forces Command (Abn) Regulation 350-1 (Component Training). Ensures detachment medical preparation and maintains medical equipment and supplies, provides examination and care to detachment members and establishes temporary, fixed and unconventional warfare medical/dental facilities to support operations with emergency, routine, and long term medical care. Provides initial medical/dental screening and evaluation of allied and indigenous personnel. Manages detachment, allied, or indigenous patients, administration, admission and discharge, care, laboratory and pharmacologic requirements and the initiation, maintenance and transfer of records. Orders, stores, catalogs, safeguards and distributes medical/dental supplies, equipment and pharmaceutical. Supervises medical care and treatment during split detachment missions. Operates a combat laboratory and treats emergency and trauma patients in accordance with established surgical principles. Diagnoses and treats various medical/veterinary dermatologic, pediatric, infectious and obstetric conditions using appropriate medications, intravenous fluid support and physical measures. Manages and supervises all aspects of deployed preventive medicine. Develops and provides medical intelligence as required. Ensures medical deployment readiness for unit of assignment.', '85f8a947f52f83b923466013c68e669a4152d56d85e0be00977369cc3a0fccbf', 125, 125, null, 265, null, null, false, 3),
  ('c529f75e-9132-5fbf-b6ba-e13d16dd057a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18D', 'Special Forces Medical Sergeant, (SF Med SGT)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs all duties of preceding skill level and maintains proficiency as previously stated for 18D3O. Supervises and manages field medical activities in a conventional or unconventional warfare environment. Advises and provides tactical and technical guidance to the Detachment Commander, indigenous and allied personnel. Responsible for the planning, execution and supervision of cross training of detachment members in medical skills. In unconventional warfare environment, instructs medical personnel, manages guerilla hospital, and field evacuation nets; coordinates the operation, interaction and activities of medical/dental facilities within an area of operation; manages battalion size troop medical/dental clinic and its administrative and logistical support. Establishes a base stock of medical supplies and equipment, internal or external procurement, storage, security and distribution of those items. Coordinates veterinary training and support for area requiring animal transportation or use. Provides guidance and training of medical personnel and preventive medicine specialists. When directed, conducts operational and intelligence planning, preparation and execution of detachment missions.', 'f51bb537804703292444ff6ebc6d32e68337a0ade38acb8dd64c7cbc0df510c9', 125, 125, null, 266, null, null, true, 4),
  ('2e3c4d99-7f6e-5424-abbb-5bf1f977eb61', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18E', 'Special Forces Communications Sergeant (SF Comm SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Special Forces Communications Sergeant provides conventional and unconventional tactical communications support during unilateral, combined, coalition, joint, interagency and multinational operations; employs ODA communications equipment to include HF, VHF, and UHF/SHF radio communications systems to transmit and receive radio messages in voice, continuous wave, and burst radio nets; trains, advises, and supervises the installation and operation of radios, communications procedures, facsimile, wire communications and computer networks; plans, manages, and advises the commander on C4I architecture, communications matters, and communications security up to Special Forces Operating Base (SFOB) level; prepares communications plan and annexes; prepares Signal Operations Instructions/Communication Electronics Operations Instructions (SOI/CEOI); serves as Communications-Electronics (C-E) NCOIC for FOB communications.', 'b35766d1989e6312be05a5d8837acb5cf72db994f19da2c0aa4f87e56751d44b', 127, 127, null, 267, null, null, false, null),
  ('da2aad82-0ae6-5b3d-9566-7c5125496513', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18E', 'Special Forces Communications Sergeant (SF Comm SGT)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Employs ODA communications equipment to include HF, VHF and UHF/SHF radio communications systems to transmit and receive radio messages in voice, continuous wave and burst radio nets. Plans, manages, and advises commander on C4I architecture, communications matters, and communications security to AOB level.', 'ad5f67c9b98a52240949573b5e4a833809b6f5fae04298567947d1869833b24a', 127, 127, null, 268, null, null, false, 3),
  ('3d1e7434-98a0-50db-98d9-70c5656d9cf4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18E', 'Special Forces Communications Sergeant (SF Comm SGT)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs all duties of preceding skill level and advises the Commander on communications matters, and communications to Special Forces Operating Base (SFOB) level. Prepares communications plans and annexes. Prepares Signal Operations Instructions/Communication Electronics Operations Instructions (SOI/CEOI). Serve as Communications-Electronics (C-E) NCOIC for FOB communications.', '8a165ccaf42195a5922bccfb1ab0726db6b7a74e69eb919ae0fe78309eaf4a88', 127, 127, null, 269, null, null, true, 4),
  ('d80df5ca-4aed-57cc-9803-6eb472f67c55', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18F', 'Special Forces Intelligence Sergeant (SF Intel SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Special Forces Intelligence Sergeant prepares intelligence estimate (analysis) during mission planning and preparation (isolation); employs conventional and unconventional techniques of intelligence collection and processing during unilateral, combined, coalition, joint, interagency, and multi-national operations; plans, organizes, trains, advises, assists, and supervises indigenous and allied personnel on collection and processing of intelligence information; establishes intelligence networks, capable of establishing personnel identification through fingerprinting and other means; processes prisoners of war and detainees; establishes security plan and performs security duties; maintains all classified documents in the operational area and establishes destruction and evacuation plans; conducts threat vulnerability assessments; provides area specialist assistance to U.S. forces and outside agencies.', '11a4b6d30150ee3e70036d39dd3cf0ad933b8a0ab289e29e56ad08285977d193', 129, 129, null, 270, null, null, false, null),
  ('af932f6f-f64f-5388-b60a-272e576c0e7e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18F', 'Special Forces Intelligence Sergeant (SF Intel SGT)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Trains and maintains proficiency in all major duties; conducts conventional and unconventional intelligence activities in a Joint Interagency Intergovernmental Multinational (JIIM) environment; analyzes security and force protection in a JIIM environment; conducts comprehensive intelligence preparation of the environment; utilizes analytical skills to develop intelligence products; performs data management utilizing the appropriate intelligence architecture; recommends and validates PIR/IR; facilitates the SOF targeting process; conducts collection management of organic assets and coordinates for outside Intel support; supports and leverages Advanced Special Operations Techniques (ASOT); plans and supports assisted and unassisted personnel recovery and evasion operations; manages the collection priorities for Sensitive Site Exploitation; drives the intelligence portion of the MDMP; assists the detachment leadership in planning and executing operations.', 'ea2ed38d08923fecd7f48ae13991d31ef478090c3a19377deb51b5a7662c7122', 129, 129, null, 271, null, null, false, 4),
  ('989c5711-f861-5151-afda-667bbd21cb13', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18Z', 'Special Forces Operations Sergeant, (SF OPS SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Special Forces Operations Sergeant supervises, leads and serves as a member of an Operational Detachment of a Special Forces unit.', '2773d586d1cadca72b4318f52cc23fe4a851cf1af9e3307809a49f446764b1ad', 131, 131, null, 272, null, null, false, null),
  ('5b86dfa8-8883-5e0e-8397-35df2aa15b9e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18Z', 'Special Forces Operations Sergeant, (SF OPS SGT)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises all administrative, operational, and training requirements of a Special Forces Operational Detachment Alpha (ODA). Leads all aspects of mission preparation (isolation) and execution.', 'a3971550fe274db66747ee749941b67f6a11ade07e890aa31e1c9d39d107685a', 131, 131, null, 273, null, null, false, 5),
  ('af12bcc6-bd00-55b3-87ed-1090964d1400', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '18Z', 'Special Forces Operations Sergeant, (SF OPS SGT)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Advises the commander and staff on all matters pertaining to enlisted personnel. Enforces the implementation of established policies and standards as they pertain to enlisted personnel within the command. Provides counsel and guidance to the NCOs and other enlisted Soldiers of the command. Manages the daily activities and operations of the unit.', '3444cb04a968e534993c06c646ed2e84ebaa5ffc9aaed5911f28e038b22e94f1', 131, 131, null, 274, null, null, false, 6),
  ('d2747f64-4db4-5f0c-ac9c-eba5ad4a6e87', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19C', 'Bradley Crewmember', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Bradley Crewmembers combine the superior capabilities of their equipment with their ingenuity to find, fix, close with and destroy the enemies of this nation through combinations of mobility; precise, lethal, and overwhelming firepower and devastating shock effect. The Armor branch is a team of teams, ready to fight and win anytime, anywhere, and under any conditions of battle. Soldiers must possess the physical ability to function and adapt to austere environments and accomplish all missions.', 'ba5f326931a2a9901eeec41850c7f91fbef2f460190d325811c2edcaebab6751', 132, 132, null, 275, '2024-10-01', null, false, null),
  ('630cf8a7-7d84-5002-aff5-99ad663abc25', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19C', 'Bradley Crewmember', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties as a driver on an M2 series Bradley Fighting Vehicle. Moves, positions, and stops the BFV. While driving, searches for covered and concealed routes and for covered positions to move to if the BFV is engaged. Maintains the vehicle’s position in formation and watches for visual signals. Monitors the steer-to indicator, if equipped, and understands and applies the best tactical route. Assists the gunner and BFV commander by scanning for targets and sensing fired rounds during engagements. Responsible for the load plan and overall maintenance of the vehicle. May also serve as a carrier driver in the Armored Assault Company HQ platoon.', '027b09339e692be0b3000e3a1e5965da3a57476fd8d0f82d8cd083b2028bf491', 132, 132, null, 276, '2024-10-01', null, false, 1),
  ('db2c939a-d153-5ce1-b042-73e369051966', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19C', 'Bradley Crewmember', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties as a gunner on an M2 series Bradley Fighting Vehicle and responsible for one subordinate. Searches for targets, aims, and fires the M242 Bushmaster, coaxial machine gun, and TOW ATGM. Responsible to the BFV commander for the immediate supervision of and assisting with the overall maintenance of the vehicle, with emphasis on the fire control system and armament, and accountability of all associated equipment. Responsible for the manual inputs and manipulation of the fire control system through the gunner’s control panel. Assumes the role of the BFV commander in their absence. Maintains the communication and internal control systems. Responsible for the training and development of their subordinates. Serves as a gunner at all echelons.', 'b470871b31c0c7219b23afdb7e3646b326a92dd84389bc9b831948f1b25505dc', 132, 132, null, 277, '2024-10-01', null, false, 2),
  ('5f7d3c29-f426-5654-ad9f-02b480d9bb56', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19C', 'Bradley Crewmember', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties as a commander on an M2 series Bradley Fighting Vehicle. Must become an expert in the following critical skills: BFV weapon systems, requesting indirect fires, integration of direct fires with dismounted personnel, and executing land navigation using both digital systems and more traditional methods, such as terrain association. Briefs crew, directs movement of the BFV, submits reports, and supervises initial first-aid treatment and evacuation of wounded crewmembers. Ensures the welfare of the crew. Lays the gun for direction, issues fire commands, and controls the vehicle’s direct fires. Prepares graphic overlays and detailed combat reports using analog and digital communications. Conducts quartering party activities, passage of lines, and CBRN operations. Trains crew on the maintenance and accountability of assigned equipment and the tactical employment of the BFV. Knows and understands the unit’s mission and the commander’s intent. Maintains situational awareness by using all available optics for observation, monitoring radio transmissions and digital displays. Responsible for ensuring equipment is stowed and secured properly per unit load plans or Standard Operating Procedures (SOP). Responsible for fostering crew cohesion and for the medical and administrative readiness of the crew. May also serve as a Master Gunner.', 'fc987e6dab637dd55692ca7c18776dca30e8fe05c9fdf9b8f4ceacd47af690fe', 132, 132, null, 278, '2024-10-01', null, false, 3),
  ('5b8f14a0-2c7d-5f5a-98a1-6e6778ba9f4c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19C', 'Bradley Crewmember', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform primary duties as a Platoon Sergeant. The Platoon Sergeant is second in command of the platoon and the most experienced enlisted member. Performs all duties of the Platoon Leader in their absence. Assists and advises the Platoon Leader, mentors crewmembers, and other NCOs on the tactical and technical employment of the platoon’s assigned equipment. Supervises the platoon’s administration, logistics, and maintenance as well as individual training. Advises and makes recommendations on all promotions and reductions, assignments, and discipline of NCOs and enlisted Soldiers in the platoon. Update the Platoon Leader on appropriate reports, and forwards any reports needed to higher echelons. Takes charge of task organized elements in the platoon during tactical operations, including quartering parties and support elements. Serves as a BFV commander when the platoon is mounted. Monitors the morale, discipline, and health of platoon members. Coordinates and supervises resupply operations. Collects, prepares, and forwards logistic status updates and requests to the 1SG. Ensures ammunition and supplies are properly and evenly distributed after the platoon consolidates on the objective and while the platoon reorganizes. Ensures support supplies are present. Directs the platoon’s casualty evacuation (CASEVAC) process. Maintains platoon strength information, consolidates, and forwards the platoon’s casualty reports, and receives and orients replacements. Monitors the commander’s tactical display to maintain awareness of the platoon’s positions relative to the company formation. Maintains accountability to the Platoon Leader for the training, discipline, and welfare of the Soldiers in the platoon. Coordinates the platoon’s sustainment requirements and handles the personal needs of individual Soldiers. May also serve as a Master Gunner.', 'dd9cce662918dbb0692911f73e45626d75254f83d224aab1a1bd46b605f8a55f', 132, 133, null, 279, '2024-10-01', null, false, 4),
  ('782c00df-5f3b-5953-8407-93d28b377eb4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19D', 'Cavalry Scout', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Cavalry Troopers combine the superior capabilities of their equipment with their ingenuity to find, fix, close with and destroy the enemies of this nation through combinations of mobility; precise, lethal, and overwhelming firepower and devastating shock effect. The Armor branch is a team of teams, ready to fight and win anytime, anywhere, and under any conditions of battle. Troopers must possess the physical ability to function and adapt to austere environments and accomplish all missions.', 'f5ca39ba2fe8efab662f7db74db03089bd82497f0b1fc1631b6c65ce5051c8f1', 135, 135, null, 280, '2024-11-01', null, false, null),
  ('268c92f8-0bea-5041-9f48-ed9f1954dbe7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19D', 'Cavalry Scout', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Functions as a scout, driver, or gunner in the conduct of reconnaissance and security missions. Soldier acquires the following critical tasks: performs land navigation; locates targets by grid location; establishes observation posts; conducts reconnaissance and security missions and reports from mounted and dismounted positions; collects information during reconnaissance; must be proficient in the following: operates and maintains assigned and crew served weapons and equipment to include optics, communications, vehicles, VBRN equipment, and sensors; operates the Long Range Advanced Scout Surveillance System (LRAS3); prepares a range card; engages targets with direct and indirect fires, and anti- tank missiles.', 'd5f58f65997629fbe64fa30aa7d9e580ba775598d6bdf5805e7e27a6094e3e69', 135, 135, null, 281, '2024-11-01', null, false, 1),
  ('7d72c0df-6ac8-5901-802a-3394ec419ff5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19D', 'Cavalry Scout', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties as a Team Leader, leading Soldiers in a scout team or crew in the conduct of reconnaissance and security missions. Soldier acquires the following critical tasks: leads, trains, and supervises subordinate personnel on the execution of all previously listed skills; leads a scout team; performs land navigation; prepares reports; constructs a field expedient antenna; conduct vehicle resupply; directs vehicle movement; conducts team fires; conducts troop leading procedures; issues fire commands. May also serve as: Assistant Operations NCO or Operations Assistant at various echelons of command.', 'c0cab3accb71b7f2af28bedb9200214c921e9581718bb79c4c3820fb61d4dd60', 135, 135, null, 282, '2024-11-01', null, false, 2),
  ('2e323cad-e73c-54e0-b5a1-1739de58659c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19D', 'Cavalry Scout', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties as a Squad Leader leading five subordinate Soldiers in a scout squad of six scouts and one or two vehicles, either tracked or wheeled, in the conduct of reconnaissance and security missions, performs duties shown in preceding level of skill and supervises subordinate personnel in performance of these duties. Operates as a MGS Commander, leading a three scout MGS crew in the conduct of precise long range direct fire support operations for Infantry and Cavalry units. Soldier acquires and becomes an expert in the following critical skills: leads, trains, and supervises subordinate personnel on the execution of all previously listed critical skills; conducts area, route and zone reconnaissance missions; conducts screen, guard and cover missions as part of a larger unit; prepares graphic overlays; prepares combat reports using analog and digital means; employs and calculates demolition; leads mounted and dismounted patrols; directs and controls squad maneuver and fires; conduct quartering party activities; conduct passage of lines and reconnaissance handover; manage recovery operations; conducts operations in a CBRN environment; may also serve as: Assistant Operations Sergeant as a member of staff at various echelons of command; Troop Master Gunner.', 'b3bb2fc677dbe82a8573cba3056ef6f903e397edbaec4d33908d37ea485b6bb8', 135, 135, null, 283, '2024-11-01', null, true, 3),
  ('37d550ec-1949-5cdf-b3e1-82fe18ab1f6b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19D', 'Cavalry Scout', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform primary duties as a Platoon Sergeant. Performs duties shown in preceding level of skill and supervises subordinate personnel in performance of these duties. Supervises and responsible for the training, discipline, and welfare of 23 to 34 personnel and readiness of six to eight platforms. Assists and advises the Platoon Leader (PL). Soldier acquires the following critical skills: supervises, trains, and leads personnel on the previously listed critical skills; supports emplacement of an obstacle by a platoon by a platoon; supervises implementation of air defense measures; develops an engagement area; supervises quartering party activities; prepare a platoon live plan; plans and executes a platoon casualty evacuation plan; plan resupply operations; conduct platoon actions on contact; conduct a relief in place; prepare an operations order; integrate attachments; directs emplacement and activation of early warning systems; plan tactical scout training exercises; conduct civil disturbance control measures; support civilian evacuation operations. Advises and makes recommendations on all promotions and reductions. Assignments, and discipline of NCOs and Soldiers in the platoon; maintains platoon readiness, consolidates, and forwards the platoon’s casualty reports; receives and orients replacements; Coordinates the platoon’s sustainment requirements and handles the personal needs of individual Soldiers. May also serve as: Operations Sergeant as a member of staff at various echelons of command; Master Gunner; Senior Intel NCO.', '933f3f8b7ed363851e55fd0e9bda57d28e30faea7b8ceef8e313968c17d353af', 135, 135, null, 284, '2024-11-01', null, true, 4),
  ('ea19a5fc-f433-5482-a430-e67309be4c7b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19K', 'Armor Crewmember', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Armor Soldiers combine the superior capabilities of our equipment with the ingenuity of our Soldiers to find, fix, close with and destroy the enemies of our nation through a combination of mobility, precise, lethal, and overwhelming firepower, and devastating shock effect. The Armor branch is a team of teams, ready to fight and win anytime, anywhere, and under any conditions of battle. Armor Crewmembers must possess the physical ability to function and adapt to austere environments and accomplish all missions. Armor Crewmembers may serve on either the Abrams Main Battle Tank or M10 Booker platforms.', '6c0f2268c0de17c0f50837ddc16b37cdbae3c20e10794da2a0f32d38249fad67', 137, 137, null, 285, null, null, false, null),
  ('7bcf2a7b-1452-5802-9711-686480415488', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19K', 'Armor Crewmember', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform primary duties as a loader or driver. Must strive to become proficient in the following areas:
a. Loader: Stows and cares for ammunition, loads the main gun and the coaxial machine gun ready box. Aims and fires the loader’s machine gun. Accountable to the tank commander for the maintenance of communications equipment. Ensures that communication equipment is inspected and is operating properly. Loads frequencies and conducts radio checks as part of routine maintenance. Search for targets, maintain rear security, and act as air guard or antitank guided missile (ATGM) guard, before engagement actions are initiated. Assists the tank commander as needed by providing directions to the driver, so the tank maintains its position in formation. Dismounts tank to assist in the positioning of tank or ground guiding. Responsible for the load plan and overall maintenance of the vehicle.', '3080d08248e46f594601ebeff6369e6ae7ac55d4d300231c4dfc843649f0b5b3', 137, 137, null, 286, null, null, false, 1),
  ('746fa255-01c0-5f21-a60b-a6004ddf1d3d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19K', 'Armor Crewmember', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs primary duties as gunner and responsible for two subordinates. Searches for targets, aims, and fires both the main gun and the coaxial machine gun. Responsible to the Tank Commander for the immediate supervision of and assisting with the overall maintenance of the entire vehicle, with emphasis on the fire control system and armament, and accountability of all associated equipment. Responsible for the manual inputs and manipulation of the fire control system through the gunner’s control panel. Assumes the responsibilities of the tank commander in their absence. Maintains the tanks communication and internal control systems. Responsible for the training and development of their subordinates. May also serve as: Assistant Operations Sergeant or Operations Assistant as a member of staff at various echelons of command.', '52033ea9f4716fc947837457244644efce3cd4e28786650b4831132b15fe003b', 137, 137, null, 287, null, null, false, 2),
  ('b1997256-c78f-52f1-9ce9-b0edf7331616', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19K', 'Armor Crewmember', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs primary duties as tank commander. Must become an expert in the following critical skills: tank weapon systems, requesting indirect fires, and executing land navigation using both digital systems and more traditional methods, such as terrain association. Brief crew, direct the movement of the tank, submit all reports, and supervise initial first-aid treatment and evacuation of wounded crewmembers. Control vehicle direct fires. Ensure the welfare of the crew. Lay the gun for direction. Issue fire commands. Prepares graphic overlays and detailed combat reports using analog and digital communications. Conducts quartering party activities, passage of lines, and CBRN operations. Trains crew on the maintenance and accountability of assigned equipment, and the tactical employment of the tank. Know and understand the company mission and company commander’s intent. Maintain situational awareness by using all available optics for observation, monitoring radio transmissions and digital displays. Responsible for ensuring equipment is stowed and secured properly per unit load plans or Standard Operating Procedures (SOP). Responsible for fostering crew cohesion and for the medical and administrative readiness of the crew. May also serve as: Assistant Operations Sergeant in a staff at various echelons of command; or Master Gunner.', '360e7f380ecf957107dc4d487715a530002b9581df5aed6a5943a6f4856f7478', 137, 137, null, 288, null, null, false, 3),
  ('0c2a01d8-d68e-53b6-b75f-22f4693e9e97', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19K', 'Armor Crewmember', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform primary duty as Platoon Sergeant. The Platoon Sergeant is second in command of the platoon and the most experienced enlisted member. In the absence of the Platoon Leader the Platoon Sergeant performs all duties of the Platoon Leader. Assist and advise the Platoon Leader (PLT LDR). Mentor crewmembers, other NCOs, and the PLT LDR on tactical and technical employment of the platoon’s assigned equipment. Supervise the platoon’s administration, logistics, and maintenance. Supervises individual training. Advises and makes recommendation on all, promotions and reductions, assignments, and discipline of NCOs and enlisted Soldiers in the platoon. Update the PLT LDR on appropriate reports, and forwards any reports needed by company HQ. Take charge of task organized elements in the platoon during tactical operations, including quartering parties, support elements. Serve as a tank commander/section leader when the platoon operates mounted. Monitor the morale, discipline, and health of platoon members. Ensure Soldiers maintain all equipment. Coordinates and supervises company-directed platoon resupply operations. Collect, prepare, and forward logistic status updates and requests to the company 1SG. Ensure ammunition and supplies are properly and evenly distributed after the platoon consolidates on the objective and while the platoon reorganizes. Ensure support supplies are present. Direct the platoon’s casualty evacuation (CASEVAC) process. Maintain platoon strength information, consolidates, and forwards the platoon’s casualty reports, and receives and orients replacements. Monitor the commander’s tactical display to maintain awareness of the platoon’s positions relative to the company formation. Maintain accountability to the PLT LDR for the training, discipline, and welfare of the Soldiers in the platoon. Coordinate the platoon’s sustainment requirements and handle the personal needs of individual Soldiers. May also serve as: Operations Sergeant or Assistant Operations Sergeant in a staff at various echelons of command: or Master Gunner.', 'aac8023f3186f7287cfc2768519db0518c2f3222ba7a64105798a2807c3a8ac0', 137, 138, null, 289, null, null, false, 4),
  ('12382045-884e-5465-8046-30bd7229560f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19Z', 'Armor Senior Sergeant', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Armor Senior sergeant serves as principal NCO in an Armor Company, Cavalry Troop, or operations staff within in Combined Arms Battalion, Cavalry Squadron, or higher-level organizations.', '4e05b9f33d0cadcad9272ca70d28130554e2fd7b149701f5974a3d3b883ee043', 140, 140, null, 290, '2024-11-01', null, false, null),
  ('cae3058f-fc45-56b4-970a-2e88546bd96f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19Z', 'Armor Senior Sergeant', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Armor Senior Sergeant serves as the principal NCO in an Armor Company, Cavalry Troop, or Operations Sections of a Combined Arms Battalion, Brigade Combat Team, or higher-level organizations. Provides tactical and technical guidance and professional support to subordinates and makes recommendations to superiors in the accomplishment of their duties. The key developmental position for MOS 19Z5O is a First Sergeant.', '1906beed109ef9545232c50ea6892c39ba73846f70bd0719c814a3c8f07c69a3', 140, 140, null, 291, '2024-11-01', null, false, 5),
  ('271f8974-715b-5683-8585-fe86791de3be', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '19Z', 'Armor Senior Sergeant', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', '(a) SGM: Serves as principal noncommissioned officer in a Combined Arms Battalion, Cavalry Squadron, or higher to supervise the processing of operations and intelligence information. Provide tactical and technical guidance to subordinates and professional support to both subordinates and superiors in accomplishment of their duties. Plans, coordinates, and supervises activities pertaining to organization, training and combat operations. Edits and prepares tactical plans and training material. Coordinate implementation of operations, training programs and communications activities.
(b) CSM: Serves as the principal advisor to the Commander (Battalion/Squadron, and higher-level unit) on all enlisted issues and is primarily focused on the training, maintaining, caring, and leading of the unit''s Soldiers, facilities and equipment. Assists the Commander in the implementation of command policies and establishes and enforces standards related to the appearance and conduct of all Soldiers within the command. Develops and executes NCO Professional Development Programs within the command and advises/counsels Soldiers on issues related to training, education, and professional development. Responsible for the unit’s individual skills training program for all CMF’s', '147ade31dd955beb8fc236a5542ccdd2b04fd00b1e626b22472499f03ecf64ca', 140, 140, null, 292, '2024-11-01', null, false, 6),
  ('6828e1f5-a777-57e6-893a-113ee1236c96', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25B', 'Information Technology Specialist (Info Tech Spec)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Information Technology Specialist installs, operates, maintains, and performs limited field level maintenance on computer systems, Information Technology (IT) networks, and cable and wire communication systems. Performs system administration (SA) on computers and servers within the computing environment (CE) and the network environment (NE). Performs network administration (NA); installs, configures and maintains network computing equipment within the network (i.e. routers, switches, desktop, and laptop computers). Performs duties associated with Communication Security (COMSEC) Account Management IAW AR 380-40. Provides SA to IT platforms in varying operational environments. Provides SA and direct support for digital management systems. Performs cyber security functions, provides the security services and attributes of availability, authentication, confidentiality, integrity and non- repudiation; verifies and implements network security policy vulnerabilities from cyber network defense teams; Network and IT management, which includes incident and problem processing, change request processing, availability management and user interaction.', 'c791f3fb3d2567bb14add02084abc9e668d2a53f5d855c9281eca39d569ef9a0', 142, 142, null, 293, '2025-10-01', null, false, null),
  ('be0f533a-cf9a-5385-a9e2-2b1cce211aeb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25B', 'Information Technology Specialist (Info Tech Spec)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Installs, operates, repairs, maintains, and performs limited field level maintenance on cable and wire systems. Performs SA functions at multiple echelons (Battalion to Army and National levels). Installs, operates, and maintains servers and information systems in the TOC. Provides direct support to end users for all CE operating systems, peripherals, and applications, including SA of digital management systems. Implements cyber security measures to computer systems and networks. Installs, tests, maintains, and upgrades operating systems software and hardware to comply with cyber security requirements. Works under the direct supervision of the Senior Information Technology Specialist for all network related functions.', '854d109ba23392837c527290568695b381e7a99a8cf2cda3ab8e360c811d2fcc', 142, 142, null, 294, '2025-10-01', null, false, 1),
  ('61cfede0-58ff-5556-854e-d65c23f02e10', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25B', 'Information Technology Specialist (Info Tech Spec)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs senior operator and SA functions at multiple echelons (Battalion to Army and National levels). Coordinates and supervises team member activities in the construction, installation, repair and recovery of cable and wire communications systems. Provides advanced level CE and NE support for unclassified and classified systems. Supervises the installation, operation and maintenance of the network and computer systems. Supervises direct support to end users for all CE operating systems, peripherals, and applications. Trains and assists less experienced Soldiers in the installation, operation and troubleshooting of information and computer systems. Configures, improves performance, and test network servers in tactical operations centers. Supervises and operates systems in support of digital management systems. Identifies potential cyber security risks and takes appropriate corrective and recovery actions as directed. Additionally, supervises the IT service workforce and serves as an alternate COMSEC Account Manager (CAM) within units that have a documented assistant CAM position.', 'a16899d58e6ca48b9497d90549101ff295e5cc37b0d92e2e04aa178019b3bea7', 142, 142, null, 295, '2025-10-01', null, false, 2),
  ('991e15ae-f6dd-5205-b07d-2c6a28248e2c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25B', 'Information Technology Specialist (Info Tech Spec)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises the deployment, installation, operation and maintenance of computer systems and the IT network and supervises, coordinates all phases of construction, recovery, repair and maintenance of cable and wire distribution systems. Performs senior level SA functions, and advance level CE. Provides support for the NE in unclassified and classified networks. Manages accounts, network rights, and access to CE systems and equipment. Supervises the installation and operation of systems in support of digital management systems. Writes standard operating procedures for all automation systems within the IT network and assists in the planning, configuration, management, and monitoring of the LAN. Assists in the planning and implementation of the units’ computer life cycle program. Develops and provides training to service support personnel, functional users and staff personnel in computer and information systems matters. Additionally, supervises the IT service workforce and serves as the CAM within units that have a documented CAM position.', 'c57cbcf5023bcd2559bfde25aa7b85a703971e3e7b3756e6eb1c6258cbc5a674', 142, 142, null, 296, '2025-10-01', null, false, 3),
  ('a4651249-5061-54f9-afa8-f781027fa937', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25B', 'Information Technology Specialist (Info Tech Spec)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans, supervises, coordinates, and provides technical assistance for computer systems and IT networks. Performs senior level NA functions as well as advance level CE support. Assists in data system integration and provides support for the NE in unclassified and classified networks. Supervises account management, network rights, and access to NE systems and equipment. Manages operations in support of digital management systems. Implements response actions in reaction to security incidents. Plans and executes the unit level computer life cycle program. Develops and provides training to staff personnel on computer and IT matters. Supervises and coordinates the development of the IT network in the TOC and assists in the planning, configuration, management, and monitoring of the LAN. Assists in the development of IT management policies and organizational procedures. Participates in the development of continuity plans, IT protocols, and establishment of best practices. Briefs and advises staff and operational personnel on IT matters. Coordinates high level or contractor support maintenance for assigned equipment.', 'b1d5bc222eff239686c022813440a6a0d8c7af4377440b817db85fc961092f1a', 142, 143, null, 297, '2025-10-01', null, false, 4),
  ('5d5cb768-3424-5977-b67c-e0992ee0e337', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25D', 'Cyber Network Defender', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs the duties associated with the five Computer Network Defense (CND) specialties (i.e., Infrastructure Support (IS), Analyst (AN), Incident Responder (IR), Auditor (AU) and Manager (MGR)), Information Assurance Technical (IAT) Levels I-III functions, Information Assurance Management (IAM) Levels II-III functions, as required by skill level IAW AR 25-2 and DoD 8570.01-M. CND protects against, monitors for, performs analysis of, responds to and detects unauthorized activity in the cyberspace domain, which includes deployment and administration of the CND infrastructure; performs deliberate actions to modify information systems or network configurations in response to CND alert or threat information; collects data gathered from a variety of CND tools to analyze events and warn of attacks that occur within the environment; plans response activities to contain and eradicate cyber incidents within the network environment or enclave; responds by validating incidents, performs incident correlation and trending, conducts network damage assessments, and develops response actions; performs assessments of threats and vulnerabilities within the network environment or enclave and identifies deviations from acceptable configurations, enclave policy, or local policy:', 'd7052638f8c1a8358a18c150002dd5beb7a22f4e5284b0097d7327fb33de57fe', 144, 144, null, 298, null, null, false, null),
  ('cf6043fd-6773-5b4c-847d-27abd93be8af', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25D', 'Cyber Network Defender', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Tests, implements, deploy, maintain and administer CND infrastructure hardware and software required to provide defense-in-depth to the network and resources. CND tools may include, but is not limited to routers, firewalls, intrusion detection systems and/or intrusion prevention systems, and other CND tools as deployed within the computing environment (CE) or network environment (NE). Responds to crisis or urgent situations within the network to mitigate immediate and potential cyber threats. Predominantly, serves in IS positions and in AN positions within limited organizations. Performs CND and IAT Level II functions in accordance with AR 25-2 and DoD 8570-01M. 25D3O will not perform duties as a Drill Sergeant or Recruiter.', 'cf32f2d7a0341538388ec66344b816249cd7d1b288c3c6930f7ce38a1f1dc09d', 144, 144, null, 299, null, null, false, 3),
  ('b3bd5a52-631d-5bec-82e1-6ed92c2dea53', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25D', 'Cyber Network Defender', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Uses defensive measures and information collected from a variety of sources (including intrusion detection system alerts, firewall logs, network traffic logs, and host system logs) to identify, analyze, and report events that occur or might occur within the network in order to protect information, information systems, and networks from threats. Provides detailed analysis reports as necessary to support mission requirements. Predominantly, serves in AN positions and in IS positions within limited organizations. Performs CND and IAT Level II-III functions as required by skill level, AR 25-2 and DoD 8570.01M. 25D4O will not perform duties as a Platoon Sergeant, Drill Sergeant, or Recruiter.', '8476b11a2e814b939980c3648d435416411c05aeb1be7bbce94a117efcd77f23', 144, 144, null, 300, null, null, false, 4),
  ('1e6fe72e-548e-58af-b1e6-04aa52b48f61', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25D', 'Cyber Network Defender', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Uses mitigation, preparedness, and response and recovery approaches, as needed, to maximize network and information system confidentiality, integrity, and availability. These tasks include, but are not limited to creating and maintaining incident tracking information; planning, coordinating, and directing recovery activities; and incidents analysis tasks, including examining all available information and supporting evidence of artifacts related to an incident or event. Conducts assessments of threats and vulnerabilities (through such tasks as authorized penetration testing, compliance audits and risk assessments) to determine deviations from acceptable configurations and enterprise or local policies; and develops and/or recommends appropriate mitigation countermeasures. Respond to crisis or urgent situations within the network to mitigate immediate and potential cyber threats. Conducts assessments of threats and vulnerabilities (through such tasks as authorized penetration testing, compliance audits and risk assessments) to determine deviations from acceptable configurations and enterprise or local policies; and develops and/or recommends appropriate mitigation countermeasures. Develops and provides training to command and staff on CND matters. Predominantly, serves in IR positions and in AU and MGR positions within limited organizations. Performs CND functions, IAT Level III functions and IAM Level II-III functions as required by skill level, AR 25-2 and DoD 8570.01M. 25D5O will not perform duties as a First Sergeant.', '13ddb908c346350f9ae04467275f6f14ef54519d67f582cfff67c63e54652d7c', 144, 144, null, 301, null, null, false, 5),
  ('7e1e6044-8a9a-56bf-9308-4b2b7afbddaa', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25D', 'Cyber Network Defender', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises, plans, coordinates and directs CND operations within their organization. Serves as the senior enlisted CND advisor and provides senior level CND technical and tactical advice to command and staff on CND matters. Leads the establishment of command level CND tactics, techniques, procedures (TTP), and policies. Assists in the development of organizational Continuity of Operations Plan (COOP). Responsible for system lifecycle management, technology integration, and DoD Information Assurance Certification and Accreditation Process (DIACAP) as it relates to CND functions and mission. Serves in MGR positions above the Corps echelon. Performs CND IAM Level III functions as required by skill level, AR 25-2 and DoD 8570.01-M. 25D6O will not preform duties as a Command Sergeants Major.', 'c33d43530b26e50aee85e68346190c3ff371c02c7d1f52d93fa430fd00a1f70f', 144, 145, null, 302, null, null, false, 6),
  ('00e62b85-9071-5b7a-88aa-fba8e390e448', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25E', 'Electromagnetic Spectrum Manager (Electro Spectrum Mgr)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The electromagnetic spectrum manager develops, produces, and distributes the Signal Operating Instructions (SOI) using computer software programs; maintains a database of frequency requests and assignments and performs periodic reviews and updates; takes steps to resolve frequency interference reports and maintains a database of interference incidents; prepares and forwards properly formatted frequency requests to the appropriate military or civilian agency for coordination and approval and maintains contact with them; performs unlimited frequency planning, selection, and deconfliction using automated tools; performs system field level maintenance on authorized signal equipment and associated electronic devices; and operates and performs preventive maintenance checks and services (PMCS) on assigned vehicles and power generators.', '3aa52c23d355c732efe39a7600eff50510ae99165971a55bd90c36bd6f71ff32', 146, 146, null, 303, null, null, false, null),
  ('43850056-0b82-51c8-acf7-8624a44067b8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25E', 'Electromagnetic Spectrum Manager (Electro Spectrum Mgr)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Receives communications network input, interprets information and creates frequency plans, organizes the data logically, and generates and distributes SOI to all users electronically or in paper copy. Prepares properly formatted frequency requests, forwards the request to the appropriate civilian or military agency, receives the frequency approval, and submits assignments to the frequency database. Generates Satellite Access Request (SAR) to proper controlling authority, receives Satellite Access Authorization, receives satellite frequency approval, submits assignment to frequency database, and informs user of the authorized frequencies. Performs regular frequency database reviews and submits requests for update when necessary. Receives requests for frequency use authorization, nominates frequencies from frequency databases, makes assignments in the database, and notifies the requestor of the assignment. Maintains contact with military and civilian agency for the request and deconfliction of frequency use within the areas of responsibility. Ensures spectrum supportability for frequency emitting equipment which is being used within a specified area and obtains electronic warfare (EW) clearances. Receives frequency interference reports from victim units, takes appropriate steps to resolve interference, reports problem to higher headquarters for assistance, and maintains frequency charts, diagrams, reports, and a database of frequency interference incidents. Performs field level maintenance on authorized signal equipment and associated electronic devices. Operates and performs PMCS on assigned vehicles and power generators. 25E3O will not perform duties as Drill Sergeants or Recruiters.', 'ee09049bafdcacbd333acc13de65237272b284d603d5ced120a1d860ca5a1889', 146, 146, null, 304, null, null, false, 3),
  ('34998892-900e-53a2-bd0a-310870570bb2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25E', 'Electromagnetic Spectrum Manager (Electro Spectrum Mgr)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. Performs the following additional tasks: validates subordinate Army unit’s electromagnetic spectrum (EMS) request using Standard Frequency Action Format (SFAF). Reviews requirements for SAR. Prepares division and higher level echelon technical reports. Serves as principle or subordinate spectrum manager in JTF/CJTF or on the staff of a Joint, Combined, or Coalition activity who develops Joint Spectrum Use Plan, maintains, assigns, and deconflicts EMS information in JTF/CJTF database and resolves EMS interference in a JTF/CJTF. 25E4O will not perform duties as Platoon Sergeants, Drill Sergeants or Recruiters.', '53fca57c71f3fa42a36c70baf3f365f4e6a4f6d481130bc62ff8e97d8db3a522', 146, 146, null, 305, null, null, true, 4),
  ('2ac155ec-def6-5fe9-9f5d-a4f2a58e573e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25E', 'Electromagnetic Spectrum Manager (Electro Spectrum Mgr)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. . Performs the following additional tasks: manages division and higher level EMS databases. Assists users in obtaining spectrum supportability through appropriate federal and host nation agencies. Assists in the resolution of frequency interference incidents, reports unresolved problems to higher headquarters for assistance, and reviews frequency interference databases for trends and repeat incidents. Provides advice and assistance to subordinate units for mission accomplishment and career progression of other Electromagnetic Spectrum Managers. Serves as advisor for EMS management to the commander. Prepares spectrum specific briefings for commander and staff. Develops theater level and higher Army EMS management policy and procedures. 25E5O will not perform duties as a Frist Sergeant.', 'e12ea7813f152fa0c23ca62faa7e2812f16dc9777b173fdf821efc81d3664b27', 146, 146, null, 306, null, null, true, 5),
  ('2cc25aab-1bc0-5147-81a4-68b472504fac', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25E', 'Electromagnetic Spectrum Manager (Electro Spectrum Mgr)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. Performs the following additional tasks: manages major geographical and functional command databases. Assists users and subordinate units in obtaining spectrum supportability through appropriate federal and host nation agencies. Assists in the resolution of frequency interference incidents, reports unresolved problems to higher headquarters for assistance, and reviews frequency interference databases for trends and repeat incidents. Provides advice and assistance to subordinate units for mission accomplishment and career progression of other Electromagnetic Spectrum Managers. Serves as advisor for EMS management to the commander. Prepares spectrum specific briefings for commander and staff. Develops theater level and higher Army EMS management policy and procedures. 25E60 will not perform duties as Command Sergeants Major.', 'a506923f094bcbc8c5cb70a35f0b824a1683d66e3e9b78e5d76664be2b9ed58c', 146, 147, null, 307, null, null, true, 6),
  ('757b78dc-8616-5e49-b2c3-9bbfe2d89efd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25H', 'Network Communication Systems Specialist (Net Com Sys Spec)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Network Communication Systems Specialist supervises, installs, operates and performs limited field level maintenance on commercial and tactical fiber, cabling and wiring, IP based high speed electronic nodal systems, integrated network control centers, network management facilities, associated multiplexing and subscriber interface equipment, multichannel line-of-site systems and associated relays, tropospheric scatter communications systems, tactical terrestrial satellite communication systems, anti-jam reliable tactical terminals, communications security (COMSEC) devices, and associated equipment. Performs network management functions in support of maintaining, troubleshooting, and reengineering of associated network assets in support of operational requirements. Installs, operates, perform strapping/re-strapping, Preventive Maintenance Checks and Services (PMCS), and field level maintenance on COMSEC devices. Operates and performs PMCS on assigned vehicles, power generators and equipment.', 'ead7035710b4fcc1b7060a611be040306e074984f090131e26bee1cf1a933f1c', 148, 148, null, 308, '2025-10-01', null, false, null),
  ('d89b415b-846f-5915-9396-66cc7e66be5d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25H', 'Network Communication Systems Specialist (Net Com Sys Spec)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Installs, operates, repairs and performs limited field level maintenance on commercial and tactical fiber, cabling and wiring, IP based high speed electronic nodal systems, integrated network control centers, network management facilities, associated multiplexing and subscriber interface equipment, multichannel line-of-site systems and associated relays, tropospheric scatter communications systems, tactical terrestrial satellite communication systems, anti-jam reliable tactical terminals, COMSEC devices, and associated equipment. Uses computers and software tools to perform system/network operations and analyze BIT/BITE diagnostics to isolate faults.', '4ed3229309eef816b37d759542b5dd0ddc9f20c8dbcf8beac53dad2c5bcf7c0a', 148, 148, null, 309, '2025-10-01', null, false, 1),
  ('25e03cea-d1c9-5aa0-b894-a8687352d59a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25H', 'Network Communication Systems Specialist (Net Com Sys Spec)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and performs as team leader or team member, in the installation, operation, employment, and limited field level maintenance on commercial and tactical fiber, cabling and wiring, coordinates remote trunking operations, updates line route maps and overlays, IP based high speed electronic nodal systems, integrated network control centers, network management facilities, associated multiplexing and subscriber interface equipment, multichannel line-of-site systems and associated relays, tropospheric scatter communications systems, tactical terrestrial satellite communication systems, anti-jam reliable tactical terminals, COMSEC devices, and associated equipment. Interprets orders and compiles system statistics for the shift and node. Assists in reconfiguration of IP based nodal systems equipment as needed. Requests logistical support for teams or shifts. Implements network operations center generated changes to support operational requirements.', '5c5ab8ee03f7816ea5843b8d1d4963157f53531dec8af9d4ba10d14f20708477', 148, 148, null, 310, '2025-10-01', null, false, 2),
  ('e42030d8-a59b-5a87-9159-59697935ef35', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25H', 'Network Communication Systems Specialist (Net Com Sys Spec)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and performs complex and multifaceted nodal operations functions. Supervises and coordinates all phases of construction, recovery, repair and maintenance of commercial and tactical fiber, cabling and wiring, and associated multiplexing, reeling, and testing equipment. Supervises the installation, operation, deployment, provisioning, and maintenance of electronic IP based nodal assemblages, combat net radios and all related COMSEC devices. Disseminates network orders, compiles, and submits operational statistics reports and processes requests for logistic support. Coordinates, integrates and controls the operation of IP based nodal systems with associated transmission systems and local subscriber interface equipment. Performs network operations center tasks for planning, reconfiguration, and employment of nodal systems equipment. Ensures contingency operations plans and nodal routing subsystems are correctly maintained in nodal databases to reflect current operational scenarios. Troubleshoots complex system faults, supervises or corrects failures to meet system availability and reliability standards. Interprets, disseminates and implement network changes/reconfigurations affecting nodal network architecture operations. Conducts technical, operational and maintenance training of subordinates on operational equipment and procedures.', 'e80b11a31fdf0c50ca8af0256b9902c97d5a492247c2bcfad65f44a6d13d8426', 148, 148, null, 311, '2025-10-01', null, false, 3),
  ('47183270-fbd3-5b71-80c8-7f5d73d2b619', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25H', 'Network Communication Systems Specialist (Net Com Sys Spec)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans, coordinates, and supervises installation, operation, maintenance, and management of network communication systems, including radio, tactical satellite terminals, switching, cable, and automation equipment. Supervises the installation, operation, strapping, re-strapping, preventive maintenance checks and field level maintenance on COMSEC devices. Directs restoration, and alternate routing of circuits, trunks, links, and systems. Develops and implements field level signal maintenance programs. Provides operational and technical assistance to subordinates and commanders. Verifies frequency operational requirements, network communication systems service requests, and disseminates operations information to ensure command and control communications connectivity. Requests and ensures appropriate logistical support is always available. Assimilates and reports system/network statistics. Develops and implements training programs for Signal personnel. Uses computers to process operational and administrative information. Operates system control facilities as part of Signal organization management functions.', '7adca506b9981982e2c00c7326e5c5e53924908af7cb253e29183d84bb158c74', 148, 149, null, 312, '2025-10-01', null, false, 4),
  ('f780c203-4210-5aa6-926e-6af6f17a21fe', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25S', 'Satellite Communication Systems Specialist (SATCOM Sys Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The satellite communication systems specialist supervises, installs, operates and maintains tactical through strategic multichannel satellite communications ground terminals, systems, networks and associated equipment. Supervises, installs, operates and maintains strategic earth terminal complexes to include associated antennas, ground terminals, and technical control facilities. Performs engineering quality control and continuity testing of circuits, trunks, links, systems, and facilities.', 'f17fe5422f50e12dcf76816a22b2a797dbf0ae40d524d29f4384012c0d409493', 150, 150, null, 313, '2025-10-01', null, false, null),
  ('2a4068a4-3156-5ccf-a1e0-f36cd26e3556', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25S', 'Satellite Communication Systems Specialist (SATCOM Sys Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Installs, configures, operates, aligns, conducts performance tests and performs field level maintenance on tactical through strategic satellite communications systems and technical control facilities. Analyzes diagnostics to isolate faults to the Line Replaceable Unit. Installs, operates, and performs Preventative Maintenance Checks and Services (PMCS), and field unit level maintenance. Operates and performs PMCS on assigned vehicles. Installs, operates, and performs PMCS on assigned power generators.', 'b104fd88025f81adc49754cb4aa7641e2d084ed92647cff61f4a482683388319', 150, 150, null, 314, '2025-10-01', null, false, 1),
  ('3b54201a-43a1-5b63-bfaf-dd8e0c5b3fa9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25S', 'Satellite Communication Systems Specialist (SATCOM Sys Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises operations and assists team members in the installation and operation of tactical and strategic telecommunication systems and networks, including satellite communication systems and technical control facilities. Supervises, performs and assists team members in the performance of field unit level maintenance on assigned communications equipment. Requests logistical support. Prepares input for statistical and other operational reports. Identifies and reports electronic jamming and deception and applies appropriate Electronic Counter Counter-Measures (ECCM).', 'c1367117dd8f53db81ac71b97908dd1737b748ea73683ba62d5cd6e51eca37cf', 150, 150, null, 315, '2025-10-01', null, false, 2),
  ('b38ab4e3-acf4-56bc-bc7b-d36a38fa5b0f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25S', 'Satellite Communication Systems Specialist (SATCOM Sys Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans, supervises, and integrates the installation, operation, and maintenance of tactical and strategic telecommunication systems and networks, including satellite communication systems and technical control facilities. Establishes workloads, work schedules and maintenance priorities. Performs and supervises quality control inspections. Provides subordinates technical assistance in resolving connectivity problems, complex maintenance faults, and during contingency situations. Requests applicable logistic support. Trains subordinate personnel in the operation and maintenance of associated equipment. Consolidates system and network statistics and reports and submits them to network control/management headquarters. Executes telecommunications service orders. Supervises and performs management and administrative duties related to personnel, systems operations, and logistics. Performs coordination with Army, Joint and commercial activities to accomplish distributed communications at all levels of command.', 'f2802b5d15ce3725ed34d8ebb6cdbb369ee7b9b8720bb5105fcb778e6fbfd0ad', 150, 150, null, 316, '2025-10-01', null, false, 3),
  ('85a4fc5d-6cf1-5139-a4e2-2e04cf715e87', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25S', 'Satellite Communication Systems Specialist (SATCOM Sys Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises, plans, and directs the installation, operation and maintenance of tactical and strategic telecommunication systems and networks, including satellite communication systems and technical control facilities. Performs Platoon Sergeant and technical staff duties. Provides technical advice to commanders and assistance to subordinates. Develops and ensures compliance with policy and procedures for all types of operational environments. Determines capabilities and limitations of assigned equipment. Disseminates telecommunications service orders to subordinate shifts, assemblages, or stations. Conducts technical evaluations of equipment and facilities. Establishes and maintains liaison with supported and supporting activities or units. Organizes, instructs, and counsels subordinate personnel. Manages security programs for telecommunications operations.', '793d85095cd4f42ce258ce3f4d229399fcee5bac883464428b23a12f31c29916', 150, 150, null, 317, '2025-10-01', null, false, 4),
  ('17475d10-0bf0-579d-8a5f-e0e66cc17250', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25U', 'Signal Operations Support Specialist (Sig Ops Spt Spc)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The signal operations support specialist supervises, installs, operates, deploys, maintains, troubleshoots, trains, and provides information systems support for Army radio systems, vehicular and dismounted configurations; Performs Network Management Operations for Internet Protocol (IP) based radio systems and other tactical radio communications systems. Configures and troubleshoots Local Area Networks and Routers. Installs, operates, and maintains field expedient antenna solutions. Performs field level unit maintenance on authorized communications and electronics systems and COMSEC devices and prepares maintenance and supply requests for field level signal support. Disseminates and enforces signal policies and integrates signal systems and networks with adjacent units. Installs, operates, and maintains Radio Retransmission (RETRANS) operations and performs Preventive Maintenance Checks and Services (PMCS) on assigned vehicles and power generators.', '8d954eea79df2434373f323f566266e39d2d8159fb882891fb110546c9051a2c', 152, 152, null, 318, '2025-10-01', null, false, null),
  ('4fb3ae57-2c94-5333-95a2-1a8db55f6b02', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25U', 'Signal Operations Support Specialist (Sig Ops Spt Spc)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Installs, deploys, maintains, troubleshoots, and assists the GPU with POR and COTS communications equipment, as appropriate, within the TOC, CP, and vehicle platforms. This includes MCS, C&E, COMSEC devices, telephone wire, LANs, and routers. Performs field level unit maintenance on authorized C&E systems and COMSEC devices and prepares maintenance and supply requests for field level signal support. Disseminates and enforces signal policies. IOMs RETRANS operations and performs PMCS on assigned vehicles and power generators. Provides access to Network capabilities and performs NCS and Network Management Operations for tactical radio networks and automated local area networks.', 'e9e4d9ae6bd7ef31074734657bb08d728653a58f71f646569d9cb20312e9be75', 152, 152, null, 319, '2025-10-01', null, false, 1),
  ('e05be6d2-de22-519c-a19a-e6d1b8d83361', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25U', 'Signal Operations Support Specialist (Sig Ops Spt Spc)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises, installs, deploys, maintains, troubleshoots, trains, and assists the GPU with POR and COTS communications equipment, as appropriate, within the TOC, CP, and vehicle platforms. Provides access to Network capabilities and performs NCS and Network Management Operations for tactical radio networks and automated local area networks. Supervises and performs field level unit maintenance on authorized C&E systems and COMSEC devices and prepares maintenance and supply requests for field level signal support. Disseminates and enforces signal policies. Supervises and IOMs RETRANS operations and supervises PMCS on assigned vehicles and power generators. Recognizes electronic countermeasures (ECM) and implements electronic counter-countermeasures (ECCM).', '6860ab1bb7ffd28bf39cf568777f3bc76f09a14db4c266449a1253d028413cf6', 152, 152, null, 320, '2025-10-01', null, false, 2),
  ('8022626a-a844-585f-bab9-fa739688f57d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25U', 'Signal Operations Support Specialist (Sig Ops Spt Spc)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans, supervises, deploys, maintains, troubleshoots, trains, and assists the GPU with POR and COTS communications equipment, as appropriate, within the TOC, CP, and vehicle platforms. Provides access to Network capabilities and performs NCS and Network Management Operations for tactical radio networks and automated local area networks. Supervises and performs field level unit maintenance on authorized C&E systems and COMSEC devices and prepares maintenance and supply requests for field level signal support. Disseminates and enforces signal policies and integrates signal systems and networks with adjacent units. Supervises and IOMs RETRANS operations and supervises PMCS on assigned vehicles and power generators.', 'c746720461af8d516724d7a3794bebf22a3409bb06145fd62e8469f1b9a06a67', 152, 152, null, 321, '2025-10-01', null, false, 3),
  ('a891510f-dc9c-582f-b144-ac6bef86e811', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25U', 'Signal Operations Support Specialist (Sig Ops Spt Spc)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans, supervises, deploys, maintains, troubleshoots, and assists the GPU with POR and COTS communications equipment, as appropriate, within the TOC, CP, and vehicle platforms. Provides access to Network capabilities and performs NCS and Network Management Operations for tactical radio networks and automated local area networks. Plans and requests signal logistics support for field level operations and maintenance. Develops and implements Battalion and Company level training in the use of signal systems. Participates in and enforces the results of staff level planning that develops and disseminates signal policies, Operation Orders annexes, and various reports. Integrates signal systems and networks with adjacent units, coordinates external signal support, and provides technical advice to commanders and subordinate units. Plans and directs the RETRANS operations team and PMCS on assigned vehicles and power generators.', '5dc2e625c87ddf8abcbf632d3bbabf5f6a6d4f5df6503f8a94a38b3738bcbc38', 152, 152, null, 322, '2025-10-01', null, false, 4),
  ('cdca79c6-a4d8-5936-a819-aeacbbec3cd6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25Z', 'Senior Signal Sergeant', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Senior Signal Sergeant plans, coordinates, directs, and supervises the installation, operation, and management of information technology and telecommunication networks. Provides technical advice and assistance to commanders, staff, and subordinate units. Coordinates Signal activities with higher, lower, and adjacent headquarters. Performs Signal staff and senior operations NCO functions, to include writing Signal policy, procedures, operational plans, orders, and reports. Understands and assimilates emerging technology to control and monitor network status within the operational environment. Develops battlefield Signal operational plans to support organizations at battalion and higher levels, and for Joint and Combined Commands and activities. Operates as part of an Army modular component at the service, joint, inter-agency, inter-governmental, and multi-national levels in multi-domain operations.', 'a847094faf64cba3f14415da12524edfbd66bc9edf96da81d82bef1ece268d0c', 154, 154, null, 323, '2025-10-01', null, false, null),
  ('54dc334b-a467-5014-9bb0-461d42fe8d3b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25Z', 'Senior Signal Sergeant', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Signal Master Sergeant leads, manages, and trains company and battalion level signal activities. Provides oversight and experience inclusive of all aspects of the Signal Warfighting Functions. Maintains Signal readiness through organizational expertise and operational guidance in the areas of various functions such as IT operations, signal support operations, communication systems, strategic networks, and signal systems to the multi- domain operations at all echelons. The Signal First Sergeant supervises the manning, training, equipping and combat readiness of a company level of command. Maintains unit readiness, enforces standards, and ensures the health and welfare of Soldiers, DA Civilians, and their families across the command.', '61f634dd536937669d2e2f3f3d267b5d433f6613d904c18c315752f5d14b6428', 154, 154, null, 324, '2025-10-01', null, false, 5),
  ('71713e06-7096-5caf-a087-2f2df96ecd36', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '25Z', 'Senior Signal Sergeant', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Signal Sergeant Major provides strategic level advice to command and staff on all aspects of Signal operations. Supervises, plans, coordinates, and directs Signal Multi-Domain Operations at all echelons. Mentors command leadership and subordinate personnel on Signal functions and capabilities. Facilitates and synchronizes joint Signal functions and capabilities at the corps, theater, ASCC, and inter-service level and develops strategic concepts. The Signal Command Sergeant Major coordinates and supervises activities pertaining to organizational and strategic Signal operations. Enforces standards of performance, training, appearance and conduct of Enlisted personnel within the command.', '1e84439d27188aba9def30c2298c39aa003083c5f0cb9d460f7cea26b411aefa', 154, 154, null, 325, '2025-10-01', null, false, 6),
  ('25df9e60-15f7-572e-9abd-849add2eb2b2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '27D', 'Paralegal Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Paralegal specialists administer and supervise the provision of legal services to unit commanders and staff and assist judge advocates/attorneys in providing professional legal services in diverse legal disciplines, including: organizational legal services (military justice, legal assistance, claims, administrative law, international law, operational law, and contract law); defense legal services; and judicial legal services.', 'ede7635e8279f15021e9298d2b25b3fc2e92aaf14229a0d2d63a9b0859f5fdc9', 156, 156, null, 326, null, null, false, null),
  ('835240ef-7d03-5ac2-922c-f2e59fcbd65a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '27D', 'Paralegal Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provides preliminary legal and administrative support to unit commanders and staff and coordinates legal actions with supervising legal office. Prepares and processes legal documents in support of courts-martial, non-judicial punishment, and other military justice matters; line of duty determinations, separation board proceedings, and other administrative law matters; legal assistance services; claims processing and investigations.', '48e88c820eb3bb490dd454fc2f409d967ecd50478477de39f99e9cffa7a98ac8', 156, 156, null, 327, null, null, false, 1),
  ('81b6429d-7e2f-5bbd-83f9-f473c7ac6706', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '27D', 'Paralegal Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises the operation of a section in a command or installation legal office. Provides technical guidance to subordinates. Maintains law/administrative library and section files and records. Monitors and reviews actions to ensure accuracy and timely dispatch or disposition.', '14970a4c6e80404882567b52c631d726e42d511a9c5a6386462fa3a953d7964d', 156, 156, null, 328, null, null, false, 2),
  ('c412099f-730f-5e42-9071-40f8b25b8ec4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '27D', 'Paralegal Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises the operation of a command legal office. Trains and provides guidance to subordinates on complex legal administrative issues. Coordinates with units concerning taskings and training of paralegal specialist and noncommissioned officers. Conducts extensive legal research. Adjudicates personal property claims.', 'dc7bdce2c23533fcac313a3a1780fab32ddeed315a228209df35d33ba280df74', 156, 156, null, 329, null, null, false, 3),
  ('f73d2608-7598-5a15-aac1-953c6f56771d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '27D', 'Paralegal Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises the operation of an installation legal office or section of a major command legal office. Plans, task-organizes, and provides logistical support to subsections. Coordinates the requisition and assignment of installation paralegal specialists/NCOs. Develops and implements installation training of paralegal specialists/NCOs.', 'f987960143b0831464fe13f407e9346eddf60bc3f1cb6d783103f5e786967a76', 156, 156, null, 330, null, null, false, 4),
  ('aea8fa4b-a898-5921-8e9b-33f31f567222', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '27D', 'Paralegal Specialist', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises the operation of a major command legal office. Provides technical and professional guidance to and coordinates the requisition and assignment of all command-wide paralegal specialists/NCOs. Advises the senior judge advocate on all matters affecting legal specialists/NCOs. Inspects command legal support activities and recommends actions to correct deficiencies and improve legal support operations. In formations with a 27D60, the 27D50 manages the military justice operations of a Staff Judge Advocate Office in Division, Corps and ASCC formations.', 'b2790c8ed635b5a6d8744e15c393e65e6546fd30674e2431af4382fdcc1496fb', 156, 156, null, 331, null, null, false, 5),
  ('ed374257-4f6a-5a70-9f1a-12c2b5ce5e22', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '27D', 'Paralegal Specialist', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises the operation of a Division, Corps, or ASCC legal office. Provides technical and professional guidance to and coordinates the requisition and assignment of all command-wide paralegal specialists/NCOs. Advises the senior judge advocate on all matters affecting paralegal specialists/NCOs. Inspects command legal support activities and recommends actions to correct deficiencies and improve legal support operations.', '9cb2f813ef21ec0e8c3cb723d2eb220c650e6215ec56ed78f565b2ecf8e819bc', 156, 156, null, 332, null, null, false, 6),
  ('4bc402d4-7d0b-505f-baa6-5188c57675ea', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31B', 'Military Police', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Military Police contribute to the combat power on the battlefield by conducting police operations, detention and security and mobility support across the full range of operations to enable protection and promote the rule of law. Military Police provide support to the peacetime Army community through professional policing, security of critical resources, crime prevention programs and preservation of law and order.', '26921252413b9a6857c66dcfe6f039dbe552edaf945a70e8bab17bf7029cf50c', 158, 158, null, 333, null, null, false, null),
  ('2a7e54fa-4ad1-5d0e-a833-35da3155d5d0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31B', 'Military Police', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform as a team member in support of police operations; detention and security and mobility support on the battlefield, security and installation law and order operations of Army resources and installations.', '8f76c89c87e4d440feaa920b32725bd0d433ede6b0d8554ef9ae9c95a8895eda', 158, 158, null, 334, null, null, false, 1),
  ('32d1a474-2d8f-5f18-ab30-5b1503ba1cd1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31B', 'Military Police', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads military police teams in support of Police operations; detention and security and mobility support on the battlefield, and leads and supervises small sections in support of security and installation law and order operations.', '0ebfd970c08b9c4fa0f02936263fbc07ac6ff821af0cb8470b57c550031bf694', 158, 158, null, 335, null, null, false, 2),
  ('a26fa1c9-d80c-50b7-b8e0-fa54a2fffd85', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31B', 'Military Police', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads military police squads and sections, operates police desks, plans crime prevention measures, operates evidence room, and prepares operations plans and orders in military police detachments in support of both battlefield and installation law and order operations; detention, security and mobility support of security and law and order operations.', '88922d2ba349998eeb0866e2f8d62fe3ee48bba441fadfaf4e753c7ca041a88f', 158, 158, null, 336, null, null, false, 3),
  ('fdea5db2-0189-5cd9-bb6a-3a42b0bc1e1f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31B', 'Military Police', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads military police platoons, large detachments and sections. Supervises and performs duties as Provost Sergeant and MP Operations NCO, prepares circulation or traffic control plans and operations orders in support of both battlefield and installation security and law and order operations, detention and security and mobility support of resources.', 'b8b805fa72583891255453ae738f02cf1b6771005555830ea7be9bea030c7129', 158, 158, null, 337, null, null, false, 4),
  ('79172c28-7bbc-5583-951a-4c1a416f5cde', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31B', 'Military Police', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs 1SG duties and advises the commander on all enlisted matters. Provides staff supervision, prepare plans, procedures and operational orders as Provost Sergeant, Intelligence NCO and security NCO in support of both battlefield and installation law and order operations, detention and security and mobility support of resources.', 'b7823cf590ae392b1b244aad608ad2ea35c0b8c9109534195009f34bc6fe28c1', 158, 158, null, 338, null, null, false, 5),
  ('81c849a6-964d-5d58-aa03-ecb8a32c03ba', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31D', 'CID Special Agent', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The CID Special Agent supervises or conducts investigations of incidents and offenses or allegations of criminality affecting DA or DoD personnel, property, facilities, or activities.', '98f1620b69e67c700c98e2c527c258f56eea0a70e7b1bac3255a697ca68be21e', 160, 160, null, 339, null, null, false, null),
  ('0a0353be-6af8-5cd2-9d2d-7f3803c33824', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31D', 'CID Special Agent', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts independent felony-level criminal investigations; General Crimes (Property & Persons), Economic Crimes and Counter-Drug Operations, with U.S. Army interest to support post, camp and station commanders around the world; processes crime scenes, collects evidence, and conducts interviews or interrogations of complainants, victims, witnesses and subjects; performs Protective Services operations.', '9a8386fd0531412294657f8e2cba03f04c7e8fe5de27db6c4428d74a8b8f04e8', 160, 160, null, 340, null, null, false, 2),
  ('d8c9ab0c-dc48-5da6-83cf-746a5a6bab7f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31D', 'CID Special Agent', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts independent felony-level criminal investigations; General Crimes (Property & Persons), Economic Crimes and Counter-Drug Operations, with U.S. Army interest to support post, camp and station commanders around the world. Processes crime scenes, collects evidence, and conducts interviews or interrogations of complainants, victims, witnesses and subjects; preserves, safeguards, accounts for, and disposes of all evidence received in the evidence room; supports law enforcement investigations and police operations with Criminal Intelligence Analysis and Crime Analysis; performs Protective Services operations.', 'dd8b108649c8e4c2d717ab74e5b1593238a64e7016e5281f71030ae4998e3b18', 160, 160, null, 341, null, null, false, 3),
  ('64e7f138-ee7d-584e-9a24-756a52732a98', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31D', 'CID Special Agent', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs Detachment Sergeant duties and advises Commander/Special Agent-in-Charge on enlisted matters, investigative support requirements and evidence management of a field investigative element supporting an Army Corps or major installation; supports law enforcement investigations and police operations with Criminal Intelligence Analysis and Crime Analysis; safeguards, provides guidance and staff supervision, directs plans, procedures and operational orders as a Detachment Sergeant in support of installation and wartime missions. Conducts felony criminal investigations in support of the U.S. Army and its installations CONUS and OCONUS; processes crime scenes; collects and preserves evidence for laboratory analysis; conducts interviews and interrogations; prepares investigative reports; briefs and coordinates with supported commanders, military and civilian prosecutors; conducts liaison with local, state, and federal law enforcement agencies; testifies at court martial and other tribunals; performs Protective Service Operations.', '1bd6316289d3071eaffc3aefcc150afa18b7396f81f4cd83b8ce2cf70753f95d', 160, 160, null, 342, null, null, false, 4),
  ('e3bf4685-7ea6-5f3c-b834-ed14df2b4942', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31D', 'CID Special Agent', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs 1SG duties and advises the Battalion Commander on all enlisted matters, investigative support requirements and evidence management, Logistics Security, Criminal Intelligence, Protective Service Operations, Force Protection Operations, and Criminal Investigations such as Anti-Terrorism and War Crimes. Provides guidance and staff supervision, directs plans, procedures and operational orders as a Battalion, Group, or Command level Operations Sergeant in support of installation and wartime missions.', '34690554365995a2c6768ebaaa0f3808a30ebd5f1c2da819f6e13050771fbfc7', 160, 160, null, 343, null, null, false, 5),
  ('3ae1378c-582b-5009-ad10-bd7d6fc0216a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31E', 'Corrections and Detention Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The corrections and detention specialist controls, supervises, counsel internees, manages detention operations, confinement operations and corrections treatment programs. Provides professional detention/correctional support to US military prisoners, host nation corrections development and detainee operations.', 'be874632e725376278a4b6d28bd639dda693bbce16cd4c9171eb4668eea23b16', 162, 162, null, 344, null, null, false, null),
  ('c2f81281-e02f-50bd-87e9-f5f382f88446', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31E', 'Corrections and Detention Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', '- Assists with the providing custody and control of US Military Prisoners/Detainees, and provides external security to detention/corrections facilities and the United States Disciplinary Barracks. Soldiers should focus on building a strong base of technical expertise in equipment accountability, basic MOS skills and common Soldier tasks. This can be acquired in assignments serving as tier/compound guard, tower guard, prisoner/detainee escort, control clerk, dining facility guard or recreation guard.', '0335162fa90372f5a570f9100f5d1a27cdd3a385e6136d3d6597c2cfd253de7f', 162, 162, null, 345, null, null, false, 1),
  ('daba5674-be2f-5fdb-8c15-b3b5f1727942', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31E', 'Corrections and Detention Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties as team leader for a three member team which is directly responsible for the leadership, discipline, welfare, morale, training, safety and professional development of all assigned Soldiers. Performs as the principle NCO within detention/correctional facilities that is responsible for supervising security personnel, custody and control and accountability of US Military Prisoners/Detainees. Ensures daily the proper adherence to rules and regulations. Gathers information on potentially dangerous opportunities, takes necessary action, to include handling hostile or suicidal threats. Observes behavior and interprets it with precision. Supervises 2-5 subordinates plus approximately 20-170 US Military Prisoners/Detainees. Duties of a Corrections and Detention NCO may include, but not limited to the following: tier/compound guard, tower guard, prisoner/detainee escort, control clerk, dining facility guard, recreation guard.', 'fccb4bc4edbc126b9882c34e0b9bb9709a9a9794f79f10069415e173faa5e1c1', 162, 162, null, 346, null, null, false, 2),
  ('277fea99-5229-568d-befd-9ede1c7e08e0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31E', 'Corrections and Detention Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties as a squad leader for an 8-12 member squad directly responsible for the leadership, discipline, welfare, morale, training, safety and professional development of all assigned Soldiers. Performs as the principle NCO within a detention/corrections facilities that is responsible for supervising security personnel, custody and control and accountability of US Military Prisoners/Detainees. Ensures daily the proper adherence to rules and regulations. Gathers information on potentially dangerous opportunities, takes necessary action, to include handling hostile or suicidal threats. Observes behavior and interprets it with precision. Supervises 6-15 subordinates plus approximately 200-600 US Military Prisoners/Detainees.', '0af67785985fb52729569c0180cf089513ae6be4e9c55644f79983290a69043e', 162, 162, null, 347, null, null, false, 3),
  ('392bebec-7f66-5f30-a91d-acae0825db15', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31E', 'Corrections and Detention Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Platoon Sergeant responsible for the training, professional development, health, morale, welfare, and discipline of all assigned Soldiers. Platoon Sergeant is the primary leader and trainer in the platoon. As a senior noncommissioned officer in the corrections environment, the Platoon Sergeant’s leadership skills, institutional knowledge, and hands-on experience in handling US Military Prisoners/Detainees are essential in the development of junior leaders.', '7c038d21ee6edad3d354da9560daffffe7e294e3b1e9366af36dcae8f168c0c1', 162, 162, null, 348, null, null, false, 4),
  ('5a53882d-9386-525b-9d27-c483b5c24727', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31E', 'Corrections and Detention Specialist', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'First Sergeant of a TO&E Detention MP Company with two line platoons, a prisoner operations and HQ platoon; trains and maintains mission readiness of 124 Soldiers capable of supporting the custody and control of inmates assigned to detention/corrections facilities to include the USDB, the only maximum-security prison in the DoD, and deploying and conducting detention operations in support of combat and contingency operations; ensures a command climate that supports Soldiers and their families while fostering individual and unit excellence and success.', 'e61c49bd7be908b61e52a1a3ef822170d159b63720dc7c9334dd830544afda5d', 162, 162, null, 349, null, null, false, 5),
  ('faee0c43-2a7c-59d1-a8f3-8d54d93f3435', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31K', 'Working Dog Handler', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Military Working Dog (MWD) teams contribute to the combat power and installation security on the battlefield and at home station by providing target odor detection (explosive/narcotics) and a less than lethal course of action that serves as a psychological deterrent in supporting police operations; detention and security and mobility support to Installation and Maneuver Commanders. Patrol Drug Detector Dog (PDDD) and Patrol Explosive Detector Dog (PEDD) Teams provide Installation and Maneuver Commanders the ability to detect and locate hidden personnel, illicit narcotics and paraphernalia, weapons, ammunition, explosive ordnance, and Improvised Explosive Devices (IED).', '1250e12e9a3bb33d40422b543346603a21aa328abe7743b7648d5268d4585d60', 165, 165, null, 350, null, null, false, null),
  ('d7c3146f-235a-5052-a445-095a29190419', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31K', 'Working Dog Handler', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform as a Dog Handler in a Military Working Dog squad in support of police operations; detention and installation security and law and order operations and security and mobility support to Maneuver Commanders. Responsible for the health, welfare and proficiency training of assigned Military Working Dog.', '1824fc30aa8bf369edc4080ae370b8dde5b443105e0f4b8126efb33e6766ec7e', 165, 165, null, 351, null, null, false, 1),
  ('652bc5be-e045-5efa-8179-44b51c483760', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31K', 'Working Dog Handler', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads Military Working Dog teams in providing support to police operations; detention and installation security and law and order operations and security and mobility support to Maneuver Commanders. Supervises the health, welfare and proficiency training of subordinate Military Working Dog teams and ensures teams are deployment ready.', '0002313cf6822fb21ad066630b010fa4850dee530d6c299f5cd4d29db4994bab', 165, 165, null, 352, null, null, false, 2),
  ('84aac5d6-9c54-5858-8ed9-4bf789fead03', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31K', 'Working Dog Handler', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads a Military Working Dog squad in support to police operations; detention and installation security, law and order operations and security and mobility support to Maneuver Commanders. Develops training plans to ensure Military Working Dog teams remain proficient in their detection capability. Validates and supervises proficiency training of all teams assigned to the squad. Ensures MWD teams maintain proficiency and are prepared for MWD certifications. Manages the daily maintenance and upkeep of kennel facilities.', 'e3f9576c4a4dbef237538decc819c2631e809eaa3618caa00d5d6525861c21a4', 165, 165, null, 353, null, null, false, 3),
  ('95f5c3fb-514a-5a6a-ba4b-52db66aea34c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31K', 'Working Dog Handler', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Leads a Military Working Dog Detachment and performs Kennel Master duties and responsibilities in support of police operations, detention and installation security and law and order operations and security and mobility support Maneuver Commanders. Monitors the health, welfare and training of assigned MWD teams. Supervises the storage and accountability of narcotic and explosive training aids, as well as all other assigned equipment. Ensures assigned MWD teams are proficient in their detection capabilities and the detachment is ready for annual certifications and worldwide deployments. Advises the Commander on the employment of MWD assets.', '7e06b327934014c8451871f4f590394ebfc0f0bffc3e1b01df16100870620d92', 165, 165, null, 354, null, null, false, 4),
  ('3f2ef8df-4779-5d8d-a848-c956c2fd4482', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31K', 'Working Dog Handler', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as subject matter expert on MWD operations at the ACOM, ASCC and DRU levels of command. Advises and makes recommendations to commanders and Provost Marshals on the utilization and employment of MWDs. Provides tactical/technical guidance and professional support to subordinates. Plans, coordinates, and supervises activities pertaining to organization, training, and combat operations. Edits and prepares tactical plans and training material.', '30a5bd00a6b3279cb453855f02c6450cae2f438508cb597ab6d0a6b7d2f396b2', 165, 165, null, 355, null, null, false, 5),
  ('0ff856d6-5611-5418-a025-4f9c0f4ed9ce', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '31Z', 'Senior Military Police Sergeant', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Senior Military Police Sergeant is responsible for supervising the manning, training, equipping and combat readiness of a BN/BDE level of command; principle staff NCO in operations whom plans, coordinates and manages BN/BDE operations, training and tasking’s to provide Police Operations; Corrections and Detention, Security and Mobility support, Criminal Investigations and Military working Dog Operations. Provides for the health and welfare of Soldiers, DA Civilians and their families across the command. Serves as the senior enlisted Leader to the Commander and Provost Marshal on policing, security of critical installation resources, and all enlisted matters; develops and implements law enforcement policies and procedures.', '387c8687732a0bf610f2daf17e37b785851d29e34afe2822ab40f67da750c283', 167, 167, null, 356, null, null, false, null),
  ('15f45994-ed50-5db8-9f5a-c3329f4e101e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35F', 'Intelligence Analyst (Intel Analyst)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The intelligence analyst conducts all-source analysis, develops the threat situation, produces, fuses, and disseminates all-source intelligence to support the military decision-making process (MDMP). Performs, coordinates, and/or supervises the Intelligence Preparation of the Battlefield (IPB) process, planning requirements and assessing collection and support to targeting. Supports the command, staff, and advises on the use of intelligence resources at all echelons.', '1d438aacaa6302418b365f0df83fdab35014c177122800ec79a5c27411ae24bc', 168, 168, null, 357, null, null, false, null),
  ('8c97d4bc-f008-5726-a60c-6bd52e86e0a3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35F', 'Intelligence Analyst (Intel Analyst)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Prepare all-source intelligence products to support the command. Establish and maintain databases and automated intelligence systems receives and processes incoming information. Analyze incoming information for significance and reliability. Performs initial intelligence preparation of the battlefield (IPB) to define the operational environment, describe environmental effects on operations, evaluate the threat, and determine threat courses of action. Supports initial threat situation development. Provide intelligence support to targeting. Analyzes information and presents intelligence products and findings.', '9d7bb227025cd9e3054ca85aa8aacefea37a928624f536411ec881ebd4c037a8', 168, 168, null, 358, null, null, false, 1),
  ('c52f6535-6763-5d4d-abbc-a9272a196759', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35F', 'Intelligence Analyst (Intel Analyst)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level, provides guidance, and trains subordinate Soldiers. Performs intelligence preparation of the battlefield (IPB) to refine the significant characteristics of the environment and intelligence gaps; perform analysis of military aspects and effects of terrain, while applying the effects of weather on operations, and considering civilian factors of area, structure, capabilities, organizations, people, and events (ASCOPE); confirm threat capabilities while refining threat models; confirm threat objectives and courses of action; creates enemy situation templates and targeting products and develops initial information collection products to answer intelligence requirements. Provides intelligence support to targeting by organizing and categorizing targeting products. Assist in the preparation of reports on captured enemy material. Presents periodic and special intelligence reports, plans, and briefings.', '983d27229bf999ee1ed891627106dae73521d6ac0e8b340d1dccfbda8f209cd5', 168, 168, null, 359, null, null, true, 2),
  ('36c549de-caad-5a7f-bae4-44245ae097a5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35F', 'Intelligence Analyst (Intel Analyst)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level, provides guidance, and trains subordinate Soldiers. Drafts unit all source intelligence training plan. Evaluates and validates subordinates’ analysis. Performs intelligence preparation of the battlefield (IPB) to validate significant characteristics of the environment and intelligence gaps; validates analysis of military aspects and effects of terrain, while applying the effects of weather on operations, and considering civilian factors of area, structure, capabilities, organizations, people, and events (ASCOPE); validates threat capabilities and threat models; validates threat objectives and courses of action. Prepares, edits, and critiques intelligence and targeting products and validates Information Collection products to answer intelligence requirements. Confirms or denies PIR satisfaction and recommends changes. Performs planning requirements and assessing collection and dissemination to answer intelligence requirements. Provides intelligence support to targeting by verifying the high value target (HVT) list, validating the target intelligence package (TIP), and nominating targets. Performs combat assessment and determines second and third order effects of enemy actions. Receives, produces, and disseminates intelligence reports.', 'b3dc27c8a106e913a8fdd6bcf76b4d23a0806790d5b33d94a07c4c6b239f281a', 168, 168, null, 360, null, null, true, 3),
  ('4c45bc8d-f265-5491-917b-a8b910b7b33c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35F', 'Intelligence Analyst (Intel Analyst)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level, provides guidance, validates, and manages planned all Source intelligence training. Coordinates flow of intelligence information between intelligence disciplines and supervises the all-source production process. Integrates Information Collection to include coordination with the operations officer for asset management and dissemination. Integrates intelligence targeting with operations. Supervises intelligence operations.', '793399403b8a2c4b69839b948d57e872c1ec2641b277612410012b899f3041d0', 168, 168, null, 361, null, null, true, 4),
  ('faf73e6c-8cfc-588c-8865-7fafdc4ff41c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35G', 'Geospatial Intelligence Imagery Analyst', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The GEOINT Imagery Analyst conducts GEOINT analysis that supports unified land operations. Geospatial imagery analysis involves identifying, analyzing, and reporting targets observed on imagery from satellite and airborne systems. They are familiar with and understand the tasking, collecting, processing, exploiting, and disseminating process. The Imagery Analyst applies theory involved in analyzing radar, infrared, moving target indicator (MTI), light detection and ranging (LIDAR), spectral imagery, and geospatial information. They provide mission critical geospatial imagery derived intelligence in support of national, theater and tactical operations. The Imagery Analyst utilizes tactical, theater and national communication networks and the employment of GEOINT systems to support operations. The Imagery Analyst queries, filters, and retrieves a variety of combat information, such as spot reports, significant activities, reconnaissance reports, and patrol debriefs to support operations. Imagery analysts push GEOINT products and data down to ground forces conducting direct and indirect combat activities. The Imagery Analyst can identify and relay environmental hazards, civil considerations, and threat activity to units maneuvering through the battlefield. They constantly research their Section’s AO to provide valuable input on the Operational Environment (OE) while conducting GEOINT support to IPB. The Imagery Analyst also interprets/analyzes Full Motion Video. They also provide support to lethal and nonlethal targeting operations through baseline or intermediate graphics, battle damage assessments and collateral damage estimates. Soldiers should devote their career to development and advancement in both leadership and technical expertise required to meet the Army’s intelligence mission.', '61cfde451fa333779d56ca462d78ec8f56051b004d9890867072acbeffca9c95', 170, 170, null, 362, null, null, false, null),
  ('95ed853b-a4d0-57d8-afc7-a64fb2d38edd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35G', 'Geospatial Intelligence Imagery Analyst', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts GEOINT analysis across competition continuum by analyzing still and motion imagery along with geospatial data. Identify conventional and unconventional military, civil activity, installations, facilities, weapon systems, orders of battle (OB), and infrastructures. Establish GEOINT automations with communications architecture. Provide GEOINT in support of MDMP, intelligence preparation of the battlefield (IPB), and the targeting process.', '2eb83932a9339bf7222f32682bc48aa4ebaef286f2f95c1ee56948bd0f6c4df9', 170, 170, null, 363, null, null, false, 1),
  ('fdd62925-329d-53d1-b583-a8136365b6a3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35G', 'Geospatial Intelligence Imagery Analyst', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill level to include intelligence analysis. Provide guidance to support GEOINT operations and the employment of GEOINT systems. Perform quality control of GEOINT products. Conduct GEOINT mission management support to MDMP and IPB. Conduct Knowledge Management of GEOINT databases.', 'bc42aa8bd9029e7ddac04c7a4216272c5f8bf3653d1bd77eda2e676e24ed086f', 170, 170, null, 364, null, null, true, 2),
  ('0badbc3c-1bc4-50a5-8cca-1b7c9de0ba5c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35G', 'Geospatial Intelligence Imagery Analyst', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill level. Manage GEOINT operations and the employment of GEOINT systems. Coordinates with staff sections to generate GEOINT requirements in support of the joint planning process. Supervise GEOINT production to include dissemination of products and reports.', '87970a7304c49c36134956ba5b08cad9fb07f63645009d0158e50affc69288b5', 170, 170, null, 365, null, null, true, 3),
  ('bc5efb23-537b-51c1-8086-fc07d61775cb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35G', 'Geospatial Intelligence Imagery Analyst', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill levels. Establish and synchronize GEOINT operations and information collection across all echelons to generate GEOINT for decision making.', 'ec046da3664c1c04de264b7724991a4a3351864480a1f7bc4d690f9aaf8a174e', 170, 170, null, 366, null, null, true, 4),
  ('6eafba47-cc9e-5ce3-acb7-ae0c4a2893a6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35L', 'Counterintelligence (CI) Agent', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts investigations, operations, collection and reporting, analysis production, and technical services to detect, identify, counter, exploit or neutralize the Foreign Intelligence Entity (FIE) and international terrorist threat to the Army and Department of Defense (DoD). Detects and identifies the CI related insider threat; identifies and counters the collection efforts and activities of foreign adversaries, which presents a threat to the lives, property, or security of Army forces. Ensures that CI activities are conducted according to current law, executive order and Army/ DoD policy.', '686e0b50a4d5bf34df0b5399d8c8c84b45dfd437500e9c551cb6083d74d7e374', 172, 172, null, 367, '2024-10-01', null, false, null),
  ('6b66c477-33e2-5d2e-b893-c102d8e3b36b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35L', 'Counterintelligence (CI) Agent', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as a CI Agent responsible for CONUS or OCONUS operations. Performs duties in support of the Covering Agent Program and the Army’s Threat Awareness and Reporting Program (TARP) to Army audiences in the area of operation (AO). Responds to incidents, conducts CI investigations, and prepares resulting CI incident and investigative reports. Assist in the management of all military CI collections, CI investigations, and Intelligence Information Reports (IIR) produced by CI elements.', 'e532c49a8a46bea84d1c71a6837dd73fb08152d53f36ec5cb817f1c95f6597f6', 172, 172, null, 368, '2024-10-01', null, false, 1),
  ('9030bc49-5063-54dd-8b82-f6daa48b30d8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35L', 'Counterintelligence (CI) Agent', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'In addition to all duties at the preceding level, serves as a CI Agent responsible for supervising, planning covering agent duties in a given area of operations, CI investigations, and collection of evidence in support of CI investigation activity; plans and conducts aggressive, comprehensive, and coordinated activities worldwide in the five functional areas of investigations, operations, collections, analysis and production; supervises CI awareness training; and develops CI support plans. Writes, edits, and disseminates CI reports and plans. Processes applications for the CI Agent recruitment program.', '8cc70240952899667085b94beca00cc791bfb614f078b2965c69f2d6e1663623', 172, 172, null, 369, '2024-10-01', null, true, 2),
  ('bed12c21-a41e-5e89-9374-f1d3ca0b6003', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35L', 'Counterintelligence (CI) Agent', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'In addition to all the duties at the preceding level, serves as CI Sergeant responsible for supervising, and planning covering agent duties in a given area of operations, CI investigations, and collection of evidence in support of CI investigation activity; plans and conducts aggressive, comprehensive, and coordinated activities worldwide in the five functional areas of investigations, operations, collections, analysis and production; supervises CI awareness training; and develops CI support plans. Writes, edits, and disseminates CI reports and plans. Processes applications for the CI Agent recruitment program.', '7bf0267eb69896ff11786b906d49740e603cbbb9a765db7dca31148781a06e5d', 172, 172, null, 370, '2024-10-01', null, true, 3),
  ('b0821cb1-6243-55da-bb50-c5e47efe650b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35L', 'Counterintelligence (CI) Agent', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'In addition to all the duties in the preceding levels, serves as the Senior (CI) Sergeant. Manages and supervises all CI activities, and special investigative collection techniques. Reviews CI related reports and plans. Writes, edits, and submits requests for special investigative techniques and special operational concepts. Performs CI Coordinating Authority (CICA) and 2X staff management for subordinate CI elements. Provides technical control and oversight. Conducts source and operational management. Manages the CI Agent recruitment program.', 'f856c62a00a636994398df2a930bc072cd5d92488ac375dcd6fca567436cee1d', 172, 172, null, 371, '2024-10-01', null, true, 4),
  ('d9af0cf6-e088-54a2-ac1d-5373f7b85273', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35M', 'Human Intelligence Collector (HUMINT Collector)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Army Human Intelligence (HUMINT) Collectors perform interrogations, debriefings, screenings, source operations and intelligence liaison in all conflict phases in support of multi-domain operations at every echelon. HUMINT Collectors identify adversarial elements, activities, intentions, capabilities, and locations through the questioning of people in the Operational Environment (OE). They perform HUMINT collection in English and foreign languages. They question enemy prisoners of war and other detainees, enemy deserters, internally displaced persons, liaison contacts, friendly forces, people in the OE with a unique capability to gather information, and other strategic sources. HUMINT Collectors prepare, edit, and disseminate intelligence and technical reports. They use Army HUMINT computer information systems and communications equipment to address intelligence requirements and to gain situational understanding while planning and conducting HUMINT operations. They also utilize and manage interpreters when applicable. HUMINT Collectors use analytic techniques, tools, and databases to develop, execute, and assess HUMINT operations. The HUMINT Collector uses classified databases and publicly available information for research; they employ security measures to reduce signatures. They conduct coordination in English and foreign languages with host-nation and coalition agencies. Duties for the MOS 35M at each level of skill are:
(1) MOSC 35M1L. Skill Level 1 HUMINT Collectors under supervision, perform interrogations, debriefings, screenings, and source operations in support of multi-domain operations to answer intelligence collection requirements. They perform HUMINT collection in English and foreign languages. They can integrate a linguist in support of operations to ensure mission objectives are met. They prepare and submit intelligence and technical reports using Army HUMINT Intelligence Architecture and communications equipment. A HUMINT Soldier uses analytic techniques, tools, and databases to develop and execute HUMINT collection in support of the IWfF. The HUMINT Soldier uses classified databases and publicly available information for research while employing collection security measures to reduce the signature of HUMINT collection. They can perform multi-disciplined intelligence analysis in support of HUMINT operations and assist in generating critical findings to refine ongoing collection operations. They conduct HUMINT operations at every echelon in accordance with (IAW) applicable laws, policies, treaties, regulations, and unit SOP. Human Intelligence Collectors must also remain in compliance with AR 11-6 (The Army Language Program).
(2) MOSC 35M2L. In addition to mastering SL1 skills, the 35M SGT provides purpose, motivation, and direction to subordinates through relevant and realistic training and leadership. They coach and counsel subordinate Soldiers as developing leaders. They can recognize pertinent information to be utilized in operations to identify opportunities for cross-cueing and dissemination to outside entities. The HUMINT Collector performs controlled source operations, interrogations, debriefings, intelligence liaison duties, and prioritizes HUMINT sources for questioning. They perform HUMINT collection in English and foreign languages. They supervise language proficiency training and manage assigned interpreters. The HUMINT Collector prepares, edits, and submits intelligence and technical reports using Army HUMINT Intelligence Architecture and communications equipment. They supervise and conduct analysis and research to develop and execute HUMINT collection missions. The HUMINT Collector supervises and employs collection security measures to reduce the signature of HUMINT collection operations. They conduct briefings to internal and external entities to provide a broader understanding of the capabilities of HUMINT and to coordinate HUMINT collection operations. Human Intelligence Collectors must also remain in compliance with AR 11-6 (The Army Language Program).
(3) MOSC 35M3L. In addition to performing duties shown in the proceeding skill level, the HUMINT Collection Sergeant leads Soldiers through subordinate leaders. They coach, develop, and counsel subordinate leaders and Soldiers. They are responsible for the development of HUMINT training, including the identification of collective tasks to train during training events, draft training plans, and preparing to execute training that supports the units’ collective tasks, METL, and meets the commander’s intent. They supervise source operations, interrogations, debriefing, intelligence liaison, and prioritization of HUMINT sources for questioning. They perform HUMINT collection in English and foreign languages. HUMINT Collection Sergeants can recognize information of interest to Counterintelligence and notify leadership of potential threats. They prepare, edit, review, and disseminate intelligence and technical reports using Army HUMINT Intelligence Architecture and communications equipment. They can perform multi-disciplined intelligence analysis in support of HUMINT operations and generate critical findings to refine ongoing collection operations. HUMINT Collection Sergeants oversee collection security measures to reduce the signature of HUMINT collection. They manage the production of intelligence and operational products from available individual assessments and threats, vulnerabilities, and opportunities in support of all phases of HUMINT operations across all domains. For additional skills, refer to paragraph 15-3. Human Intelligence Collectors must also remain in compliance with AR 11-6 (The Army Language Program).
(4) MOSC 35M4L. In addition to performing duties in the proceeding skill level, the Senior HUMINT Collector executes and manages missions while leading NCOs, who in-turn lead Soldiers. They are responsible for the evaluation of HUMINT training and provide guidance on the development of the training plan in support of the units’ collective tasks, METL, and the commander’s intent. They manage collective HUMINT operations. They provide oversight and technical asset management to ensure intelligence collection requirements are prioritized based on criticality to the mission and allocate the appropriate HUMINT assets to conduct collection activity. They manage source operations, debriefing operations, intelligence liaison activities, interrogation operations, and screening operations. The Senior HUMINT Collector integrates cultural intelligence and analysis into HUMINT operations. They serve as an advisor to the command and staff on HUMINT operations, training, and policies and procedures. They build relationships and continuously communicate with leaders in other disciplines and sections to create synergy of effort to maximize effectiveness of the IWfF. They integrate HUMINT considerations into MDMP to maximize effectiveness of HUMINT activities. The Senior HUMINT Collector coordinates external capabilities to support HUMINT operations. Human Intelligence Collectors must also remain in compliance with AR 11-6 (The Army Language Program).', '8d7c0b75e6534aafe64113e91d77463fa48214df44c7bc20b7b8b821a6a6fdb4', 174, 175, null, 372, null, null, false, null),
  ('8deaca03-7428-5196-9ef6-fec0c8db6a7f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35N', 'Signals Intelligence Analyst (SIGINT Analyst)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Signals Intelligence (SIGINT) Analyst performs and supervises analysis and reporting of intercepted foreign communications and on-communications signals at all echelons; produces tactical, operational, and strategic intelligence; assists in the collection management process. Produces combat, strategic, and tactical intelligence reports.', '766a5553f43b13d06214ba11d6252bdfb828d9b35d7c40ebf8f2a2fb3316f2e3', 177, 177, null, 373, '2023-11-01', null, false, null),
  ('706d1da3-165c-5fa7-a38c-e30867e3b980', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35N', 'Signals Intelligence Analyst (SIGINT Analyst)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Analyzes intercepted information to isolate valid foreign intelligence. Establishes target identification and operational patterns. Identifies, reports, and maintains SIGINT technical data and Electronic Order of Battle (EOB) information; uses technical references to analyze communications and non-communications information. Operates automated data processing equipment to access SIGINT collection for processing, exploitation, and dissemination. Maintains analytical working aids and databases to support target collection, identification, and location. Prepares technical and tactical intelligence reporting to meet intelligence requirements. Assist in the emplacement, employment, and recovery of assigned SIGINT equipment.', '8369c3ff1fb1a684f5deac4efa328b2a27a3493e9611e2d0ba1623567457470f', 177, 177, null, 374, '2023-11-01', null, false, 1),
  ('0efc485c-7045-54d1-b1ef-917192dbf675', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35N', 'Signals Intelligence Analyst (SIGINT Analyst)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level and provides guidance to subordinate Soldiers. Performs intermediate analysis of intercepted communications and non- communications information. Validates SIGINT technical data and EOB information; verifies correlation and fusion of SIGINT data and products. Reviews intelligence reports. Supervises the emplacement, employment, and recovery of assigned SIGINT equipment.', 'c1be43e6161b975d0d2448f67cea22db9b9d7a3f41c73435a3155146f6e9d9aa', 177, 177, null, 375, '2023-11-01', null, true, 2),
  ('7a52a73d-08d2-5631-b76c-c9002d896309', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35N', 'Signals Intelligence Analyst (SIGINT Analyst)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level and provides guidance to subordinate Soldiers. Performs advanced analysis of intercepted communications and non- communications information. Validates technical documents and reports. Evaluates and releases SIGINT reports. Integrates SIGINT requirements into the Information Collection Process.', 'e88618a711b5a3426fa63d3bfa9f849f5b0fcde0ae906c40da18151973b4cbcf', 177, 177, null, 376, '2023-11-01', null, true, 3),
  ('1960e755-7254-5854-99c4-4ce23746c6c3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35N', 'Signals Intelligence Analyst (SIGINT Analyst)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels and provides guidance to subordinate Soldiers. Determines mission objectives and priorities based on requirements. Manages processing, analysis, and reporting functions. Implements operational readiness strategy. Supervises and coordinates collection management of supported commands and other agencies. Coordinate collection activities with other disciplines. Provides guidance on the interpretation of SIGINT information and employment of collection assets.', '54b214af4023d93f51fc593f5b79e9f0129c8ffa22dc2c4e64f8c537c991bcc0', 177, 177, null, 377, '2023-11-01', null, true, 4),
  ('9375b9a3-8a78-5b95-b677-eba29e087f70', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35P', 'Signals Intelligence (SIGINT) Voice Interceptor', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The SIGINT Voice Interceptor performs and supervises detection, acquisition, geolocation, identification, and exploitation of foreign communications at all echelons using SIGINT systems. The SIGINT Voice Interceptor copies, translates, transcribes, gists and/or produces summaries of foreign communication transmissions. The SIGINT Voice Interceptor contributes to Information Collection (IC) synchronization to support mission requirements and conducts basic Intelligence Oversight in support of SIGINT operations. Duties for MOS 35P at each skill level are:
(1) MOSC 35P1L. Identifies foreign communications from an assigned geographic area and categorizes signals by activity type. Recognizes changes in transmission modes and tips the appropriate authority. Produces gists, transcriptions, translations, and summaries of foreign communications. Operates systems to support SIGINT tasking. Conducts military briefings. Conducts basic Intelligence Oversight in support of SIGINT operations.
(2) MOSC 35P2L. Performs and trains duties shown in preceding skill level and provides guidance to subordinates. Leads independent team-level SIGINT operations. Enforces basic SIGINT Intelligence Oversight operations. Performs quality control and validates the sanitization of reports. Directs the implementation of subordinates’ Individual Language Training Plans (ILTP).
(3) MOSC 35P3L. Performs and trains duties shown in preceding skill levels and provides guidance to subordinates. Directs section-level SIGINT activities and determines priorities. Supervises quality control of SIGINT products. Requests non-organic Intelligence collection support. Enforces Command Language Program.
(4) MOSC 35P4L. Performs duties and manages training shown in preceding skill levels and provides guidance to subordinates. Supervises multi-mode foreign communications intercept and processing. Refines Essential Elements of Information requirements for identification and extraction. Determines SIGINT requirements for supported units. Supervises SIGINT collection management in support of IC synchronization. Coordinates collection activities across multiple disciplines and platforms.', '92d7c7fbc394442b1c3698a0a9e0437676343e0440b6bfb4cecd65bd662bbb13', 179, 179, null, 378, null, null, false, null),
  ('dd06384f-53cc-5380-9b81-7191e754b718', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35S', 'Signals Acquisition/Exploitation Analyst', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts and supervises tasking, survey, collection, geolocation, processing, and exploitation of foreign signals through Technical SIGINT (TechSIGINT) and Communication Intelligence (COMINT) analysis and dissemination supporting multi-domain electromagnetic spectrum operations at the tactical, operational, and strategic levels across National, Joint, Coalition, and Army echelons; assists in the collection management process; operates and employs cryptologic equipment', 'fe0896f63c7eac0196a67155826b6ce3354f2a77aa8a62f1aac0ae50dc9a7c36', 182, 182, null, 379, '2023-11-01', null, false, null),
  ('e5a8b4c3-8781-51fa-b816-6b0186f1a5b0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35S', 'Signals Acquisition/Exploitation Analyst', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts basic TechSIGINT analysis of foreign signals at echelon in support of National, Joint, Coalition, and Army requirements to determine signal parameters for identification and processing utilizing cryptologic equipment. Surveys the multi-domain electromagnetic spectrum to characterize and locate target analog and digital signals; prepares logs and technical reports for dissemination and coordination.', '33a71c9ea1333ce6ad5a21e21b8d2219ebc142d507e6db864219aad7ebdcbf94', 182, 182, null, 380, '2023-11-01', null, false, 1),
  ('7a538301-4e08-5b0e-afd1-c2a2fe9eaa14', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35S', 'Signals Acquisition/Exploitation Analyst', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level, supervises, and develops Soldiers. Conducts intermediate level TechSIGINT and COMINT analysis to determine parameters for processing. Leads missions, determines SIGINT selection sites, and maintains mission related databases in support of signal survey and collection missions.', 'c794bbc69bba768405937f0e276bf5ec3c4fbd9e5943192e952b64f55cbd8981', 182, 182, null, 381, '2023-11-01', null, true, 2),
  ('68e46168-bf15-5d83-91e8-4376f9002dbd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35S', 'Signals Acquisition/Exploitation Analyst', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level and provides guidance to subordinate Soldiers. Leads TechSIGINT and COMINT missions, implements certification, and conducts advanced analysis to determine parameters for processing. Maintains dataflow configuration for mission related databases in support of SIGINT information needs and requirements at echelon. Develops collection tasking, drafts SIGINT mission management documentation, and publishes related reports.', '2792c22b7509b54b2402071d8afe60f4095061b92751a414d50a10f179869099', 182, 182, null, 382, '2023-11-01', null, true, 3),
  ('3713c679-1e1d-5e13-a320-cafdeced29d7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35S', 'Signals Acquisition/Exploitation Analyst', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level; leads, plans tactical and strategic TechSIGINT and COMINT operations. Develops training certification programs, validates SIGINT dataflow, reviews mission management documentation, publishes technical findings of SOIs, and releases collection tasking in support of SIGINT information needs and requirements at echelon.', '64e9b7d46f23ef226e4691281c15a98d6160ca65f50632d67bb0be25c598e3a4', 182, 182, null, 383, '2023-11-01', null, true, 4),
  ('74ca4e25-3b03-5b75-802f-746316bf96b6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35T', 'Military Intelligence (MI) Systems Maintainer/Integrator, (MI Sys Mntr/Intgr)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Military Intelligence Systems Maintainer/Integrator configures, monitors, integrates, maintains, troubleshoots, repairs, and manages Intelligence Information Services (IISs), equipment, transmission media, and networks. The 35T conducts Program of Record and Non-Standard Equipment integration into Intelligence Architecture compatible with Mission Command systems and architecture. The MI Systems Maintainer/Integrator performs computer hardware and software programming, installation, and configuration for aerial and ground IISs. They provide field and sustainment level maintenance to multi-functional, multi-user, data and information gathering, intelligence processing, peripheral, and associated systems and devices in deployed and fixed sensitive compartmented information facilities. The 35T performs and supervises the planning, employment, configuration, integration, monitoring and maintenance of complex computer-controlled networks and national cryptologic systems to enable the IWfF to provide support to the Intelligence Community in multiple domains and operational environments.', '8506139dc39a0da63084267c9241c9fc65520ebabab6fc8400d7c2d68a6c3a4b', 184, 184, null, 384, '2023-11-01', null, false, null),
  ('67997bb7-2787-599b-96fd-494ffb7d65f0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35T', 'Military Intelligence (MI) Systems Maintainer/Integrator, (MI Sys Mntr/Intgr)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Skill level 1 MI Systems Maintainer/Integrators apply power, computer, network, communications/signal, receiver, elements of troubleshooting theories to IISs. They integrate into an intelligence architecture and perform maintenance on and administration of intelligence workstations, servers, networks devices, sensors, and communications aerial and ground systems. They deploy intelligence satellite communication systems. Lastly, the 35T performs shop operations as directed through standard operating procedures', '481581202e50b8500e71f7189d2e18c33094c1249148213964407ec7c2aa1e5a', 184, 184, null, 385, '2023-11-01', null, false, 1),
  ('2169a993-79ee-584a-aa50-4ab280527578', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35T', 'Military Intelligence (MI) Systems Maintainer/Integrator, (MI Sys Mntr/Intgr)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The 35T SGT, in addition to mastering the SL1 skills, trains and provides purpose, motivation, and direction to subordinate Soldiers. Furthermore, they lead the integration of aerial and ground intelligence systems into an intelligence architecture. They also lead shop operations.', 'c3f33b6ab366a05407083d5c80b9c5f42709f3a822c2719104dafb1a6aaab1df', 184, 184, null, 386, '2023-11-01', null, false, 2),
  ('dd8e1362-c37e-5b3e-a66c-da6b10d6be4c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35T', 'Military Intelligence (MI) Systems Maintainer/Integrator, (MI Sys Mntr/Intgr)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The SSG 35T, in addition to mastering the SL1-2 skills, coach, counsel and mentor subordinate NCOs. They also manage the integration of aerial and ground intelligence DA PAM 600-25 01 October 2022 systems into an intelligence architecture. Additionally, they manage shop operations and the technical training and certification program for the 35Ts within their unit.', '618a929c48e6c8b4f13717ec7e9c5c41383a1b122825084262d7db0d6ca91f96', 184, 184, null, 387, '2023-11-01', null, false, 3),
  ('e0c143ea-69dd-5460-b1f9-1a87a1ce65c6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35T', 'Military Intelligence (MI) Systems Maintainer/Integrator, (MI Sys Mntr/Intgr)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'In addition to mastery of the preceding skills at SL1-3, 35T SFCs evaluate the integration of aerial and ground intelligence systems and shop operations. They coordinate with sustainment organizations to ensure the success of maintenance operations with the IMSA. Furthermore, they evaluate the technical training and certification program managed by the SSG and counsel senior leaders on the employment, training, and personnel required for intelligence systems.', '6eb7ce10bf89e015c8cf68c07b9592b5ccc66a631d24aa9040f773fd8ca2b94e', 184, 184, null, 388, '2023-11-01', null, true, 4),
  ('4566e138-4989-569f-a60f-41392952fa6e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35Z', 'Intelligence Senior Sergeant', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Intelligence Master Sergeant leads, manages, and trains company and battalion level intelligence activities; they will be able to operate as part of an Army modular component at the service, joint, inter-agency, inter-governmental, and multi- national levels on intelligence operations. Provides oversight and experience inclusive of all aspects of the Intelligence Warfighting Functions. Manages intelligence readiness, the intelligence cycle and empowers the intelligence enterprise through organizational expertise and operational guidance in the areas of All Source, CI, SIGINT, HUMINT, GEOINT, intelligence systems maintenance and intelligence support to the Cyber Domain at all echelons. Synchronizes intelligence efforts with operational requirements to achieve unit of effort to meet the commander’s intent. Reviews, evaluates, prepares, and executes intelligence asset deployment, employment, and redeployment. Compares intelligence TOE and TDA authorizations and recommends revisions per the Commander’s mission. Supervises and oversees the implementation of the Intelligence Architecture, to include the conduct of Military Intelligence systems maintenance and test operations. Success in this MOS requires demonstrated expertise in a variety of progressive assignments including leadership, key billet and staff positions at the strategic, operational, and tactical levels.', 'e56df6d1423578d59651abf0377ec95674070449c91f283aa85f2c153d40f840', 186, 186, null, 389, null, null, false, 5),
  ('d0235bef-0720-5e1b-81ed-0c85945f153f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '35Z', 'Intelligence Senior Sergeant', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Intelligence Sergeant Major enables mission command by serving as the principle enlisted advisor at the service, joint, inter-agency, inter-governmental, and multi- national levels on intelligence operations in support of multidomain operations. Provides oversight and experience inclusive of all aspects of the Intelligence Warfighting Function. Manages intelligence readiness, the intelligence cycle and empowers the intelligence enterprise through operational guidance and technical expertise in the areas of All Source, CI, SIGINT, HUMINT, GEOINT, intelligence systems maintenance and intelligence support to cyber at all echelons. Synchronizes intelligence efforts with operational requirements to achieve unity of effort and meet the commander’s intent. Reviews, evaluates, prepares, and executes intelligence asset deployment, employment and redeployment. Compares intelligence MTOE and TDA authorizations and recommends revisions. Supervises and oversees the implementation of Intelligence Architecture, to include the conduct of Military Intelligence systems maintenance and test operations. Success in this MOS requires demonstrated expertise in a variety of progressive assignments including leadership, key billet and staff positions at the strategic, operational, and tactical levels.', '510e86ba9bdc45b39bfc9cefdfc9c312c0fe796fd81c6db8eca4e1dcb5f8c9b4', 186, 186, null, 390, null, null, false, 6),
  ('5b3d80f9-35c9-549d-b51e-e095c6715e39', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '36B', 'Financial Management Technician', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The financial management technician performs duties specific to the following financial management processes: budgeting, disbursing, and accounting for government funds; payment for travel and commercial vendor services; pay support of Soldiers, DoD Civilians and contractors; and internal control operations.', '20db4714f7b1be1e069c585bada2270e507b54db9073151a14a4f28589cebf41', 188, 188, null, 391, null, null, false, null),
  ('b4627d19-b82a-52c4-a5e3-e84776984a08', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '36B', 'Financial Management Technician', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Financial management technician receives and posts funding, commitment and obligation documents to accounting and budget systems. Applies the basics of Fiscal Law, Accounts Payable, and Army Comptroller principles in the execution of job requirements. Exercises basic knowledge of General Fund Enterprise Business System. Receives and processes treasury checks for payment. Maintains disbursing files and prepares periodic financial reports. Receives, reviews, prepares and computes travel vouchers. Receives, reviews, and processes pay documents. Receives and reviews contracts, invoices and receiving reports. Prepares payment vouchers in accordance with various government regulations. Performs duties as cashier and conducts Financial Management Support Team operations.', '3cbb5ec5b45a51157c25ecb44411f9ba775de7383ec22fa2061a6a77dc710669', 188, 188, null, 392, null, null, false, 1),
  ('ccfc6202-6dfa-5d12-927c-ce1083a368af', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '36B', 'Financial Management Technician', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Financial management technician performs the duties shown in the preceding level of skill. Verifies accuracy of commitment registers, accounting documents and databases such as Operation Data Store (ODS), Logistics Information Warehouse (LIW), ITS.gov, Computerized Accounts Payable System (CAPS), and Deployable Disbursing System (DDS), as well as Planning Programming Budget Execution (PPBE) process, disbursing reports and documents, travel vouchers, vendor payments, and pay documents. Exercises the principles within Deployed Operations Resource Management and demonstrates familiarity with Enhanced Defense Financial Management processes and the Principles of Cost Analysis and Management. Plans, prepares and leads Financial Management Support Team operations.', '849ad4fb20851623afcc1ffffeec6ce00d5fa8125266934134d1d6b2675b9ed9', 188, 188, null, 393, null, null, true, 2),
  ('4167cf05-0cd1-5b36-91f6-c431fc8fe476', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '36B', 'Financial Management Technician', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Senior financial management technician performs the duties shown in the preceding level of skill. Supervises and prepares training to support accounting, disbursing, budget, travel, military pay, internal control, and vendor services operations. Certifies accuracy of accounting, budget, travel, pay, disbursing and vendor pay documents. Exercises routine knowledge of Resource Management and Budget, Cost Management, Audit Readiness, and Army Comptroller duties and responsibilities. Performs internal control inspections incompliance with various government and Financial Management regulations.', 'a28be232264801bdb443d7aa921a3a208565fe0f15409c22c14e007db50fe606', 188, 188, null, 394, null, null, true, 3),
  ('99c6ccd5-cca5-5647-bbfb-4b8d905880cb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '36B', 'Financial Management Technician', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Senior financial management technician performs the duties shown in the preceding level of skill. Provides technical guidance to lower grade personnel in accomplishment of those duties. Supervises financial management operations. Serves as Senior Financial Management Analyst to prepare and brief statistical data. Demonstrates familiarity with Enhanced Cost Management, Audit Readiness and Contracting responsibilities. Serves as Financial Management Inspector to identify systemic trends that affect overall Financial Management theater operations.', 'dd261ed20fe910d0650dcfe58c2265972561861702bb674fcc1a9a667e5ccbd8', 188, 188, null, 395, null, null, true, 4),
  ('a64a076f-423f-50d0-bfae-20962734a488', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '36B', 'Financial Management Technician', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Senior financial management technician performs the duties shown in the preceding level of skill. Provides technical guidance to personnel in accomplishment of those duties and supervises financial management operations. Senior enlisted financial management advisors provide technical and operational advice to commanders on all matters relating to financial management. Exercises familiarity with the Defense Decision Support model. Exercises principles within the Defense Financial Management and Cost Management requirements. Senior enlisted financial management inspectors inspect all functions and activities of financial management.', 'a1ef30b9e86dafc22dd1ab19280acfeae9357dabad8129fa82b4e91991cbcfbe', 188, 188, null, 396, null, null, true, 5),
  ('b044fd6e-d7be-5eee-a749-ec8ac7ec4110', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '36B', 'Financial Management Technician', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Senior Financial Management Advisor performs the duties shown in the preceding level of skill. The FM Sergeant Major (SGM) is a role with broad ranging responsibilities, regardless of specific position or assignment. In addition to those mission specific priorities and requirements by the Senior Commander, there are general requirements that a FM SGM must monitor and execute in the performance of his/her duties in order to ensure the health of the organization, development, and professional growth and guidance of the future enlisted leaders of the Finance Enlisted Corps. Plans, prepares and executes mission analysis to determine the level of finance support to theater operations. Provides direct mentorship, readiness and training oversight to all component subordinate detachments; serves as the conduit between the FM community and all supported external organizations; serves as the eyes, ears, and conscience of the commander with regard to Soldier morale, professional conduct and appearance of Soldiers within the organization; prevention of waste, fraud, and abuse of government funds; and ensures dignity and respect are afforded every Soldier within the organization.', '8f2258c59aa2c676f977ee67b145b56c0f8950fc44ec47471d4a33f7144c9d04', 188, 188, null, 397, null, null, true, 6),
  ('0cbd510a-d9ad-56e1-b429-fbc9329d2a2f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '37F', 'Psychological Operations Specialist, (PO Specialist)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Psychological Operations (PO) specialist conducts analysis of target audiences and environments; advises commanders and staffs; plans influence activities; develops series; conducts influence operations, and assesses progress towards approved objectives in support of the five branch functions (Military Information Support Operations [MISO], Psychological Warfare [PSYWAR], Build Partner Influence Capacity, Military Deception (MILDEC), and Civil Authority Information Support [CAIS]) to create and reinforce desired behaviors in selected foreign individuals and groups to achieve military and U.S. national objectives across the range of military operations.', '3c461d9b0228f97960a941b14bc3b463b76d465a1794bdd35a84b47a157dde20', 190, 190, null, 398, '2025-11-01', null, false, null),
  ('8fc64557-8d62-5dc4-b06a-75a7c36e0386', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '37F', 'Psychological Operations Specialist, (PO Specialist)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', '(USAR Only) Trains and maintains proficiency in all major duties. Research finished and current intelligence and open-source information Records, cross- references, stores and retrieves information manually or using automated data processing equipment. Develops concepts and designs product prototypes. Distributes and disseminates PO products. Performs initial analysis of adversary propaganda products and other media. Safeguards classified and sensitive material. Maintains journals, status boards, operations maps, and overlays. Operates and maintains organic communications, production, and other equipment. Prepares and presents briefings. Operates PO specific equipment.', 'a68977135209a405fe1453183bd9ea7abd680f85629f51aee352e5c2325ab5b9', 190, 190, null, 399, '2025-11-01', null, false, 1),
  ('52cc44a8-ee6b-55b0-89a8-75433094e991', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '37F', 'Psychological Operations Specialist, (PO Specialist)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform all duties of preceding skill level. Provides specific guidance and training for subordinates. Identifies and maintains information on the availability of products and delivery means. Determines the appropriate mix of media to implement PO. Supervises packaging of PO products for delivery by various means. Evaluates the effectiveness of PO products. Analyzes psychological vulnerabilities, and susceptibilities of PO target audiences to determine potential for exploitation. Evaluates current intelligence, PO studies and estimates to determine PO targets. Establishes and maintains reference files of translated materials. Analyzes adversary propaganda and other media.', 'ef14a353f5ec8daf67dce62e8c3a3ebf499a7128ab8efd70f612e33d6aef1056', 190, 190, null, 400, '2025-11-01', null, true, 2),
  ('fd6e1a30-4cb9-5881-aaed-95714acbc786', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '37F', 'Psychological Operations Specialist, (PO Specialist)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform all duties of preceding skill level. Provides specific guidance and training for subordinates. Assists in preparing and conducting PO training programs. Plans and organizes work schedules and assigns specific tasks in support of PO missions. Conducts liaison with the supported unit staffs. Coordinates resource requirements for the development, production and dissemination of PO products. Advises supported units on PO planning considerations. Integrates PO into conventional and special operations tactical through strategic level planning. Analyzes current intelligence products to identify gaps and subsequent collection requirements to support PO. Supervises receipt, analysis, and storage of PO-related information. Assists in the planning, identification and deployment of PO forces. Coordinates PO information collection requirements with supported command. Reviews analysis performed by subordinates. Supervises scriptwriters, broadcast specialists, journalists, and illustrators in the development and production of PO products. Supervises PO distribution and dissemination of PO products. Determines dissemination requirements for PO products. Assesses the overall impact of the PO series on target audience behavior.', 'e933757458682607eab0ae4cb8bf9e0650386029637638f26d139a781de2bf1e', 190, 190, null, 401, '2025-11-01', null, true, 3),
  ('eb8bdfa6-fc63-572d-8a3a-bee095bfbdce', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '37F', 'Psychological Operations Specialist, (PO Specialist)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform all duties of preceding skill level. Provides specific guidance and training for subordinates. Develops and conducts PO specific training programs. Plans and organizes PO task organizations. Supervises the planning, production and dissemination of PO products. Supervises the implementation and execution of PO. Coordinates PO liaison activities within supporting and supported unit staffs. Assists in planning for PO units at Brigade Combat Team (BCT) and above.', 'd7584db7c3bc71a001b10cc46321d6450bf186fe1128559c2d66cca882806d1c', 190, 190, null, 402, '2025-11-01', null, true, 4),
  ('27cd66d2-96ac-5dc0-afba-c8f774b1ecd3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '37F', 'Psychological Operations Specialist, (PO Specialist)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform all duties of preceding skill level. Provides specific guidance and training for subordinates. Coordinates PO liaison activities within supporting and supported unit staffs. Supervises the planning, organization, training, and coordination of activities within PO units. Supervises the employment of PO forces and execution of PO activities. Conducts planning for PO units at GCCs. Performs duties as PO staff NCO at Division and above, Command headquarters and joint commands.', '970186519e1fb17a673d87ccf8ea0aa41ccb73273974ae10901b3315ff811ac2', 190, 190, null, 403, '2025-11-01', null, true, 5),
  ('4580e968-a386-57a0-929f-c197ea75df99', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '37F', 'Psychological Operations Specialist, (PO Specialist)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform all duties of preceding skill level. Advises the commander and staff on all matters pertaining to enlisted personnel. Enforces the implementation of established policies and standards as they pertain to enlisted personnel within the command. Provides counsel and guidance to the NCOs and other enlisted Soldiers of the command. Manages the daily activities and operations of the unit.', '3cbe694421e43465cd816d6aa306db64c5c73aeeb2425434454a327ac3f3d700', 190, 191, null, 404, '2025-11-01', null, true, 6),
  ('bebc8c9a-6ce1-5e4f-afed-c835e4987d13', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38B', 'Civil Affairs Specialist (CA Specialist) (USAR Only)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Civil Affairs (CA) Specialists are trained and equipped to engage and influence unified action partners, indigenous populations, and institutions. Establishes and conducts military government operations, and provides civil considerations expertise through the planning and execution of Civil Affairs Operations (CAO) to enable Civil Military Operations (CMO).', '38333d05ba83e0ff35e483c5eb01c1d6566395909ab059d66c79aa274107b021', 193, 193, null, 405, null, null, false, null),
  ('20c5ecf8-35ce-5eaf-8b7f-ae3b610fc7d4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38B', 'Civil Affairs Specialist (CA Specialist) (USAR Only)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Gathers data for and produces geospatial representation of the Civil Component of the Operational Environment. Assists in the conduct of planned CAO assessments which can include literature and document review, visual observation, and interaction with local populace. Maintains and operates various voice and data communication systems, automated data processing equipment and various computer programs.', '4564bcf96835bf057215d09aecb9e918dc729adbb554f90e92fbfb600effa05a', 193, 193, null, 406, null, null, false, 1),
  ('375277b1-bc40-57c9-ab99-4bde11c66431', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38B', 'Civil Affairs Specialist (CA Specialist) (USAR Only)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and supervises duties of the preceding skill level. Coordinates resources required to support Civil Affairs Teams (CATs). Coordinates with Unified Action Partners, and conducts planned CAO assessments, and Key Leader Engagements (KLEs) to gather civil information and produce a depiction of the human terrain.', '48d2715d5be8407be8ef1adb8bc839e49b552a9e32cac6edd52007f254b6549f', 193, 193, null, 407, null, null, true, 2),
  ('e0cfb269-17e4-5f29-af9c-9ead2fbd76a3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38B', 'Civil Affairs Specialist (CA Specialist) (USAR Only)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and supervises duties of the preceding skill levels. Provides Civil Affairs support, language, and regional expertise as part of a CAT and identifies protection considerations for that team. Coordinates and assists with planned CAO assessments and conducts trend analysis on civil information, develops plans for dislocated civilian operations, determines civil vulnerabilities and develops CA operations measures of effectiveness. Integrates directly with supported organizations to identify requirements for CAO as part of the Military Decision-Making Process (MDMP).', '471f870c4f7765bf66e154e33f8d522e9a07851e699746905e06e15e29a4f43c', 193, 193, null, 408, null, null, true, 3),
  ('cde73972-8c5a-5c03-8a33-b624584d0a7f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38B', 'Civil Affairs Specialist (CA Specialist) (USAR Only)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The CA Team Sergeant is the master trainer of a four-person CAT responsible for ensuring the team is proficient in individual and collective critical tasks. The CA Team Sergeant is overall responsible for providing tactical and technical guidance and professional support to subordinates in accomplishing their duties. The CA Team Sergeant is the principal advisor to the leadership in the tactical employment of the CAT in their assigned environment by utilizing proven tactics, techniques, and procedures to conduct civil affairs operations in support of consolidating gains across the competition continuum.', 'dc239a6d5833c2506474dbbcbe11d5947354a0afe6293f6a8d3eb7ac96d16745', 193, 193, null, 409, null, null, false, 4),
  ('a03c14ea-a6cf-523e-9a00-e28ffe5ac467', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38B', 'Civil Affairs Specialist (CA Specialist) (USAR Only)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'MSG: Supervises the processing of operations and civil knowledge in a CA company or higher-level unit. Provides tactical and technical guidance to subordinates and professional support to both subordinates and superiors in accomplishment of their duties. Plans, coordinates, and supervises activities pertaining to organization, training, and operations. Develops and reviews tactical plans and training materials. Coordinates implementation of operations, training programs. 1SG: Serves as Senior Enlisted Advisor to the Company Commander. Responsible for maintaining and enforcing standards, ensuring training objectives are met, developing the Soldiers in the unit, all administrative functions, and ensuring the health, welfare, and morale of the unit and their families. Responsible for Enlisted manning and talent management; Leader professional development; NCO Common Core Competencies. Provides tactical and technical guidance to subordinates and professional support to both subordinates and superiors in accomplishment of their duties. Plans, coordinates, and supervises activities pertaining to administration, training, and logistics for the company. Supervises implementation of operations and training programs.', 'c04d246da90b0a409a16e725ed78c7d824a9f4c9d954a175b691ba7ffd33c79e', 193, 193, null, 410, null, null, false, 5),
  ('db8292e2-8613-5e41-ac12-afe59a07c0dd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38B', 'Civil Affairs Specialist (CA Specialist) (USAR Only)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'SGM: Serves as principal noncommissioned officer in a Civil Affairs battalion or higher to the staff and Operations Officer. Leverages experience to supervise the processing of operations. Provides tactical and technical guidance to subordinates and professional support to both subordinates and superiors in accomplishment of their duties. Plans, coordinates, and supervises activities pertaining to organization, training, and operations. Develops and reviews tactical plans and training materials at the battalion and higher level. Coordinates implementation of operations and training programs. The SGM is a subject matter expert in their field, primary advisor on policy development, analytical reviewer of regulatory guidance and often fulfills the duties of the CSM in the incumbent’s absence. CSM: Serves as Command Senior Enlisted Advisor to the Commander (Battalion and higher- level unit) on all enlisted issues and is primarily focused on the training, maintaining, caring, and leading of the unit''s Soldiers, facilities, and equipment. Assists the Commander in the implementation of command policies and establishes and enforces standards related to the appearance and conduct of all Soldiers within the command. Develops and executes NCO Professional Development Programs within the command and advises/counsels Soldiers on issues related to training, education, and professional development. Responsible for the unit’s individual skills training program for all CMFs. (Battalion and higher-level unit).', '2cb0cf8401fdecd77900e26fb073859cdd7a5e93f3340e22768537de7e9408d3', 193, 194, null, 411, null, null, false, 6),
  ('47240b12-6be3-5910-94e7-9aa2e046f5b7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38R', 'Civil Reconnaissance Sergeant (CR SGT) (Active Component Only)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Civil Reconnaissance Sergeant serves as the technical civil reconnaissance expert of a regionally aligned four-person Civil Affairs Team (CAT). The Civil Reconnaissance Sergeant employs reconnaissance efforts on a CAT in hostile, denied, or politically sensitive environments through the utilization of specialized tactics, techniques, and procedures to conduct civil reconnaissance, civil engagement, and civil network development to find, disrupt, and defeat threats in the civil component.', 'f3f5c0db2c009c7d7211a0390f8fea247df0d5fb99a53e41750e1737fb825662', 195, 195, null, 412, '2024-10-01', null, false, null),
  ('c3b9610f-dfd2-5943-a2fa-e560b0b5a54b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38R', 'Civil Reconnaissance Sergeant (CR SGT) (Active Component Only)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provides reconnaissance, infrastructure assessment, language, and regional expertise as part of a CAT. Conducts civil reconnaissance, performs civil engagements, assists in civil network development and engagement, and supports Transitional Governance. The Civil Reconnaissance Sergeant also integrates with supported organizations to identify requirements for Civil Affairs Operations (CAO) and Civil Military Operations (CMO) that enables supported commanders the ability to preserve combat power while consolidating gains across the competition continuum.', 'b0d12080f3135785e4d6ca107068c4dce5ca764c0e040065ebbee85c600e4654', 195, 195, null, 413, '2024-10-01', null, false, 3),
  ('70b67cbc-9f66-541f-85b0-478c7b63d6df', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38W', 'Civil Affairs Medical Sergeant (CA Medical SGT) (Active Component Only)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Civil Affairs (CA) Medical Sergeant conducts medical mission planning and performs advanced emergency medical treatment and prolonged field care in austere environments on a four-person Civil Affairs Team (CAT). The Civil Affairs Medical Sergeant provides field sanitation assessments, evaluates medical systems and infrastructure, conducts civil network engagement, medical reconnaissance, and provides situational understanding to transitional governments. These functions provide situational understanding, targeting data, information operations, freedom of maneuver, and stability. They shape the operational environment, affect the civil component, preserve combat power, maintain operating tempo, and consolidate gains by supporting Transitional Governance. The Civil Affairs Medical Sergeant performs their principal duties in hostile, denied, or politically sensitive environments.', 'f0e2e81a7131f4094392cbc630eedc73aa25493f976484c34e9021b1f901bfff', 197, 197, null, 414, '2024-10-01', null, false, null),
  ('3b035e1a-bcc6-5267-826a-7484a9d7a4dc', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38W', 'Civil Affairs Medical Sergeant (CA Medical SGT) (Active Component Only)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provides medical, language, and regional expertise as part of a CAT. Conducts medical mission planning and performs advanced emergency medical treatment and prolonged field care in austere environments on a four-person Civil Affairs Team (CAT). Provides field sanitation assessments, evaluates medical systems and infrastructure, conducts civil network engagement, medical reconnaissance, and provides situational understanding to transitional governments.', '68cdad636b236e6f601ab3de8e9ec4369ad1d64d1af374c03ff6ec6de0a4461d', 197, 197, null, 415, '2024-10-01', null, false, 3),
  ('427ed46a-47ca-5d38-88b8-e84c35094984', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38Z', 'Civil Affairs Senior Sergeant (Active Component Only)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Civil Affairs (CA) Senior Sergeant supervises, leads, or serves as a member of a CA unit that executes CA missions in support of national security objectives or as a CA subject matter expert in an Army or Joint Service organization.', 'd50a6f5809f6124845f7870bc73f51c088334fc5ebcffd465f57e14a54abfa41', 199, 199, null, 416, '2024-10-01', null, false, null),
  ('296e8fb8-2c0e-5fc0-af6a-3b91e6e0cd10', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38Z', 'Civil Affairs Senior Sergeant (Active Component Only)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The CA Team Sergeant is the Master Trainer of a four-person, regionally aligned Civil Affairs Team (CAT) responsible for ensuring the team is proficient in individual and collective critical tasks. The CA Team Sergeant is overall responsible for providing tactical and technical guidance and professional support to subordinates in accomplishing their duties. The CA Team Sergeant is the principal advisor to the leadership in the tactical employment of the CAT in hostile, denied, or politically sensitive environments through the utilization of specialized tactics, techniques, and procedures to conduct civil reconnaissance, civil engagement, and civil network development to find, disrupt, and defeat hybrid threats in the civil component. The key developmental position for MOS 38Z4O is a Team Sergeant on a Civil Affairs Team.', '141f6d1932d28784dd40d85ca3b6c1082df3e49e387067be6d22a236c25256fc', 199, 199, null, 417, '2024-10-01', null, false, 4),
  ('f9e451a2-56f3-544b-9eea-1da1211d0106', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38Z', 'Civil Affairs Senior Sergeant (Active Component Only)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', '(a) MSG: Supervises the processing of operations and civil knowledge in a CA company or higher-level unit. Provides tactical and technical guidance to subordinates and professional support to both subordinates and superiors in accomplishment of their duties. Plans, coordinates, and supervises activities pertaining to organization, training, and operations. Develops and reviews tactical plans and training materials. Coordinates implementation of operations, training programs.
(b) 1SG: Serves as Senior Enlisted Advisor to the Company Commander. 1SGs are responsible for maintaining and enforcing standards, ensuring training objectives are met, developing the Soldiers in the unit, all administrative functions, and ensuring the health, welfare, and morale of the unit and their families. Responsible for enlisted manning and talent management, leader professional development, and NCO Common Core Competencies. Provides tactical and technical guidance to subordinates and professional support to both subordinates and superiors in accomplishment of their duties. Plans, coordinates, and supervises activities pertaining to administration, training, and logistics for the company. Supervises implementation of operations and training programs. The key developmental position for MOS 38Z5O is First Sergeant in a Civil Affairs Company.', 'c025a57d977597a4655e7a0acdacadfdda307d0adc4c2af70b3b4449fa9e32bd', 199, 199, null, 418, '2024-10-01', null, false, 5),
  ('1e9dea95-baf9-51f6-b7dd-50b34a366110', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '38Z', 'Civil Affairs Senior Sergeant (Active Component Only)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', '(a) SGM: Serves as principal noncommissioned officer in a Civil Affairs battalion or higher to the staff and Operations Officer. Leverages experience to supervise the processing of operations. Provides tactical and technical guidance to subordinates and professional support to both subordinates and superiors in accomplishment of their duties. Plans, coordinates, and supervises activities pertaining to organization, training, and operations. Develops and reviews tactical plans and training materials at the battalion and higher level. Coordinates implementation of operations and training programs. The SGM is a subject matter expert in their field, primary advisor on policy development, analytical reviewer of regulatory guidance and often fulfills the duties of the CSM in the incumbent’s absence.
(b) CSM: Serves as Command Senior Enlisted Advisor to the Commander (Battalion and higher-level unit) on all enlisted issues and is primarily focused on the training, maintaining, caring, and leading of the unit''s Soldiers, facilities, and equipment. Assists the Commander in the implementation of command policies and establishes and enforces standards related to the appearance and conduct of all Soldiers within the command. Develops and executes NCO Professional Development Programs within the command and advises/counsels Soldiers on issues related to training, education, and professional development. Responsible for the unit’s individual skills training program for all CMFs. (Battalion and higher-level unit).', 'd61390dfbd76f7469bf5458174d42645ff7585a120a8772207fbe596b282efbf', 199, 199, null, 419, '2024-10-01', null, false, 6),
  ('59a8c750-de48-5f4b-8ec8-61c33be4caed', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '40D', 'Space Operations Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The space operations specialist serves in operating and generating force positions that deliver space or strategic missile defense capabilities and effects to the warfighter at all levels as outlined in JP 3-14, Space Operations, and FM 3-14, Army Space Operations in tactical and strategic multidomain operations environments.', '26f49916e1f96e25f3c8235b8138f02b179d633c9d485d0daacfdac2735bf754', 201, 201, null, 420, '2026-10-01', null, false, null),
  ('67a1da61-15de-5421-85ad-76e5dc6e8462', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '40D', 'Space Operations Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Member of a space operations element, team, section, or crew that provides space operations and strategic missile defense capabilities, products, and services. Emplaces, as needed, and operates space operations and strategic missile defense equipment and systems, troubleshoots issues and conducts quality control checks, and performs preventive maintenance checks and services (PMCS) and repairs as needed. Operates and performs PMCS on assigned vehicles and equipment. Prepares system and equipment related forms and reports. Ensures data connectivity between operational equipment and operational Joint service networks. Initializes and operates data networks and remote video displays. Executes offensive and defensive operations.', '3088f1b1e037537cd3e988f4bb4354ab8774323541b474f6b6ac396fce32a94e', 201, 201, null, 421, '2026-10-01', null, false, 1),
  ('99be0d96-b6a0-5701-bc74-30466d2c8682', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '40D', 'Space Operations Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provides technical guidance to subordinate Soldiers in the performance of their duties. Leads small elements, teams, sections, or crews that provide space or strategic missile defense capabilities. Trains subordinate Soldiers on space and strategic missile defense capabilities available and provided, space operations and strategic missile defense tasks, and how to operate in a denied, degraded, and disrupted space operational environment (D3SOE). Performs technical analysis and provides the appropriate capability, product, service, and/or report. Provides intermediate level quality assurance on capabilities, products, and services provided. Performs technical analysis, and ensures appropriate action taken to initiate reports, warnings, and offensive and defensive operations.', '6f7aeb737f5e01e482e8f689b9af6ee4e8bd05e1702a20028ade766cf5569685', 201, 201, null, 422, '2026-10-01', null, false, 2),
  ('3031ca05-7d36-567e-8812-e295c91f6d40', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '40D', 'Space Operations Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in the preceding skill level and provides technical guidance to subordinate Soldiers in the performance of their duties. Leads larger space or strategic missile defense operations elements, teams, sections, or crews. Performs liaison, operations, and training noncommissioned officer (NCO) functions. Member of the staff in battalion and brigade level units with or without other space operations personnel assigned where they participate in the Military Decision-Making Process (MDMP), and advise commanders and their staff on the availability, use, and integration of space and strategic missile defense capabilities. Coordinates with other space and strategic missile defense operations organizations as needed. Trains staff and subordinate units on space and strategic missile defense capabilities and how to operate in a D3SOE. Supervises emplacement, employment, maintenance, and march order of capabilities and equipment. Organizes, participates in, and supervises unit level space and strategic missile defense operations training and certification programs.', 'e9928611527eac5e35f641dc987c8f1d0c410d1506960b1a7f750069a2c7df6c', 201, 201, null, 423, '2026-10-01', null, true, 3),
  ('2715fcd2-7f56-5ff4-b8ea-06825f5fc10c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '40D', 'Space Operations Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in the preceding skill levels and provides technical guidance to subordinate Soldiers in the performance of their duties. Leads space or strategic missile defense operations sections, platoons, and detachments. Plans, organizes, supervises, and focuses the efforts of subordinate space and strategic missile defense operations elements, teams, sections, crews, and units and organizations, and monitors and evaluates their space and strategic missile defense related and D3SOE training programs. Member of the staff at brigade and higher-level units with or without other space operations personnel assigned where they participate in MDMP and effectively advise the commander and staff on all aspects of space and strategic missile defense operations.', '9cda9d723793b83cb1e22915e7ed98f696f0b9e3172517060b99826d830e43d2', 201, 201, null, 424, '2026-10-01', null, true, 4),
  ('3bbe7778-8876-5cb3-9d27-c75a918de2a3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '40D', 'Space Operations Specialist', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs all duties of preceding skill level. Supervises, plans, coordinates, and directs the space and strategic missile defense operations provided to the warfighter at all levels in the generating and operating force in a multidomain operations environment. Supervises, provides technical guidance, mentors, and counsels Soldiers and NCOs. Advises the commander and staff on enlisted personnel matters and enforces the implementation of established policies and standards. Serves as First Sergeant in space and strategic missile defense operations companies, and as key NCO in a battalion- level or higher staff section providing space and strategic missile defense operations-related oversight, planning, capability development, technical advice, and assistance to commanders, staff, and subordinate units.', '50d043b77571553b0079c1bc630dbc4d26d7e112b6e9a332a17ae1520660bb23', 201, 201, null, 425, '2026-10-01', null, true, 5),
  ('3225ab2f-c005-50df-b671-f7bf68661b6f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '40D', 'Space Operations Specialist', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs all duties of preceding skill level. Advises the commander and staff on all matters pertaining to enlisted personnel. Enforces the implementation of established policies and standards as they pertain to enlisted personnel within the command. Provides counsel and guidance to the NCOs and other enlisted Soldiers of the command. Manages the daily activities and operations of the unit.', '626cd88d4056f1655c470d1c38fd318abb761883c3ce9af3aa4e8e711822d231', 201, 202, null, 426, '2026-10-01', null, true, 6),
  ('d7af064d-0aa9-55eb-b5ff-148f872a945c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42A', 'Human Resources Specialist (HR SPC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The human resources specialist supervises or performs personnel and administrative functions in support of company, battery, troop, detachments at division, corps, and echelons above corps; in brigade and battalion S1''s or in other similar organizations, activities and units; and advises the commander, the staff, and unit Soldiers on human resource matters. The human resources specialist also participates in occupational classification and management of human resources or supervises personnel management of human resources or supervises personnel management activities to include maintaining officer and enlisted personnel records and processing personnel actions concerning Soldiers and their families. The human resources specialist operates and manages field personnel information systems, trains and assist system users, or monitors system activities. The human resources specialist provides and manages postal operations.', 'e025093c03628ba447f3fc4b59e1642c3ede4935b20d202f8a503f99cbed4d56', 203, 203, null, 427, null, null, false, null),
  ('5bbf43a8-38ca-5bf0-9f15-8c405f45e898', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42A', 'Human Resources Specialist (HR SPC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Prepare personnel accounting and strength management reports. Prepare and reviews personnel casualty documents. Monitor appointment of line of duty, survivor assistance and summary court officers. Processes line of duty investigations. Prepare letters of sympathy to next of kin. Prepares and processes recommendations for awards and decorations and arranges for awards ceremony. Prepares, updates, and coordinates requests for evaluations, to include responding to evaluation inquiries. Prepares and monitors requests for promotions and arranges for promotion ceremony, to include promotion declinations, reconsideration for promotions, and arrange for reduction and removal boards for Soldiers on local promotion standing lists. Processes centralized and decentralized promotions and reduction actions. Prepares and monitors requests for reductions, transfers, and discharges. Prepares and monitors requests for identification cards and tags, leaves, and passes, line of duty determination, MILPER data and information management, orders for temporary duty and travel, personnel processing, personnel security clearances, training and reassignment, retention, military and special pay programs, personnel accounting and strength management, transition processing, meal cards, training Soldier support file, and unit administration. Apply knowledge of provisions and limitations of Freedom of Information and Privacy Acts. Requisitions and maintains office supplies, blank forms, and publications. Types military and non-military correspondence in draft and final copy. Prepares and maintains functional files per Army Records Information Management System (ARIMS). Evaluate personnel qualifications for special assignment. Prepares and processes requests for transfer or reassignment. Process classification/reclassification actions. Prepare orders and request for orders. Prepares and maintains officer and enlisted personnel records. Transfer records. Process personnel for separation and retirement. Process applications for OCS warrant officer flight training or other training. Processes bars to reenlistment, suspension of favorable personnel actions. Initiate action for passports and visas. Posts changes to Army regulations and other publications. Executes and monitors automated interface with other automated systems. Monitors status of unresolved errors and initiates required corrective action. Monitors processing of feedback from HQDA and takes necessary corrective action. Monitor performance of systems users. Identify problems and discrepancies. Provides assistance or refers resolution to superiors. Conduct postal operations.', '1356cc7fdc80cdc10bab3e7535b70b0f0060793a72ef4f560cee54a305e6e2d9', 203, 203, null, 428, null, null, false, 1),
  ('bd68b492-d6ac-50ef-a0d0-050af8269767', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42A', 'Human Resources Specialist (HR SPC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at preceding skill level and provides technical guidance to subordinate Soldiers in accomplishment of these duties. Review cyclic and other reports to assess systems performance. Maintain liaison with servicing data processing facility and field managers of interfaced systems. Prepares and monitors plans for supporting mobilization. Conducts postal inspections and audits. Conducts postal planning.', '76bcf8c054634d7b29a28edcee09fe8b141007982cb42e8238c933bc759ec617', 203, 203, null, 429, null, null, true, 2),
  ('db8e42e5-6537-51f7-b3cd-5d5e89ab7e27', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42A', 'Human Resources Specialist (HR SPC)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties of and supervises the functions of the preceding skill levels. Supervise specific human resources functions in a personnel office, Battalion S1 and human resources support activity. Advise commanders and other staff members on Soldiers, personnel readiness and strength levels of supported reporting units. Reviews consolidated reports, statistics, applications, and prepares recommendations for personnel actions to higher headquarters. Reviews and prepares reports and data on strength (gains and losses) of personnel and makes duty assignments of enlisted personnel. Review cyclic and other reports to assess systems performance. Maintain liaison with servicing data processing facility and field managers of interfaced systems. Supervise postal operations.', 'abb35cd2aa124a8fc9ae684f9e5d583347ea83bd534192c4f970c63dae289a55', 203, 203, null, 430, null, null, true, 3),
  ('76c4a967-0bbd-55f5-9234-66250ade204e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42A', 'Human Resources Specialist (HR SPC)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise HR office, specific human resources functions, Battalion S1 and human resources support activity. Performs duties of and supervises the functions of preceding skill levels to include quality assurance of product.', '652a0418d043c5a482d856bc5d043e174cb666053f87a85f93c27ad25aa72204', 203, 203, null, 431, null, null, true, 4),
  ('2ed1c5d1-1c0f-5ab1-a7d5-65ac461be8e4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42A', 'Human Resources Specialist (HR SPC)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties of and supervises at preceding skill level including quality assurance, in a personnel activity, while performing specialized or all encompassing human resource functions.', '008b792f064d2954e5f2c59cfcad70895db9102606ef8555d168e406c63a4bbb', 204, 204, null, 432, null, null, true, 5),
  ('830b684f-ecb3-5a49-b094-787ae6708983', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42A', 'Human Resources Specialist (HR SPC)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise duties at the preceding skill levels. The G-1/AG Sergeant Major (SGM) is a role with broad ranging responsibilities, regardless of specific position or assignment. In addition to those mission specific priorities and requirements by the Senior Commander and the G-1, there are general requirements that a G-1/AG SGM must monitor and execute in order to ensure the health of organizations, and development and growth of the future enlisted leaders of the AG Enlisted Corps. Provide direct mentorship to S1s, provide training oversight to units (within their installation or area of operation), maintain external relationships, provide readiness oversight, integrate and utilize HR metrics, and advise the G-1 and organic CSMs.', '02e16a9dbb15a4c76780dd4d3279066e06ab8cf6f762c87b0d2695c2b032e6b7', 204, 204, null, 433, null, null, true, 6),
  ('eb059bc0-18ff-5af3-9013-c345c4c864dd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42R', 'Musician', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'MOS breakdown for band member (MOS 42R). This paragraph covers 16 individual musical specialties. This MOS requires an ASI indicating the musical instrument/equipment on which the Soldier is qualified to perform. By ASI they are:
(1) Cornet or Trumpet player, ASI 9B. (2) Euphonium player, ASI 9C. (3) French Horn player, ASI 9D. (4) Trombone player, ASI 9E. (5) Tuba player, ASI 9F. (6) Flute player, ASI 9G. (7) Oboe player, ASI 9H. (8) Clarinet player, ASI 9J. (9) Bassoon player, ASI 9K. (10) Saxophone player, ASI 9L. (11) Percussion player, ASI 9M. (12) Keyboard player, ASI 9N. (13) Guitar player, ASI 9T. (14) Electric Bass player, ASI 9U. (15) Vocalist, ASI 9V. (16) Music Support Technician, ASI 9X. b. Major duties. The brass, woodwind, rhythm section player, percussionist, vocalist or music support technician performs as a member of a Music Performance Team (MPT) in an Army Band.', 'c97575943cd6a793fc994d27e66839c6d5a4276a789612783b455b793dacdb2b', 205, 205, null, 434, null, null, false, null),
  ('b9053f5d-6562-5b5b-8311-be854d9566f5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42R', 'Musician', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Musician. A Musician (instrumentalist, vocalist, or music support technician) performs all applicable styles of music as directed by unit mission. Performs confidently as a member of an MPT in various settings. Must possess the ability to memorize music and perform on individually assigned instrument or equipment. Prepare and perform music of various styles with minimal errors in order to accomplish mission requirements. May perform duties as clerks or assistants in Band Critical Function Areas.', 'a0d5f075d3c9808f716eb3a069580495591a8d03aafc3020f359cc7475acb737', 205, 205, null, 435, null, null, false, 1),
  ('23c2cb32-b9a7-5261-a4d1-7f5f3d2b94a2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42R', 'Musician', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Musician. A Musician performs duties shown in preceding level of skill, and provides technical guidance to junior grade personnel. May perform duties as Assistant MPT Leader, Section Leader, or Section NCO in Band Critical Function Area. Performs duties as ASAP Coordinator, Barracks NCO, Master Fitness Trainer, Retention NCO, Unit Armorer, Ammo Handler, Unit Prevention Leader, CBRN NCO, and Master Driver as required. They may also perform collateral duties as Drum Major or Lessons Learned NCO.', 'e9449808f515f9b3640096930420afc5d440f52729254673647f641350a4d4d8', 205, 205, null, 436, null, null, true, 2),
  ('1c54d70e-5b1b-5658-98c4-114933cbb313', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42R', 'Musician', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Squad Leader or Support NCO. An Advanced Musician performs duties shown in preceding skill levels. May serve as a Squad Leader in a Platoon, or as a Support NCO in a Band Critical Function Area. As a Squad Leader, the NCO organizes, instructs, trains, counsels, and evaluates junior grade Soldiers within the squad. SSGs who are assigned to Army Bands as Support NCOs will supervise the following Band Critical Function Areas: Safety, Security, and Communications section, Public Affairs/Production section; and Training section (select Direct Support Units). SSGs may also serve in Band Critical Function Areas as a Section NCO, Advanced Musicians in an MPT, Assistant MPT Leader, and MPT Leader. May perform duties as Ceremonial Conductor, Drum Major, EO Leader, Master Fitness Trainer, Master Resilience Trainer, Lessons Learned NCO and Retention NCO as required.', 'd499797ca71899fdb1154a21a10719c616208d3d863d534b515384995f6af1f7', 205, 205, null, 437, null, null, true, 3),
  ('5ed8b2be-1753-58d1-bf37-f72994461e92', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42R', 'Musician', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Platoon Sergeant, Senior Support NCO or Operations Sergeant (select Direct Support Units). A Senior Musician performs duties shown in preceding skill levels. May serve as Platoon Sergeant or as Senior Support NCO in Band Critical Function Areas. Platoon Sergeant accounts for, counsels, trains, mentors, and evaluates Squad Leaders; senior rates Musician Sergeants within the platoon and others as required; and trains and leads a Platoon of two to three squads. Senior Support NCO supervises the following Band Critical Function Areas: Human Resources section; Logistics and Resource Management section; and Training section as required. Operations Sergeant advises the commander on all aspects of band operations, collects lessons learned, and in select Direct Support Units, supervises the operations section of the unit. May perform duties as MPT Leader, Drum Major, EO Leader, Master Fitness Trainer, Master Resilience Trainer, and Group Leader as required.', '3f3f37b0018e010fda4c00015b7c864dfbf3a1d0f1e9693ce0dfbce2979e17a5', 205, 206, null, 438, null, null, true, 4),
  ('c64f2ced-ec68-55e2-8361-e76936254bbe', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42R', 'Musician', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'First Sergeant or Operations Sergeant. A Master Musician performs duties shown in preceding skill levels. May serve as First Sergeant or Operations Sergeant.
(a) First Sergeants: First Sergeants in Direct Support Units manages enlisted musical structure of organization, and manages critical function duty support structure of organization. The First Sergeant counsels, trains, mentors, and rates skill level 4 Musicians, and senior rates skill level 3 Musicians as required. Serves as the band commander in their absence. Is the principal enlisted conductor of the band in Direct Support Units.
(b) Operations Sergeant: The Operations Sergeant advises the commander on all aspects of band operations, supervises the operations section of the unit in both Direct Support Units and General Support Units, collects lessons learned, and serves as quality control alongside the commander. Responsible for collecting, analyzing, archiving, and disseminating their individual unit’s best practices and lessons learned from their units operations, experiments, and training events. The Operations Sergeant counsels, trains, mentors, and rates skill level 4 Musicians, and senior rates skill level 3 Musicians as required.', 'aec5431806a610032176ee61eba117fd4fee7548849bd5b788e60a61a8ecbd38', 206, 206, null, 439, null, null, true, 5),
  ('f24900ab-5243-5b7f-8290-f8411f723709', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42R', 'Musician', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Band Sergeant Major (General Support Units), performs duties shown in preceding skill levels, manages enlisted musical structure of organization, manages critical function duty support structure of organization, counsels, trains, mentors, rates skill level 5 musicians, and senior rates skill level 4 musicians as required. Advises the commander on all aspects of band operations and serves as band commander in their absence. Is the principal enlisted conductor of the band. Serves as CSM, USASOM, upon selection.', 'e8a5e93bc5e5da802e267853e8a2f83953645faa3f43b8ad33d7468492c5f3c5', 206, 206, null, 440, null, null, true, 6),
  ('e375cc36-8d06-59df-ac01-ba280835cb8d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42S', 'Special Band Musician', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The special band musician performs as a musician or in direct support of the mission of The U.S. Army Band, The U.S. Army Field Band, U.S. Military Academy Band, or the 3rd Infantry (The Old Guard) Fife and Drum Corps. Use of MOS 42S is restricted to the special bands only.', '797695f338f63d704a4ad78712308ba7b83677a87a651ca183d326538b7469c1', 210, 210, null, 441, null, null, false, null),
  ('54ba1d9e-9090-56cd-ac26-10dcd3d6ec1a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42S', 'Special Band Musician', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform as instrumentalist or vocalist in field music element or special band. Serve in administrative, training, supply, or operations positions.', '5672e41790560976c0549f01ef41f90d6e8968b711a539b8e06a1ce68046f08a', 210, 210, null, 442, null, null, false, 3),
  ('cea43dd4-3494-5dce-a855-21eea0c8e178', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42S', 'Special Band Musician', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform as solo instrumentalist or vocalist, NCO in an instrumental group, band support technician, administrative and supply support, library support, and a senior vocalist music annotator/commentator.', 'ee7b3a7b2cf1834ef5d550a0b2b3d399568bc38dbee40241bb0479397ea18107', 210, 210, null, 443, null, null, false, 4),
  ('6a9cfe73-ed4a-5429-bb3c-04b742c7f9ee', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42S', 'Special Band Musician', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serve as principal NCO in music or support section, group, element or band.', '96e1dde0737183a8194112e2e5e357af14ab201748a82351fbee49141a2147bb', 210, 210, null, 444, null, null, false, 5),
  ('4f3271d3-3670-508e-b45b-da233cdb7c64', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42T', '42T Talent Acquisition Specialist (Active Component and USAR)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Recruits qualified personnel for entry into the Army in accordance with applicable regulations, supervises recruiting and recruiting support activities.', '456358aa6df740d77ff5fb359406e757154e56c5c2f6b93d636739a49b507caa', 212, 212, null, 445, '2025-10-01', null, false, null),
  ('eda499f3-d794-5dba-a5a9-894a387340cd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42T', '42T Talent Acquisition Specialist (Active Component and USAR)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Recruits, interviews, counsels and qualifies applicants for enlistment. Distributes and displays recruiting publicity material. Identifies and cultivates community centers of influence. Explain benefits. Prepare enlistment forms and documents. Arranges for transportation, meals, and lodging for applicants where required. Assists in market research and analysis and makes appropriate recommendations to the chain of command.', 'b7a6388a88f930fb830979e1cd88c8b82aadb411a79b006ea141e6838659e093', 212, 212, null, 446, '2025-10-01', null, false, 3),
  ('3f225db2-6a37-5718-ae64-fc7a14813f78', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42T', '42T Talent Acquisition Specialist (Active Component and USAR)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Utilizes and analyzes management data to evaluate subordinates'' performance. Conduct professional development programs. Accomplishes administration, prepares plans and SOPs. Maintain statistics on recruiting programs. Maintain enlistment publications and administrative files. Prepare enlistment reports.', '00be5f7844ecda4a23e0d107dd793c50c7258520f7928d4881c18f48da7c4114', 212, 212, null, 447, '2025-10-01', null, false, 4),
  ('5d58f9e1-3aa2-5f3d-880f-dfec4fe2e090', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42T', '42T Talent Acquisition Specialist (Active Component and USAR)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans, organizes, and coordinates recruiting activities. Develops and directs training programs to assist subordinates. Plans and conducts seminars and conferences. Assigns duties and evaluates performance of subordinate recruiting personnel. Conduct inspections to ensure proper and efficient operation and management. The USAR talent acquisition specialist also performs duties shown in preceding level of skill.', '689bae63f8771870ce59f939c4b29bf4a903d28abf78b9b831b0b762d43f1e07', 212, 212, null, 448, '2025-10-01', null, true, 5),
  ('2ba40731-81de-5bf2-8e38-1ebfa0f7161e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '42T', '42T Talent Acquisition Specialist (Active Component and USAR)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Develops and implements operational plans and procedures in support of all units, assigned recruiters, recruiting stations, and recruiting companies; records and reports recruiting force achievements and shortfalls to evaluate organizational and individual recruiting performance; assists in overseeing enlistment processing of Future Soldiers; coordinates enlistment waiver processing, special missions, and ensures regulatory compliance in all areas of concern; Plans and conducts seminars and conferences. Assigns duties and evaluates performance of subordinate recruiting personnel. Conduct inspections to ensure proper and efficient operation and management.', 'b7e1bfd25a00d738c6f337de41e3f22ea21de36e7db785e2d137509aa235f160', 212, 212, null, 449, '2025-10-01', null, false, 6),
  ('ac6cc3d8-5f2e-51df-b16a-bde6478431ac', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46S', 'Public Affairs Mass Communication Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The public affairs mass communication specialist participates in and assists with the execution, supervision and administration of successful Army Public Affairs programs and activities in support of Theater Army, joint, interagency, intergovernmental, multinational and unified operations. Public affairs mass communication specialists provide direct public affairs support through the planning, coordination, execution and supervision of public affairs operations to inform internal and external audiences, media and key publics. The public affairs mass communication specialist is a professional communicator, employing modern technology, equipment and information systems to collect, process and rapidly deliver print and broadcast multimedia products in support of expeditionary and campaign public affairs operations. The public affairs mass communication specialist is trained and equipped to fulfill the public affairs functions of public information, command information and community engagement. The public affairs mass communication specialist supports public affairs operations through the public affairs core tasks to conduct public communication, media facilitation, public affairs training and planning. The public affairs mass communication specialist releases official information about Army personnel, materiel, activities and operations through news releases, media engagements, press conferences and social media and Internet-based platforms. The public specialist performs unit level maintenance on assigned equipment and performs operator maintenance on assigned vehicles and generators. The public affairs mass communication specialist may be assigned to brigade combat teams, multifunctional brigades, divisions, corps, Theater Army staff sections, separate public affairs units, and broadcast communications under the Defense Media Activity. The public affairs mass communication specialist may volunteer for assignment with Special Forces and Airborne units. The CMF is primarily non-accession in the active component and primarily initial accession in the reserve components (ARNG/USAR).', 'b0670cac4df0294df94780a28498a6bdd37c9654944c3f1bd2e389a792a1800c', 214, 214, null, 450, null, null, false, null),
  ('8d55cf94-810d-5664-916a-34a3f9211edb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46S', 'Public Affairs Mass Communication Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The public affairs mass communication specialist conducts digital news gathering; collects, processes and delivers multimedia and Internet-based news releases and information products, articles, digital photographs and digital broadcast packages of Army personnel, materiel, activities and operations for release to key publics and internal and external audiences; performs as a writer, photographer, videographer, and public affairs representative; prepares commercial-quality digital content for release through radio, television, multimedia and Internet-based mediums; performs operator-level maintenance on assigned equipment. The Public affairs mass communication specialist provides limited support to media facilitation, public affairs training, public affairs planning and community engagement.', '5f670046fb74b495bec37ee9265f788f217afeb959afbc66e6513e20fd152b44', 214, 214, null, 451, null, null, false, 1),
  ('34ed8de7-8779-5cce-b023-6779206e0725', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46S', 'Public Affairs Mass Communication Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in the preceding level of skill. The Public Affairs Sergeant is an expert on public affairs activities, core tasks, tenets and characteristics; provides training and technical guidance to subordinates; serves as a first-line supervisor in public affairs operations; reviews public information products for security, accuracy, policy, and propriety; performs all functions of digital news gathering and digital content production for documentation and release to global and domestic audiences; performs as a writer, photographer, producer, editor, and public affairs representative; participates in or supervises the operations of a broadcast section, team or detachment; performs operator-level maintenance on assigned equipment vehicles and generators. The Public Affairs SGT provides support to media facilitation, public affairs and common skills training, public affairs planning and community engagement.', 'fc1d195dfc14a7d8b8c0b88a5c9d4a66a1f2f43eb9388e4c6fd7434e3e10f96d', 214, 214, null, 452, null, null, true, 2),
  ('378159cd-7d1e-5a3d-97c1-2835d3464640', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46S', 'Public Affairs Mass Communication Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in the preceding level of skill. The Public Affairs NCO may serve as the commander’s senior enlisted public affairs advisor; supports public affairs and operations plans and orders; provides tactical and technical guidance to subordinates and professional support to both subordinates and superiors in accomplishment of their duties; supervises the administration of the Army Public Affairs program and activities; supervises and reviews information products for release; supervises multimedia television broadcast sections or elements; prepares work schedules and assigns tasks based on operational requirements. The Public Affairs NCO participates in staff processes and procedures and provides support and supervision to media facilitation, public affairs and common skills training, public affairs planning, and community engagement.', '0476f9ca8a981c3ac2545fe77298313eb2411070c815e366eac75c3fd2482e76', 214, 214, null, 453, null, null, true, 3),
  ('746480d0-2e0e-510d-9386-7f3bd41e5fea', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46T', 'Mass Communications Systems Engineer (Mass Comm Sys Eng)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Installs, operates, maintains, and performs unit and higher levels of maintenance on mass communications equipment and systems in support of Army, Joint, and multinational operations; maintains forms, records, prescribed load lists (PLL) special tools. and test equipment; performs preventive maintenance checks and services (PMCS) on assigned vehicles and generators.', '13728335cca7b191c1f47eaad4dbec80aaba1b5f2b53475d1afda9ffad357c34', 216, 216, null, 454, '2026-10-01', null, false, null),
  ('409eda13-e4f9-5ef8-8baf-c8470a7bd175', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46T', 'Mass Communications Systems Engineer (Mass Comm Sys Eng)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates and performs unit and higher levels of maintenance on visual acquisition systems and cameras; studio accessories consisting of computer controlled video switchers and audio mixers/consoles, synchronous generators, distribution equipment, and amplifying equipment; motion/still photo imaging equipment; closed circuit systems; visual imagery satellite, microwave, RF transmission and cable distribution systems associated with visual information (VI) operations; operates and performs PMCS on assigned vehicles and power generators.', 'a42791b1176cbb93f8b96a6b7d6609dc4f4ae920471d05ad428f23045643f32a', 216, 216, null, 455, '2026-10-01', null, false, 1),
  ('e834361d-843e-5d5e-b7fe-9ab12d73e91a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46T', 'Mass Communications Systems Engineer (Mass Comm Sys Eng)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provides technical guidance on complex operations and maintenance tasks; adjusts and maintains mass communications to prescribed standards; ensures that proper techniques and procedures to diagnose malfunctions of VI and associated equipment are employed; supervises receipt, storage, and issue of VI supplies.', '7984c11bbb0f37aca7c8c4402484f0ae443cdd89cd6bca2921739a2320b3e3da', 216, 216, null, 456, '2026-10-01', null, false, 2),
  ('770c0573-6e3a-5117-be3c-9f64e0ac2ea6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46T', 'Mass Communications Systems Engineer (Mass Comm Sys Eng)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Prepares work schedules and assigns tasks based on requirements; plans technical aspects to satisfy on-air maintenance requirements; develops and advises commanders on mass communications and VI production engineering requirements; establishes and applies quality control measures in mass communications and VI productions; serves as team leader on mass communications equipment repair teams.', '0168820a62acc90a5693b4271992e57f5d4e6e5749f72a86432f366c20209c7e', 216, 216, null, 457, '2026-10-01', null, false, 3),
  ('577d61ac-9453-5491-8851-8accd6ad88bc', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46T', 'Visual Information Equipment Operator-Maintainer (VI Equip Op-Maint)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Installs, operates, maintains and performs unit and higher levels of maintenance on visual information equipment and systems, to include Video Teleconferencing VI equipment, in support of Army, Joint, and Combined operations; maintains forms, records, PLL, special tools and test equipment; performs PMCS on assigned vehicles and generators.', 'd68a5072cfe54d697d2cf579990a0346ad5c519d41b12e116f24a22c256b4829', 218, 218, null, 458, null, '2026-10-01', false, null),
  ('ffd7c887-fbb6-5aac-a801-78a0c482b8c3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46T', 'Visual Information Equipment Operator-Maintainer (VI Equip Op-Maint)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates and performs unit and higher levels of maintenance on television receivers/monitors and cameras; studio accessories consisting of computer controlled video switchers and audio mixers/consoles, synchronous generators, distribution equipment, and amplifying equipment; motion/still photo imaging equipment; closed circuit systems; visual imagery satellite, microwave, RF transmission and cable distribution systems associated with VI operations; operates and maintains VI equipment used for Battlefield Video Teleconferencing and in a Video Teleconferencing facility; operates and performs PMCS on assigned vehicles and power generators.', '2b61333b37c642d685e8637a20c6d040518ea250d197d543f6f5a4aaa5209d18', 218, 218, null, 459, null, '2026-10-01', false, 1),
  ('9b293d87-38cd-5743-8f17-873286994282', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46T', 'Visual Information Equipment Operator-Maintainer (VI Equip Op-Maint)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provides technical guidance on complex operations and maintenance tasks; adjusts and maintains TV and radio equipment to prescribed standards; ensures that proper techniques and procedures to diagnose malfunctions of VI and associated equipment are employed; supervises receipt, storage, and issue of VI supplies.', 'be43ce18b20b564ac1c854b7b9b51ca0e0cfb05f826573ff8bba1ce68a003cc6', 218, 218, null, 460, null, '2026-10-01', false, 2),
  ('8ca40a67-7c7d-5b02-9343-842481af028d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46T', 'Visual Information Equipment Operator-Maintainer (VI Equip Op-Maint)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Prepares work schedules and assigns tasks based on requirements; plans technical aspects to satisfy on-air maintenance requirements; develops and advises Commanders on TV broadcasting and VI production engineering requirements; establishes and applies quality control measures in TV broadcasting and VI productions; serves as team leader on VI/Audio equipment repair teams.', '60b33fa54cfd7c05df760448c7c3eeea78967a1b0c92919d960404474d405a0a', 218, 218, null, 461, null, '2026-10-01', false, 3),
  ('7180a137-2f3a-5230-afa8-a40f38217dbe', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46V', 'Visual Information Specialist (Visual InfoSp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates audio visual equipment to combine text, sound, photo, animation, video, and graphics into a multimedia product in support of combat documentation, battlefield operations, Psychological Operations, Military Intelligence, Medical, Public Affairs and training functions; operates broadcast, collection, television production, video teleconferencing and distribution equipment; creates illustrations, layouts, map overlays, posters, graphs, charts, and internet web pages; performs unit level maintenance on assigned equipment and PMCS on assigned vehicles and generators.', '264b787e01e7a1d441201812df1b435b39cbc69e541a6b4d26cde5471310a738', 220, 220, null, 462, null, null, false, null),
  ('2c161768-08da-5763-b07c-79e672cfaaa8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46V', 'Visual Information Specialist (Visual InfoSp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates motion, still, and studio television cameras; electronic based processing, editing, audio, and printing equipment; prepares captions for documentation images; creates multimedia presentations and prepares graphic products using manual and electronic equipment; performs unit level maintenance on assigned equipment and PMCS on assigned vehicles and generators.', 'e911babbca964f3c3de924466831b7ee99c3b571d14b8b22450dab21590c6b6c', 220, 220, null, 463, null, null, false, 1),
  ('2e253c99-46f5-5744-93af-885b4beceeb1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46V', 'Visual Information Specialist (Visual InfoSp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate documentation/production team members; directs the manipulation and enhancement of images; determines media, style, design and technical requirements for subordinates to create, sequence, and develop visual information presentation products; determines and develops sequence and manner of presentation of products; aligns and adjusts video cameras; prepares video reports for review by commanders and planning staff; monitors, operates, and performs unit level maintenance on master control and still video transmission systems.', '930acf964ef68dfd8b1d5fc71c30cb224af23bca05ba9af06e6e97b3679d5c5b', 220, 220, null, 464, null, null, false, 2),
  ('e5354df3-a373-5ffd-b5db-251b1c07780c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46V', 'Visual Information Specialist (Visual InfoSp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs as team leader of visual information documentation teams; supervises personnel and plans operational workload and priority for creating, manipulating, and integrating visual information products; determines documentation/production equipment and systems mission support requirements; coordinates and directs personnel and operational requirements to produce audiovisual, audio, and television productions in both fixed and tactical environments.', 'cfd7d5b8e2eb6ae23f1e90c8d51e87c4e13c03f40d3dbf6d0f901a1e08a5df44', 220, 220, null, 465, null, null, false, 3),
  ('9dd00787-4967-508f-890a-b1b0fdb3c5f2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46Y', 'Visual Information Operations Chief (VI Op Chief)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans, supervises, and coordinates the operation, maintenance, deployment and management of fixed and deployable VI systems, facilities, and personnel engaged in peace time and combat visual information operations; supervises PMCS on assigned vehicles and power generators.', '54b0dc75906e2f77c5f1d583b9ce3cc968641f77b6a7b3f6184db2b933d82813', 221, 221, null, 466, '2022-10-01', null, false, 4),
  ('8d40d4ee-b865-5f41-9f6e-e0e8e0bf3670', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46Y', 'Visual Information Operations Chief (VI Op Chief)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans, develops, and implements visual information operational training, doctrine, and major command operations; directs visual information operations for larger scale VI operations at Theater and Corps level.', '342c831496cc2057538da8a32e1bf6d16549aa40f4d2811f341c3765c6b47eff', 221, 221, null, 467, '2022-10-01', null, false, 5),
  ('76ecff5e-75f4-5b2e-9444-0a8a4fac6727', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46Y', 'Visual Information Operations Chief (VI Op Chief)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill level. Mentors command leadership and subordinate visual information personnel on visual information operational training and doctrine. Plans, develops, and implements visual information operational training, doctrine, and major command operations; directs visual information operations for larger scale VI operations at Department of the Army level. Serves on national committees, work groups, and advises international, national, military and civil organizations.', 'ccce247259435ce865ba3fc673974956e40230e0422b715108fadc05bd30d015', 221, 221, null, 468, '2022-10-01', null, true, 6),
  ('25d7ee07-9d9c-5bde-a606-5ca114aa3193', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46Z', 'Chief Public Affairs NCO', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises personnel performing the duties of MOS 46S at skill “3” and below. The chief public affairs NCO advises the commander and public affairs officer on all matters pertaining to public affairs, including command information, public information and community relations. Supervise Army public affairs programs, radio and television broadcasting. Advises on accuracy, propriety, timing and relative importance of information for release to the public and recommends methods of communicating information. Develops, coordinates, supervises and participates in plans and policies pertaining to organizations, training and operations. Can serve as the principal noncommissioned officer in public affairs and broadcast organizations.', '9e2690d78ea574748a623ec4f7be456e49a3bbcc5c482ab4665f3316fffd7c7d', 222, 222, null, 469, null, null, false, null),
  ('9b7a62a6-0d9a-5842-afd9-f9acba102034', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46Z', 'Chief Public Affairs NCO', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans and organizes work schedules and assigns specific tasks in support of command information and public affairs programs. Supervise the preparation of information for release on Army matters through news releases, articles, web-based media and photographs. Facilitate public information through media relations. Supervises or prepares evaluations, reports, correspondence, records and plans pertaining to Army public affairs programs. Supervise the operation of AFRTS affiliates or comparable broadcast activity, to include a separate broadcast section, team or detachment. Supervise the preparation of information for release on Army matters through radio, web-based media and television.', '87168117d900cc019e17dd29c6018542e6bbf08f7731665da234129e1ac56743', 222, 222, null, 470, null, null, false, 4),
  ('6a7f286d-e123-5b2c-8a91-134f82819625', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '46Z', 'Chief Public Affairs NCO', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Advise the commander and public affairs officer on all matters pertaining to public affairs, including command information, public information and community relations. Supervise Army public affairs programs, radio and television broadcasting. Advises on accuracy, propriety, timing and relative importance of information for release to the public and recommends methods of communicating information. Develops, coordinates, supervises and participates in plans and policies pertaining to organizations, training and operations. Can serve as the principal noncommissioned officer in public affairs and broadcast organizations.', '66b19a139aafba94f3b01f9bd4645adea5084837d4b63b3a817ad22ff3ff5b7b', 222, 222, null, 471, null, null, false, 5),
  ('e5b8dbf1-0698-5f13-bc24-4114b37c18ed', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '51C', 'Contracting Noncommissioned Officer (NCO)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform theater contracting support situational training; manage theater contracting support; coordinate theater contracting support; prepare Contracting Detachment (CONDET) for deployment; assist with the administration of contracting support integration plans (annex W); prepare for contracting deployment; review requirements packages; conduct contract solicitation process; perform contract administration and management; conduct contract administration services (CAS); complete contract close outs; establish a regional contracting office/center (RCO/RCC); serves as a Division and/or Corps-level liaison staff NCO for a Contracting Battalion (CBn) and/or Contracting Support Brigade (CSB), instrumental in performing all three functions of effective Operational Contract Support (OCS) per ATP 4-10 (i.e., Contract Support Integration, Contracting Support, and Contractor Management); performs all aforementioned duties throughout all phases of unified land operations and joint operations. General duties for NCOs in MOS 51C at each skill level are:
(1) MOSC 51C2. (Personnel Only). Skill level used to identify NCOs accessed into MOS 51C (Non-prior Service (NPS) and In-Service (IS)) after MOS qualification training, but during the month after training prior to obtaining automatic promotion to the rank of SSG. Promotion occurs on the first day of the month after successful completion of the MOS 51C qualification course either via the Army Acquisition Center of Excellence, or in the case of many USAR and ARNG NCOs an appropriate contracting course of study via the Defense Acquisition University (DAU), as defined by the Army Director of Acquisition Career Management (DACM). The DAU track is not appropriate for active-duty NCOs (see paragraph b, “Physical demands rating and qualifications for initial award of MOS”).
(2) MOSC 51C3. 51C SSGs perform all the traditional duties expected of any SSG in the Army (e.g., assist in preparation of an operation order, use the military problem-solving process, and assist in the military decision-making process). SSGs also assist, 51C sergeants first class (SFCs) in their conduct of duties. In units in which a personnel shortage exist, workload is over personnel capacity, and/or the SSG is very experienced and competent, a SSG may assume some or all of the duties of a SFC. SSGs may be eligible to serve as warranted contracting officers (able to obligate the U.S. Government) depending on current unit, command, and Army policies. They serve as contracting NCOs in a CONDET, CBn, or CSB, as well as various table of distribution and allowances (TDA)/generating force organizations. In CBns and CSBs, they can be found in the Operations Section or the Contract Administration Services section. Dependent on their experience and competence level, 51C SSGs assist or are responsible for:
(a) establishing a contracting work center (RCO/RCC);
(b) soliciting contract actions.
(c) processing/executing purchase orders;
(d) performing contract administration and management (e.g., conduct contract award orientations; notify unsuccessful offerors; post contract award synopsis; process contract protests; exercise contract option; monitor contract performance/quality assurance; process contract documents for payment; modify contracts, process unauthorized commitments; train and manage contracting officer representatives; terminate contracts; process claims);
(e) perform specific tasks related to CAS (e.g., administer contract-related property requirements, terms, and conditions; provide property management system analysis; administer use of government sources by contractors; administer quality assurance; perform audit services; monitor subcontract management; manage Logistics Civil Augmentation Program [better known as LOGCAP] government property).
(f) processing/executing orders through the General Services Administration (i.e., GSA);
(g) serving as curators of contract files (paper and electronic);
(h) prepare for individual deployment,
(i) administer a contract support integration plan; and
(j) review a contract requirement package.
(3) MOSC 51C4. SFCs generally serve in: CONDETs as NCOICs on mobile teams or Contracting Support NCO; CBn as an Operations NCO; CSBs Contracting Support NCOIC, Theater Contracting Support NCO, Operations NCO, and Support Operations NCO; and other TDA and generating force assignments. 51C SFCs perform all the traditional duties expected of any SFC in the Army. In addition, the SFC is tasked to:
(a) provide general contracting advice and assistance to operational commander;
(b) provide technical advice and assistance to supported units;
(c) assist with leading, deploying, and executing orders, contingency plans, and deliberate plans for contingencies and military operations;
(d) manage operations and requirements generation support for deployed/exercising joint task forces;
(e) assist with the development, revision and maintenance for all operational databases and plans for deployable contingency contracting computer hardware/software;
(f) assist with development of procedures that best support the supported unit/organization’s needs with the main intent to familiarize supported unit/organizations with the location, mission, and procedures to expedite supply, services, and construction contracts;
(g) manages the execution and administration/revision of contracting support plans, annexes, and appendices in support of operational, contingency and deliberate plans associated with the supported area of responsibility (AOR);
(h) manage pre and post-award contract actions;
(i) execute other contracting support tasks as assigned;
(j) assists in preparing CONDET for deployment; and
(k) assists in deploying and redeploying CONDET.
(4) MOSC 51C5. MSGs serve as detachment sergeants on CONDETs organic to the CBn and provide FCEs in the affected AO per METT-TC; MSG serve as Operations NCOIC and Support Operations NCOIC in CSBs. 51C MSGs can also be found in other TDA and generating force assignments. This stated, MSGs generally conduct their duties at the detachment and brigade level. In addition to the duties of the SSG and SFC, MSGs are tasked to:
(a) coordinate/identify commander’s intent and mission-critical points with supporting units;
(b) determine levels of support required that may be provided by the supported units;
(c) report projected requirements for sustainment of missions to the supported units;
(d) provide pre-award theater contracting oversight; and
(e) provide post-award theater contracting oversight.
(5) MOSC 51C6. SGMs/CSMs are expected to be masters of all the previously listed tasks/duties at lower skill levels. The small size of contracting units presents a somewhat non-traditional role at skill level 6; the SGM/CSM in MOS 51C is expected to perform a substantive amount functional contracting in order to stay relevant and to train/mentor his/her NCOs in this highly technical MOS. All SGM/CSM serve as the senior enlisted advisor to the CBn/CSB commander or primary staff LTC/COL in TDA units (dependent on the SGM’s/CSM’s professional development proficiency code). The SGM/CSM performs all tasks to ensure the health and welfare of Soldiers in his/her assigned unit/command. The SGM/CSM assigned to a CBn/CSB ensures a high level of readiness and training proficiency within her/his unit. In the CBn, the SGM serves as the primary enlisted contracting and business advisor to the commander in support of division-level operational commands. The CSM serves as the primary enlisted contracting and business advisor to the CSB commander in support of Corps, Army Service Component Commands, and/or Sub-unified Commands. The SGM/CSM mentors subordinate 51C NCOs on leadership, contracting, general acquisition, and general Soldier skills.', '3f075183c5ed85a272ddd96dc185fff50d8592aed80a405b74f24641f0314887', 223, 224, null, 472, null, null, false, null),
  ('6913bc27-ca69-5e1c-a405-9d5fe2398bc7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '56M', 'Religious Affairs Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Religious Affairs Specialists shape the environment to accomplish the Commander’s Religious Support (RS) mission by providing technical expertise in religious support operations and the impact of religion on the unit and mission. Religious Affairs Specialists fulfill the Chaplain Corps Mission in Operating and Generating Force organizations by performing two primary capabilities (Religious Support Provider and Religious Support Staff Advisor) which are executed through three core competencies (Strengthen Spiritual Readiness, Integrate Religious Support into Operations, and Manage Religious Support Resources). Religious Affairs Specialists integrate RS into multi-domain operations (MDO) at the tactical, operational, and strategic levels.', 'a58895e4ea75d36af12a5d7f64dffbe822abe6d1f99fc8f7838fda0fc91c9c9c', 227, 227, null, 473, null, null, false, null),
  ('10eea470-bb04-5e84-a9ff-3b54d5c334eb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '56M', 'Religious Affairs Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Soldiers serving at this level are primarily assigned to battalion level headquarters elements. Perform crisis intervention. Assess unit morale for targeted RS. Conduct specialized peer counseling for combat stress casualties. Conduct peer to peer counseling under the auspices of the chaplain. Coordinate RS for all faith groups. Synchronize RS within the MDO. Integrate RS into unit’s operations process. Integrate the Unit Ministry Team (UMT) into a tactical element. Coordinate force protection for RS operations. Maintain situational awareness for the UMT. Coordinate the military movement of the UMT. Operate a tactical vehicle platform. Operate communications equipment and digital reporting systems. Assist in planning RS operations and deployments. Integrate religious operations with Civil Military Operations. Research religious information to answer Commander’s Critical Information Requirements (CCIR). Prepare religious area analysis. Provide coordination, security, and analysis support to indigenous religious leader liaison operations. Safeguard privileged communications. Provide emergency RS for casualties. Manage RS resources to include property, ecclesiastical equipment, and section materials/supplies. Coordinate RS in the absence of the chaplain. Plan and execute appropriated and non-appropriated budget for section. Manage multi-purpose RS facilities and programs. Maintain reports, files, and administrative data.', '8c0956d3333bbe05a35d2351565ea4388518ada627970d95376d00fd7c97b221', 227, 227, null, 474, null, null, false, 1),
  ('ab3de61a-1e6a-5bdd-b6ee-6f09ba3216c8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '56M', 'Religious Affairs Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Proficient with duties shown in previous level of skill and is primarily assigned to a battalion level headquarters. Train spiritual fitness tasks. Integrate UMT into tactical elements and directs small unit actions. Supervise tactical vehicle platform operations. Supervise RS facility staff and operations. Analyze religious data and conducts religious civil military activities. Synchronize RS requirements with staff elements. Coordinate for movement of the UMT by air, land, and sea. Assist in the development of RS planning. Advise senior NCO leadership on RS issues. Counsel and develop subordinates within technical channels.', 'a5d6c3d1fdf2059cb59f59c6089255cfa5ef2d944ee05974181aac8de45ff7af', 227, 227, null, 475, null, null, true, 2),
  ('e1d13e8c-e38f-59ac-ab5b-fa81cd602c59', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '56M', 'Religious Affairs Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Proficient with duties shown in previous levels of skill and is primarily assigned to a brigade level headquarters or generating force positions. Lead subordinates in the execution of RS operations. Plan, develop, and execute the UMT’s annual training plan. Supervise communications and Operations Security (OPSEC) for RS operations. Manage taskings for RS operations. Develop the RS plan and synchronize RS in formations across the MDO. Supervise subordinate UMT indigenous religions analysis process. Develop counseling skills in subordinates. Train subordinates in UMT Tasks. Supervise the establishment of multi- purpose RS facilities.', 'c8d46be16d2013fd0b980decdd93a6819c2d2470d1a86ef3f369a478d426c9d3', 227, 227, null, 476, null, null, true, 3),
  ('cb0a65b5-1ba7-5fb4-8108-49cf53e3c984', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '56M', 'Religious Affairs Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Proficient with duties shown in previous levels of skill and is primarily assigned at installation and theater level. Supervise implementation of spiritual fitness program. Develop plans, orders, and annexes in support of Garrison, Division, Corps, and Theater RS operations. Synchronize garrison support with operational RS requirements. Integrate personnel from other services into the full range of military operations. Collect, sort, and distribute religious analysis products. Plan and supervise enlisted training. Integrate, train, and validate USAR and ARNG RS personnel and equipment during mobilization. Proficient in the force structure development process.', '7bd843d771b6149852971bcc109c5c3c799fdf708a3e7812e21a0b7e28650ad4', 227, 227, null, 477, null, null, true, 4),
  ('a0ca9181-b369-5a33-b1df-99d09466dca1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '56M', 'Religious Affairs Specialist', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Proficient with duties shown in previous skill levels and is primarily assigned at the operational level. Develop plans, orders, and annexes for operational and strategic RS in the MDO. Plan, develop, and supervise UMT training for subordinate echelons. Manage force structure and assignment processes. Supervise religious data management. Manage and update the Joint Manning Document and requisitions replacement for Joint Organizations.', 'e9c0b409d0a07916669c7a9c38a72e9142d8484cc9f8ec5bc66d38e020709409', 227, 227, null, 478, null, null, true, 5),
  ('d53f603f-fb59-5ce8-a841-53f2add1892e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '56M', 'Religious Affairs Specialist', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Proficient with duties shown in previous skill levels and is primarily assigned at the operational and strategic level. Serves as the subject matter expert on all aspects of RS and the primary advisor on policy development and is the analytical reviewer of regulatory guidance. Recommends policy to Army Commands, DA and DOD for RS operations. Shapes RS leaders through talent management efforts that develop NCOs through educational and training opportunities. Promotes Chaplain Corps heraldry and history.', 'a29f59c415b325af8e024d046d9be6a4c8bb5fe374ef3c695693a96a22e1bfac', 228, 228, null, 479, null, null, true, 6),
  ('b28499a7-f15a-5b65-b02e-ff62f6ba63e6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68A', 'Biomedical Equipment Specialist (Biomed Eq Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The biomedical equipment specialist performs maintenance services and repairs on all medical equipment, medical systems, medically related equipment and medically related systems.', 'cfc271d6117b86e55158f823cd91920c7363311e8a43518504faf6abdc69c2e3', 230, 230, null, 480, null, null, false, null),
  ('73f9781f-9be2-56cc-9cc4-bfc2a2716603', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68A', 'Biomedical Equipment Specialist (Biomed Eq Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs Preventive Maintenance Checks and Services (PMCS) (i.e., test, operates, lubricates, adjusts, tightens, and cleans, etc.), Calibration, Verification, Certification (CVC), electrical safety tests, on medical and medically related equipment, maintain networked medical equipment. Troubleshoot to isolate malfunctioning or defective parts and/or boards on medical and medically related equipment. Affect repairs by replacing malfunctioning or defective parts and/or boards on medically related equipment. Computes power requirements for field medical equipment. Perform pre- issue inspections (does not include Center for Devices and Radiological Health-CDRH compliance testing or acceptance of Imaging Systems) and installations of medical equipment. Conducts In-Service PMCS training programs for medical equipment operators.', '60ab9a37533976ae07e66796ccb0e48b611d7cfa9915d361526dca582d017507', 230, 230, null, 481, null, null, false, 1),
  ('075f4af9-e292-5375-8c1a-aaad1923b0bb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68A', 'Biomedical Equipment Specialist (Biomed Eq Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises, and performs as senior team member. Performs duties shown in preceding skill levels and provides guidance to subordinate Soldiers. Establishes and maintains procedures to ensure an effective preventive maintenance program. Performs quality control and acceptance inspections (does not include Center for Devices and Radiological Health-CDRH compliance testing or acceptance of Imaging Systems) on medical equipment and medically related equipment. Rebuilds and overhauls medical equipment and medical systems. Performs quality assurance/quality control (QA/QC) on medical equipment and medically related equipment. Administrates networked medical equipment. Provides medical maintenance advice to units not authorized 68A3O/4O/5O personnel. Contribute to the development of medical maintenance Standard Operating Procedures (SOP) and Commanders Maintenance Directive. Supervises, advises and assists in the training of subordinate personnel and may serve as Team Leader for maintenance operations.', 'e187a32ef849efbe1e2f916ddc32e4c7c64208dc9b6292f2c1acdfdf622531b5', 230, 230, null, 482, null, null, true, 2),
  ('17cf7cb4-4632-561e-bae3-736de21db4b3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68A', 'Biomedical Equipment Specialist (Biomed Eq Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels and provides guidance to subordinate Soldiers. Troubleshoot malfunctioning or defective discrete electronic components and/or boards on 3 phase radiological systems, lasers, and other complex integrated medical and medically related systems. Maintains, administrates and protects networked medical equipment. Affect repairs by replacing malfunctioning or defective discrete electronic components and/or boards on 3 phase radiological systems, lasers, other complex integrated medical systems and medically related systems. Performs quality control and acceptance functions (to include Center for Devices and Radiological Health (CDRH) compliance testing or acceptance of Imaging Systems), at all levels of medical maintenance to include depot. Perform quality control functions relevant to the performance of medical maintenance operations. Provide recommendations regarding the purchase of medical equipment, medical systems, medically related equipment and medically related systems. Participates in the planning of power and space requirements for installation medical equipment and medical systems and installs units to manufacturer’s specifications. Performs duties as Contracting Officer Representative and supervises contract equipment installations and performs acceptance inspections of contract compliance. Develops medical maintenance SOPs. Conducts training of subordinate maintenance personnel. Prepares and conducts In-Service PMCS training programs for medical equipment operators. Advise commanders and senior personnel on medical equipment and basic medical maintenance operations in Company/Battalion/Divisional units and small/medium health readiness platforms. Continuously improve performance of medical maintenance operations by establishing and implementing processes into daily activities to minimize deviation.', 'f1aebf825fe5aedafcb47752d89a7db0ff172a53bb3f10945d75f6ad30bd1196', 230, 230, null, 483, null, null, true, 3),
  ('abf8572b-d75d-5c7e-8bf3-ee110ce157e3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68A', 'Biomedical Equipment Specialist (Biomed Eq Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels and provides guidance to subordinate Soldiers. Supervise medical maintenance operations at the company/battalion level and small/medium health readiness platforms. Oversee technical and administrative training to subordinate Military, Civilian, and Contracted personnel to include networked medical and medically related equipment. Supervise quality assurance and quality control functions relevant to the performance of medical maintenance operations. Supervise the requisitioning and stocking of maintenance repair parts and supplies. Organize and supervise Maintenance Assistance and Instruction Teams (MAITs). Review installations and acceptance procedures for all types of medical equipment and medical systems. Advise and assist in administrative, fiscal, personnel, Medical Care Support Equipment (MEDCASE)/Capital Expenditure Equipment Program (CEEP) and supply matters. Advise procurement personnel of functional and safety aspects of medical equipment and medical systems. Advise commanders and senior personnel of Company/Battalion/Divisional units and small/medium health readiness platforms on patient safety concerns, capabilities for providing maintenance and associated logistic assistance, and instructions to organic, attached, and supported units to include requirements for utilities and advantages and disadvantages of contract versus in-house maintenance.', '7d2df615b27eb1e91ba2e2ba9d10aa7afbc125730cf6400c081155b5d85a7985', 230, 231, null, 484, null, null, true, 4),
  ('523852b1-164c-5d7d-b4e6-5a41b9a307d9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68A', 'Biomedical Equipment Specialist (Biomed Eq Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels and provides guidance to subordinate Soldiers. Supervise medical maintenance operations at the echelon above brigade and large health readiness platforms. Writes, develops, and coordinates command-wide regulations and policies relating to Army Medical Department Logistical Material Maintenance Programs. Serve as the subject matter expert on medical equipment and maintenance operations to commanders and senior personnel of Brigade/Corps/echelons above corps units and large health readiness platforms.', '1ea8931b4cf426f4126551e690b1b5111426214f438fd6ed0734968da48b399b', 231, 231, null, 485, null, null, true, 5),
  ('fc252e49-b155-5f4f-91a4-290ccb7532a5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68B', 'Orthopedic Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Orthopedic Specialist assists with management of orthopedic clinic, or assists in treatment of patients with orthopedic conditions and injuries, under the supervision of an orthopedic physician, orthopedic physician assistant, or podiatrist.', '496613872327e6664362fa1eb1bb23ec221a86bf0532745c9a9a4d4fdfc9cdf4', 232, 232, null, 486, null, null, false, null),
  ('06570264-4dbb-5dd2-b3d9-eb10cb41a089', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68B', 'Orthopedic Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists physicians in treatment of orthopedic patients.', 'fc3473dfdcf9b4c6448bf2904d6642301034ae3ce918be5a5b20e32fcf9d7ec9', 232, 232, null, 487, null, null, false, 1),
  ('20fe5cd9-1d7c-59ea-b756-d1569e21805b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68B', 'Orthopedic Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists physicians in treatment of orthopedic patients. Serves as castroom NCOIC/NCO. Serves as the Podiatry NCOIC.', '67cb5fa7f1c028fc299d9e779696fa590851e9477d98aed64e7282ac7fa68d51', 232, 232, null, 488, null, null, false, 2),
  ('f014ee48-7251-5e60-aebb-73c8294e9b9f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68B', 'Orthopedic Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists physicians in treatment of orthopedic patients. Serves as the clinical NCOIC for MEDDAC’s, MEDCEN’s, and MEDCOM’s. Supervises ancillary sections within the orthopedic department. Serves as instructors/Phase two coordinators.', '9d29e0323d1b909021a531ace3e112a60a2e11648c01bf0798e76031ea16fc61', 232, 232, null, 489, null, null, false, 3),
  ('787357a0-b312-574b-8072-996ef660b89b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68B', 'Orthopedic Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists physicians in treatment of orthopedic patients. Serves as the Department NCOIC for MEDDAC’s, MEDCEN’s, and MEDCOM’s. Supervises ancillary sections within the orthopedic department. Serves as instructors/Phase two coordinators.', '8c90abaf4c8ea7689d185aba17e5ebc3c35463c54c06df7740e7b073600eccf0', 232, 232, null, 490, null, null, false, 4),
  ('1a232388-dcf4-57dd-b867-f2dc71877405', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68C', 'Practical Nursing Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Practical Nursing Specialist supervises or performs preventive, therapeutic, and emergency nursing care procedures under supervision of a physician, nurse or NCO.', 'a3af00f2fc5616859faceb5b003fbab8e07377db882183abc841dea85b9250a1', 234, 234, null, 491, null, null, false, null),
  ('241674cc-be54-5c15-9bee-1c7832f686c8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68C', 'Practical Nursing Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs preventive, therapeutic and emergency nursing care procedures under supervision of a physician, nurse or NCO.', '016a72fafd59b111a245d811770539ef2670ebe514ed731633161a569ba8759b', 234, 234, null, 492, null, null, false, 1),
  ('ffa16750-26e3-543d-acab-58a7d086998e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68C', 'Practical Nursing Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs preventive, therapeutic and emergency nursing care procedures under supervision of a physician, nurse or NCO.', '016a72fafd59b111a245d811770539ef2670ebe514ed731633161a569ba8759b', 234, 234, null, 493, null, null, false, 2),
  ('e44c2b68-d7d2-5c52-b7ce-469fae78c4c5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68C', 'Practical Nursing Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs preventive, therapeutic and emergency nursing care procedures or supervisory management of small ward, clinic, or unit.', '94fd6757e199983d0ddd3ed0a02f8f201867b944084e6d7adbff38d6ca0edfd2', 234, 234, null, 494, null, null, false, 3),
  ('88052f6d-d1aa-50f6-b3e0-7e57c528f66f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68C', 'Practical Nursing Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises management of one or more wards, clinics, or units and manages para-professional nursing personnel.', '12cf2387b9778691a4c3a8de7c4eef1790b307a656522655141ac9e1356b4db8', 234, 234, null, 495, null, null, false, 4),
  ('3ad074a5-64db-57e1-8c6d-8cb333cf312d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68C', 'Practical Nursing Specialist', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Manages ward/unit operations in large hospitals.', '3380aceff4b489acc1c03ebe606390f9d3454c3226b3706eb58916e3c786f606', 234, 234, null, 496, null, null, false, 5),
  ('50eced24-a0cf-5abb-8d0d-60ea3d418464', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68D', 'Operating Room Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The operating room specialist assists the nursing staff in preparing the patient and the operating room (OR) environment for surgery and for providing assistance to the medical staff during surgical procedures. They also operate the centralized material service (CMS) and are responsible for preparing and maintaining sterile medical supplies and special equipment for medical treatment facilities. The operating room specialist also assists in the management of operating room suites.', 'd35df88a8d45887e468cd1479ab0176fba4f52ca42dbfee13b30b4da9aad2cac', 236, 236, null, 497, null, null, false, null),
  ('ba2f2d12-f211-559b-9327-49df426b584f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68D', 'Operating Room Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assist in preparing patients and operating room environment for surgery and provides assistance to the medical staff during surgical procedures to include the creation and maintenance of sterile fields for surgical procedures, the draping of patients, the preparation, manipulation, and delivery of basic surgical instruments and equipment, and the accountability for all instruments, needles, sponges and medications placed within the sterile field. The duties do not include the manipulation of tissue (cutting, suturing, cannulating, grafting, sawing or drilling). Perform various preoperative and postoperative procedures as directed. Maintain the cleanliness of the operating room. Receives, cleans, decontaminates, sterilizes, stores and issues various medical supplies and equipment used during surgical procedures. Responsible for the sterilization process, which includes inspecting, cleaning, assembling, warping and sterilizing equipment. Operates and runs sterilization checks on a variety of sterilization equipment to include Steam, ETO, Sterrad and Steris Systems.', 'b522dd34a63d62b4cd3ae4d729c2ba34076314503353b9854776dcde0ff47967', 236, 236, null, 498, null, null, false, 1),
  ('f3b866ee-c547-57e8-89e4-87ec0343d60e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68D', 'Operating Room Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in the preceding skill level and provides technical guidance to subordinates. Perform circulator services under the direct supervision on an RN as required. Sets up, positions, and operates specialized and advanced operating room equipment. Supervises and advises subordinate personnel.', '7f7f9432b7051201b40e0587351171cbd8b39a288088a1706a60d9b7b2ef6199', 236, 236, null, 499, null, null, true, 2),
  ('93129ea7-72ac-55f4-9385-e3101b0a67c3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68D', 'Operating Room Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in the preceding skill level and provides technical guidance to subordinates. Implements and monitors the automatic war and clinic delivery system. Monitor quality of sterilization techniques to ensure adherence to established standards. Supervise the maintenance programs in the operating room and the central material service. Establishes stock levels for requisitioning supplies and equipment and supervises their storage and issue. Prepares and maintains various reports and files. Supervises and advises subordinate personnel.', 'd59fb15eb3d525b9890ed6f1a3a3a193e40601c04147e74cc1a998e92f862b02', 236, 236, null, 500, null, null, true, 3),
  ('a8e30a10-233e-5bf3-847d-74cadfbce884', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68D', 'Operating Room Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in the preceding skill level and provides technical guidance to subordinates. Coordinate activities of the OR and CMS with other elements of the medical treatment facility. Develops, monitors, and evaluates training. Establishes policies for and monitors exposure levels of sterilization chemicals and anesthetic gases with the OR. Participates in the preparation of the OR and CMS budget. Supervises and advises subordinate personnel.', 'ffb49d2591d149e39c217f45ab46bbe928ce5107d0d2425ea4ba485aceb88dca', 236, 236, null, 501, null, null, true, 4),
  ('fe69eb5a-d5e7-543a-bf18-084967661f46', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68E', 'Dental Specialist (Dental Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The dental specialist assists the dental officer in prevention, examination, and treatment of diseases of teeth and oral region, or assists with the management of dental treatment facilities.', 'c98d5e485d478501542279dea806359a10cd6cbb3398cc9037200f493319cab2', 238, 238, null, 502, null, null, false, null),
  ('dc114c63-e1ba-5cec-9572-64b0916566b7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68E', 'Dental Specialist (Dental Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Patient care. Receives and seats patients. Prepares dental operatory, selects and arranges instruments, measures and records temperature, blood pressure and pulse, and assists dentist during patient exams. Provides oral hygiene instructions. Assist with administration of anesthesia and in placement and removal of sutures. Prepares restorative and impression materials. Performs Cardiopulmonary Resuscitation and operates resuscitative equipment. Manages infection control and disposes of contaminated waste and dental radiography. Loads and unloads radiographic film cassettes, protects self and patient from excessive ionizing radiation exposure, exposes bite-wing periapical, occlusal film, and panoramic radiographic darkroom procedures. Perform administration, supply, and maintenance. Schedules appointments, retrieves, files, and maintains dental records. Receives, stores, packs, unpacks and safeguards dental supplies and equipment. Perform preventive maintenance on dental equipment. Sets up, maintains, disassembles and packs dental field equipment shelters.', '9a3ae4c4fa86b0c204558def953984910ea872fce883fa8664ce2d5556831742', 238, 238, null, 503, null, null, false, 1),
  ('4f0d2952-928c-5fd7-a5a3-1c2ee22393bc', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68E', 'Dental Specialist (Dental Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises dental teams, sections, or small fixed or mobile dental facilities. Assist dental officer in prevention, examination, and treatment of diseases of teeth and oral region. Assists and advises subordinate personnel on supply economy procedures. Supervise the packing, unpacking, loading, setting up and storage of dental unit field equipment and shelters. Assist in presentation of training programs. Prepare the site for field dental treatment facilities. Assist with technical and administrative management of dental treatment facilities under the supervision of a Dental NCO.', '6e8aa79e6bb9b3625f36ec8d7e7765f891cf78dc7f3ffae551ce5d2c79e3a10c', 238, 238, null, 504, null, null, false, 2),
  ('fa7ea907-246b-5369-9371-d6ebf4a907b0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68E', 'Dental Specialist (Dental Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises activities of dental teams, sections, or clinics in small medium- sized fixed or mobile dental facilities. Provide technical guidance. Ensure comfort, safety, and cleanliness of dental facilities. Determines personnel requirements, establishes work priorities, organizes work schedules and assigns duties. Instructs subordinates in work techniques and procedures. Evaluates personnel performance, counsels personnel and prepares evaluation reports. Supervise movements and establishment of field dental units. Prepares unit NBC (CBRN) plans and supervises procedures. Prepare administrative, technical, patient and manpower reports. Establishes and monitors stock level for supplies and equipment. Requisitions and maintains dental supplies and equipment.', '72faed44dfbfa1a6e36db0d904ad81fdc5e8dfd804e9a4c57c08d6e7077ccbb5', 238, 238, null, 505, null, null, false, 3),
  ('499e46a3-e9dc-5a4b-a24b-46b23b7cebec', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68E', 'Dental Specialist (Dental Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise activities of dental teams, large fixed or mobile dental facilities or dental clinic commands. Assist with the planning, execution and oversight of missions within multifunctional medical battalions. Prepares periodic and special reports concerning personnel, patients, dental care and treatment operations. Supervises and plans training in general military and MOS specific subjects. Coordinates the administrative activities and prepares dental treatment facility SOPs. Revises topography of selected operational site and advises on the location of field treatment and sanitation facilities. Prepares operational orders and fragmentation orders in support of medical missions. Ensures compliance with infection control protocols. Manages dental readiness of supported units. Coordinates the deployment, establishment, disestablishment, redeployment of mobile dental facilities. Plans, develops and supervises loading plans for dental field organizations. Perform staff, budget and advisory duties.', '6cd075127a6c3791e9d468ba25983082ed1d3cccf118a1aa543d1bc28f4348e3', 238, 238, null, 506, null, null, false, 4),
  ('d364b6d2-a666-5c45-aa12-4b8037ac20ff', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68E', 'Dental Specialist (Dental Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as senior enlisted advisor of fixed dental activity, deployable dental company, area dental laboratory or staff NCO at a medical battalion or brigade. Supervises general administrative functions and coordinates personnel assignments. Evaluate training programs and requirements. Assist Commander in the administrative and technical supervision of subordinate dental facilities. Assist in the planning, development and management of the command budget programs. Coordinates and supervises unit preventive maintenance and supply programs. Assist with the planning, execution and oversight of missions within a medical brigade/medical command. Assist with the coordination, reception, staging and integration of deployed units. Assist with deployment, reintegration, reconstitution, and retraining. Assist in the development of operational plans and tactical SOPs. Provide technical assistance in planning and staffing of facilities.', 'bd0e4b27793d2d573dcd0488d7a08b888cfcca1dd3f67e2c7bb6e2017a70f7ff', 238, 238, null, 507, null, null, false, 5),
  ('95457015-e813-5f10-81a4-787928e05d34', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68F', 'Physical Therapy Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Physical Therapy Specialist, under the direction of a physical therapist and following medical referral, supervises or administers physical therapy to decrease physical disabilities and promotes physical fitness of patients.', '09de51562328a81073e47bdb0761385555694fcc7836f4a4ab199685896b55b4', 241, 241, null, 508, null, null, false, null),
  ('2b690094-7d54-5e8c-a9dd-92076ed4d402', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68F', 'Physical Therapy Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Under close supervision, administers physical therapy treatment to patients.', 'dab07b30b8bbbca21adaeb995fd364b559c9352efe79dd6aa458a31b7897559f', 241, 241, null, 509, null, null, false, 1),
  ('5761a2e2-687e-505d-b03c-a89ad94eed2f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68F', 'Physical Therapy Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Administers physical therapy treatment to patients and assists with the management of a small clinic.', 'a3b5463552abaa778163f6d617b776a2654c0d7ff90c68936543ff22e3f98193', 241, 241, null, 510, null, null, false, 2),
  ('9f59ff67-ede0-53a8-bdc3-04183270e1ca', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68F', 'Physical Therapy Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Administers physical therapy treatment to patients and manages small, or assists with management of medium or large sized physical therapy section.', 'b1e115d8a524ceb316b85b43efb6bab4ac8889100d5863ceb952a6ca89423a9d', 241, 241, null, 511, null, null, false, 3),
  ('0634203d-6e7b-5be1-9aff-37a7beddb17c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68F', 'Physical Therapy Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Manages a medium or large physical therapy section.', '3b7f9d51e6c9f369a9a0becb85a00be79b5b5c61a44bf35ca9b82730076aec63', 241, 241, null, 512, null, null, false, 4),
  ('6d6b215f-bb38-573e-9da7-fe051fab1a7b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68G', 'Patient Administration Specialist (Patient Admin Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The patient administration specialist supervises or performs administrative duties in patient administration division of hospital or other medical activity.', '75585fe4dd14af382d716b3b67ad3eb210ffdab73dc80509088a275db1e90664', 243, 243, null, 513, null, null, false, null),
  ('be8b7194-ae08-5ae4-bb70-5be9878436b7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68G', 'Patient Administration Specialist (Patient Admin Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Compiles data and prepares required statistical report on outpatient visits, inpatient visits, admissions, dispositions, and other selected workload area. Prepare reports and data on births, deaths, and reportable conditions for submission to military and civilian authorities. Initiate correspondence pertaining to medical records, medical board proceedings, line of duty investigations, and other records and reports pertaining to patient administration. Possess working knowledge of patient medical eligibility programs such as DEERS. Prepares and consolidates medical documents and files authorized documents ensuring proper sequencing of forms. Applies knowledge of medical terminology as it applies to anatomy and physiology. Prepare medical records for retirement. Assist in the preparation of medical information for release. Maintain a medical record tracking system within the medical treatment facility. Process patients for admission to medical facilities. Checks and verifies eligibility for care. Performs administrative duties and prepares appropriate forms to process and report very seriously ill and seriously ill personnel, to include notification of next of kin and progress reports. Accounts for and safeguards funds received for deposit in medical services account. Prepare patient and associated documentation for medical evacuation.', '74b032588cd644ac7f122b2676ecf8f2ecc618ea2dae77dec8038b85fc5d8006', 243, 243, null, 514, null, null, false, 1),
  ('0e51f5d4-889e-55eb-bc60-280c45f57a09', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68G', 'Patient Administration Specialist (Patient Admin Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at preceding level of skill and provides technical guidance to lower grade personnel in accomplishment of their duties. Performs medical administrative duties in various departments or services of hospitals to include: Posting administrative entries in medical records; Scheduling patients for medical board action; Monitoring long-term patient rosters; Maintaining patient workload data from subordinate services; Audits medical records for quality control based on the nature of care and treatment given; and Releases medical information, answers inquiries and provides information from medical records to requesting parties as authorized.', '02a58ac3afe2c3f1f4c44797eefb65ccf7b41cd723bbdff7f4a0117fcc1d1402', 243, 243, null, 515, null, null, true, 2),
  ('2edcc2fb-ef85-5401-a816-f0bdc2c6a7e3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68G', 'Patient Administration Specialist (Patient Admin Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at preceding level of skill and provides technical guidance to lower grade personnel in accomplishment of their duties. Assigns tasks to subordinate personnel to affect orderly flow of workload and ensure timely accomplishment of tasks inherent to patient record keeping, movement of patients, and other patient administrative matters. Reviews completed correspondence, records, and forms for administrative and technical correctness. Counsels eligible beneficiaries concerning military health care benefits. Counsels patients on physical disability processing procedures. Provide guidance to professional staff on cases requiring medical board action. Coordinate administrative aspects of medical board processing. Coordinate requests for care from other federal and civilian hospitals. Supervise performance of patient administration duties.', '833860b433a2f85f13a918048e5deeeaf4e2425688cc898d6e9a485509ceeb21', 243, 243, null, 516, null, null, true, 3),
  ('96f5b992-8518-5579-9a5d-8b9ccfbc3860', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68G', 'Patient Administration Specialist (Patient Admin Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at preceding level of skill and provides technical guidance to lower grade personnel in accomplishment of their duties. Advise hospital staff on Joint Commission on Accreditation of Hospital pertaining to Medical Services to include: documentation, confidentiality, quality assurance, utilization review, and risk management. Coordinate medical care for military members, civilian emergencies, and other eligible beneficiaries. Manage MTF Defense Eligibility Enrollment Reporting System (DEERS). Serve as alternate Physical Evaluation Board Liaison Officer (PEBLO). Supervise performance of patient administrative duties.', '70bf10d5a57167faa68fdcbc07907b1eff63bf9ffe7535b0c816ec6b2edbae7b', 243, 243, null, 517, null, null, true, 4),
  ('6d055051-7dd4-557c-a94c-82465f42ddae', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68G', 'Patient Administration Specialist (Patient Admin Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at preceding level of skill and provides technical guidance to lower grade personnel in accomplishment of their duties. Establishes and maintains coordination with other military/civilian medical treatment facilities. Coordinate patient administration activities in regional medical commands. Supervise performance of patient administration duties.', '7896633eb1d16089bc62229609714219dde1c3b07a7ab1df3ad97d6fde76e0c6', 243, 243, null, 518, null, null, true, 5),
  ('97ef3300-cff2-5485-9eea-e480aedf5339', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68H', 'Optical Laboratory Specialist (Optical Lab Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The optical laboratory specialist assembles spectacles utilizing presurfaced single-vision lens; surfaces multi-vision lens and assembles multi-vision spectacles; repairs and fabricates spectacles and supervises optical laboratory personnel.', '4bce56890e13bdcaf3212098410569fa1d6b24e629f8f533cb76b8e7d71bb09c', 245, 245, null, 519, null, null, false, null),
  ('4ab670ad-96de-5382-9349-eff9c5f913e8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68H', 'Optical Laboratory Specialist (Optical Lab Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Surfaces lens blanks, fabricates, repairs and assembles prescription spectacles. Maintain tools and equipment.', 'c6afa35d5bc99267e010f3a329262e8e0f1c39a6aebe48edfcd900ed522e1d69', 245, 245, null, 520, null, null, false, 1),
  ('fb3b5d8b-54b5-5ff0-9a1f-61ef41fd3bf9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68H', 'Optical Laboratory Specialist (Optical Lab Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in the preceding skill level and provides technical guidance to subordinates. Performs prescription related administration.', 'c0eecb7e57d7a869bbcd834d5a1e3fd43cd25aaae1ea0fb639c0606e1c5d2166', 245, 245, null, 521, null, null, true, 2),
  ('eda48e84-19f6-5a31-b0bb-bad6f01e2c92', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68H', 'Optical Laboratory Specialist (Optical Lab Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provides technical guidance, inspects completed spectacles, and ensures quality control standards. Develops stock levels, requisitions, stores and maintains optical supplies and equipment. Prepares and conducts training programs and instructs on preventive maintenance and safety procedures.', 'afb09a1192664c51a14a3f0248e640c25390a6ff248f6566fccedf21f7fa2a81', 245, 245, null, 522, null, null, false, 3),
  ('dc2b4de7-f1e1-5311-80c4-754ff63ed598', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68H', 'Optical Laboratory Specialist (Optical Lab Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Determines personnel requirements, establishes priorities and organizes work schedules. Plan layout of work areas. Prepares and conducts training programs. Inspect to ensure a safe, clean and orderly working environment. Supervise quality control procedures. Drafts and prepares budget estimates and monitors records of cost data and expenditures. Perform staff, budget and advisory duties. Prepare other technical, administrative and personnel reports. Coordinate activities of optical laboratory with medical treatment facilities.', 'e7b02d167496bcaea5b77a43fb35a1c0cc6e6776ccb4a784290b646cf63ec67c', 245, 245, null, 523, null, null, false, 4),
  ('2e52b08d-faa6-542e-b187-0d28d6c009d1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68J', 'Medical Logistics Specialist (Medical Log Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The medical logistics specialist performs or supervises requisitioning, receipt, inventory management, storage, preservation, issue, salvage, destruction stock control, quality control, property management, repair parts management, inspection, packing and shipping, care, segregation and accounting of medical supplies and equipment.', '49af722e05d6bc6f466d914d052f8f3ad3d32f180e8c53ce53333592743735d0', 247, 247, null, 524, null, null, false, null),
  ('6250b6bd-600b-5ef2-b6d8-f027acc8beec', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68J', 'Medical Logistics Specialist (Medical Log Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform receipt, storage, issue, packing and shipping, care, inspection, quality control, segregation, inventory control, requisitioning, preservation, salvage, and destruction of medical supplies and equipment.', '86962521eb377b514b83ef36c84e3ab248de74f19ffa44e3b60ce3eea2c849bd', 247, 247, null, 525, null, null, false, 1),
  ('73d1c45a-dba3-5c68-9da5-308cf6b3885b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68J', 'Medical Logistics Specialist (Medical Log Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform receipt, packing and shipping, care, inspection, quality control, segregation, inventory control, requisitioning, storage, preservation, issue, salvage, destruction, repair parts management, distribution, supply management, property management and accounting of medical supplies and equipment.', 'bd46abf6149df2d711656b0ea60dd21e6db4c63c068ac48355a2bcffae357009', 247, 247, null, 526, null, null, false, 2),
  ('2a99a072-5541-57e0-9f5e-505b0aab6163', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68J', 'Medical Logistics Specialist (Medical Log Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise small sized logistics division, medical supply, stock control, property management or storage activity.', '28aa435c2b04ca83f97d869009013675658d837fd554951ed4769ff943622b21', 247, 247, null, 527, null, null, false, 3),
  ('890ddccc-3259-54fc-a126-9d5aa022553c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68J', 'Medical Logistics Specialist (Medical Log Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise medium sized logistics division, medical supply, stock control, property management or storage activity.', '92be7b0ac8c66149dafaa71a04b0aa0b19a46ecec503e5b3dbe5877e9850612e', 247, 247, null, 528, null, null, false, 4),
  ('bc2ccd23-4a48-5bc3-a554-1a934b57decd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68J', 'Medical Logistics Specialist (Medical Log Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise large sized logistics division medical supply, stock control, property management and storage activity. Manage the functional areas pertaining to the highly specialized and technical materiel and services utilized in support of the health care delivery system. Exercises staff responsibility for units engaged in medical supply and service operations and other logistical support. Serve as a focal point for medical property management and accountability procedures. Advise staff on matters regarding supply and services support and other medical logistical functions. As a materiel manager, develops, coordinates, and supervises the supply support portion of an integrated logistics support plan. Duties are performed in MTOE/TDA organizations, both CONUS and OCONUS.', '12dff0749f5753216430385e3ffb0677a52408a844b1daec5919a3e2851314df', 247, 247, null, 529, null, null, false, 5),
  ('402fd06b-e3e4-5ad6-9249-3fb77ca17b6d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68K', 'Medical Laboratory Specialist (Medical Lab Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The medical laboratory specialist performs bloodbanking procedures and elementary and advanced examinations of biological and environmental specimens to aid in the diagnosis, treatment, and prevention of disease and other medical disorders. MOS 68K personnel require manual dexterity and no aversion to the sight of blood or needles.', '13cf4c962603392869173f9b9dd00bd060b8311536ebd4e210131ac6d785b8d9', 248, 248, null, 530, null, null, false, null),
  ('0e5767c3-adca-5dfa-b917-d4392744b4fe', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68K', 'Medical Laboratory Specialist (Medical Lab Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform elementary blood banking and clinical laboratory procedures in hematology, immunohematology, clinical chemistry, serology, bacteriology, parasitology and urinalysis. Collects blood specimens by venipuncture and capillary puncture. Packs, unpacks, inspects, stores and distributes blood and blood products. Assembles, disassembles and maintains laboratory equipment.', '45420f9bae2d1343ca3ddf234b5709f7006adf37b6bca07ec9b111b76c1bb5d9', 248, 248, null, 531, null, null, false, 1),
  ('a1bc35b8-a03c-50d1-a4b4-51096ae88859', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68K', 'Medical Laboratory Specialist (Medical Lab Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform elementary blood banking and clinical laboratory procedures in hematology, immunohematology, clinical chemistry, serology, bacteriology, parasitology and urinalysis. Collects blood specimens by venipuncture and capillary puncture. Packs, unpacks, inspects, stores and distributes blood and blood products. Assembles, disassembles and maintains laboratory equipment. Supervise laboratory sections in the performance of their duties. Performs and monitors Quality Control and Assurance.', '57250cb3808e9d38ca729cd65c5304e2b466397765c4e1506ab2c18ac9a3c798', 248, 248, null, 532, null, null, false, 2),
  ('9c65431c-cec5-5d38-a38d-1935321fdd79', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68K', 'Medical Laboratory Specialist (Medical Lab Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform elementary and advanced blood banking and clinical laboratory procedures in hematology, immunohematology, clinical chemistry, serology, bacteriology, virology, mycology, toxicology, parasitology and urinalysis. Collects blood specimens by venipuncture and capillary puncture. Packs, unpacks, inspects, stores and distributes blood and blood products. Assembles, disassembles and maintains laboratory equipment. Supervise technical and administrative functions for a small medical laboratory. Train lower skill levels in all elementary laboratory procedures and contributes to process improvement.', '611f87eb8cbca71a98e3da5b2c4decf54bf87ffc27bd70bc27678254ac6e44e2', 248, 248, null, 533, null, null, true, 3),
  ('b6f7a823-db2c-59ee-b5af-94e762e871d6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68K', 'Medical Laboratory Specialist (Medical Lab Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform advanced blood banking and clinical laboratory procedures. Supervise the technical and administrative functions for a medium medical laboratory. Develops and manages budgets, supplies and training work schedules. Establishes and analyzes quality control and assurance programs. Reviews and makes appropriate recommendations on doctrine and training policies and procedures. Supervise personnel blood storage and distribution units.', '05307aa5dd96be48efb7605f8159e5b5b7a9364cccf47eec9f238f02eac35938', 248, 248, null, 534, null, null, false, 4),
  ('97b674ba-348c-50fa-b61b-57901f4f04bd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68K', 'Medical Laboratory Specialist (Medical Lab Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serve as general supervisor for large medical laboratory activities. Develop budgets, training schedules and authorization documents. Provide technical and administrative management, coordination, control and operational duties as the senior medical laboratory NCO. Evaluates training programs, devises solutions and implements improvements to training. Participate in a wide variety of studies and reviews. Advises command in strategic planning, risk management, blood management and all matters concerning enlisted Soldiers. Participate in command review, inspection and approval of subordinate unit activities.', '0f7b5e8510745f5f8db4feefd2634bf0d31ad2ec10905a883c725623b0e5945a', 248, 248, null, 535, null, null, false, 5),
  ('0c35dd82-d1c4-5cca-894e-e40b1327006b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68L', 'Occupational Therapy Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Occupational Therapy Specialist, under the direction of a registered military occupational therapist, supervises or interviews, tests, plans treatment programs, and teaches and assists patients to facilitate maximum recovery by decreasing physical and mental disabilities resulting from illness or trauma, prevent injury, and promote life-style modification to improve fitness.', '386e62e81af04d5ad56bf1ab5972b44ca4a5afdff5143d549a732af86c05cd5d', 250, 250, null, 536, null, null, false, null),
  ('d13d109a-1a2f-560b-b175-941fd676ce26', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68L', 'Occupational Therapy Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Administer emergency and routine combat stress/orthopedic treatment to battlefield casualties, performs interviews, tests, and assists patients in activities of daily living with outpatient care and treatments or with inpatient care and treatment under the supervision of an Occupational Therapist (OTR) or a Certified Occupational Therapy Assistant (COTA).', '96d9d6fdc056709186b824c8dbd398178e80e71a4a3ef94d7c6e70a0e28eb9ce', 250, 250, null, 537, null, null, false, 1),
  ('23619aab-eb12-554d-8613-f3b34b22b868', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68L', 'Occupational Therapy Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Administer emergency and routine combat stress/orthopedic treatment to battlefield casualties, performs interviews, tests, and assists patients in activities of daily living with outpatient care and treatments or with inpatient care and treatment under the supervision of an Occupational Therapist (OTR) or a Certified Occupational Therapy Assistant (COTA).', '96d9d6fdc056709186b824c8dbd398178e80e71a4a3ef94d7c6e70a0e28eb9ce', 250, 250, null, 538, null, null, false, 2),
  ('9290475c-33c8-549a-a41b-7255b6ddb411', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68L', 'Occupational Therapy Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise activities of combat stress unit, medium-sized occupational therapy clinic and mobile treatment facilities.', 'f259bda49d35e75480f2833b23cc02ac7b7800471b65ea871a24fd0a4f763a65', 250, 250, null, 539, null, null, false, 3),
  ('83b0a753-def8-5d3c-9524-eb243d4db9df', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68L', 'Occupational Therapy Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise activities of combat stress unit, large-sized occupational therapy clinic and mobile treatment facilities.', 'ce85409738a6aaec134f9d78db9c7c57baa696857c72abe08256d74efd5ac000', 250, 250, null, 540, null, null, false, 4),
  ('e93807f5-6195-5661-9ad1-9f8097b8cb84', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68M', 'Nutrition Care Specialist (Nutr Care Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The nutrition care specialist serves as an extender to the AOC 65C (dietitian) by providing medical nutrition care therapy to patients and staff as well as in support of humanitarian missions in field and fixed hospitals.', 'b4f9031c1cd10e631b57ad713696b72d2acf6aacbda7c91c54ef453f73ddfb9d', 252, 252, null, 541, null, null, false, null),
  ('007ee1f5-40e6-53d9-b0c4-8873402beaef', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68M', 'Nutrition Care Specialist (Nutr Care Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform basic clinical dietetics functions in the dietary management and treatment of patients in nutrition clinics, clinical dietetics branches, health promotion and wellness clinics. Perform nutritional assessments and screening of individual patients for nutritional risk. Prepares and serves modified and regular food items in the management of the normal nutrition needs of individuals across the life span, i.e., infants through geriatrics and a diversity of people, cultures and religions in support of the mission, under the supervision of a dietitian or NCO.', '8c54d944fc780a3918d7a1376a5ef13741512e5fc6b5e06f363a44ef3a8cb582', 252, 252, null, 542, null, null, false, 1),
  ('16c715cd-9e2c-52a0-8316-5a1cd953e679', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68M', 'Nutrition Care Specialist (Nutr Care Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and supervises basic clinical dietetics functions in the dietary management and treatment of patients in nutrition clinics, clinical dietetics branches, health promotion and wellness clinics. Perform nutritional assessments and screening of individual patients for nutritional risk. Prepares and serves modified and regular food items in the management of the normal nutrition needs of individuals across the life span, i.e., infants through geriatrics and a diversity of people, cultures, and religions in support of the mission, under the supervision of a dietitian or senior NCO.', '33b3d063a2b7020cb9cdb18ddea573a52498eb002aeb623e374212a1c6fc4a08', 252, 252, null, 543, null, null, false, 2),
  ('6cca461f-c2e7-5a19-9062-206337eac174', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68M', 'Nutrition Care Specialist (Nutr Care Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise the clinical dietetics management aspects in nutrition clinics, clinical dietetic branches, health promotion and wellness clinics and production and service branches. Supervise the performance of basic clinical dietetics functions in the dietary management and treatment of patients and staff. Supervise the nutritional assessment and screening of individual patients. Supervise the preparation and service of modified and regular food items in the management of the normal nutrition needs of individuals across the life span, i.e., infants through geriatrics and a diversity of people, cultures, and religions in support of the mission, under the supervision of a dietitian.', '59b994b37caf10d7075ca3f1c11560951a3ff9aba5e04e020064d8d509662619', 252, 252, null, 544, null, null, false, 3),
  ('c8b9f687-c7d5-579a-b2dd-d329efffa6ba', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68M', 'Nutrition Care Specialist (Nutr Care Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise the clinical dietetics management aspects in nutrition clinics, clinical dietetic divisions, health promotion and wellness clinics and production and service divisions. Supervise the performance of basic clinical dietetics functions in the dietary management and treatment of patients and staff. Supervise the nutritional assessment and screening of individual patients. Supervise the preparation and service of modified and regular food items in the management of the normal nutrition needs of individuals across the life span, i.e., infants through geriatrics and a diversity of people, cultures, and religions in support of the mission, under the supervision of a dietitian.', 'b279c8a0059559d85e7be7aed751e24c1049db72c77d8a83229ce00ffc337365', 252, 252, null, 545, null, null, false, 4),
  ('e8875786-399b-552e-8061-fd26523b7c92', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68M', 'Nutrition Care Specialist (Nutr Care Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise the Nutrition Care Division. Manage the day-to-day operations of the division. Ensure that all resources are available to the division. Serve as the primary hand-receipt holder and budget manager. Ensures training for all staff members is conducted and coordinated with the Combat Support Hospital (CSH) for Medical Proficiency Training (MPT) in accordance with FORSCOM Regulation 350-1, in support of the hospital’s mission essential task list (METL).', '822d4568ccbf03fdf636dff93dc0d257f60e403e7ecf5d3684463d1b8d1adc80', 252, 252, null, 546, null, null, false, 5),
  ('4101aaae-7eb9-5903-a9a2-8ad3a99b10d1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68P', 'Radiology Specialist (Radiology Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The radiology specialist operates fixed and portable radiology equipment or supervises radiology activities. MOS 68P personnel require good eye-hand coordination and manual dexterity, no aversion to the sight of blood and be able to stand for long periods of time.', 'fb7b3cb73650567dcc60463554e42b2b7be886ec04bd35512b8c82f8805b8704', 254, 254, null, 547, null, null, false, null),
  ('ad6540b6-42dd-53e4-b704-4b68dd43005b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68P', 'Radiology Specialist (Radiology Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates fixed and portable radiology equipment. Reads and interprets radiographic requests and physician''s orders. Provide patient care within the radiology area. Prepares, assembles and adjusts instruments, materials and equipment. Perform radiographic examinations of the upper and lower extremities, vertebral column, trunk and skull. Performs soft tissue radiographic examinations and bone surveys. Perform body section radiography, foreign body localization, prenatal, pediatric, urogenital, and radiographic examinations of the digestive, respiratory, vascular and nervous systems. Develop radiographic image using digital and manual processing. Apply radiation, electrical and mechanical protective measures. Utilizes hospital information systems and performs routine patient administration. Maintain patient locator file, radiographic files and report files. Inspects and performs operator maintenance on radiology equipment. Packs, unpacks, loads and unloads radiology equipment, assembles and dissembles radiology equipment and shelters.', '9cc2a5fa53abf5383ff96f601ea582511365a996dc10ea7ece3c1c8cf989abac', 254, 254, null, 548, null, null, false, 1),
  ('63850dda-6679-5d32-963d-0a9c149698eb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68P', 'Radiology Specialist (Radiology Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates fixed and portable radiology equipment. Performs duties shown in preceding level of skill and provides technical guidance to lower grade personnel in accomplishment of their duties. Disseminate radiographic reports. Assembles radiographs for reading. Perform body section, prenatal and pediatric radiographic procedures. Performs follow-up radiographic examinations of the digestive, urogenital, respiratory, vascular, and nervous systems. Assist with special radiographic and fluoroscopic procedures. Requisitions and maintains necessary levels of radiographic/medical supplies. Evaluate radiographic personnel performance. Supervises packing, loading, unpacking, assembly and dissembling of radiology equipment and shelters.', '5be5434b1d6fcfffa3b8048cce0d735ee8633abb11fd6cdee007e169acb9079c', 254, 254, null, 549, null, null, true, 2),
  ('ca05798d-54ea-5265-ad50-ab79fbe869dc', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68P', 'Radiology Specialist (Radiology Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform complex or specialized radiographic procedures to include duties shown in preceding level of skill or activities medium-size radiology activity. Inspects radiology activities for compliance with radiation safety procedures and to ensure orderly and clean environment for patients and initiates corrective action. Organizes work schedules. Assigns duties and instructs personnel in technical procedures. Supervise operator maintenance on equipment. Prepares and updates unit and section SOP. Prepares and conducts radiology training programs. Assist in quality assurance program. Coordinate radiographic examinations of patients.', '1e9c9d6b825b01c89087b397b9b6662ada80e27de4036495f26f32f944db8de8', 254, 254, null, 550, null, null, true, 3),
  ('d0ce77c0-6c02-591e-b7a7-b235cce0b971', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68P', 'Radiology Specialist (Radiology Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise large radiology activity. Perform duties shown in preceding level of skill. Establishes work priorities and distributors workload. Reviews, consolidates and prepares technical, personnel and administrative reports. Coordinates and prepare sites for installation of radiographic equipment. Manage0 personnel affairs, supply economy procedures and fiscal matters. Prepare manpower survey reports. Prepare the operating budget for Department of Radiology. Review operations to ensure compliance with Joint Commission on Accreditation of Health Care Organizations (JCAHO) standards.', 'dfaff0da6acc1539fb6d360404b1ca9dde2fb5c6f89b564046c4176b71766e50', 254, 254, null, 551, null, null, true, 4),
  ('c2a6d335-fa2d-556e-9a9f-78775d72d45b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68P', 'Radiology Specialist (Radiology Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise radiology activity in MEDCEN, large MEDDAC or Combat Support Hospital (CSH). Perform duties shown in preceding level of skill. Instruct in the procedures for developing and conducting training of military and civilian radiographic technicians. Monitor the use, requirement, maintenance and management of resources.', 'cdc0505c791efd172fc513bf0dcfa0a9397a96b7d3ad5c28d2b55353faae7c8f', 254, 254, null, 552, null, null, true, 5),
  ('fd7ac93b-bf55-5a85-ac91-4c544b9d1f42', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Q', 'Pharmacy Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The pharmacy specialist prepares, controls and issues pharmaceutical products under the supervision of a pharmacist or physician and supervises pharmacy activities. MOS 68Q personnel require finger dexterity in both hands.', '8a8b2f7ccd59c7ed7faad73db528188b18016fce7dd938ad1b78dfb307400ec6', 256, 256, null, 553, null, null, false, null),
  ('52c5fb78-1ef9-5163-b948-b80b6f03262b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Q', 'Pharmacy Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Prepares, controls and issues pharmaceutical products. Prescription handling and dispensing: Under close supervision, manually or using a computerized system, receives, interprets, compounds, fills, labels, issues, files prescriptions, bulk drugs, sterile products, and/or unit dose orders. Evaluates orders to verify proper dosage, dosage regimens, and quantity to be dispensed. Checks for completeness and correctness and for common interactions, incompatibilities and availability. Refers questionable orders or questions on basic formulation to supervisor for clarification. Reduces or enlarges formulas, as required. Calculates and annotates proper dosage. Evaluates completed orders to ensure integrity of final product. Provides information regarding availability, strength and composition of medications to physicians or pharmacists. Verifies patient eligibility for receipt of medication. Provides instructions to patients regarding medication consumption and side effects. Performs quality control checks on medications. Issues medication to patients, wards, clinics and other agencies. Supply, administration and maintenance: Assigns and records prescription numbers. Delivers unit dose, sterile products, bulk drugs and controlled drug orders. Prepares prescription labels and affixes auxiliary labels. Maintains signature cards and prescription files. Prepares and maintains files of controlled substances stock cards, records, and work units. Maintains master formula records, batch sheets, and patient medication record. Maintains pharmacy reference files and publication library. Prepares and files pharmaceutical reports. Prepare requisitions for supplies and receives, packs, unpacks, stores, safeguards, and accounts for inventories. Controls and issues pharmaceutical and pharmacy supplies. Inspects, calibrates, operates and performs preventive maintenance on common pharmaceutical compound and packaging equipment. Cleans and disinfects pharmacy equipment, and work areas. Packs, unpacks, loads and unloads equipment and assists in setting up unit equipment.', 'b6cb452bbdcde193802d5db1c9a23f6870c0d105d565473d080716b471f80bea', 256, 256, null, 554, null, null, false, 1),
  ('ae3cc804-79f8-5662-9f1d-969fd7dc093e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Q', 'Pharmacy Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Prepares duties shown in preceding level of skill and provides technical guidance to lower grade personnel in accomplishment of these duties. Prepares, controls and issues pharmaceutical products to include chemotherapeutics. Evaluates sterile products and orders to include calculations, identification of drug interactions, and drug compatibilities. Maintain pharmacy system database.', '0c175f00045fcb096a6328a53fbd076d1f30deae6403e68ff0cfdeeb043c7303', 256, 256, null, 555, null, null, true, 2),
  ('7f51dcdb-bd2a-5f84-8ecc-6de0ff4f56ba', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Q', 'Pharmacy Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding level of skill. Assists with or supervises pharmacy operations. Prescription handling and dispensing: Refers questionable drug orders or questions on basic formulation to appropriate professional for clarification. Prepares master formula cards and drug control ledgers. Reviews and updates compounding formula reference file. Supervise requisitioning of standard and nonstandard supplies. Establishes and maintains stock levels. Researches and interprets pharmaceutical supply catalogs. Disposes of unserviceable and outdated pharmaceuticals. Organizes work schedules, assigns duties and instructs subordinates in work techniques, procedures, and evaluates pharmacy operations. Establishes work priorities and distributes work load. Inspects pharmacy area to ensure orderly, clean and safe environment. Supervises operational maintenance program of pharmacy equipment. Prepares and conducts training programs. Evaluates personnel performance, counsels personnel and prepares evaluation reports. Prepares and updates pharmacy Standard Operating Procedure (SOP).', 'd9161ebd04845010a31af9a521c13144c84de059018d251835be94f6a1736024', 256, 256, null, 556, null, null, true, 3),
  ('22a3ac76-2acf-5253-809e-1ffc3889337e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Q', 'Pharmacy Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise pharmacy operations. Performs duties shown in preceding level of skill. Ensures compliance with quality control methods and procedures. Assists in compiling information for Pharmacy and Therapeutics Committee Meetings. Assists in revision and update of hospital formulary or drug list. Reviews work schedules. Establishes, reviews, evaluates and makes necessary revisions to training programs. Ensures compliance with Army and Federal rules, laws and regulations relative to pharmacy operations. Directs and supervises supply inventories. Reviews established stock levels to ensure compliance with command guidance. Reviews requisitions for standard and nonstandard items and emergency medications. Reviews, consolidates and prepares technical, personnel, and administrative reports. Assists pharmacist in personnel matters. Prepares manpower survey reports. Coordinates pharmacy and personnel matters pertaining to pharmacy with other elements of medical treatment facility. Reviews operations to ensure compliance with Joint Commission standards.', '81b92bb1a5c0421360ad9e29a49413d00f84b12eb60db35ddf6e61d2bace1cbe', 256, 256, null, 557, null, null, true, 4),
  ('2634d0bc-956a-5d03-b0b8-2d28e8ec8581', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Q', 'Pharmacy Specialist', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises pharmacy activities within the U.S. Army Medical Center of Excellence (MEDCoE). Performs duties shown in preceding level of skill. Assists in establishment and operation of formal training programs for specialized areas. Ensures compliance with quality control standards for doctrinal material in formal training programs. Compiles information for Pharmacy and Therapeutic Committee Meeting.', '6685ff1b797fac23a61324c59d62c288ecbdc6cd12f203b7a99fd3e4794e50bb', 256, 257, null, 558, null, null, true, 5),
  ('0aa85452-bce8-58bf-8ffc-23cae2a477cf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68R', 'Veterinary Food Inspection Specialist (Vet Food Insp Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The veterinary food inspection specialist supervises the inspection of, or inspects meat, poultry, waterfoods, eggs, dairy products, operational rations, fresh fruits and vegetables in depots, supply points, and on military installations to assure a safe, high quality food supply for DoD personnel in all environments with emphasis on the field wartime environment.', 'a005f3fac0db91352b92793de5c1c38a3e103e67841e995c01cc475310ee79e7', 258, 258, null, 559, null, null, false, null),
  ('fc5380a9-0773-551d-b35b-fc2aebcf1d7e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68R', 'Veterinary Food Inspection Specialist (Vet Food Insp Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Inspects food products designated for human consumption on receipt and in storage. Selects food samples using statistical sampling methods, makes sensory evaluations, determines and records temperatures of products and food in storage areas using the Installation Food Vulnerability Assessment System to ensure quality control. Evaluates packaging, packing and marking requirements in accordance with DoD standards and contractual documents. Classifies defects, determines quality of product, advises supervisor and prepares subsistence inspection reports for input into the Installation Food Vulnerability Assessment System. Collects, prepares and transmits samples to laboratory for testing. Identify unsanitary conditions in food storage facilities and commissary stores. Operates and maintains inspection equipment. Packs, unpacks, loads, unloads and assists in setting up veterinary unit equipment. Performs duties in accordance with approved standards of conduct and reports suspected fraud.', '67707da5856127d9cf2ad834eea050d8e399abb153e67b6fd86faf9079eed902', 258, 258, null, 560, null, null, false, 1),
  ('b2bfa2fa-9c17-5b4d-b2e8-e81741ab0b51', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68R', 'Veterinary Food Inspection Specialist (Vet Food Insp Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding level of skill and provides technical guidance to junior personnel. Develop statistical sampling procedure. Collects, prepares, and transmits samples to laboratory for testing. Reviews laboratory test results and compares to product requirements. Records contractual deficiencies and initiates recommendations for corrective actions. Conducts subsistence quality assurance inspections in food handling establishments, evaluates and recommends corrective actions for unsanitary conditions. Prepares and maintains food defense vulnerability assessments, quality history record and product verification record and distributes as required using the Food Defense database system. Perform pest management, monitoring of packaged water supplies, and field sanitation procedures. Conduct sanitary inspections in military and commercial facilities. Maintain MTOE and TDA organizational equipment.', '9e29b7e517882a33ac2ce6a7a78fa69b265582deff17ea8265a2242b64ec060a', 258, 258, null, 561, null, null, true, 2),
  ('13f09715-5f3d-591d-8cbe-d4c1c0e4fb3e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68R', 'Veterinary Food Inspection Specialist (Vet Food Insp Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties of and supervises the functions of preceding skill levels. Develops and directs procurement quality assurance activities in contractor establishments. Supervises small food inspection or combined veterinary service unit. Supervises the food inspection equipment maintenance program, prepares and conducts technical training. Monitors subordinate personnel performance, performs counseling and prepares evaluation reports. Assist veterinarian in control of zoonotic diseases and other animal diseases of military concern and significance. Reviews, consolidates and analyzes food defense inspection/assessment reports, submits and/or briefs report content as required using the Food Defense database system. Conduct sanitary inspections in military and commercial facilities. Conducts NBC surveys and decontaminates subsistence supplies. Utilize as the subject matter expert and team leader for the food protection quality assurance program.', 'dbe45a924f0771928d2e98f60860520180a18367598f369938d29d93e36c2a34', 258, 258, null, 562, null, null, true, 3),
  ('1557f5e0-6b1e-5d46-883b-3894335efd97', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68R', 'Veterinary Food Inspection Specialist (Vet Food Insp Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise medium sized or combined veterinary service unit. Coordinates transportation, administration, and logistical support of food inspectors and animal care specialists assigned to local activities and at remote sites. Develops, evaluates, and directs individual and collective training programs. Reviews, analyzes, consolidates and prepares food defense inspection/assessment technical reports as required using the Food Defense database system. Reviews and updates publications. Prepares and reviews correspondence. Serve as advisor to veterinary officer in developing food product quality assurance programs. Supports a variety of administrative and programs related ancillary duties associated with installation and MSC operations,', '05456b3b18364c6f00e73162ecdf67a255efe49e22a57f07de85dc724857af40', 258, 258, null, 563, null, null, false, 4),
  ('1df6069c-bd19-5f69-995b-bf4b34289d50', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68R', 'Veterinary Food Inspection Specialist (Vet Food Insp Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises large combined veterinary service units or serves on veterinary staff. Coordinate veterinary service activities with all elements of Department of Defense organizations, veterinary staff elements, and subordinate organizations. Participates in command review of subordinate unit activities, evaluates training programs, and provides recommendations for improvement. Develop budgets, training schedules, and authorization documents. Assists commander in strategic planning, risk management procedures, tactical communication plans, and advises commander on all issues involving enlisted soldiers.', 'ff70a81ecfcba953c61371f28b0cc27396ddb2730feb07e1d5eefc7e8bbb8dcc', 258, 258, null, 564, null, null, false, 5),
  ('c058d7f9-401b-52c9-97fd-6e8bd71af5f8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68S', 'Preventive Medicine Specialist (Pvnt Med Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The preventive medicine specialist conducts or assists with preventive medicine inspections, surveys, control operations and preventive medicine laboratory procedures, supervises preventive medicine facilities, or serves on preventive medicine staff.', '3e29fbc3b13a40793ef07d26193b3fc8ab12c81dc4f6c9e47a480c229b39c48d', 260, 260, null, 565, null, null, false, null),
  ('5d687cb7-5791-5141-a73c-4b6088ba39e0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68S', 'Preventive Medicine Specialist (Pvnt Med Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts preventive medicine inspections, surveys and control operations and assists with preventive medicine laboratory procedures.', '5d9114393d17cc6e9da9c05cbe5f0d7596c2d0c4af736933578e5db9b24e22c9', 260, 260, null, 566, null, null, false, 1),
  ('21a2030f-b7ad-5bc6-8200-70e69531fc17', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68S', 'Preventive Medicine Specialist (Pvnt Med Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts preventive medicine inspections, surveys and control operations and assists with preventive medicine laboratory procedures. Supervise subordinate personnel in the performance of their duties.', '0036047d619e20dd5df38a4be910a31531debaf28480325883cc32c8b4f0667d', 260, 260, null, 567, null, null, false, 2),
  ('0106243f-1bd3-5481-a5c0-68a8c7223ce1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68S', 'Preventive Medicine Specialist (Pvnt Med Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise small preventive medicine services or units. Organize water, food sanitation, hospital environment, entomological, epidemiological and environmental stress surveillance programs. Analyzes and evaluates collected data. Supervise technical and administrative functions of preventive medicine activities.', 'e9be92ded63ff245bc66c928bc2160b0935475911200af601509e086f24e3b2c', 260, 260, null, 568, null, null, false, 3),
  ('c79a1b0a-9787-5b4a-b2dd-7350e2009890', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68S', 'Preventive Medicine Specialist (Pvnt Med Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise medium size preventive medicine services or medical teams/detachments. Assist with development of unit defense plans and operational orders. Reviews and makes appropriate recommendations on doctrine and training literature. Maintain intelligence information and records. Establish quality control procedures for inspection programs and laboratory analysis. Develop community health education programs. Evaluates existing preventive medicine programs and modifies as necessary to meet the needs of the population served.', '1e442da9b21b1e51fb89aefb41392b9c069e45dd58265af256f67c494faa3615', 260, 260, null, 569, null, null, false, 4),
  ('4bf262fb-1472-562f-97a0-89e7c871fe74', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68S', 'Preventive Medicine Specialist (Pvnt Med Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises large preventive medicine services or units, or serves on preventive medicine staff. Staff activities include writing, developing and coordinating command-wide regulations and policies relating to preventive medicine services. Participate in command review and approval of subordinate unit activities. Assist in planning and placement of field medical units. Evaluates training programs and provides recommendations for improvement. Participate in studies and reviews. Maintain records of strength, location and employment of preventive medicine assets.', '3bd46b38c1e6f63b2b809e7de4baa7d5c3afbb0607b58a95ebf71538985284b3', 260, 260, null, 570, null, null, false, 5),
  ('4b357569-591f-55a0-811a-9759a2bba4ae', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68T', 'Animal Care Specialist (Animal Care Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The animal care specialist supervises or provides the care, management, treatment, and sanitary conditions for animals, with a primary responsibility of prevention and control of diseases transmitted from animal to man and comprehensive care for government owned animals.', '41b9fcb7724b823ccf8d54c03eb47ad8f1ef7a3c003cb1a1f0c4cdb7569a9fbe', 262, 262, null, 571, null, null, false, null),
  ('104e98a9-72bf-5835-b8f0-57257add613d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68T', 'Animal Care Specialist (Animal Care Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provide routine daily care for animals in veterinary treatment or research and development facilities. Obtain medical history from owners and/or handlers and measures and records animal vital signs. Perform physical examinations to detect obvious abnormalities and reports findings to veterinarian. Positions and restrains animals for examination and treatment. Calculates doses and administers oral and topical medications as directed by the veterinarian. Maintain sanitary conditions for all components of the veterinary treatment facilities to include operating room and equipment. Assists veterinarian in surgical procedures and performs euthanasia when instructed by veterinarian. Cleans, debrides, and sutures superficial wounds. Collects, preserves, and prepares blood, urine, feces, skin scrapings, and post mortem specimens for shipment and evaluation. Perform routine diagnostic laboratory tests such as fecal smears, urinalysis, blood counts, and chemistries. Records laboratory test results in the Remote Online Veterinary Records (ROVR) System. Takes and develops radiographs of designated animal body parts. Initiates and maintains animal health records, immunization records, animal registration files, animal bite case reports, and other administrative office files within ROVR. While deployed, order medical supplies on the Defense Medical Logistics Standard Support (DMLSS) Customer Assistance Module (DCAM) on the Medical Communications for Combat Casualty Care (MC4) computers.', '7190e98d1efed68e0a2f3a81485de82bac208ca6d7fe1126e3250168f48ed950', 262, 262, null, 572, null, null, false, 1),
  ('12748748-1409-5878-8401-0719afbc78d3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68T', 'Animal Care Specialist (Animal Care Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown at preceding skill level. Provide technical guidance, management, and training to junior personnel. Performs advanced emergency medical procedures on animals such as triage, tracheotomy, burn and poison management, venous cutdown, and insertion of stomach tubes. Operate mechanical respirators, heart monitors, and gas sterilizer apparatus. Supervises non-appropriated fund activities, day-to-day operations, supply management and patient administration procedures. Prepares budgets, trains handlers in emergency care of animals, and assists on research protocol teams. Maintain clinical and organizational equipment.', 'cdf2987ba885e308ad023315feb0690c7802ba7efb126ee834fc0656a6dfa301', 262, 262, null, 573, null, null, true, 2),
  ('9852558a-a2cc-50f5-a6f9-33f448fded9d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68T', 'Animal Care Specialist (Animal Care Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties of and supervises the functions of preceding skill levels. Develops and establishes standard operating procedures for operations of veterinary treatment facilities. Assists in scheduling, conducting, and evaluating training of veterinary service enlisted personnel. Coordinate procurement of high dollar value equipment. Reviews, consolidates, and prepares technical reports. Perform as a liaison for the veterinary officer to interact with installation medical authorities, installation commanders, and civilian agencies.', '73b5d4177f49c066144357a53db0fac19c60ca9d295ec4b1a20a2edf6532276f', 262, 262, null, 574, null, null, true, 3),
  ('367f891a-15d4-5da0-a304-85c4320e20df', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68T', 'Animal Care Specialist (Animal Care Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties of and supervises the functions of preceding skill levels. Schedules, monitors, and evaluates the unit training program and maintains unit/individual training records. Assist the commander in preparing, monitoring, and evaluating the unit operations plan. Compiles and evaluates management and personnel data. Review operations of veterinary service to ensure compliance with laws and regulations regarding humane care and treatment of animals. Monitors laboratory animal procurement procedures and serves on laboratory animal protocol boards. Provide technical assistance in planning, staffing, and modifying existing animal facilities. Supports a variety of administrative and program related ancillary duties associated with installation and Major Subordinate Command (MSC) operations.', '62654c467824d30974fd5148db8013a335a9adb21c1fad11d875c931cd31ecbb', 262, 262, null, 575, null, null, true, 4),
  ('fbf885e9-6bec-5c13-ba94-eca7370808b9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68V', 'Respiratory Specialist (Respiratory Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The respiratory specialist assists the physician in the care, examination and treatment of acute and chronic diseases of the respiratory and cardiac region or assists with the management of the respiratory care areas at both the general and intensive care areas.', '69ef906590d10c114bbf69d570cec48462062f07dd774700bec0d01acce9b853', 264, 264, null, 576, '2025-10-01', null, false, null),
  ('b42d08ee-7173-5398-8e7c-4773b9d588ba', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68V', 'Respiratory Specialist (Respiratory Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Receive orders on treatment requested by the physician. Gathers and checks equipment, takes history, and assesses the patient. Documents results on treatment, administers drugs as ordered, troubleshoot any problems that occur with patient during treatment. Place patient on continuous ventilator care if ordered. Adjust treatment to situation. Perform pulmonary functions, additional assessments (i.e. blood gases) as required, transports patients needing ventilator support by air and/or land. Perform cardiopulmonary resuscitation on both adults and infants. Calculates and runs blood gas machines. Draws up and calculates drug as ordered.', 'aad9fabc14ecbf86e134617815a2431c81c005849ac770455f8ba6a32c4731bb', 264, 264, null, 577, '2025-10-01', null, false, 2),
  ('daf6e2c5-0d59-5529-ae32-3bd680b74cfb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68V', 'Respiratory Specialist (Respiratory Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in the preceding skill level and provides mechanical guidance, management and training to junior personnel. Performs and assists in advanced medical procedures such as thoracentesis, bronchoscopy and tracheal intubation. Operate sterilizing equipment and patient transport apparatus. Prepares budget, train other medical care personnel on respiratory support and assists in research on practical teams. Schedules, conducts and evaluates in-service training of respiratory care personnel. Reviews, consolidates, and prepares technical reports. Perform as a liaison for pulmonary care officer with installation medical authorities, commanders and crucial agencies.', 'c2b651e6e753eeec50ad5123fed442080e7ee9028a5a1a6d51e3ddbbdca14693', 264, 264, null, 578, '2025-10-01', null, true, 3),
  ('5a387be4-039c-5d47-aacf-587c706d66de', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68V', 'Respiratory Specialist (Respiratory Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in the preceding skill level and schedules, monitors, and evaluates unit training. Maintain unit training records. Assists commander in preparing, maintaining and evaluates management and personnel data. Monitor departmental procedures to assure compliance with government regulations. Serve on disciplinary and specialty boards. Develops mobilization plans for superiors. Coordinate requests for care to outside agencies. Supervises home care programs. Coordinates proper short course and advanced training programs.', 'd18343d67de248e2f8e2ec3f863d51f388909291d8f7070296e6be91e74d907a', 264, 264, null, 579, '2025-10-01', null, true, 4),
  ('6cd17e43-c439-515c-a8fb-833cad540d7b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68W', '68W Combat Medic Specialist (Combat Medic Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The combat medic specialist provides emergency medical treatment, limited primary care, force health protection, evacuation in a variety of operational and clinical settings from point of injury or illness through the continuum of military health care and, as a field combat medic, provides emergency medical care/treatment at point of wounding on the battlefield or to battle and non-battle casualties during wartime.', '3d3906387310f764045e0035ac5a6687c8b1f1c98b93dd6b6c69133c612dbcf1', 266, 266, null, 580, null, null, false, null),
  ('eaa334ba-a868-5d1d-9b4c-f50340f87743', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68W', '68W Combat Medic Specialist (Combat Medic Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Administer emergency medical treatment to battlefield casualties, assists with outpatient care and treatment or assists with inpatient care and treatment under the supervision of a physician, nurse, physician’s assistant or a combat medic NCO. Instructs platoon Combat Lifesaver/First Responder 40 hour training course and annual recertification. Responsible for platoon level personnel medical readiness, medical supplies and equipment.', 'b3154f915c39e26de28b2e587f906599aaf83c78976abede140f2827b5f4f19c', 266, 266, null, 581, null, null, false, 1),
  ('809c3292-d0a4-5d22-a10c-2a0f0fce82a7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68W', '68W Combat Medic Specialist (Combat Medic Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Administers emergency and routine medical treatment to battle and non- battle casualties, assists with outpatient care and treatment and supervises field and clinical medical facilities under the supervision of a physician, nurse, or physician’s assistant. Serves as a team leader/supervisor to subordinate combat medical specialists and lead instructor of company Combat Lifesaver/First Responder medical training. Conducts company level medical planning. Supervises unit personnel medical readiness, requests medical supplies, and performs triage NCO duties.', '79230fd3872d672739d129186f7d5de30a666433c5fa7cd2e3bd466bb8bbae2e', 266, 266, null, 582, null, null, false, 2),
  ('8ffe042c-06cf-55cc-8252-608301058ef9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68W', '68W Combat Medic Specialist (Combat Medic Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises activities of field, clinical and mobile treatment facilities. Serves as squad leader/section supervisor. Optimizes the use of Class VIII medical supplies and resources. Develops medical standard operating procedures (SOPs). Performs medical interventions with a higher technical ability. Principal trainer of squad/section personnel.', '53947eecb97c70a6a8e7c29996d55fd94e67780c0d33749d6485d541b3bae1c3', 266, 266, null, 583, null, null, false, 3),
  ('18d58bec-ee39-5661-95f4-addaf14d050e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68W', '68W Combat Medic Specialist (Combat Medic Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises para-professional medical service activities in large fixed and mobile treatment facilities. Serves as medical platoon sergeant/detachment NCO or clinic NCOIC. The organization’s senior medic and medical training NCO. Responsible for all unit combat medics, medical equipment/supplies, and coordination of key resources. Mentor of the junior medical officer/platoon leader.', '71a9d110fc51f5a7bcf3cb2752a61c8ed6ad44f8d4c380c1f6c59c319d1a3eb1', 266, 266, null, 584, null, null, false, 4),
  ('5c8efd2f-99bc-5f6d-9553-20f74d3131b5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68W', '68W Combat Medic Specialist (Combat Medic Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance within the Army Medical Department and Army Special Staff Activities. Serves as First Sergeant, the senior enlisted advisor to the medical company commander. As Master Sergeant, serves as senior medical planner, operations, or intelligence NCO for battalion sized units and above. Department NCOIC in large medical treatment facilities.', '6e3bca26cde0bef1850d209ea8a73dc332c4b018a083b1873d9f8f0c3616911d', 266, 266, null, 585, null, null, false, 5),
  ('f0a31b61-5013-5780-8cb2-6fa1646ce388', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68X', 'Behavioral Health Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The behavioral health specialist, under the supervision of a psychiatrist, social worker, psychiatric nurse, psychologist, assists with the management and treatment in/out-patient mental health activities, during peace time or mobilization; collects and records psychosocial and physical data; counsels and treats clients/patients with personal, behavioral or mental health problems.', 'ef11ec07635e53fa903dd9be09cf7b41048be8fea89e1918d69303bf86a24d2d', 268, 268, null, 586, null, null, false, null),
  ('433d598f-e06f-57ee-beb8-c9ff22765741', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68X', 'Behavioral Health Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Under close supervision, collects and records psychosocial and physical data, assists with care and treatment of psychiatric, drug and alcohol patients and counsels clients/patients with personal, behavioral or psychological problems.', '59f0a61353dd8bf4ff41675f62acf160f9699ccffff9416be268fc42e8b85aaf', 268, 268, null, 587, null, null, false, 1),
  ('3af320a5-0576-589d-a9ef-acfca24b81b8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68X', 'Behavioral Health Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Collects and records psychosocial and physical data and assists with care and treatment of psychiatric and drug and alcohol patients and counsels clients/patients with personal, behavioral or psychological problems.', '2c2327b8495d96df613669477cdeb6979402523322b6e6d59bda0376855978c7', 268, 268, null, 588, null, null, false, 2),
  ('c8c403d9-995e-5b90-b123-bc63e693a7c0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68X', 'Behavioral Health Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Collects and records psychosocial and physical data and assists with direct treatment of psychiatric, drug and alcohol patients, with the management of psychiatric in/outpatient settings, counsel clients/patients with personal, behavioral or psychological problems and assists with management of mental health activity.', '91c77f909296fb5ab7ba982bcb16745f61a3c1c7ee27b99dc8923b64d3e76a5d', 268, 268, null, 589, null, null, false, 3),
  ('ff43ab9f-a781-5906-a354-ead07f748ba6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68X', 'Behavioral Health Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists professional staff with management and supervision of patient treatment in inpatient and outpatient mental health activities. Assists professional staff in the supervision of patient treatment programs, personnel matters, supply economy procedures, fiscal, technical and administrative matters.', '8eec999d3dc4e8ec0a5cc5d327742e112bc43438478266cfe55f25943cffd926', 268, 268, null, 590, null, null, false, 4),
  ('0f3cf5ab-d934-5ba6-9237-a1d427ea7195', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Y', 'Eye Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Eye Specialist supervises or conducts routine diagnostic tests and assists in the care and treatment of ophthalmology or optometry patients.', '905d6b34d8d3e36504615afe06342fa077ad02eb5ab1b04c487b85a2791924c2', 269, 269, null, 591, null, null, false, null),
  ('143fa6f4-ba38-5f4b-84c2-0b8e3508a083', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Y', 'Eye Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts routine diagnostic tests and assists in the care and treatment of ophthalmology or optometry patients under the supervision of an Ophthalmologist, Optometrist, or Ophthalmic Specialist NCO.', '126dde7be0aa1435e61efeff375116b4bcdc8bcaea265360e4146dfcf7da3840', 269, 269, null, 592, null, null, false, 1),
  ('7bacde1b-5cd2-5503-acec-87cb74244c01', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Y', 'Eye Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conducts routine diagnostic tests and assists in the care and treatment of ophthalmology or optometry patients under the supervision of an Ophthalmologist, Optometrist, or Ophthalmic Specialist NCO.', '126dde7be0aa1435e61efeff375116b4bcdc8bcaea265360e4146dfcf7da3840', 269, 269, null, 593, null, null, false, 2),
  ('f1460390-00f6-51dc-9b90-8b3bf99b63ad', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Y', 'Eye Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists in the management of small ophthalmology or optometry clinic. May serve as detachment NCO for a deployable eye team.', 'ac7b483d762dcf2bcb7db47764aa9e483c90590cb7f18adbbd4cc3a00394318d', 269, 269, null, 594, null, null, false, 3),
  ('d2551da2-c833-59ee-acf4-d5294ceb9f19', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Y', 'Eye Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists in the management of large ophthalmology or optometry clinic.', '55f4a7958f2e11f7c81d762aca056d175aaa5a153e4521d772b5f1104906cc01', 269, 269, null, 595, null, null, false, 4),
  ('41d4c6ac-c3b5-5e92-8ec3-039201c375d5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '68Z', 'Chief Medical NCO (Ch Med NCO)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', '(1) The chief medical NCO is the principal non-commissioned officer who supervises, and performs related duties as the senior advisor to Commanders, Directors, and Chiefs of Departments and staff agencies on all matters pertaining to enlisted personnel. They perform these duties in multifunctional medical treatment facilities and medical staff activities, or in medical units formed under the Table of Organization and Equipment (TOE), or Table of Distribution and Allowances (TDA) concept.
(2) The chief medical NCO must be qualified in one of the following twelve MOS (68A, 68C, 68E, 68G, 68J, 68K, 68M, 68P, 68Q, 68R, 68S and 68W) at the grade MSG. Must be knowledgeable in technical mission, responsibilities and operations of all medical functional activities, to include: division and higher levels of medical special, general and joint staff sections, Medical Centers, large and medium size hospitals, Medical Activities, health centers and clinics, battery, company and troop size units, and all levels of echelons for medical organizations to include all major commands. Must be able to plan, coordinate and supervise activities pertaining to unit organization, training, tactical and technical operations.', '6bd8549dcad535993b825f05b532bf5b43896122205dcc531748444d7d8611ac', 271, 271, null, 596, null, null, false, null),
  ('9e2d1f02-0348-5969-bb19-93069229fd17', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '74D', 'Chemical, Biological, Radiological and Nuclear (CBRN) Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The CBRN specialist conduct CBRN reconnaissance and surveillance; perform decontamination operations; conducts CBRN sensitive site assessment and exploitation; and operates and performs operator maintenance on assigned CBRN defense and individual CBRN protective equipment. Additionally, in non-chemical units, CBRN NCOs/specialist plan, conduct and evaluate individual and collective CBRN training, and provide technical advice on all CBRN operations and hazards for company and higher-level organizations.', '6d0097f64b1eb0350549c9ad160122d11da499893d600d923e8058ed84f59cd7', 272, 272, null, 597, null, null, false, null),
  ('9dc31adb-4d80-5b05-8f1c-6494955b577c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '74D', 'Chemical, Biological, Radiological and Nuclear (CBRN) Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs as a team member in support of CBRN reconnaissance, surveillance, detection, and decontamination operations; serve as company CBRN specialist operations readiness specialist.', '7691ad01f0f1cf77d2744def2c83ad25a8a6380d62e8ea6c89aca7e0e0e3d724', 272, 272, null, 598, null, null, false, 1),
  ('b5573455-c040-58f5-b569-01734f7b2ba2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '74D', 'Chemical, Biological, Radiological and Nuclear (CBRN) Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise CBRN reconnaissance and surveillance, detection, and decontamination operations; serve as company CBRN NCOs or operations readiness NCOs.', 'ec8efdf4d759dff00bbe748bcbb12dd03296a63b650a99ff97decf2b5b978fc6', 272, 272, null, 599, null, null, false, 2),
  ('fd8e6a9c-9d50-5896-8390-85278c8353f3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '74D', 'Chemical, Biological, Radiological and Nuclear (CBRN) Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as squad or team leaders and leads CBRN reconnaissance/decontamination squads, and biological detection teams; serve as battalion CBRN NCOs who supervise and train company level CBRN NCOs/specialists and inspect company-level CBRN readiness.', 'eecd17c73559b5822d76bea7fad890b6539dfa8b70a40240d6035bbd27afbd54', 272, 272, null, 600, null, null, false, 3),
  ('93659db3-810a-5051-9df4-fd467fc678a1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '74D', 'Chemical, Biological, Radiological and Nuclear (CBRN) Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as platoon sergeants and supervises CBRN reconnaissance and surveillance, detection, and decontamination platoons; manage operations of a chemical company; serves as the CBRN staff advisor at battalion level and higher who supervises and trains subordinate level CBRN NCOs/specialists and inspects subordinate unit CBRN readiness.', '61f46a0d11cdac769d3f0f9c7921dad211df6f92f973fb73327aba83a14cedbb', 272, 272, null, 601, null, null, false, 4),
  ('38999305-3dd7-574a-b367-435f27184e26', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '74D', 'Chemical, Biological, Radiological and Nuclear (CBRN) Specialist', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as first sergeant, or CBRN Response Team (CRT) team sergeant; coordinates, supervises and conducts group and Army Service Component Command (ASCC)-level CBRN operations.', 'e77efdc84d4fdb1db73efa8f858bdd46d992d6e8871382665ff2e5ca55bb713b', 272, 272, null, 602, null, null, false, 5),
  ('1235ea9e-7e7e-50d9-80ff-ca5a030a56fb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '74D', 'Chemical, Biological, Radiological and Nuclear (CBRN) Specialist', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as command sergeants major and operations sergeants major; advises the commander and staff on all matters pertaining to enlisted personnel; enforces the implementation of established policies and standards as they pertain to enlisted personnel within the command; provides staff supervision; coordinates, supervises, and conducts group, division, corps and ASCC-level CBRN operations.', '545671171655d1b5268ddcc7411ca928aa987cb7b9a44f13c367bc8f9e04d828', 272, 272, null, 603, null, null, false, 6),
  ('41ee7c56-aaf4-5348-93d0-e6319d17964a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79R', 'Recruiter (Active Component and USAR)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Recruits qualified personnel for entry into the Army in accordance with applicable regulations, supervises recruiting and recruiting support activities.', '456358aa6df740d77ff5fb359406e757154e56c5c2f6b93d636739a49b507caa', 274, 274, null, 604, null, null, false, null),
  ('def906ec-a954-578c-bd63-f7e25c388686', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79R', 'Recruiter (Active Component and USAR)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Recruits, interviews, counsels and qualifies applicants for enlistment. Distributes and displays recruiting publicity material. Identifies and cultivates community centers of influence. Explain benefits. Prepare enlistment forms and documents. Arranges for transportation, meals, and lodging for applicants where required. Assists in market research and analysis and makes appropriate recommendations to the chain of command.', 'b7a6388a88f930fb830979e1cd88c8b82aadb411a79b006ea141e6838659e093', 274, 274, null, 605, null, null, false, 3),
  ('15172990-caea-556f-85b6-a89dc78dcf0b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79R', 'Recruiter (Active Component and USAR)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Utilizes and analyzes management data to evaluate subordinates'' performance. Conduct professional development programs. Accomplishes administration, prepares plans and SOPs. Maintain statistics on recruiting programs. Maintain enlistment publications and administrative files. Prepare enlistment reports.', '00be5f7844ecda4a23e0d107dd793c50c7258520f7928d4881c18f48da7c4114', 274, 274, null, 606, null, null, false, 4),
  ('c96397fd-54e2-5b89-82be-f544972b274c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79R', 'Recruiter (Active Component and USAR)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans, organizes, and coordinates recruiting activities. Develops and directs training programs to assist subordinates. Plans and conducts seminars and conferences. Assigns duties and evaluates performance of subordinate recruiting personnel. Conduct inspections to ensure proper and efficient operation and management. The USAR recruiter also performs duties shown in preceding level of skill.', 'a679c15bef8b4952d03352b3a988a5a5da99f75e087a8d38b91a02b2c218e16e', 274, 274, null, 607, null, null, true, 5),
  ('4c08995a-2fd9-50b5-9f09-a32d2547ef9b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79R', 'Recruiter (Active Component and USAR)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Develops and implements operational plans and procedures in support of all units, assigned recruiters, recruiting stations, and recruiting companies; records and reports recruiting force achievements and shortfalls to evaluate organizational and individual recruiting performance; assists in overseeing enlistment processing of Future Soldiers; coordinates enlistment waiver processing, special missions, and ensures regulatory compliance in all areas of concern; Plans and conducts seminars and conferences. Assigns duties and evaluates performance of subordinate recruiting personnel. Conduct inspections to ensure proper and efficient operation and management.', 'b7e1bfd25a00d738c6f337de41e3f22ea21de36e7db785e2d137509aa235f160', 274, 274, null, 608, null, null, false, 6),
  ('82f8a04f-fe87-55ae-b818-9eeb1dda1d01', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79S', 'Career Counselor (Active Component)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists commanders at all levels with sustaining the Army’s readiness posture and achieving their retention mission. Advises commanders on all matters relating to the Army Retention Program, ensures mission accomplishment and processes reclassification actions. Process Bars to Continued Service. Counsels, reenlists, extends, or transitions qualified Soldiers in the Active and Reserve Component to achieve the command’s retention mission. Conducts staff assistance visits. Manages a retention program budget.', '93f4959e45079e18ab6d553700e95667a1ad896115c0fde90dc48b76154a6b55', 276, 276, null, 609, '2027-10-01', null, false, null),
  ('f997f873-ce1c-5709-b52e-7e73c810fd04', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79S', 'Career Counselor (Active Component)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provides career counseling to Soldiers. Conducts retention interviews. Determines Soldiers’ eligibility to immediately reenlist or extend their enlistment, to include options and bonuses; prepares and reviews reenlistment and extension documents for accuracy; coordinates retention ceremonies. Advises commanders on criteria for selection of unit level retention NCOs. Advises Soldiers on all aspects that could impact their decision for continued service, to include the Declination of Continued Service Statement. Evaluates and trains unit level retention NCOs. Briefs leaders, Soldiers and families on matters relating to retention and reclassification actions. Maintains liaison with local personnel, agencies, and finance offices. Manages retention mission, statistics, incentives, and awards program.', 'b0db9f244de990027d973b7cfab4876d974c82eefe98282ab800f5c003203939', 276, 276, null, 610, '2027-10-01', null, false, 3),
  ('5d3c1dcf-6a65-57b6-b2b6-d545073891ea', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79S', 'Career Counselor (Active Component)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level and provides technical guidance as required. Reviews retention actions for accuracy. Interprets regulations and provides guidance to subordinates. Assists in the development and direction of command retention programs. Coordinates with strength managers to ensure command’s readiness posture. Plans, coordinates, and conducts retention training. Explains unit performance data to leaders and superiors. Evaluates subordinates’ conduct of a retention interview. Determines Soldiers’ eligibility and recommends Soldiers for retention duty. Plans and conducts retention training.', '7cd5c4ffb1f2c2943a8f3da15d56b4af90aa4450c1f0144f01d97a2d488d8b65', 276, 276, null, 611, '2027-10-01', null, true, 4),
  ('24fb8e21-495b-5b7c-a40f-5cc29edf97b4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79S', 'Career Counselor (Active Component)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels and provides technical guidance as required. Analyzes retention trends; provides leadership, mentorship, and training, and recommends courses of action to achieve the commander’s retention mission. Reviews packets, interviews, and recommends Soldiers for retention duty. Serves as the Field Reclassification Authority (FRA) (applies to SGM, SR Retention Operations, and DRU SR Career Counselor positions only).', '8c8d2773b330a8af8d971634856d1004c8fd742ad92f661132947055bb0819e5', 276, 276, null, 612, '2027-10-01', null, true, 5),
  ('2d7dd61a-c79f-50b3-bd21-6cff4803dd88', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79S', 'Career Counselor (Active Component)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Principal advisor to the Commander, CSM, staff and senior leadership on all retention matters; develops and directs the retention program for units dispersed throughout the command. Mentors subordinate Career Counselors, battalion, and unit retention NCOs; develops and coordinates actions for management and utilization of a retention budget; interfaces with higher headquarters and HQDA on retention actions; interprets policy and regulations.', 'e5196a97f92ea1e0bb3307378875b6d520d209664e14aded6d5777da6be91361', 276, 276, null, 613, '2027-10-01', null, false, 6),
  ('26daec86-7854-5420-982e-adf9049749e4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79T', 'Recruiting and Retention NCO (Army National Guard of the United States/ Recruiter and Retention NCO)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Recruits and retains qualified Soldiers for entry into the Army National Guard in accordance with applicable regulations. Supervise recruiting and retention activities.', '579e2b0e759923c8271f49f74e3952c83b5a4f4dc2bd4725b1d9cf1c58bf1754', 279, 279, null, 614, null, null, false, null),
  ('33929773-6fd5-5a04-a714-52af018390ef', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79T', 'Recruiting and Retention NCO (Army National Guard of the United States/ Recruiter and Retention NCO)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as a RRNCO. Area canvasses and telephone prospects to find leads, referrals, and prospects. Pre-qualifies referrals, prospects, leads, and/or current members to determine their eligibility for enlistment, re-enlistment or extension and updates records in Recruiter Zone (RZ). Schedules appointments and conducts sales interviews to obtain enlistment and retention interviews to retain current enlistments and gain re-enlistments, then updates records in Recruiter Zone. Counsels’ applicants on test results, (mental and physical), enlistment contracts, service obligations, incentives and benefits, initial entry training (IET) requirements and disqualification, and update record in RZ. Prepares Prior-Service (PS) and Non-Prior Service (NPS) enlistment packets in RZ and conducts a Military Entrance Processing Station (MEPS) pre-enlistment screening briefing as required. Prepares and conduct presentations about the ARNG on such topics as the role of the ARNG, state/federal missions, features and benefits, employment opportunities and ARNG history. Establishes and maintains a partnership with assigned units and assists the Commander and First Sergeant in executing the unit strength maintenance (SM) plan and attrition management program. Assist unit leaders in all matters pertaining to SM by providing SM guidance, support and recommendations for SM training, and development of SM incentive award programs. Attend at least a portion of each multiple unit training assemblies (MUTA) for unit(s) supported. Distribute and display SM promotional items in the unit and community. Conduct interviews with Soldiers, family members, employers, and other key people to determine the effectiveness of current policies, unit training, ARNG benefit programs, and other initiatives and provide recommendations to the unit leadership for improvement. Maintain regular contact with unit members to help prevent and solve problems, discuss issues, provide information, and answer questions. Provide trends and recommendations to unit leadership. Train first line leaders (FLL) in career planning, recommend available programs and options. Provide SM guidance and training for unit attrition personnel and on all administrative requirements necessary for Soldiers retention. Provide feedback as required after each unit drill and provide information papers and other reports as needed or required to keep the unit leadership informed of strength status and provide the company leadership the following information. Explain ARNG opportunities to Soldiers and their families; research and explain available features, benefits, and entitlements. Use RZ to complete and send all enlistment packets to MEPS, download leads, update leads as they progress, and make appointments. Use RZ to demonstrate work activity to allow higher echelons to validate RRC funding. Use RZ to maintain prospect information, school program information, centers of influence (COI), very influential people (VIP), and unit member information as required. Assist in transfer, separation, and discharge requests. Assist and support the State NPS Recruit Sustainment Program (RSP). Operate Recruiter Temporary Reservation System (RTRS). Build and process waiver packets in accordance with (IAW) state and/or NGB SOP. Obtain, prepare, distribute, and display attrition management promotional items. Assist in the development and implementation of the Unit Sponsorship Program. Assist with ETS counseling when the Soldiers are not available during the scheduled UTAs. Work directly with unit administrative personnel to support/complete retention issues. Provide guidance to Soldiers entering and completing the RSP.', 'a926fe8fcb55e2757170bda1c62033db060e01e50131144c56e21d375496f99b', 279, 279, null, 615, null, null, false, 3),
  ('b9e684d0-5afb-5ab8-9a42-e26ae0f172d5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79T', 'Recruiting and Retention NCO (Army National Guard of the United States/ Recruiter and Retention NCO)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as Senior RRNCO preforming all duties of the previous skill level while providing mentorship to new RRNCOs. May also serve as Recruiting and Retention Team Leader providing leadership while managing a recruiting and retention station of RRNCOs and SRRNCOs. Establishes performance standards, monitors, and evaluates RRNCOs and SRRNCOs on the overall effectiveness of their recruiting and retention activities/programs (e.g., presentations and briefings, sales interviews and techniques, enlistment and re-enlistment packets, waiver requests, RZ usage and provide training as needed). Counsels and rates RRNCOs and SRRNCOs assigned IAW AR 623-3 and locally established policy. At a minimum, conducts monthly performance counseling with each assigned RRNCO and SRRNCO. Assists the Recruiting and Retention Section Chief (R&R Section Chief) or First Sergeant with establishing and implementing a written yearly training program designed to address the specific training needs and levels of experience of assigned RRNCOs and SRRNCOs.', '2ec30cc3bbd6b6149f1a278642c714a925ad82e7cf09f972b91cd81a5cbab752', 279, 279, null, 616, null, null, true, 4),
  ('3485062b-49f1-5656-a76b-4f14f48af32f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79T', 'Recruiting and Retention NCO (Army National Guard of the United States/ Recruiter and Retention NCO)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Establishes performance standards, monitors, and evaluates Recruiting and Retention Team Leaders (R&R Team Leaders) on their overall effectiveness to include their leadership capabilities while managing and mentoring their RRNCOs and SRRNCOs, evaluates recruiting and retention activities/programs (e.g., presentations and briefings, sales interviews and techniques, enlistment and re-enlistment packets, waiver requests, RZ usage and provide training as needed). Counsels and rates R&R Team Leaders assigned IAW AR 623-3 and locally established policy. At a minimum, conducts monthly performance counseling with each assigned R&R Team Leader. Responsible for establishing and implementing a written yearly training program designed to address the specific training needs and levels of experience of assigned RRNCOs, SRRNCOs, and R&R Team Leaders. Provide RRNCOs and SRRNCOs with market data, trends, and other pertinent demographic information. Coordinate with State Quota Manager for training seats and conduct new RRNCO orientations and training as required. Works with unit leaders to ensure awareness of and compliance with the SM Program. Discusses and plans activities to meet strength missions and conducts SM training, presentations and briefings as required. Assists RRNCOs by making and evaluating periodic presentations to local schools, government, civilian and other influential persons and informing them of the benefits available in the ARNG. Assists in the hiring of new RRNCOs as directed by the RRC. Constantly scan assigned units for qualified Soldiers. Assess the effectiveness of area recruiting, attrition management and retention incentive/awards programs and make recommendations for improvement. Provides administrative guidance and technical support to assigned R&R Team Leaders. Monitors assigned R&R Team Leaders, SRRNCOs, and RRNCOs to ensure compliance with applicable regulatory guidance in the use of GSA vehicles, information technology hardware/software and expense accounts. Assign and assist in the training of recruiter assistants. Advises the O&T Officer or RRSGM/ CSM concerning mission accomplishment, operations, training, assists in developing, maintaining, and analyzing statistical data of assigned area demographics, as well as unit losses, unit climate information and SIDPERS data to form current and projected trends. Works with the State Family Assistance Program representatives and coordinates program activities. Provides sustainment and remedial training for assigned R&R Team Leaders as needed to maintain skills and prevent poor performance. Makes recommendations for disciplinary action and/or dismissal of R&R Team Leaders, SRRNCOs, and RRNCOs as required. Verifies priority leads are “worked”, MEPS-bound Soldiers are projected, and prior service Soldiers are entered into Recruiter Zone to allow the state leadership to validate funding levels. Ensure RZ data correctly portrays the work completed.', '0b0f8e8d23a4793dd465b3a1619feefa7d8fae76d92d15f35c61514c51d6989b', 280, 280, null, 617, null, null, false, 5),
  ('9e731a5b-8166-5649-bc2e-f6a7f6f72274', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79T', 'Recruiting and Retention NCO (Army National Guard of the United States/ Recruiter and Retention NCO)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists the RRC in developing the State SM Plan and implementing and monitoring the State SM Program. Makes recommendations as appropriate to successfully achieve assigned end strength mission. Assists the RRC in the development and implementation of a SM awards program that provides incentives for all RRF personnel. Assists in the planning of recruiting and retention workshops. Obtains and analyzes demographic and market share data to determine the most effective utilization of assigned First Sergeants, R&R Section Chiefs, R&R Team Leaders, SRRNCOs and RRNCOs. Supervises, counsels, and rates First Sergeants and R&R Section Chiefs assigned IAW AR 623-3 and locally established policy. At a minimum, conducts monthly performance counseling’s with each assigned First Sergeant and R&R Section Chief establishing and assigning written mission requirements and performance standards for all assigned. Overall responsible for establishment and implementation of written training programs designed to address initial, sustainment, and remedial training needs and levels of experience of all assigned Soldiers. Overall responsible for the development and implementation of the sponsorship program for newly assigned RRNCOs. Develops and implements a written policy that addresses poor job performance. Assist in the hiring and dismissal of members of the RRF within assigned region and other RRF personnel as directed by the RRC. Monitor all RRF enlisted personnel actions and requests within the assigned area. Provide SM guidance and recommendations to Administrative Officers (AO) and commanders at brigade and battalion levels. Coordinate with the RRC regarding development and implementation of long-range SM programs within assigned region. Ensure fair and equitable mission assignment for all assigned First Sergeants, R&R Section Chiefs, R&R Team Leaders, SRRNCOs, and RRNCOs. Ensures proper training and career development for all RRF personnel within assigned area. Assists and advises the RRC concerning production, operations, training, administration, and personnel status or actions within assigned area. Monitors the SM Plans of subordinate First Sergeants and R&R Section Chiefs. Assists the RRC in monitoring the efficiency of the RRF through the use of Recruiter Zone. Assists leaders and commanders, through the State Liaison for ESGR, and national ESGR, with solving employer conflict issues. Implements the Non-Commissioned Officer Professional Development (NCOPD) program for NCOs in assigned region. Serve as CSM/ SGM to all Soldiers assigned to the RSP.', '2b0e253bbe93af5b71ec138a5b94fff3c62d174f00c3f2c0e421e44ebc91c0ec', 280, 281, null, 618, null, null, false, 6),
  ('46d3caee-808d-51ff-b22e-3e010eed7a71', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79V', 'Army Reserve Career Counselor (Army Reserve)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Transfers, counsels, informs, and retains qualified Soldiers in the Individual Ready Reserve (IRR), Troop Program Unit (TPU), Active Guard and Reserve (AGR), and Individual Mobilization Augmentee (IMA) programs to continue service and professional growth in the U.S. Army Reserve (USAR). Supports USAR end strength objectives by retaining qualified Soldiers and filling critical vacancies. Prospects units for qualified applicants for officer commissioning programs and AGR CMF 79 accessions. Supports USAR units in executing the U.S Army Reserve Retention Program and Chief, Army Reserve (CAR) policies.', 'f8274c1c1fb287d1346a15c24feef37f2d4808eb4e6b4fad9100ee3c1b54e609', 282, 282, null, 619, null, null, false, null),
  ('b3e737f0-4414-54ae-be26-108afaa13b71', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79V', 'Army Reserve Career Counselor (Army Reserve)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Determines eligibility for transfer, reenlistment or extension, and officer accessioning programs. Updates records contained in the Retention Management Software (RMS) as well as applicable personnel systems. Conducts multiple methods of contacting IRR, TPU, and IMA Soldiers. Pre-qualifies and counsels to determine military and civilian status. Schedules appointments and conducts sales interviews to obtain transfers to the selected reserve (SELRES) and retention interviews to gain reenlistments and extensions. Updates personnel records contained in RMS through unit personnel or Total Army Personnel Database – Reserve (TAPDB -R). Counsels IRR and TPU Soldiers on enlistment contracts, service obligations, incentives, and benefits of Army Reserve participation. Executes documents to complete IRR to SELRES transfer, reenlistment, extension, and developmental counseling forms in accordance with applicable United States Army Reserve Careers Group (ARCG), USAR and U.S. Army regulations, pamphlets, and policies. Prepares and conducts unit presentations on personal and professional development, Army Reserve features and benefits, employment opportunities, officer commissioning programs, retention topics, and the Selected Reserve Incentive Program (SRIP) policy. Executes the HRC Personnel Accountability Muster Program in efforts to ready the IRR population in support of U.S. Army missions. Establishes and maintains a partnership with multiple assigned units and assists command teams in executing the Army Reserve Retention Program. Assist unit leaders in all matters pertaining retention by providing guidance, support, and recommendations for development of unit incentive award programs. Attends multiple unit training assemblies (MUTA) for unit(s) supported. Conduct interviews with Soldiers, Family members, and unit leadership to address the effectiveness of current unit policies and unit training on the unit retention program. Provide recommendations to the unit leadership for improvement. Maintain regular contact with unit members to help prevent and solve individual problems, discuss issues, provide information, answer questions, and recover unsatisfactory participants. Provide retention trends and recommendations to unit leadership. Trains unit personal as Duty Appointed Reenlistment NCO (DARN). Provide unit leadership information and training attrition personnel and on all administrative requirements necessary to retain Soldiers. Provide leadership with feedback as required after each unit Battle Assembly and Annual Training mission to keep the unit leadership informed of the unit retention program. Assist unit with recommendations and options for transfer, separation, and discharge requests. Assist in the development of the Unit Sponsorship Program. Complete expiration term of service (ETS) counseling. Work directly with unit administrative personnel to support/complete retention issues. Establish and maintain relationships with agencies outside of the United States Army Reserve. to assist the total Army end-strength.', '487579d5bb52bd0b51613f2f970eeb8c0761c0592e98f69365a7962a09936de4', 282, 282, null, 620, null, null, false, 4),
  ('9df73ff7-a6ae-5de3-8865-3bb918688b5d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79V', 'Army Reserve Career Counselor (Army Reserve)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill levels and provides technical guidance as required. Establishes performance standards, monitors, and evaluates subordinates on their overall effectiveness to include their leadership capabilities while managing and mentoring their subordinate ARCCs. Evaluates retention activities/programs (e.g. presentations and briefings, qualification interviews and techniques, reenlistment packets) for assigned area of responsibility. Counsels, develops, motivates, and rates ARCCs assigned IAW AR 623-3 and locally established policy. Conducts monthly performance counseling with each assigned ARCCs. Responsible for establishing and implementing a written yearly training program designed to address the specific training needs and levels of experience of assigned ARCCs. Provide ARCCs with market data, trends, and other pertinent demographic information. Works with senior unit leaders to ensure awareness of and compliance to the Army Reserve Retention Program, CAR policies, and ARCG guidance. Advise JAG and IG on inquires related to Army Reserve retention. Discusses and plans activities to meet strength missions and conducts Army Reserve retention training, presentations and briefings as required. Assists in the hiring of new ARCCs as directed by the Battalion. Constantly scan assigned units for qualified Soldiers for active, guard, and reserve (AGR) program, officer commissioning programs, and professional growth opportunities. Assess the effectiveness of area retention, attrition management and retention incentive/awards programs and make recommendations for improvement. Provides administrative guidance and technical support to assigned ARCCs. Monitors assigned ARCCs to ensure compliance with applicable regulatory guidance. Assign and assist in the training of unit DARN personnel. Advises the Battalion leadership concerning mission accomplishment, personnel, operations, and training. Assists in developing, maintaining, and analyzing statistical data of assigned area demographics, as well as unit losses, unit climate information and personnel data to form current and projected trends. Provides sustainment and remedial training for assigned ARCCs as needed to maintain skills and prevent poor performance. Verifies all applicable updates, documents, transactions, and actions are completed and correct in RMS. Ensure RMS data correctly portrays the work completed.', '61eddb5a20fdc75b82fa14b5ecbf9659da3af3e05676e252b22d539f54ede5d7', 282, 283, null, 621, null, null, true, 5),
  ('a28127ed-80f0-5e2c-a7d9-9d8e66a166a0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '79V', 'Army Reserve Career Counselor (Army Reserve)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', ', Serves as the senior enlisted subject matter expert (SME) for retention and transition and advises commander at all levels concerning retention. Coordinates and employs strategic plans for mission success including mission and operational market analysis, and historical trends. Manages enlisted Soldiers through the talent management process of hiring, assignments, and transfers. Continuously monitors and assesses organizational training, makes recommendations, and evaluates training outcomes through measures of performance and measures of effectiveness. Oversees the Noncommissioned Officer Development Program (NCODP). Enforces standards, discipline, and assesses morale. Supervises headquarters staff personnel and provides counsel to the operations team and executive officer. Conducts area quality assurance visits. Fosters relationships and liaisons with command leadership of troop program units (TPUs), regional support commands (RSCs), major supporting commands (MSCs), Soldier readiness processing centers (SRPCs), Reserve Components Career Counselors (RCCCs), and United States Army Recruiting Command (USAREC) personnel', '33e465db22ece991b55e0829f562910de2f2644401395a38703bf4fe79f2f5d0', 283, 283, null, 622, null, null, false, 6),
  ('728c21d7-7957-5c1c-a9ca-3bbef000b1ae', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88H', 'Cargo Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The cargo specialist transfers or supervises the transfer of passengers and cargo to and from air, land, and water transport by manual and mechanical methods.', '777a612e2fd132ce1ac6935c9fad8bd295dc7b8d1a7ca1bccbf62088521ca573', 285, 285, null, 623, null, null, false, null),
  ('39635974-a01c-5f3c-8c96-77fd3e88a53b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88H', 'Cargo Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Checks, tallies, and documents cargo utilizing both manual and automated data processing systems. Rig ships'' gear as part of a team. Loads and unloads supplies and equipment from ships, docks, beaches, railheads, boxcars, warehouses, motor vehicles and aircraft (to include internal and external helicopter loading). Operates and maintains all types and sizes of winches, cranes, and forklifts. Masters lashing procedures using various vehicle lashing assemblies IAW DOT and other regulations.', 'd7b19241cdb7b67e63401d1003861cdf1eeac1a9df321593098f31c78c9eeb0a', 285, 285, null, 624, null, null, false, 1),
  ('ef1203ac-f680-54c3-bad6-4efe88ce343f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88H', 'Cargo Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assigns cargo handlers, signal and winch operators to duty stations. Provide technical guidance to subordinates. Inspects cargo, supervises cargo checking and hatch operations, controls aircraft loading and unloading (to include helicopter external sling loading operations), oversees railhead tie-down crews, directs container stuffing and unstuffing, plans warehouse storage, and manages crane operations. Supervises operator maintenance for cargo handling equipment such as cranes and forklifts. Enforce safety practices and documentation procedures.', '354e7493fa5601939ece1bbf6e90c65528d2392f0a7d82974b211fe6d1f7e9f5', 285, 285, null, 625, null, null, false, 2),
  ('0d1b5f2c-accf-5d4b-b648-e19ff576a109', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88H', 'Cargo Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans work schedules for terminal operations, airfield arrival/departure control groups (A/DACG), (to include passengers) and container/trailer transfer points. Prepares and utilizes stowage plans, aircraft load plans and other documentation to conduct cargo operations. Issue materiel handling equipment, nets, slings, ropes, cables, wire, rope and other cargo operations gear. Enforce safety practices. Prepares, consolidate, and reviews administrative, personnel, and technical reports covering unit activities. Assist in the planning and supervision of Central Receiving and Shipping Points.', 'c20d5fa85e412622f5f64eb2fe673739dae86463b41d803bdbf820baafbdb723', 285, 285, null, 626, null, null, false, 3),
  ('4fd29584-3746-5510-8c70-a1a984275df6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88H', 'Cargo Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and manages work force. Coordinate administrative matters, communications activities and training programs. Prepare tactical plans and training materiels. Provide staff supervision, policy, and guidance for personnel and cargo movement by air, rail, motor and water transport. Plan and supervise Central Receiving and Shipping Point and A/DACG operations. Evaluate sites for depots, truck terminals, railheads, beachheads, air terminals and water ports/terminals.', '833eabdeed92ac0988e2b3e199a182d0490bc6eaf6d50fb5ba172feaff7ea6fa', 285, 285, null, 627, null, null, false, 4),
  ('8bee28ae-f54e-5fdf-b1ed-bc0e9f2aaae4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88K', 'Watercraft Operator', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The watercraft operator performs mariner duties and supervises other personnel on Army watercraft and amphibians.', '77aada5af01a01ac4c2516fe1435f57d3f9d07f3033cba95b43a747f5c2e2eb4', 286, 286, null, 628, null, null, false, null),
  ('32077dc9-6447-5155-88c1-f34f7ca44cca', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88K', 'Watercraft Operator', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assist in docking and undocking the vessels. Drops and weighs the vessel anchor. Stands lookout and helm watches. Identifies and interprets single-letter international code signal flags. Sends and receives messages with radios, beacons and signal flags. Operates and maintains lifeboats and vessel firefighting equipment. Knowledgeable in all aspects of marlinespike seamanship. Secure all type of cargo using shipboard machinery such as capstans, winches, hoists and davits. Paints surfaces, and cleans compartments and decks.', '21f3fcb5e1352709b7e01b5361620bd46e986c2cafee31fdda0e9c7c711d6973', 286, 286, null, 629, null, null, false, 1),
  ('e3364417-5313-52c3-b07c-e155165c4cd2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88K', 'Watercraft Operator', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operator for Class B Vessels. Provides supervision and technical guidance for subordinates. Maintain vessel charts, publications and orders. Keep the vessel log book. Navigate a boat or other watercraft. Beaches and retracts landing craft. Tow vessels and barges in harbors and inter-coastal waterways. Conducts stowage operations aboard Class B vessels.', '988984328cd18bc2f8ebb4b2942ba4a2a83cb2c7aff6aa712d02b5234925e7a2', 286, 286, null, 630, null, null, false, 2),
  ('94d58967-6c3c-5b4a-bb53-a4a9dc4cbf25', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88K', 'Watercraft Operator', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Instructs subordinates in watercraft and amphibian operational practices, procedures and techniques. Supervise the embarking and disembarking of troops from the vessel. Establishes and enforces safety procedures. Schedules shipboard watches. Prepares vessel load plans. Schedules and oversees deck maintenance. Supervises maintenance of life saving and firefighting equipment.', '08da2271f95494f1b0780c6e5f59fef1cf535e2607406604267801b51ae1f9d0', 286, 286, null, 631, null, null, false, 3),
  ('ccaaafff-dc8a-5e0f-9364-a09ddcb7dfb6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88K', 'Watercraft Operator', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serve as the Vessel Master on board a Small Tug. Apply Inland and International navigation rules while operating vessels. Conducts crew drills and supervises training on the vessel. Disseminate information on weather and navigational aid changes. Maintain the vessel station bill and crew list. Operate the gyrocompass and other navigational equipment. Process operations and intelligence information. Receive, store, distribute, turns in vessel supplies, equipment, and food. Administer the vessel mess functions to include all money exchanges, headcount records, daily cook worksheets, and food utilization reports. Coordinate the operation of collective lighter control points (LCPs).', '25e8b90791362cc42fdaf5b700f983501e09f2cddbec231d91544f5e759c3fa4', 286, 286, null, 632, null, null, false, 4),
  ('21b4a80a-46c8-5a6c-a9f9-a4501f687281', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88L', 'Watercraft Engineer', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The watercraft engineer supervises or performs) field and sustainment level maintenance. Service Army watercraft, amphibians and auxiliary equipment on marine vessels.', '207853f50778dccc288c38b4e63b8348f9c4075ffd86b814d55a66010eeb0561', 288, 288, null, 633, null, null, false, null),
  ('4674b91d-d353-581c-b861-4bc4f85fad9f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88L', 'Watercraft Engineer', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Stands engine room and throttle watch while the vessel is underway. Stands anchor watch and ramp discharge watch during sea and anchor details and while the vessel is in port. Performs daily systems checks and posts all instrument and gauge readings to the engineer log book. Positions fuel control racks and adjusts throttle controls to maximize engine efficiency. Inspects, troubleshoots, tests, services, adjusts, repairs and replaces batteries, electrical system components, fuel system elements, propellers and propeller shafts, pumping assemblies and parts and other marine engine equipment. Cleans, performs surface preparation and paints engineer space equipment.', '16235a3755456580f5efc886847420f5f59bdadd72b4af06aeb628ac8109a117', 288, 288, null, 634, null, null, false, 1),
  ('7330ea22-1610-52fd-9e10-94084f160843', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88L', 'Watercraft Engineer', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provide supervision and technical expertise for subordinates performing their duties. Prepare marine vessel equipment for operation. Starts, operates, troubleshoots and secures vessel engines. Inspects, services, adjusts, replaces, repairs and overhauls engine components, throttle controls, accessory drives, boiler and piping systems, vessel steering mechanisms, electrical and wiring assemblies, cooling and lubrication systems and vessel hulls for general upkeep. Computes fuel requirements and documents vessel fuel usage. Compiles and maintains the engine room records.', '6d8e7018786cd1880ec99023611a94b331a1ca4fa592d7caf4d8e158495ca24f', 288, 288, null, 635, null, null, false, 2),
  ('bcdaa181-6bd4-5627-bc6d-52d7a786ce24', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88L', 'Watercraft Engineer', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises fire fighting, damage control, sanitation and pollution control procedures aboard a vessel. Establishes and enforces engine department safety practices, supervises shipboard watches. Oversees, instructs and provides technical advice in the maintenance of engines, electrical systems, cooling systems, lubrication systems, refrigeration systems, fuel systems, pneumatic systems, power and drive trains, steering systems, boilers and piping, hydraulics and general vessel upkeep. Conducts crew or section drills and training. Prepares maintenance SOPs and organizes the work of the maintenance shop.', 'ba9be92eae37fb9457bd73b50258a476b06919c7111ede8f23627161bd53122a', 288, 288, null, 636, null, null, false, 3),
  ('c43e18fa-d4db-5422-b1cd-cf337882222e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88L', 'Watercraft Engineer', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Instruct and supervises marine engine department personnel in all systems maintenance. Oversee posting of vessel log books, forms and records. Assign personnel to duty positions. Schedules equipment for calibration. Establish maintenance priorities. Prepares and reviews shipyard specifications. Prepare marine vessel historical reports and records, preventive maintenance schedules and records, materiel readiness reports, equipment improvement recommendations and unsatisfactory/faulty equipment reports. Records required and completed modifications.', '813624e4a09503c451fa55118d23c4db01f6d8f295adffec23344352b7c4edaa', 288, 288, null, 637, null, null, false, 4),
  ('2f99bfa5-3808-5b93-ab62-0f14ee7708d9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88M', 'Motor Transport Operator', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The motor transport operator supervises or operates wheel vehicles to transport personnel and cargo.', '081f7e123b2f5a161ff2bd57479319e33a2190298bbdf4aa2cd588296b15aaf4', 290, 290, null, 638, null, null, false, null),
  ('30d8a3dd-2d50-5b79-80c9-18a98e29fd41', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88M', 'Motor Transport Operator', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates all wheel vehicles and equipment over varied terrain and roadways in support of military operations. Manage entrucking and detrucking of personnel being transported. Oversees and checks proper loading and unloading of cargo on vehicles and trailers. Secures cargo against inclement weather, pilferage, and damage. Operates vehicle component Material Handling Equipment (MHE), as required. Employs land navigation techniques. Must be knowledgeable of tactical automated communications systems and weapons when they are mounted on the vehicle. Perform vehicle self-recovery and field expedients to include towing of vehicles. Corrects and reports all vehicle deficiencies; supports mechanics where necessary. Prepare vehicles for movement/shipment by air, rail, or vessel.', 'e4e56be920bc550198a34dfc8fe6aba6ec065793e853b9fa7e73598d972c4364', 290, 290, null, 639, null, null, false, 1),
  ('b2e762f0-5119-5913-a0f2-403ec90e408a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88M', 'Motor Transport Operator', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinate in accomplishing their duties. Assist in organizing and participates in convoys. Dispatches vehicles; verifies vehicle logbooks. Receives and fills requests from authorized persons for motor transportation. Compiles time, mileage and load data. Supervise and or operates all wheel vehicles, equipment and performs self-recovery operations.', 'e7af825499c83529689fec5351d8dd20e6b819a59b43b3cc0ea25a9f466052eb', 290, 290, null, 640, null, null, false, 2),
  ('7f4cf56f-f147-5d1e-b6bd-7acf3bc8d8e9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88M', 'Motor Transport Operator', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises drivers performing preventive maintenance checks, and services (PMCS) on vehicles. Operates in the truck terminal as a squad leader. Trains new drivers and manages the driver sustainment training program. Plans, organizes, and operates a motor vehicle convoy. Perform convoy route reconnaissance; commands a convoy or convoy security element. Prepares OPORD/OPLAN/CONOP and overlays. Supervise the transportation of all types of cargo and equipment. Takes charge of vehicle recovery. Supervise personnel preparing vehicles for military operations.', '4356171a4a04025a15e863e328054a3416d6a30d1456660745a8024dacbb63fe', 290, 290, null, 641, null, null, false, 3),
  ('f67ca8ad-a9c3-5ac7-b57b-4ef3414f0caf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88M', 'Motor Transport Operator', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provides professional support and technical guidance to all personnel requiring motor transportation. Plans, manages, and monitors motor transport and support operations. Establishes and organizes the unit motor pool. Prepares and implements the truck company security and defense plan. Receives and distributes highway motor transport missions. Assembles and prepares highway reconnaissance data for motor convoy transport. Supervises and directs unit dispatching of vehicles and coordinates external support requirements.', 'e3735867df46d7bf46bcedc35ba7213fe37c78ab98f6a035c29050b745102ddc', 290, 290, null, 642, null, null, false, 4),
  ('53ec8015-37fd-505f-9452-bb2120084646', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88N', 'Transportation Management Coordinator (Trans Mgt Coord)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The transportation management coordinator coordinates, monitors, controls and supervises the movement of personnel, equipment and cargo by air, rail, highway and water. Determine the most efficient mode of transport that accomplishes mission requirements.', 'fc4e4f35109f560bd8bd37efc7284be62dfa4f218d3d89cdb35c83c21797b08c', 292, 292, null, 643, null, null, false, null),
  ('f700bf86-314f-5e26-84ae-21aedb61315c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88N', 'Transportation Management Coordinator (Trans Mgt Coord)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Advises military and DoD civilians of their entitlements for shipment of personal property and passenger travel and prepares the necessary documentation. Requests and coordinates transport capability to meet a movement mission. Mark, label cargo and freight shipments in accordance with regulatory requirements. Documents and inventories freight, cargo and materiel shipments of all types; operates automated data terminal equipment to prepare movement documentation or related correspondence. Arrange documentation and reports for follow-up or response to tracer actions. Prepare transportation movements documents and related forms for the type of shipment and mode of travel (e.g., GBLs, MTAs, GTRs, airline service requests, etc). Perform office duties such as posting regulations, files maintenance and routine office correspondence.', '382d59dda10180a1e23cf58562c71fb5307ad77d4c21b9093aef56895c219b75', 292, 292, null, 644, null, null, false, 1),
  ('7ef92748-17e1-5587-add3-d14fb39db7ac', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88N', 'Transportation Management Coordinator (Trans Mgt Coord)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Provide supervision and technical guidance for subordinates. Researches, interprets, prepares and coordinates actions pertaining to travel entitlements. Function as the customs officer for shipment releases in overseas theaters. Operate as quality control NCO for commercial movement contracts. Monitors all freight, cargo and materiel shipments to ensure accountability; identifies and reports problem areas within the traffic management system to prevent additional costs, losses and damage. Conduct briefings for unit moves. Requests, coordinates and monitors movement schedules and programs; ensures transport capability is appropriate, cost effective and meets mission requirements. Checks and inspects equipment blocking and bracing. Prepares and consolidates transportation movement reports. Operates automated data processing equipment to document movement information, conducts research, monitors movements, inspects commercial contracts and responds to shipment inquiries, discrepancies and routine movements transactions.', '77cedf12766ba4802b287612034f251fb6627eca2244233844f50bbfe5bc5667', 292, 292, null, 645, null, null, false, 2),
  ('d6974186-ecb0-5388-bef9-fdc844c6d917', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88N', 'Transportation Management Coordinator (Trans Mgt Coord)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conduct a training program for subordinate personnel. Supervise the operation of a cargo and materiel documentation unit, a movement control branch or section, a break bulk point/terminal warehouse, a trailer transfer point, a port operations unit, an air terminal section and the installation personal property and passenger travel section. Evaluates work techniques and procedures for all functions. Maintain liaison with air, rail, highway and water transportation facilities. Initiates, researches and proposes necessary changes to the traffic management system for cost effectiveness and mission requirements. Supervises customs officers and reviews customs procedures in overseas theaters. Prepares, consolidates and reviews technical, personnel and administrative reports and forms covering transportation matters (e.g., unit movement, personal property, passenger travel, freight/cargo and materiel movement reports). Checks, reviews and consolidates movement requirements; ensures appropriate transport capability and prepares movement schedules. Assist in planning transportation requirements for logistical support. Supervise any diversion, re-consignment or transfer of personnel, freight and materiel shipments for all modes of transportation.', '3509b79105ea7b0513a957ef53c32af6837dcb9cc58eb0685e514d7f4dfad358', 292, 292, null, 646, null, null, false, 3),
  ('43fe5489-f450-587d-941d-a16e49608527', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88N', 'Transportation Management Coordinator (Trans Mgt Coord)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise cargo documentation and movement control units for all transportation modes. Supervise freight, cargo, personal property and passenger travel at installation level. Analyzes, evaluates and proposes changes to the Defense Transportation System. Formulates and reviews documentation on technical traffic management functions. Devises and reviews movement programs for logistical support functions in a theater of operations. Serve as the transportation liaison representative between other military services, commercial agencies and host nation support elements. Advisor for the preparation of operation orders where transportation is required. Review DoD contracts and agreements with host nations. Verify the accuracy of movement control documents. Evaluate sites for depots, truck terminals, railheads, beachheads, air terminals and water ports/terminals. Determine transportation capabilities and limitations of units. Perform as staff NCO in military traffic management agencies. Monitors quality controls that ensure commercial transportation services meet contract obligations. Monitors and documents all customs discrepancies and reports them to appropriate authorities. Ensures allocation of transport capability is appropriate to accomplish each mission in a cost effective manner.', 'b2aa847d3cc5000c282416b528d9ccd86b59016593f1f160e811e4e6a471f764', 292, 293, null, 647, null, null, false, 4),
  ('4ee8d10d-b579-54db-b35f-9149453e24ce', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88P', 'Railway Equipment Repairer (USAR only)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The railroad equipment repairer supervises or performs unit and direct support/general support (DS/GS) maintenance on diesel-electric locomotives and railway cars.', 'e22b30b91b9768f0e7803372c50f24de58cd76641e4cad265bccd63331ab4ce1', 294, 294, null, 648, null, null, false, null),
  ('b218af47-fc68-5ff5-89a4-39e1744fa171', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88P', 'Railway Equipment Repairer (USAR only)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Use technical blueprints and sketches. Inspects locomotives for malfunctions. Repairs cooling systems, fuel systems, exhausts, airbrake components, lube oil systems, electrical systems, and diesel engine components on locomotives. Inspect, tests and services locomotive batteries. Inspects frame and running gear for breaks, cracks, or worn surfaces; welds, rivets, caulks, paint, and stencils as necessary. Inspects and repairs couplers. Examines and repairs truck and wheel assemblies, safety appliances, car underframes and crossbearer, and interiors of cars. Prepare written reports of any airbrake defects.', '3d55dd332a94996e2f9fb1d7858c00af951154f14c1e7d1b347b0ccf3e0580de', 294, 294, null, 649, null, null, false, 1),
  ('0c986f23-bba7-5e61-a548-f7669456d660', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88P', 'Railway Equipment Repairer (USAR only)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinates performing their duties. Inspect railway cars prior and subsequent to maintenance. Perform initial terminal airbrake tests for outbound trains. Repairs draft gears. Supervise a team salvaging cars or rehabilitating captured enemy rolling stock. Enforce safety practices.', '73d375eb8d9d5bddee582d21aedb06577ec273241fd3f56566a1fb588a7ba617', 294, 294, null, 650, null, null, false, 2),
  ('bb49abe1-3aa4-58b8-ba05-c04ae7ed6fab', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88P', 'Railway Equipment Repairer (USAR only)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Calculate supplies, parts, and equipment necessary to restore locomotives and cars to efficient operating condition. Supervise personnel in methods and techniques of repair to mechanical components of locomotives. Set work accomplishment priorities and enforces shop safety practices. Perform initial and final inspection of locomotives and cars scheduled for maintenance. Resolves technical problems encountered in locomotive and railway car maintenance.', '4b74a5da0b3839a2f5493c93b232c02a4fd584d05ec6d8ec664e8eec81713bdf', 294, 294, null, 651, null, null, false, 3),
  ('ab8f6c38-e074-5bcb-afde-7eff1e8bb45a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88P', 'Railway Equipment Repairer (USAR only)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform final inspections of locomotives and rolling stock. Determines shop priorities based on guidance from train movements section and resource availability. Posts and maintains equipment status reports.', 'f36a1045b387c82265d06e9ecd2397cfa527f8ff9f8c3a4f53dca3f7b76a5a45', 294, 294, null, 652, null, null, false, 4),
  ('d53d33db-9176-551b-9fd4-0222a733929d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88U', 'Railway Specialist (USAR only)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Railway Specialist provides rail network capability and infrastructure assessments. Performs and assists with rail planning. Coordinates the use of Host nation or contracted rail assets. Performs Contracting Officer’s Representative (COR) duties to oversee contracts.', 'ce72ba4fd7fb7f318658f798fb24bb84ce434d30cb58dd0810d04c64913a54d5', 295, 295, null, 653, null, null, false, null),
  ('537c30e2-2c77-5c44-abef-3cc6493480c5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88U', 'Railway Specialist (USAR only)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Interprets train orders. Oversees the execution of instructions received from signal towers, switches, other trains and trainmen. Oversees car coupling and uncoupling operations. Inspects cars at route stops; to include lashing and bracing to ensure safe hauling of cargo. Advises dispatcher of arrival and departure times for all passing trains. Ensures locations of all rolling stock are recorded. Ensures cars are seals cars seal numbers are recorded.', '6c97828ae36d84f26d6fb0c72bc0e6c565333ac7095a44191f6747bec0ec45a3', 295, 295, null, 654, null, null, false, 1),
  ('bc5a9eea-df21-5be5-9b3a-edff47362864', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88U', 'Railway Specialist (USAR only)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and provides technical guidance to subordinates, contractors, and Host nation personnel performing their rail related duties. Supervise operation of the locomotive''s controls and safety appliances. Observes and interprets instructions received from signal towers, switches, other trains and trainmen. Coordinates train movements; ensures compliance with operating timetables, rule book, and other specific instructions. Ensures performance delay and locomotive reports for each trip are completed and necessary corrections are made.', 'eb99ed9c27afc72de0c34772615d958debee44ace7ad7f1d07dc7a3f8130ae9c', 295, 295, null, 655, null, null, false, 2),
  ('2b5ca879-0ce6-5162-bffe-0ee1edb7eb31', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88U', 'Railway Specialist (USAR only)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Advises and assist in the effective management of railway systems. Inspects and validates track structure and roadway. Supervises handling, classification and switching of cars and trains in railway yards; evaluates records of daily movement of cars. Review written and transmitted train orders; keeps subordinates, contractors, and/or HN personnel informed of changes in road/rail conditions and schedules and prioritization changes. Review operation and inspection reports. Investigates train schedule delays and recommends corrective action.', 'bdad41dae823b375518255320f8c6ac85dcb2e0c79c29c9c2bf709f2958051cc', 295, 295, null, 656, null, null, false, 3),
  ('8c8c260e-f3be-59b0-99fe-893bd93daa48', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88U', 'Railway Specialist (USAR only)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Conduct rail network capability and infrastructure assessment, rail safety assessments, and uses assessments to inform and advise the commanders on the employment of rail in a theater of operations. Establishes liaison with using agencies and representatives of civilian and military railroads. Manages personnel engaged in railway operations. Supervise receipt and transmission of telephonic and telegraphed messages relating to train movements. Review time sheets to keep abreast of each scheduled train passing through territory. Investigates accidents and unusual operating incidents and recommends corrective action. Assist in providing staff supervision of subordinate unit, contracted, or host nation railway operating activities. Evaluate host nation/contractor railway safety programs.', 'd3d2ae181af39f7776b79a1007c73e2a043c94305029d33673406c76ac4ceedd', 295, 295, null, 657, null, null, false, 4),
  ('0aa9e067-1ec1-555d-bbc9-b324755584c4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '88Z', 'Transportation Senior Sergeant (Transportation Sr SGT)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The transportation senior sergeant supervises the operation and control of movement for personnel and cargo by air, rail, motor transport and water, maintenance-of-way, maintenance of equipment and technical expert on all matters relating to railway operations. Manages and coordinates the operation and maintenance of Army watercraft and maintains records of strength, location and employment of railway personnel and equipment. Provide direct assistance and advice related to Host Nation (HN) rail infrastructure and the employment of HN assets in support of nation building and military operations; coordinates and communicate with the HN, supported unit, or contracted entity to facilitate rail operations. Serves as the principal NCO associated with SQI M in transportation companies. Assist in the coordination and implementation of operations, administration, training programs and communications activities. Account for location, employment and deployment of organic operating equipment and maintenance activities. Plans and lays out a maintenance shop and facilities. Coordinate transportation actions with subordinate and serviced activities. Consolidates, prepares, reviews and processes regular and special reports of command transportation and watercraft activities. Plans, manages, and monitors unit motor transport operations as the senior truckmaster. Establishes and organizes the unit motor park. Prepares and implements the truck company security and defense plan. Prepares map overlays. Receives and prepares highway reconnaissance data for motor convoy transport. Supervises and directs unit dispatching of vehicles. Coordinates engineer requirements to support a truck battalion.', '9fadd28b3a9d14a626a7db6a727a187a07a3f28d696b8fdb8bf069115ed394d6', 297, 297, null, 658, null, null, false, null),
  ('34e1435f-3dd6-571f-810f-bc168bae059a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89A', 'Ammunition Stock Control and Accounting Specialist (Ammo Stk Con/Acctg Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The ammunition stock control and accounting specialist operates the Standard Ammunition and Accounting System (SAAS) computer hardware and software/utilities manual records to perform stock control and accounting procedures.', '3bd77a6f89d922f976445d7b22cef8cd5fa5ac04bf17d971ac48d05d9cc00fa6', 298, 298, null, 659, '2025-04-01', null, false, null),
  ('59a2645c-aacf-5ff4-ba36-3dfe73679da0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89A', 'Ammunition Stock Control and Accounting Specialist (Ammo Stk Con/Acctg Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform ammunition supply stock control and accounting duties using both automated and manual procedures. Maintain hardware and software/utilities to perform stock control and accounting procedures.', '6c06215b74c5cbb5f9b7b6ec84b816b87e7c1d4636726412aa0b9b6a28655649', 298, 298, null, 660, '2025-04-01', null, false, 1),
  ('fbed446c-cd1e-5073-be6a-2bbe379187dd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89A', 'Ammunition Stock Control and Accounting Specialist (Ammo Stk Con/Acctg Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill level, supervises junior grade Soldiers, and provides technical guidance to the Soldiers in the accomplishment of their duties.', '7032cb8785d4d169490a5079703852380e78aab092b6c68151c754ed1381589f', 298, 298, null, 661, '2025-04-01', null, true, 2),
  ('0dfd55fd-d8e3-5df7-847c-4d3e0dc8ab73', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89B', 'Ammunition Specialist (Ammo Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The ammunition specialist receives, stores and issues conventional ammunition, guided missiles, large rockets and other ammunition related items; performs maintenance, modification, destruction and demilitarization on ammunition and explosive components.', '4595b2a123c64e81a63743a84e511f1565ac4801024aa2c0be1ea712f95ef178', 299, 299, null, 662, '2025-04-01', null, false, null),
  ('a32100c3-7c77-5f5a-8eb3-190fafff1b22', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89B', 'Ammunition Specialist (Ammo Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assist in receipt, storage, issue, maintenance, modification, destruction and demilitarization of explosive items. Operate MHE to maneuver ammunition.', '440963bb5da7d829ad596ed8494370575ec755985722c4d006dc4957b66abf61', 299, 299, null, 663, '2025-04-01', null, false, 1),
  ('1cca19cd-1716-5053-8c7e-644fdbbc5080', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89B', 'Ammunition Specialist (Ammo Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Assist in the preparation of transportation of ammunition, ammunition components and explosives.', '14f0fb12baf513ace4b5d276158714f9260df2899096fb0f3e9317de77f98c9b', 299, 299, null, 664, '2025-04-01', null, true, 2),
  ('9df1b2ff-db3b-5440-a8a1-f038b49c171d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89B', 'Ammunition Specialist (Ammo Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in the preceding skill levels, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Prepares/reviews ammunition storage waivers. Prepare complex ammunition malfunction reports. Ensures ammunition quality assurance/quality control procedures are followed.', 'bd5aba963b9942f006a33865c75e7d7614e3caf24fc88eab2be591d4fef15572', 299, 299, null, 665, '2025-04-01', null, true, 3),
  ('85c8930e-3258-549d-b9c1-30e91cc12210', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89B', 'Ammunition Specialist (Ammo Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Interprets technical data and instructs subordinates in the technical aspects of ammunition, missile and other explosive items receipt, storage, maintenance and supply. Technical advisor on ammunition surveillance and safety matters.', '45dca3137a6a5689af023af504e3fd2b6bdbe1245d6a90f696ad45756ee26e42', 299, 299, null, 666, '2025-04-01', null, true, 4),
  ('eb25f996-72d2-5065-a916-00c9ff760609', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89B', 'Ammunition Specialist (Ammo Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Supervises and manages the SAAS-MOD at Theater Sustainment Command Distribution Management Centers (TSC DMC), Expeditionary Sustainment Command Distribution Management Centers (ESC DMC), Ammunition Supply Activities at the Sustainment Brigade and TSC levels, Brigade Ammunition Office (BAO) and Ammunition Transfer Holding Points (ATHP). Assists in the survey and layout of areas allocated for the establishment of ammunition storage areas. Plans requirements for labor, equipment and supplies in preparation and application of plans, work policies and procedures.', '8975867d4144b35baea73b5e6bf9d5c7171dc053a1f4de17989fb12bd30c0dfd', 299, 299, null, 667, '2025-04-01', null, true, 5),
  ('b53715ed-0159-572c-ac78-0f42e63cc934', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89B', 'Ammunition Specialist (Ammo Sp)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels. Responsible for advising echelons above brigade on strategic munitions sustainment related issues. Operates as a liaison, ensuring mutual understanding, and the direct link to commanding general in the Army Field Support Battalion. Logistical advisor on plans, policies, and training of munitions and deployment operations.', 'f8e1e699ff32c448b55419fcac317e8ddeb20f2a6c679662f80c458ff392fddd', 299, 299, null, 668, '2025-04-01', null, true, 6),
  ('ed045555-6cb6-542f-b57b-759bc581bb25', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89D', 'Explosive Ordnance Disposal (EOD) Specialist (EOD Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Locates, identifies, renders safe and disposes of foreign and domestic conventional, biological, chemical, or nuclear ordnance and improvised explosive devices (IED); weapons of mass destruction and large vehicle bombs; conducts intelligence gathering operations of first seen foreign ordnance; supports VIP missions for the U.S. Secret Service, State Department and other Federal agencies.', '073778874bc7c9fb88bdc44a3627567cc2fdeab4ded9bc4abd9a021abd53f58e', 300, 300, null, 669, null, null, false, null),
  ('1d63a1da-7177-553d-92f6-8fba391f7a9a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89D', 'Explosive Ordnance Disposal (EOD) Specialist (EOD Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', '(Personnel Only for Active Component and USARNG). MOS used to identify Soldiers accessed into MOS 89D prior to obtaining rank of SGT.', 'e6cfc0188b7008e63d13dc82e5a40867de9e6fdae289a59f9ddebc8e743b58f2', 300, 300, null, 670, null, null, false, 1),
  ('b36b4352-ddb7-5392-bf57-a94d17c17c6b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89D', 'Explosive Ordnance Disposal (EOD) Specialist (EOD Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in the preceding grade level. Supervises and provides technical guidance to less experienced Soldiers. Prepares and maintains Explosive Ordnance Disposal (EOD) tools and equipment; employs and operates the EOD Mobile Field Kit; identifies commercial, military, and homemade explosives; prepares and employs demolition materials to conduct disposal operations, to include electric and non-electric firing systems, explosive charges, and associated firing devices; employs non-render safe procedure EOD tools and equipment; performs low-order procedures on unexploded ordnance; stores and transports hazardous materials (includes but not limited to Class V); employs and maintains protective clothing ensembles and detection equipment required for chemical, biological, radiological, and hazardous material environments; performs leak, seal, and package procedures for chemical and biological ordnance; employs EOD tools and equipment to locate, access, and recover buried unexploded ordnance; prepares, maintains, and employs EOD robotic systems and radiographic equipment; performs collection on forensic and explosive materials; assists Team Leader during Very Important Persons Protection Support Activities.', '19d5ce155a5a336240e7331abad8527496a6b640b7ac9a75a45cd6310c8e7328', 300, 300, null, 671, null, null, true, 2),
  ('2166d65f-6036-52f2-bbe3-fa19b2e25f1d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89D', 'Explosive Ordnance Disposal (EOD) Specialist (EOD Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs all duties of the 89D10/20; leads an Explosive Ordnance Disposal team; plans and directs disposal operations; conducts reconnaissance on unexploded ordnance and improvised explosive devices; employs render safe procedure EOD tools and equipment; formulates and performs render safe procedures on conventional, chemical, biological, radiological, and nuclear unexploded ordnance; formulates and performs render safe procedures for improvised explosive devices; performs technical intelligence procedures on first seen unexploded ordnance and improvised explosive devices; prepares and submits EOD reports (includes but not limited to technical intelligence reports, incident reports, and storyboards); conducts attack scene investigation to include crater and fragmentation analysis; performs Very Important Persons Protection Support Activities.', '4023ef2ccca46f3256a05fa2f8b923326d9851f84166c6649b4bed93504385d7', 300, 300, null, 672, null, null, false, 3),
  ('37ac3867-aca7-5ed9-a776-a98c556433bb', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89D', 'Explosive Ordnance Disposal (EOD) Specialist (EOD Sp)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs all duties of the 89D10/20/30; develops Explosive Ordnance Disposal (EOD) response plans; coordinates technical intelligence activities for EOD units; provides explosive vulnerability assessments to Department of Defense installations and organizations; establishes ammunition holding areas for EOD units; integrates EOD support into organizational through strategic level organizations; manages ammunition and explosives for EOD units; coordinates logistical support for EOD teams; serves as the subject matter expert on EOD operations and procedures during staff operations as well as all explosive safety related incidents and issues; serves as duty officer for high profile EOD incidents both on and off installation.', 'b608722312945d75aacb30476e7ef0af0ef68fb388a621c00ce3e874e13a6660', 300, 300, null, 673, null, null, false, 4),
  ('425a2cd5-cfee-5076-88bc-1563324a0e33', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89D', 'Explosive Ordnance Disposal (EOD) Specialist (EOD Sp)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in the preceding grade levels. Responsible for maintaining continuity of all unit operations and movements. Supervises coordination and deployment of EOD response teams over a wide geographical area. Supervises establishment and maintenance of situation maps, journals and technical intelligence reports. Technical advisor at staff levels. Supervises CONUS operations that support VIP missions for the U.S. Secret Service, State Department and other Federal agencies. Implements orders, policies and procedures. Performs personnel management operations at brigade/battalion level for assigned personnel.', 'db1d3e38b953f2b7cf0f1873e76f5086805e8756c9439c6a6f0aa13ba726f73b', 300, 300, null, 674, null, null, true, 5),
  ('8c0ec2f8-3732-5e05-9531-a8cd8aefa9e9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '89D', 'Explosive Ordnance Disposal (EOD) Specialist (EOD Sp)', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Advises the commander and staff on all matters pertaining to enlisted personnel; Enforces the implementation of established policies and standards as they pertain to enlisted personnel within the command; Provides counsel and guidance to the NCOs and other enlisted Soldiers of the command; manages the daily activities and operations of the unit.', 'fc89b579fc50b054d60338266792956936b1f30d19d9adfdb009d115c395f9e6', 300, 300, null, 675, null, null, false, 6),
  ('1bec9a1c-aa4b-551e-813d-9da8bb147748', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91A', 'M1 Abrams Tank System Maintainer (M1 Abrams Tank Sys Maint)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The M1 Abrams tank system maintainer supervises and performs field maintenance.', 'ba6a7443ff6dec5f1102984de58261683fb6ffef374e2700c94fa7a2a7d9991f', 302, 302, null, 676, '2025-10-01', null, false, null),
  ('5320337d-0dcd-594c-807a-1b3af82f779c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91A', 'M1 Abrams Tank System Maintainer (M1 Abrams Tank Sys Maint)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Diagnoses and troubleshoots malfunctions, performs field maintenance tasks on the suspension systems, steering systems, hydraulic systems, auxiliary power units, fire extinguisher/suppression systems, gas particulate systems, vehicular mounted armament, gun turret drive system and the fire control system on the M1 tank.', '801d6e15130f1323bf2d3b2690e6a9b1d5ec4e20aabf7518cadef046275db9e7', 302, 302, null, 677, '2025-10-01', null, false, 1),
  ('7754ab4d-f90b-546e-b020-26e20ea105ab', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91A', 'M1 Abrams Tank System Maintainer (M1 Abrams Tank Sys Maint)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Diagnoses and corrects malfunctions of various subsystems. Assist skill level 1 Soldiers with troubleshooting and maintenance tasks on the M1 tank.', 'c35a14bae6f7726f9924b00a244e59b7509704ad0f93d70cdd8cea2995caee92', 302, 302, null, 678, '2025-10-01', null, true, 2),
  ('06e7e2c2-bed5-5d45-8019-b2275a610b87', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91A', 'M1 Abrams Tank System Maintainer (M1 Abrams Tank Sys Maint)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises skill level 1 and 2 Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties, supervises recovery operations and performs battlefield damage assessment and repair (BDAR) on all systems.', '56700e45f249a429f7815896d63bde0df43466b03404e2fb755b2bfd7e815c31', 302, 302, null, 679, '2025-10-01', null, true, 3),
  ('e71e809e-f644-5e7b-9776-5052c3b4a018', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91A', 'M1 Abrams Tank System Maintainer (M1 Abrams Tank Sys Maint)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises skill level 1 through 3 Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Supervise the inspection and troubleshooting of M1 Abrams automotive and armament systems.', 'd5c1173bf8cb6b8102d8b7c1f5c5f38f64ad24d09d0d189ba6b1424493fe8755', 302, 302, null, 680, '2025-10-01', null, true, 4),
  ('d4275269-4334-5ac2-9d4d-ab1c3d6a3e69', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91B', 'Wheeled Vehicle Mechanic', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The wheeled vehicle mechanic supervises and performs field level maintenance and recovery operations on light and heavy wheeled vehicles, their associated trailers and material handling equipment (MHE).', '105437da08948f4b69fb5f86925778ceb8986ef49a4e0d3bbccab8449905928f', 303, 303, null, 681, '2024-06-01', null, false, null),
  ('9a463108-8f71-50b8-abe6-33500abda763', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91B', 'Wheeled Vehicle Mechanic', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Maintains wheeled vehicles, their associated trailers and MHE systems to include: use of applicable references, inspecting, servicing, maintaining, repairing, replacement, adjusting and testing of wheeled vehicles and MHE systems, subsystems and components such as: power plant/packs, compression ignition engines and engine fuel systems, air induction and exhaust systems and cooling systems. Vehicle chassis and powertrain components including, frame cross members, clutches assemblies, transmissions, transfers, final drives, propeller shaft assemblies, brake systems, steering systems, suspensions systems, fifth wheel assemblies, wheeled vehicle crane, hoist and winch assemblies, and hydraulic systems. Automotive electrical systems including wiring harness, starting and charging systems. Perform wheeled vehicle recovery operations.', '3758f101acdc4c40a4a8d2e63925e94db13c6f6982894e2fed2b241ebc60da97', 303, 303, null, 682, '2024-06-01', null, false, 1),
  ('70f7dfda-9329-56c3-9d79-61946fce3ca5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91B', 'Wheeled Vehicle Mechanic', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties assigned in preceding skill level, supervises and provides technical guidance to junior grade Soldiers in the accomplishment of their duties. Conduct in-process inspection/troubleshooting procedures, during repairs and overhaul of engines, transmissions and power train major assemblies and components, hydraulic system and fuel system components. Supervise recovery team performance of wheeled vehicle recovery operations.', 'cce7c26aa6029b964919954f86a19ec4dfa69f185fc482c2f258f7e97a9c3943', 303, 303, null, 683, '2024-06-01', null, true, 2),
  ('91c96018-e6d8-5eac-9e2c-638c185066ce', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91B', 'Wheeled Vehicle Mechanic', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties assigned in preceding skill level, supervises and provides technical guidance to junior grade Soldiers in the accomplishment of their duties. Supervise compliance with shop safety program and use, maintenance and security of hand and shop power tools. Supervises and performs diagnostic troubleshooting to determine maintenance repair criteria using Test Measurement Diagnostic Equipment (TMDE). Performs equipment classification inspections and annotate and submit appropriate forms and documents. Supervise wheeled vehicle recovery operations. Perform battlefield damage and assessment and repair (BDAR).', '057318e38ff74b993258d7e4e880094b0d1268a897ad82566aac12acce49c3a3', 303, 303, null, 684, '2024-06-01', null, true, 3),
  ('58f038fd-1e46-5472-b40e-8ff9ac5351fc', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91C', 'Utilities Equipment Repairer (Util Equip Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The utilities equipment repairer supervises and performs field level maintenance on utilities equipment and special purpose support systems.', '4c93057bb085c1ce80699b69621630044af62d184e57100070c424cc212b9c12', 305, 305, null, 685, '2024-06-01', null, false, null),
  ('50fb25d1-d7b5-56dc-b24f-7a68651f6d1a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91C', 'Utilities Equipment Repairer (Util Equip Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Maintains (inspects, repairs, tests and adjusts) air conditioner electrical systems, air conditioner vapor systems, refrigeration unit electrical systems, portable heater fuel/electrical systems, fire extinguisher rechargers and fire extinguishers/valves.', '2a2cd5dd452d6d42e9376352a73d587b3a3298f7fb0933ba58d3111b7c25a74d', 305, 305, null, 686, '2024-06-01', null, false, 1),
  ('91fb347c-6a5d-59dd-ac93-e369ecbd9907', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91C', 'Utilities Equipment Repairer (Util Equip Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill level, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties.', 'b5a7dd8b2860631bf778d0d9adec403a793f5dce7e4025f15ace0912b5377f46', 305, 305, null, 687, '2024-06-01', null, true, 2),
  ('d2d4ad4b-2b8a-5fce-9e2d-8a3440812c7f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91C', 'Utilities Equipment Repairer (Util Equip Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill levels, perform quartermaster and chemical equipment repairer (MOS 91J) duties, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Inspects and troubleshoots petroleum, oil and lubrication equipment, smoke generators, laundry and bath units, chemical equipment, water purification equipment systems, portable forced air heaters, air conditioner units, refrigeration units and fire extinguisher recharger. Perform maintenance management activities, including production and quality control.', 'c0d7da94d61cb7be83ab2ffa7aba0db57a8ee8dc2592cca08ecca530201d58f7', 305, 305, null, 688, '2024-06-01', null, true, 3),
  ('da43bf34-ecde-57d8-a2ba-127bc4489388', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91D', 'Tactical Power Generation Specialist (Tac Pwr Gen Spec)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Tactical Power Generation Specialist supervises operation and performs field level maintenance functions, including overhaul, but not rebuild of power generation equipment, internal combustion engines and associated equipment from 0.5KW to 500KW (except for turbine engine driven generators).', '7f9788b34bd2e5abcc767761da071070ad6f5e42f724c5f87ebc2e026d711846', 306, 306, null, 689, '2024-06-01', null, false, null),
  ('a338064e-9fc8-5a60-bd13-af956aaff2fd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91D', 'Tactical Power Generation Specialist (Tac Pwr Gen Spec)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform field level maintenance on tactical power generation sets, power distribution systems, and internal combustion engines and associated items of equipment. Assists operators in proper employment of tactical power generation equipment.', '6df9ed409571275feb5462f0d6242be68b81ab5c84dbc9b40d52c9d24da9ab7e', 306, 306, null, 690, '2024-06-01', null, false, 1),
  ('f5538fd9-19db-51ef-ad5f-d5184646f2a0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91D', 'Tactical Power Generation Specialist (Tac Pwr Gen Spec)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill level, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Repairs/overhauls starters, alternators, generators, fuel injectors, voltage regulators, switches, control circuits, etc. Perform duties as unit power planner. Determine proper generator selection to efficiently meet power demands. Train operators in the proper maintenance and employment of tactical power generation and power distribution systems.', '12b0cd5b7e7f6385dfe7a1f89439be24f08a2139234a5ca0f8041ef40a49c4be', 306, 306, null, 691, '2024-06-01', null, true, 2),
  ('9f497ef9-4987-5d3a-95c9-20f564e070e6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91D', 'Tactical Power Generation Specialist (Tac Pwr Gen Spec)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill levels, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Supervise activities of a section performing field maintenance on tactical power generation sets, power distribution systems, and internal combustion engines and associated equipment. Apply maintenance management and quality control including production and quality control in maintenance activities. Perform duties as tactical power planner. Complete power assessments and tactical power grid designs to achieve proper operating efficiencies. Advises unit staff personnel on how best to employ tactical power generation and power distribution equipment to best meet unit power requirements.', '5ba013d56b13e9a58f327733b53facd57dfc4f06b60cdf852d36a3471ba883d0', 306, 306, null, 692, '2024-06-01', null, true, 3),
  ('da6acc29-87ee-51a3-9df1-9950f4ccba5c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91E', 'Allied Trades Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The allied trades’ specialist supervises and performs the fabrication, repair and modifications of metallic and nonmetallic parts and supervises metalworking shop activities.', 'e02919813f0b4c75fcea24fc83d5b63797cc9d71cebc41610c5ac06b47599551', 307, 307, null, 693, null, null, false, null),
  ('1a9b989c-5c7f-5a4b-b51b-936cb4044a47', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91E', 'Allied Trades Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Fabricate, repair and modify metallic and nonmetallic parts, utilizing such machines as engine lathes, utility grinders, power cutoff saws, armature under cutters, arbor and hydraulic presses, drill presses, oxyacetylene, electric arc, inert gas welding machines and their associated attachments, accessories and tools.', '2ad46e2b942c1ceec8112590b800b89912106ee5825c85f3c46717e8c15ba12b', 307, 307, null, 694, null, null, false, 1),
  ('239f886f-6de4-5b49-b162-bf818212c8ac', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91E', 'Allied Trades Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill level, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties.', 'b5a7dd8b2860631bf778d0d9adec403a793f5dce7e4025f15ace0912b5377f46', 307, 307, null, 695, null, null, true, 2),
  ('8004e21a-90a7-5652-a20c-e92333bf202e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91E', 'Allied Trades Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill levels, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Supervises recovery operations and inspects completed work.', '93c530b38b4275932fbee01e1b5bc614c59648fa810902c43e606ee69a88d065', 307, 307, null, 696, null, null, true, 3),
  ('09f7c89e-3557-575f-b73e-aff98455ee75', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91F', 'Small Arms/Towed Artillery Repairer (Small Arms/Towed Arty Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Small Arms/Towed Artillery Repairer performs field level maintenance and repairs on small arms and other infantry weapons and towed artillery.', '3ea2e750efd146083be51dff456ad49ce754aa7eb16418f19d5b5572dcc2a956', 308, 308, null, 697, '2024-06-01', null, false, null),
  ('b397cd3b-1bbf-5187-8d59-1547422960d2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91F', 'Small Arms/Towed Artillery Repairer (Small Arms/Towed Arty Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform field level maintenance on small arms and other infantry weapons and towed artillery. Performs field level maintenance on periscopes, telescopes, commander’s weapon station/auxiliary sights, aiming circles, image transfer assemblies, quadrants, mount assemblies, fire control support equipment, and test, measurement, and diagnostic equipment (TMDE). Performs battlefield damage assessment and repair (BDAR).', '5950edd3e61848309e58cc7d66aabe5637de8cedf0eecd234cd9a62e02fde5b4', 308, 308, null, 698, '2024-06-01', null, false, 1),
  ('7b519e07-3e1c-5d4e-9e39-9f032ebe311a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91F', 'Small Arms/Towed Artillery Repairer (Small Arms/Towed Arty Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill level, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Diagnoses and troubleshoots malfunctions of small arms and other infantry weapons and towed artillery.', '6dd3407aea0f14ff68a16c9cda13f2ae1a38c1a1963f1616e942051635bc5a2d', 308, 308, null, 699, '2024-06-01', null, true, 2),
  ('2f4a85bd-c569-5206-ac2f-d4d03c411f49', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91F', 'Small Arms/Towed Artillery Repairer (Small Arms/Towed Arty Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels. Supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Inspects and troubleshoots fire control system components, towed artillery fire control systems, self-propelled artillery fire control systems, tank fire control systems, small arms, other infantry weapons and towed artillery. Classifies equipment for disposal IAW Army regulations.', '7e9e9641093ba2db9393b194bcc4edfb0363994c86926d998cf4bd8de6fc010c', 308, 308, null, 700, '2024-06-01', null, true, 3),
  ('c2757456-98b3-53cd-804b-463e93da0eab', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91H', 'Tracked Vehicle Repairer (Tracked Veh Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The tracked vehicle repairer supervises and performs field level maintenance on tracked vehicles (other than the M1, M2, and M109 family of vehicles).', 'ee39562bb0bb624f0ed84bc789e7e6942a127f48f57c06cd5c30074e14531d28', 309, 309, null, 701, '2024-06-01', null, false, null),
  ('5c2b0348-4f46-5eae-9c37-c715701911ad', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91H', 'Tracked Vehicle Repairer (Tracked Veh Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs repair of diesel power plants/packs, compression ignition engine fuel systems, compression ignition air induction systems, vehicle air cooling systems, vehicle liquid cooling systems, tracked hull electrical systems, automatic transmission assemblies, tracked vehicle cross drive transmission assemblies, transfer assemblies, hydraulic brake systems, mechanical/hydraulic steering systems, tracked vehicle hydraulic assemblies, fire extinguisher/suppression systems. Repair tracked vehicle using battlefield damage assessment and repair (BDAR).', '63bcc00b770357cc5c397af7cd1dedda2e0e11b70386ebe4f168456a552613a3', 309, 309, null, 702, '2024-06-01', null, false, 1),
  ('48e01da2-0fc2-549b-b495-44f483c7eba7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91H', 'Tracked Vehicle Repairer (Tracked Veh Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties.', '1e8ad6c76f182d02a52d6db8eacb943853dd371f9bfe8a556f4a463d57ca1a3a', 309, 309, null, 703, '2024-06-01', null, true, 2),
  ('a45a70d4-4375-539b-a52b-869ab329db70', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91H', 'Tracked Vehicle Repairer (Tracked Veh Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises junior grade Soldiers, and provides technical guidance to the Soldiers in the accomplishment of their duties. Supervise the repair of fuel systems, fuel system components, electrical systems, electrical system components, diesel engines, cooling systems, transmissions, brake systems, steering systems, hydraulic systems, and auxiliary drives. Inspects and troubleshoots tracked vehicle automotive systems and classifies equipment.', '98bbf3cff57b78bceef25cee0c549a40773214d4c521551c9435581519e725ae', 309, 309, null, 704, '2024-06-01', null, true, 3),
  ('29350062-f322-5471-b34e-0bc4b5bbe81e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91J', 'Quartermaster and Chemical Equipment Repairer (QM & Chem Equip Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The quartermaster and chemical equipment repairer supervises or performs field level maintenance on chemical equipment, quartermaster machinery, forced air-heaters, and special purpose equipment.', '820614e48f8c9e82745e19046163f7a5d721cb1fbefc974769a66ea234eccbd6', 310, 310, null, 705, '2025-10-01', null, false, null),
  ('26a3baf7-8b00-571e-bd41-f27190f3a659', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91J', 'Quartermaster and Chemical Equipment Repairer (QM & Chem Equip Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Maintains and repairs electrical/fuel heater systems, liquid pumps and pumping systems, tactical and lightweight reverse osmosis water purification systems, decontamination systems, protective filter systems, smoke generator systems and laundry systems. Maintain internal combustion engine ignition/fuel/cooling/electrical systems. Perform battlefield damage assessment and repair (BDAR).', 'faa6e657eef2daa33c3a72de61d95529cebab38efe99d9cd8c1515392500ff26', 310, 310, null, 706, '2025-10-01', null, false, 1),
  ('bae8fd49-279d-5c08-ba23-13ae0efc7ce4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91J', 'Quartermaster and Chemical Equipment Repairer (QM & Chem Equip Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties.', '1e8ad6c76f182d02a52d6db8eacb943853dd371f9bfe8a556f4a463d57ca1a3a', 310, 310, null, 707, '2025-10-01', null, true, 2),
  ('33a13a2c-515e-5141-a643-1ec0fe40efb3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91L', 'Construction Equipment Repairer (Const Equip Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The construction equipment repairer supervises and performs field level maintenance on construction equipment which includes that used for earthmoving, grading, and compaction; lifting and loading; quarrying and rock crushing; asphalt and concrete mixing, and surfacing; water pumping; air compression and pneumatic tools; and powered bridging.', 'fa881440bb59057cd0012fce48b6c1fd9a6d3fc4b8a15dee7c42d1959aecafe0', 311, 311, null, 708, '2024-06-01', null, false, null),
  ('10f01dc4-1282-51a3-9e4c-18279ff5c6f4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91L', 'Construction Equipment Repairer (Const Equip Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Maintains and replaces brake actuators, batteries, starter motors, alternators, mechanical fuel pumps, hydraulic cylinders/pumps/control valves, drive shafts, universal joints, service brake shoes, disc-brake pads, water pumps, turbochargers, cylinder heads, high-pressure fuel injection pumps, wheel bearings/seals, steering unit torque link and road wheels. Adjust engine speed governor/valves, carburetors, boom-hoist brakes/clutches, dry-disc clutches, steering brakes, track tension/assemblies, fuel injector racks and steering unit brake levers. Charges suspension accumulators, transmission shift accumulators and main hydraulic accumulators.', '8bc19bc019f416c5c0996cc00688953d39f457d2038a68b734f55ac80e09c313', 311, 311, null, 709, '2024-06-01', null, false, 1),
  ('b96e269e-c75c-59ba-b94c-7f2e529acbf7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91L', 'Construction Equipment Repairer (Const Equip Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Troubleshoots, repairs and overhauls engines, final drives, power trains, hydraulic systems, and fuel system components. Performs welding and cutting to accomplish repairs.', '84d84d562f58f73942ebaffe22d70619ef0f94dec18296ae082014ce9fe4e7dc', 311, 311, null, 710, '2024-06-01', null, true, 2),
  ('1dc0a5d9-3a2f-57f2-9711-02078a0d21ec', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91L', 'Construction Equipment Repairer (Const Equip Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Supervise and inspect maintenance of construction, powered bridging and associated equipment. Perform troubleshooting of engines, power trains, fuel and electrical systems, hydraulic systems, earth-moving components and pneumatic equipment.', 'f5482ecd587e40068b342545da610997cb4d4a81407ef21f075806dfa01dd1f6', 311, 311, null, 711, '2024-06-01', null, true, 3),
  ('8260eaa9-c029-53a8-b3e2-f40b7cc9d5b5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91M', 'Bradley Fighting Vehicle System Maintainer (BFVS Maint)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Bradley fighting vehicle system maintainer supervises and performs field level maintenance tasks i.e., major assembly and LRU replacement on the M2/M3 A1/A2 series Bradley fighting vehicle (BFV), and M7 Bradley Fighting Infantry Support Team (BFIST) (hull and turret).', '1f714692bea96c4eb9ce12ce20b23e26d710ef669be848b9da084094fa29b94c', 313, 313, null, 712, '2025-10-01', null, false, null),
  ('8fba733b-dcf2-5170-ae17-aab1325cc73c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91M', 'Bradley Fighting Vehicle System Maintainer (BFVS Maint)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Diagnoses and troubleshoots malfunctions and performs field level maintenance on the Bradley Fighting Vehicle suspension systems, steering systems, fire extinguisher/suppression systems, gas particulate systems, vehicular mounted armament, and associated fire control systems.', 'ebffb1a545db06e232f19700b2ec8e95cd4c838d33fc030fbc4bc1e53dc24974', 313, 313, null, 713, '2025-10-01', null, false, 1),
  ('23066a4d-0f62-5c83-990f-15d8b98a6ae9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91M', 'Bradley Fighting Vehicle System Maintainer (BFVS Maint)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Diagnoses and corrects malfunctions of various subsystems, performs field level maintenance i.e., major assembly replacement. Assist skill level one Soldiers with troubleshooting and maintenance tasks.', '6b119b483ac4dcdde105f0ffb0cc675a3226b938cd8d3b3d7bbbe2e24abb59df', 313, 313, null, 714, '2025-10-01', null, true, 2),
  ('0c0e2217-f54f-5cee-80e8-ffcddbce2d66', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91M', 'Bradley Fighting Vehicle System Maintainer (BFVS Maint)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises skill level 1 and 2 Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties, supervises recovery operations and performs BDAR on all systems.', '8ba4bd02526bf831089189be385640160a9f5c4db29331d402c72f4f88cac34f', 313, 313, null, 715, '2025-10-01', null, true, 3),
  ('d3e4db57-352c-5a5a-9465-3e6bdfdc5095', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91M', 'Bradley Fighting Vehicle System Maintainer (BFVS Maint)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Supervise the inspection and troubleshooting on Bradley Fighting Vehicle automotive and armament systems.', '05a6c85c65f3256c2678d0d939388e6beb3bc0936cb5d88fc74c043bd9e1b72b', 313, 313, null, 716, '2025-10-01', null, true, 4),
  ('fa4ac909-00ad-5854-bde2-5cc597991542', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91P', 'Self-Propelled Artillery Systems Mechanic (Self-Prop Arty Sys Mech)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The self-propelled artillery systems mechanic supervises and performs field level maintenance and recovery of all self-propelled field artillery cannon weapon systems, including automotive, turret, carriage-mounted armament, associated fire control systems, and chemical protection subsystems thereof.', '8235dd7331addbe51be333f45c441b7126d0958057641ae39991ab29222b17ee', 314, 314, null, 717, '2025-10-01', null, false, null),
  ('84836353-585c-50b2-9683-f46563a3b3a8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91P', 'Self-Propelled Artillery Systems Mechanic (Self-Prop Arty Sys Mech)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The self-propelled artillery systems mechanic supervises and performs field level maintenance and recovery of all self-propelled field artillery cannon weapon systems, including automotive, turret, carriage-mounted armament, associated fire control systems, and chemical protection subsystems thereof. Duties for MOS 91P at each skill level performs field maintenance on automotive, turret, carriage-mounted armament and associated fire control and related systems and components on the M109-series self-propelled Howitzers, M992 Field Artillery Ammunition Carrier (FAAC) and M88A1 Medium Track Recovery Vehicle. Maintains diesel power plants/packs, compression ignition engines and engine fuel systems, air induction systems, exhaust systems, cooling systems, engine starting and charging systems, track hull electrical and hydraulic systems, automatic cross drive transmission assemblies, auxiliary drive assemblies, track vehicle suspension and suspension lock out systems, mechanical/hydraulic steering and braking systems, fire extinguisher/suppression systems and gas particulate filter systems. Diagnoses malfunctions, troubleshoots and performs other field maintenance on carriage-mounted armament, associated fire control and related systems and components on all self-propelled field artillery weapon systems.', '95c35df817ec337e04c77526ff78d0f65ba9df39f69fb4843145e4cc79efb377', 314, 314, null, 718, '2025-10-01', null, false, 1),
  ('8d835ba8-d906-5e50-95f3-4a71cafbdb36', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91P', 'Self-Propelled Artillery Systems Mechanic (Self-Prop Arty Sys Mech)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises junior grade Soldiers and provide technical guidance to the Soldiers in the accomplishment of their duties. Troubleshoots, inspects and corrects malfunctions in automotive systems, turret, carriage mounted armament, associated fire control systems and chemical protection subsystems of self- propelled field artillery weapon systems and supporting track vehicles.', '99a051da53ff140ec6ed73cb2dd4b4fe150d5259828f2a5553c27a065bbddd69', 314, 314, null, 719, '2025-10-01', null, true, 2),
  ('e1ac74ac-c445-595a-9bc0-4086d4e9106c', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91P', 'Self-Propelled Artillery Systems Mechanic (Self-Prop Arty Sys Mech)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises junior grade Soldiers and provide technical guidance to the Soldiers in the accomplishment of their duties. Perform battlefield damage assessment and repair (BDAR) of track vehicle armament/automotive systems. Inspects, troubleshoots and diagnoses faults in armament and automotive systems of the M109-series howitzer, M992 Field Artillery Ammunition Carrier (FAAC) and the M88A1 Medium Track Recovery Vehicle. Supervise recovery operations.', 'd8c0846422f7ab66532248d67d1a20c93abea8ea2462bfd6ae35bf2f1ac349eb', 314, 314, null, 720, '2025-10-01', null, true, 3),
  ('2898fbdb-4b28-54c6-8b34-1134c5e72f67', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91P', 'Self-Propelled Artillery Systems Mechanic (Self-Prop Arty Sys Mech)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties in preceding skill levels, supervises junior grade Soldiers and provide technical guidance to the Soldiers in the accomplishment of their duties. Supervise the performance of battlefield damage assessment and repair (BDAR). Direct recovery operations.', '9262bd11c9c6620b5fdb6dc199a17348fe3d1a45f189a81d9763cba844e3a591', 314, 314, null, 721, '2025-10-01', null, true, 4),
  ('7cd4fc6f-9ff8-5de3-b940-eec9d6dd6288', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91S', 'Stryker Systems Maintainer, Stryker Sys Maint', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Stryker Systems Maintainer supervises and performs field level maintenance on the Stryker family of vehicles (M1126 Infantry Carrier Vehicle, M1127 Recon Vehicle, M1128 Mobile Gun System (MGS), M1129 Mortar Carrier, M1130 Commander’s Vehicle (CV), M1131 Fire Support Vehicle (FSV), M1132 Engineer Support Vehicle (ESV), M1133 Medical Evacuation Vehicle (MEV), M1134 Anti- Tank Guided Missile (ATGM), and M1135 NBC Recon Vehicle (NBCRV).', '2d77a538b9c2ca79990c820bbc54a0f562afd58f619d73c98b993a9907fc4c0c', 316, 316, null, 722, '2025-10-10', null, false, null),
  ('ce59dfcb-6d81-55e1-86d5-12962e99ddf4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91S', 'Stryker Systems Maintainer, Stryker Sys Maint', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Diagnoses and troubleshoots malfunctions, performs field level maintenance on the engines, transmissions and power train major assemblies and components, vehicular mounted environmental control systems, fuel system components, suspension systems, steering systems, hydraulic systems, vehicular mounted armament, gun turret drive system and the fire control system on the Stryker family of vehicles.', '5e5d86879833a30a097a9d3f3d838c9f87db1b26df246b965e588504d27f4e06', 316, 316, null, 723, '2025-10-10', null, false, 1),
  ('ace0058d-2e8a-50ad-abd1-704ac82568f5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91S', 'Stryker Systems Maintainer, Stryker Sys Maint', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties assigned in preceding skill level, supervises and provides technical guidance to junior grade Soldiers in the accomplishment of their duties. Diagnoses and corrects malfunctions of various subsystems, Conducts in-process inspection/troubleshooting procedures, during repairs and overhaul of engines, transmissions and power train major assemblies and components, vehicular mounted environmental control systems, fuel system components, suspension systems, steering systems, hydraulic system, fire extinguisher/suppression systems, vehicular mounted armament, gun turret drive systems and fire control systems.', 'bdb308a40ff651ed943c993cb7c68ced014113f6e6d89e562ab836dcfc51ecbb', 316, 316, null, 724, '2025-10-10', null, true, 2),
  ('58ed3062-9291-507e-8c65-cd75673828a7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91S', 'Stryker Systems Maintainer, Stryker Sys Maint', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties assigned in preceding skill level, supervises and provides technical guidance to junior grade Soldiers in the accomplishment of their duties. Performs equipment classification inspections and annotate and submit appropriate forms and documents. Performs battlefield damage assessment and repair (BDAR).
(4) MOCS 91S4O. Performs duties in preceding skill levels, supervises skill level l through 3 Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Supervises compliance with shop safety program and the use, maintenance and security of hand and shop power tools. Supervises and performs diagnostic troubleshooting to determine maintenance repair criteria using Test Measurement Diagnostic Equipment (TMDE) in the repair of the automotive and armament systems of the Stryker family of vehicles.', '26519c0ca8a12df80d8fb2468d8c51b159c891e94f2a1ba096e5ea46979c3c66', 316, 316, null, 725, '2025-10-10', null, true, 3),
  ('2f1680c6-62da-5839-85e2-1fdb989ad1bd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91X', 'Maintenance Supervisor (Maint Supv)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The maintenance supervisor supervises and performs field maintenance on tracked and wheeled vehicles, construction equipment (which includes that used for earthmoving, grading and compaction; lifting and loading; quarrying and rock crushing; asphalt and concrete mixing and surfacing; water pumping; air compression and pneumatic tools; powered bridging and their associated trailers and material handling equipment (MHE)); special purpose equipment maintenance activities to include: (1) Power Generation Equipment; (2) Air Conditioning/Refrigeration Systems; and (3) Quartermaster and Chemical Equipment; combat vehicles, infantry and artillery fire control systems and equipment, and related test equipment; small arms and other infantry weapons and towed artillery. Perform as support maintenance machine ship supervisor or metalworking supervisor. Supervise recovery operations on track vehicles, wheel vehicles and related activities including electrical wiring harness system repair/maintenance.', '37aa63951c2bbf77dbcf40af8e7eed2867c008261d923fe7b0b3abdb7ae765a1', 318, 318, null, 726, null, null, false, null),
  ('1539a3dd-c927-5f44-bcdd-eacb108e2c38', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '91Z', 'Senior Maintenance Supervisor (SR Maint Supervisor)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The senior maintenance supervisor supervises, plans, coordinates, and directs the field maintenance of all wheeled, tracked, armament, power generation, and utility equipment.
(1) Serves as principal maintenance or operations NCO in maintenance battalion or higher-level organization.
(2) Supervises personnel performing the duties of--
(a) M1 Abrams Tank System Maintainer (MOSC 91A4O)
(b) Self-Propelled Artillery Systems Maintainer (MOSC 91P4O)
(c) Bradley Fighting Vehicle System Maintainer (MOSC 91M4O)
(d) Stryker Systems Maintainer (MOSC 91S4O)
(e) Maintenance Supervisor (MOSC 91X4O).', '44da44e11e6fee792f618521b9e65383f97cb6b6ca187779b4fe4b288fbdbfe2', 319, 319, null, 727, null, null, false, null),
  ('46d965ea-be54-5118-8e0a-b730bcbd1718', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Automated Logistical Specialist supervises and performs management or stock record/warehouse functions pertaining to receipt, storage, distribution, and issue, and maintains equipment records and parts.', 'a5a14c29ae2952251685e784880a0273d807a72c9378d04d55729b2b200c360d', 320, 320, null, 728, '2026-10-01', null, false, null),
  ('a043fff1-1963-5abe-8e54-b0ec9172ee07', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Uses the Enterprise Resource Planning (ERP) systems to maintain stock records and other inventory, materiel control, accounting, and supply reports. Establishes and maintains accounting records, posts goods receipts and turn-ins. Reviews and verifies quantities received against bills of lading, contracts, purchase requests and shipping documents. Unloads, unpacks, visually inspects, counts, segregates, palletizes, and stores or issues incoming materials and equipment. Conducts preventive maintenance checks and services (PMCS) on Long Life Reusable Containers (LLRC). Repairs and constructs fiberboard or wooden containers. Packs, crate, stencil, weigh and band equipment and materials. Construct bins, shelving, and other storage aids. Processes request and turn-in documents through warehousing section. Processes inventories, and warehousing documents. Performs shop stock list (SSL) duties in manual and automated supply applications. Prepares, annotates, and distributes shipping documents. Breaks down and distributes field rations. Operates material handling equipment (MHE). Perform accounting and sales functions in self-service supply. Uses ERP systems to simplify and standardize the collection and use of maintenance and material logistics data. Improves readiness management and visibility by providing equipment status and asset data. Raise the quality and accuracy of performance, cost, backlog, man-hour, and material information through improved maintenance management. Sets up and connects logistics communications enablers to ERP systems to effectively transmit logistics data between the enterprise.', '17ee61a72fb4a031e1e3e887a5dcfc6914d686c8817046bcefefafdbb2c55485', 320, 320, null, 729, '2026-10-01', null, false, 1),
  ('a22c3587-d113-53af-9396-e9a35c97939d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at preceding level of skill and provides technical guidance to junior graded personnel. Ensures that inventory and bin management are performed in accordance with established procedures. Instruct warehouse personnel in loading, unloading, segregation, palletizing and selection of stock and storage areas. Perform property disposal storage functions. Ensure application of special procedures for handling, storing, packaging, and shipping retrograde material. Performs analysis of history and activity files pertinent to ERP system rejected documents. Reviews recommended additions and deletions to authorized stockage list directed by Army expert ASL team. Maintains accounting records of property disposal activity. Review requests for major and controlled items. Reconcile activity records for monthly and quarterly reporting and status reviews. Manages controlled, critical, and reserve stocks and operational readiness floats. Perform financial management functions. Prepares data input and utilizes Automated Data Processing (ADP) output to assist in materiel management. Prepares reports on labor and equipment, available storage space, relocation of materiel, warehouse refusals and stock requirements. Assist unit maintenance personnel in planning maintenance program. Simplifies and standardizes the collection and use of maintenance data. Improves readiness management and visibility by providing equipment status and asset data. Responsible for the quality and accuracy of performance, cost, backlog, man-hour, and parts data through improved maintenance management. Plans and coordinates subsistence supply activity. Ensures subsistence items stockage objectives are met. Directs corrective action to minimize spoilage, flavor contamination and improper warehouse practices. Supervise the set up and connection of logistics communications enablers. Ensures communications enablers and ERP systems work in sync and troubleshoots when out of sync.', 'cf3c37d86f7c76a7a3efcac7628429be8f9e828625a11c13657ce2ba90daf246', 320, 320, null, 730, '2026-10-01', null, true, 2),
  ('735fac03-6b2a-54f3-bbd3-b920d983b24f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs supervisory duties shown in preceding levels of skill. Assigns duties, instructs, and supervises subordinates in proper work techniques and procedures. Plans and analyzes operational data and reports to ascertain degree of conformity with established policies, work standards and procedural directives. Reviews all goods movement through the storage activity ensuring all movements are completed within established time guidelines. Reviews and analyze business intelligence/business workplace (BI/BW) reports to identify deficiencies and determine ways to improve warehouse efficiency. Inspects and evaluates inventory management activities. Directs logistics personnel in establishment and maintenance of supply and inventory control management functions. Reconcile problems in the ERP system. Analyzes, establishes, and directs modification to authorized stock levels based on recommendations provided by the expert ASL team. Plans and organizes receipt, issue, storage, and maintenance of records for all classes of supply except CL III (Bulk), CL V and CL VIII. Ensures compliance with current regulations and directives pertaining to financial inventory, accounting, and stock funding. Determines current and projected repair requirements. Direct lateral redistribution of stock. Prepares and updates warehouse planograms. Conducts inspection of activities to ensure compliance with standards of serviceability, reclamation, salvage and disposal procedures. Conduct warehousing surveillance and inspections IAW Care of Supplies in Storage (COSIS) program directives. Prepares reports on personnel and equipment availability, storage space, relocation of materiel and warehouse goods reversals. Serves as warehouse foreman, chief accountant, or accountable officer (if required). Establishes issue schedules and procedures. Manages and maintains communications enablers. Conducts execution management for planning logistics sustainment requirements at the brigade combat team (BCT) level. Conducts material management planning at sustainment brigade or higher element for tactical logistics requirements.', 'b3615a9a7f02cee9cedd4484493cb581ab0c814765f89f545e8ebd0a838d08c1', 320, 321, null, 731, '2026-10-01', null, true, 3),
  ('97e4d149-1f0e-56a0-9715-371432eee0a7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs supervisory duties shown in preceding level of skills. Conducts inspections and provides technical assistance to storage activities. Assist in the development and preparation of operations information including plans, maps, sketches, overlays, and other data related to supply organization employment. Performs liaison and staff duties in a supply and maintenance activity or in a command and staff logistics activity. Analyze operations statistical data and reports to ascertain functional trends, conformance to standards and directives and efficiency of operations. Review material receipt and off-line document processing procedure. Responsible for the requisition, accountability, wholesomeness, and the safe storage of subsistence items for division size elements and larger. Plans and writes LOIs for subsistence support for major field exercises. Works with and advises installation food service and installation menu board. Interprets and uses command and CONUS annual food plans. Ensures compliance with directives related to subsistence supply storage and distribution operations, including worldwide operations. Manage the operation of a troop issue subsistence activity.', 'e94348c8ae4f99663a83314b3d8011d1d2275d53616538a3c5f53b2ef29ba5d5', 321, 321, null, 732, '2026-10-01', null, true, 4),
  ('a9ec1bca-50db-57b0-9cb8-9b36cd95c5bf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Automated Logistical Specialist receive, store, and issue supplies and equipment, conducting inventory management and audits. Oversee motor pool vehicle maintenance records and parts management, processing logistical actions and maintaining reports. Manage and maintain logistical systems within the Sustainment Automation Support Management Office. Participate in operational planning, providing logistical support and expertise to ensure mission success.', 'b27624e676c98598bedbce39b57e8794f15ae970271363d2759097da86edef34', 322, 322, null, 733, '2025-10-01', '2026-10-01', false, null),
  ('240522d1-6885-5008-b281-b3b475599566', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Manage the flow of supplies and equipment, performing essential warehouse duties in receiving, storing, and issuing goods. Maintain accurate inventory records using ERP systems, and process documentation. Ensure compliance with regulations, often assisting with subsistence management and property disposal. Prepare reports on supply activity, working under supervision to support overall logistics operations.', '0f3b57607679d924eee55468dce3ece37fd868f86369b72642d763c7cad76a49', 322, 322, null, 734, '2025-10-01', '2026-10-01', false, 1),
  ('371dc481-6b5d-5831-99c2-de2bcd807ba7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise and train lower-level Supply Specialists, provide technical guidance. Analyze inventory levels and implement corrective actions, manage controlled stocks. Assist with requisitioning supplies and resolve order issues, prepare complex reports and analyze data for improvements. Reconcile ERP system issues, manage materiel records, and conduct inventories. Plan logistics support for exercises and operations, coordinate subsistence activities and serve as a liaison between units.', '726191d39d997b2f0489cf080bf04a6a18dd8ec124efe836f83a1082faccb131', 322, 322, null, 735, '2025-10-01', '2026-10-01', false, 2),
  ('3b4c3ecf-a89d-5b26-8ba9-d1fd30c0babf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Lead and supervise supply sections, coordinating daily operations and enforcing standards. Analyze logistical plans and recommend improvements, managing stockage levels and distribution systems. Oversee property accountability procedures, conducting inventories and resolving discrepancies. Develop and implement supply policies, ensuring compliance with regulations and maximizing efficiency. Train and mentor subordinate personnel, evaluating performance and identifying development needs. Manage automated supply systems, troubleshooting issues and optimizing data flow. Prepare detailed reports on supply status, forecasting requirements and justifying resource allocation. Coordinate with other units to fulfill logistical requests, ensuring timely support for missions and exercises.', 'c26555cd6c33a6f70a6f90d82ffe14ca286ee0c583f505ce1d104f39b34157f9', 322, 322, null, 736, '2025-10-01', '2026-10-01', false, 3),
  ('e32912e3-312a-5be4-afe1-2b9b76c92caf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Direct and manage all supply and logistics functions within a battalion or brigade-level unit. Develop and implement comprehensive supply plans, coordinating with higher headquarters and subordinate elements. Analyze logistical data and forecast future requirements, optimizing resource allocation and minimizing waste. Supervise property accountability, conduct audits and resolve complex discrepancies. Evaluate and improve supply procedures, ensure compliance with regulations and maximize efficiency. Mentor and train supply personnel at all levels, foster professional development and technical expertise. Manage automated supply systems, resolve critical issues and implement system upgrades. Advise commanders on all logistical matters, providing expert guidance and support for mission success.Performs supervisory duties shown in preceding level of skills. Conducts inspections and provides technical assistance to storage activities. Assist in the development and preparation of operations information including plans, maps, sketches, overlays and other data related to supply organization employment. Performs liaison and staff duties in a supply and maintenance activity or in a command and staff logistics activity. Analyze operations statistical data and reports to ascertain functional trends, conformance to standards and directives and efficiency of operations. Review material receipt and off-line document processing procedure. Responsible for the requisition, accountability, wholesomeness and the safe storage of subsistence items for division size elements and larger. Plans and writes LOIs for subsistence support for major field exercises. Works with and advises installation food service and installation menu board. Interprets and uses command and CONUS annual food plans. Ensures compliance with directives related to subsistence supply storage and distribution operations, including worldwide operations. Manage the operation of a troop issue subsistence activity.', '8eeb397b65c0f753e9a1cfe1e32b1ae0b842e3c3b01790c5703c678edd055524', 322, 322, null, 737, '2025-10-01', '2026-10-01', true, 4),
  ('e925a1db-5017-5983-b435-3b5b675d5025', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92A', 'Automated Logistical Specialist (Auto Log Spec)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serves as the principal NCO of logistics support operations. Supervises operations of organizations performing supply and related service operations such as decontamination, transportation, and property disposal operations. Supervises the planning of all classes of supply requirements in support of Army operations based on the operational environment. Supervises open and covered storage, receiving, classification, issue materiel handling, supply locator systems, facility safety and supply security operations. Supervise management of materiel support functions in stock control and accounting, procurement, inventory control and item financial management. Supervises development and preparation of operations information, plans, maps, sketches, overlays and related data to employment supply and service organizations. Analyzes reports on supply and service support operations.', '39f0c314d5c0eb339e652f53d5425eed4a48d5f844372413fce54833fa1a0255', 322, 322, null, 738, '2025-10-01', '2026-10-01', false, 5),
  ('1a3c4981-19d7-5fa6-8e23-3d8004bd7bee', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92F', 'Petroleum Supply Specialist (Petro Sup SPC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The petroleum supply specialist supervises, receives, stores, accounts for and cares for, dispenses, issues and ships bulk or packaged petroleum, oils and lubricants (POL) products.', '0cf37cc99d9181ecfe4bfcef11131cc19d54ce4429d4e55aa05d9542340f5099', 324, 324, null, 739, '2026-10-01', null, false, null),
  ('8419ec76-94f8-53d1-816d-723f90faee95', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92F', 'Petroleum Supply Specialist (Petro Sup SPC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Receives and stores bulk and package POL products. Issues and dispenses bulk fuels and water from storage and distribution facilities to using units. Selects and submits samples of POL to laboratory for testing. Performs petroleum and water accounting duties. Operates equipment associated with petroleum and water distribution system and multi-product pipeline system. Fuels and defuels vehicles, aircraft, and stationary equipment. Takes emergency precautions to prevent harm to self and facilities in event of petroleum spillage or fire.', '1c026850c4663025bfca563bec657bdffb45ab3cfa11f3bc6fbfed2689203e5d', 324, 324, null, 740, '2026-10-01', null, false, 1),
  ('25ff6d91-e60c-54bc-9439-9f30668412a0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92F', 'Petroleum Supply Specialist (Petro Sup SPC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at preceding level of skill. Assigns duties, spot checks work adequacy and instructs and supervises subordinates in work techniques and procedures. Determines source of product contamination in storage areas and pipelines and directs reclamation and disposition for petroleum products. Assures adherence to safety procedures and ensures keeping of efficient, clean, and safe work environment. Supervises aircraft refueling and defueling operations.', 'a39df757fc94134fc25ccaa6c6b5027cebbcd510a3bdeae1956e88affdb672c1', 324, 324, null, 741, '2026-10-01', null, true, 2),
  ('046b85e8-7552-59b9-ad1f-026cd28d72ea', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92F', 'Petroleum Supply Specialist (Petro Sup SPC)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs supervisory duties shown in preceding level of skill. Estimates requirements for personnel, equipment, user/organizational maintenance, and repair of petroleum distribution facilities. Schedules and dispatches petroleum and water products through pipelines and other distribution facilities or equipment. Initiates and supervises environmental protection activities and contingency plans. Reviews, consolidates, and prepares technical, personnel and administrative reports associated with POL and water activities in assigned unit. Supervises unit-level quality assurance operations. Plans and organizes petroleum laboratory activities. Establishes files and technical references and specifications. Prepares and reviews administrative and technical reports. Supervises all supply activities, coordinates activities with POL storage and distribution. Assists in establishment and supervision of quality surveillance programs. Ensures adherence to laboratory fire and safety procedures. Applies principles of Occupational Health and Safety Act and EPA regulations for possible violations of environmental control laws.', 'a8812467be998c15dd8509c3a823a970a440679d9dcd39971019ea25f29b98d7', 324, 324, null, 742, '2026-10-01', null, true, 3),
  ('90f3a66a-b71c-54f6-91fe-6957e84cfb18', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92F', 'Petroleum Supply Specialist (Petro Sup SPC)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs supervisory duties shown in preceding level skill. Supervises and monitors quality assurance programs and activities. Ensure compliance with fire and safety regulations. Performs staff and advisory duties by assisting and planning quality assurance, surveillance operations and programs. Makes inspection of contractor facilities to ensure that all provisions of the contract are complied with. Coordinates special testing of POL products, including troubleshooting of differences in results among laboratories.', 'c40b3ee2716e064adbfb98b026d6745070baed99ab75c83aacbb1600b4d63f89', 324, 324, null, 743, '2026-10-01', null, true, 4),
  ('3fc6ccd7-32e4-567d-8400-e864fb3bde21', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92F', 'Petroleum Supply Specialist (Petro Sup SPC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The petroleum supply specialist receives, stores, and issues petroleum products, operates and maintains petroleum equipment, and performs quality control tests on fuel and lubricant. Provide refuel support for vehicles and aircraft, conduct bulk-to-bulk transfers, and manage fuel inventories, while also ensuring compliance with environmental and safety regulations to support unit operations and maintain equipment.', '2fcdbbd29ce57b622de09cd821f64576f66963bed32016c211be79cbf6066efe', 326, 326, null, 744, '2025-10-01', '2026-10-01', false, null),
  ('a59982b4-4252-5240-b869-c9580368ab86', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92F', 'Petroleum Supply Specialist (Petro Sup SPC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform basic petroleum laboratory testing, receiving, storing, and issuing petroleum products. Inspect and test fuel for contamination and adherence to quality control standards. Operate and maintain petroleum distribution systems, including pumps, tanks, and pipelines. Maintain accurate records of fuel inventory, consumption, and testing results. Assist in managing fuel storage facilities, ensuring safety and compliance with regulations. Perform preventative maintenance on petroleum equipment, reporting any discrepancies or malfunctions. Follow established procedures for handling and disposing of petroleum waste.', 'a073c7eeb2492e9fa9e2d0e6ba537f3508ca3cc53ec7deb4d5a23d4d2e960511', 326, 326, null, 745, '2025-10-01', '2026-10-01', false, 1),
  ('3cfaf4ea-1cc9-512f-8b3b-1dd33c3779d2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92F', 'Petroleum Supply Specialist (Petro Sup SPC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform petroleum quality control testing, analyzing fuel samples and interpret results. Manage petroleum distribution operations, oversee tank farms and issue points. Maintain accurate inventory records and prepare detailed reports on fuel consumption and stockage levels. Troubleshoot and repair petroleum distribution equipment, ensure operational readiness. Train and mentor junior petroleum specialists, enforce safety regulations and proper procedures. Inspect and evaluate petroleum storage facilities, identify and correct deficiencies. Coordinate fuel requests and deliveries, ensure timely support for operational requirements.', 'd8a51fd3792791082a5ec82e7bafae6761d2d17a5be5b307f8c4ef2cf9c93d90', 326, 326, null, 746, '2025-10-01', '2026-10-01', false, 2),
  ('b689d7e5-6627-556e-aef9-7f0ed964d418', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92F', 'Petroleum Supply Specialist (Petro Sup SPC)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise and manage all aspects of petroleum operations, including quality control, distribution, and storage. Plan and coordinate fuel supply for large-scale operations, anticipating requirements and resolving logistical challenges. Analyze fuel consumption data and recommend improvements to optimize efficiency and minimize waste. Inspect and evaluate petroleum facilities and equipment, ensuring compliance with safety and environmental regulations. Train and mentor petroleum specialists, developing their technical expertise and leadership skills. Manage automated petroleum management systems, troubleshooting issues and maintaining data integrity. Advise commanders on petroleum-related matters, providing expert guidance and support for mission success.', '0bb9cb5b86d9a1fc34185d2b0fe5bcc8f2d9982b7c5d2df3539da4acf59e802d', 326, 326, null, 747, '2025-10-01', '2026-10-01', false, 3),
  ('5adf4383-848c-52bf-8bb0-2dd4d9ed443b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92F', 'Petroleum Supply Specialist (Petro Sup SPC)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Direct and manage all petroleum logistical functions within a theater of operations or large-scale organization. Develop and implement petroleum supply plans, coordinating with higher headquarters and subordinate units. Analyze fuel requirements and allocate resources, ensuring efficient distribution and stockage. Oversee quality control programs, establishing standards and ensuring compliance with regulations. Supervise personnel responsible for petroleum storage, distribution, and testing, providing leadership and technical guidance. Manage automated petroleum management systems, optimizing data flow and improving operational efficiency. Advise commanders on complex petroleum-related issues, providing expert recommendations and support for strategic decision-making.', '13aabc6044f5e01aedb18fda478eb50f64ad7fc097f873672cddc8e1118374ab', 326, 326, null, 748, '2025-10-01', '2026-10-01', false, 4),
  ('423a7c83-d1a2-5163-8e37-fe53991b1e83', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92G', 'Culinary Specialist', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Culinary Specialist is responsible for Army food service operations; ensure food safety and sanitation standards, manage food inventory and maintenance of field feeding equipment. Responsible for menu planning, personnel management, and performing supervisory and inspection functions. Their role is critical in supporting the health and morale of Soldiers by providing nutritious and appealing meals while they are supporting garrison and multidomain operations in support of large-scale combat operations.', '0028546713b752a55c37e9116b0058e56b939851778b0f52560ee1a5ff3ba954', 327, 327, null, 749, '2025-10-01', null, false, null),
  ('4aee3c1d-e22c-5286-9fbd-34cbe9753361', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92G', 'Culinary Specialist', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Prepare and serve food in tactical field kitchens, following standardized recipes and procedures. Operate and maintain kitchen equipment, ensuring cleanliness and sanitation standards. Receive, store, and issue food supplies, maintaining inventory control. Assist in menu planning and preparation of special meals for field operations. Practice food safety and sanitation procedures to prevent foodborne illness during deployments. Wash dishes, clean work areas, and maintain a sanitary kitchen environment in both garrison and field settings. Perform basic baking and cooking tasks under supervision, supporting tactical feeding operations.', 'b56cec4ae32e4539a162f1ff68d0bb91f145261f3bc2c69f31159e21993a1233', 327, 327, null, 750, '2025-10-01', null, false, 1),
  ('89a7566e-91b0-5ff5-8491-b8de4e789bf0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92G', 'Culinary Specialist', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Prepare and cook a wider variety of foods, utilize more complex cooking techniques. Operate and maintain a full range of kitchen equipment, perform preventative maintenance checks. Manage food inventories, order supplies and ensure proper storage. Plan and prepare menus for both garrison and field feeding operations. Supervise and train junior culinary specialists in food preparation and kitchen procedures. Enforce food safety and sanitation standards, conduct inspections and correct deficiencies. Adapt recipes and cooking methods to accommodate dietary restrictions and special requests. Prepare field kitchens for tactical deployments, ensure all necessary equipment and supplies are available.', 'e7d07009355159fa6812caad9617a6ed59300321385abf6b7f5b4e44b7d99ba2', 327, 327, null, 751, '2025-10-01', null, false, 2),
  ('8c0f7856-9818-54cb-9376-0d0339e761bd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92G', 'Culinary Specialist', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise and manage all aspects of food service operations, including menu planning, food preparation, and sanitation. Train and evaluate culinary specialists, developing their skills and ensuring adherence to standards. Manage food budgets and inventory control, minimizing waste and maximizing resources. Plan and coordinate field feeding operations for large-scale exercises and deployments. Inspect kitchens and food service facilities, ensure compliance with health and safety regulations. Adapt menus and cooking techniques to meet diverse dietary needs and operational requirements. Troubleshoot and repair kitchen equipment, coordinate with maintenance personnel as needed. Advise commanders on culinary matters, provide expertise on food service logistics and planning.', '4a3e3af711fa362d2290de08a393ba2fc03b6c26d931a08b849dd55a74576054', 327, 327, null, 752, '2025-10-01', null, false, 3),
  ('7e1b840b-3415-59bc-acf9-3d5c454cba2d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92G', 'Culinary Specialist', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Direct and manage all culinary operations within a brigade or larger unit, overseeing multiple food service facilities. Develop and implement food service plans, coordinating with higher headquarters and subordinate elements. Manage food service budgets and personnel, ensuring efficient resource allocation and effective training. Plan and coordinate large-scale field feeding operations for extended deployments and contingencies. Evaluate food service programs and recommend improvements to enhance quality and efficiency. Inspect and audit food service facilities, ensuring compliance with health, safety, and sanitation regulations. Serve as a subject matter expert on culinary matters, advising commanders on logistical and operational issues. Develop and maintain relationships with food vendors and suppliers, ensuring quality and cost-effectiveness.', 'ca2a7a61200b32b77ffe973756a3056459e86b1f8d82d2e28b4b23ed676a6826', 327, 327, null, 753, '2025-10-01', null, false, 4),
  ('3a8ccb5d-721b-5018-ad34-4fbc85f7f87e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92G', 'Culinary Specialist', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Serve as the senior culinary advisor at the battalion or brigade level, developing and implementing comprehensive food service programs. Manage all aspects of food service operations, including budgeting, personnel management, and logistical support. Develop and revise food service policies and procedures, ensuring compliance with regulations and best practices. Conduct inspections and evaluations of food service facilities, identifying areas for improvement and implementing corrective actions. Mentor and train culinary personnel at all levels, fostering professional development and technical expertise. Plan and coordinate large-scale food service support for complex operations and contingencies. Analyze food service data and trends, recommending improvements to enhance efficiency and effectiveness. Represent the organization in external food service forums and conferences, sharing expertise and best practices.', '44349b97fe7a30793000d10b83141b95308821c1f63e2439bddc6d37b3ec132a', 327, 327, null, 754, '2025-10-01', null, false, 5),
  ('7cfbaddd-1ef8-5fce-b414-d51c7c9cb96b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92L', 'Petroleum Laboratory Specialist (Petro Lab SPC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The laboratory petroleum specialist collects, tests, and analyze petroleum products to ensure quality and compliance. Operate and maintain specialized laboratory equipment, accurately interpreting test results. Report findings to commanders, providing expert advice on fuel management. Maintain laboratory standards, adhering to strict quality control procedures. Troubleshoot equipment issues and manage laboratory resources, supporting operational readiness.', '5680a8d710e43306d6bdc0e43031d6a953d69e78ad00e6485ba13a4c03664dba', 329, 329, null, 755, '2025-10-01', null, false, null),
  ('b38d1be4-ddd0-5a26-8d2b-514cffa26b68', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92L', 'Petroleum Laboratory Specialist (Petro Lab SPC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Collect and test petroleum, oil, and lubricant (POL) samples for quality control, following established procedures. Perform basic laboratory tests, measuring properties like viscosity, flash point, and water content. Record test results accurately and maintain laboratory logs. Assist in operating and maintaining laboratory equipment, ensuring proper calibration and functionality. Clean and organize the laboratory workspace, adhering to safety regulations. Prepare samples for shipment to higher-level testing facilities. Follow instructions from supervisors and senior specialists during testing procedures.', '0a0c7c6ed618869dd531e0be28f6cf91af033a0a7b4262a3dabf67be0a933c6b', 329, 329, null, 756, '2025-10-01', null, false, 1),
  ('bc2e5891-2870-59d0-a81d-998ae8385ff5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92L', 'Petroleum Laboratory Specialist (Petro Lab SPC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform a range of petroleum quality control tests, analyze samples for contaminants and degradation. Operate and maintain complex laboratory equipment, troubleshoot malfunctions and perform preventative maintenance. Interpret test results and identify potential fuel quality issues, recommend corrective actions. Prepare detailed reports on laboratory findings, document test procedures and results. Supervise and train junior petroleum laboratory specialists, ensure adherence to safety protocols. Calibrate and standardize laboratory equipment, maintain accuracy and reliability. Assist in developing and implementing quality control procedures, improving testing efficiency. Manage laboratory inventory, ordering supplies and maintaining stock levels.
(3) MOCS 92L converts to 92F3O.', '165ebfa0e7915a1c0af1db24226b9bf18ae80651599d1dbabdaf3f2bb9c8836a', 329, 329, null, 757, '2025-10-01', null, false, 2),
  ('4e0b0d9e-9a7e-5711-8e1b-0cc9ae4857fd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Management SPC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs or supervises recovery, collection, identification, escort, and temporary burial. Inventories, safeguards, and evacuates personal effects of deceased personnel.', 'ea5eae00dd12ba6a717433c4ea33713bb0edfd35f43fac61f13e9e60bf6fbaea', 330, 330, null, 758, '2025-10-01', null, false, null),
  ('e6c7e6fe-9b73-5c77-80e0-a24a6f230c37', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Management SPC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Searches areas for unburied dead, hasty, isolated, or unmarked graves, personal effects, and identification media. Disinters remains, records personal effects, and evacuates remains and personal effects to designated points. Determines and records recovery locations on maps, sketches, and overlays. Establishes and records tentative identification. Assists in preparation, preservation, and shipment of remains. Inventories, safeguards, and evacuates personal effects. Assists in mass casualty burials.', '540d6043c24e5f99fb3a8e9cac1d445d78696449033f132850adf3fccc0ed103', 330, 330, null, 759, '2025-10-01', null, false, 1),
  ('74a22a7a-b18f-55a2-99c6-f07c94360778', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Management SPC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans and supervises search and recovery operations of deceased personnel, personal effects, and identification media. Instructs in special handling, marking, and shipping of contagious disease cases and processing of contaminated remains. Supervises receipt, storage, and issue of supplies and equipment. Accompanies remains and personal effects to designated locations and assists with arrangements for military honors at place of burial.', 'bb902c1eb0a6f9d0e5750b261cb7f5a2450a21e9e9a26fc17e515b173791da2c', 330, 330, null, 760, '2025-10-01', null, false, 2),
  ('03d2941b-98a7-5c9f-b9cb-47cdaefd3cc7', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Management SPC)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in previous skill level when required. Advises commanders and headquarters staff on fatality management activities and coordinates activities of subordinate units. Establishes and maintains liaison with support and combat units. Coordinates transportation requirements for deceased personnel.', '8e61404530aa9e379a151d185e372556a73914231cb9b74a9e0e3977884e8de9', 330, 330, null, 761, '2025-10-01', null, true, 3),
  ('8abcabab-9092-53e4-aa69-6bc17fd91834', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Management SPC)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at the preceding skill level and provides technical guidance to junior grade personnel. Advises on temporary cemetery locations, emergency burials, and security and disposition of remains and personal effects. Coordinates with non-U.S. service authorities, other service authorities and civilian officials on fatality management matters. Coordinates and advises on military burials and ceremonies. Assists in review of fatality services contracts. Advises summary court authorities on disposition of personal effects. Supervises fatality management activities.', 'f3e4dad205e0021cd1b24f8e6fd41be9b6ba92290b50486287075950dc5282fb', 330, 330, null, 762, '2025-10-01', null, true, 4),
  ('b0d8ba63-b87f-56bd-bb1c-5635b15fa991', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Management SPC)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises fatality management activities, provides technical and administrative support on graves registration matters, acquisition of land for temporary cemeteries, equipment requirements for mortuaries, and recovery/evacuation procedures.', '1dd520c4fa56447d26e37335b569ee3fe6140fd4ac093fa3b86c003061e9d522', 330, 330, null, 763, '2025-10-01', null, false, 5),
  ('cd9c6a1e-b461-5770-a896-66f7f2b88712', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Mgmt SPC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties relating to deceased personnel to include recovery, collection, evacuation of remains and personal effects, and the establishment of tentative identification through postmortem data collection.', '79470f0388e15f641d2bf06d1670cc5f28b49abda644e2ece3dd796461a09ed2', 331, 331, null, 764, '2025-10-01', null, false, null),
  ('32cc6107-f116-59ab-b114-9d12f17ab925', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Mgmt SPC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Assists with recovery of unburied dead, hasty or isolated graves, personal effects, and identification media. Disinters remain, records personal effects, and evacuates remains and personal effects to designated points. Determines and records recovery locations on maps, sketches, and overlays. Establishes and records tentative identification. Assists in preparation, preservation, and shipment of remains. Inventory, safeguard, and evacuate personal effects. Assists with temporary interment operations.', 'e05a89370cc8328371b5b948dd0584b1fe89e3f8073cb43c2a52068894bf4f02', 331, 331, null, 765, '2025-10-01', null, false, 1),
  ('9f603abd-bb12-59e4-bea2-687c349b5b5d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Mgmt SPC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Plans and supervises incident site operations of deceased personnel, personal effects, and identification media. Supervises personnel in special handling, marking, and shipping of contagious disease cases and processing of contaminated remains. Supervises receipt, storage, and issue of supplies and equipment. Oversee documentation and record-keeping throughout the recovery and disposition process. Train junior specialists in proper procedures and techniques for dignified remains handling. Coordinates with relevant agencies to ensure smooth and dignified transfer of remains.', '9855a3f5daf0f07987dbc2385e8ee0a49f7005b581f14bc2b7517b41fcb6ba78', 331, 331, null, 766, '2025-10-01', null, false, 2),
  ('dfa2f226-ff8b-55d5-83c0-f62a6a8a53d8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Mgmt SPC)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in previous skill level when required. Advises commanders and headquarters staff on fatality management activities and coordinates activities of subordinate units. Establishes and maintains liaison with support and combat units. Trains nonfatality management unit recovery teams (URTs) on search procedures at the 20 level. Coordinates transportation requirements for deceased personnel, manage logistical requirements. Develops and implements fatality management plans, preparing for potential contingencies. Oversee the accurate documentation and reporting of all recovery and disposition activities. Instructs, trains and mentors’ personnel, enhancing their expertise in fatality management procedures.', 'caeecc6f066174b5d77e5bf05288312673eed5e315dc8b68c08bc6fa40a0b541', 331, 331, null, 767, '2025-10-01', null, true, 3),
  ('f14c34d9-304e-58aa-9df6-759ba082c63e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Mgmt SPC)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Coordinates with U.S. and international authorities on fatality management issues, ensuring compliance and cooperation. Performs duties shown at the preceding skill level and provides technical guidance to junior grade personnel. Advises staff on temporary interment locations, emergency burials, and security and disposition of remains and personal effects. Coordinates with non-U.S. service authorities, other service authorities and civilian officials on fatality management matters. Coordinates and advises on military burials and ceremonies. Assists in review of fatality services contracts. Advises summary court authorities on evacuation of personal effects. Supervises fatality management activities.', '1b43273970e771f9cd9ae2e2ece6dd1dab73af68ecf80612dff94e6b9aeba89d', 331, 331, null, 768, '2025-10-01', null, true, 4),
  ('0ad39512-2886-5a8e-9a10-75600876b00f', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92M', 'Fatality Management Specialist (Fatality Mgmt SPC)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises fatality management activities, provides technical and administrative support on temporary interment matters, acquisition of land for temporary interment, equipment requirements for mortuaries, and recovery/evacuation procedures. Advise on policy and procedures, contributing to improvements in fatality management practices. Manage resources and personnel, optimize effectiveness and maintain readiness. Serve as a subject matter expert, providing guidance and support to commanders and staff.', '54274369ef7f978fdd2026bb54fe8cc735187d290aac81a0e0ca52f995293c7d', 331, 331, null, 769, '2025-10-01', null, false, 5),
  ('c0475647-5a86-5dc4-92c1-ff51ac394fa0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92R', 'Parachute Rigger', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The 92R Parachute Rigger is responsible for inspecting, repairing, and packing parachutes, as well as other aerial delivery equipment, to ensure safety and operational readiness. They conduct routine maintenance, perform quality control checks, and prepare equipment for airborne operations, including heavy drop operations, where they rig and prepare large cargo, such as vehicles, containers and equipment, for airdrop, playing a critical role in supporting airborne missions and ensuring the safety of personnel and equipment. At higher levels, they plan, manage, execute, and supervise Airborne and Aerial Delivery Operations.
(1) MOSC 92R1P. Inventories, cleans, receives, stores, and issues all airdrop equipment used in airdrop operations. Rigs supplies, equipment and vehicles for airdrop. Assembles airdrop platform, cushioning materials, cargo, extraction and personnel parachute along with other airdrop related equipment. Inspects, tests and installs extraction and release systems. Performs technical, routine, and in-storage rigger-type inspection on cargo, extraction, and personnel parachute as well as other airdrop equipment before, during, and after each use. Packs cargo, extraction, and personnel parachutes. Performs unit, direct and general support maintenance on all parachutes, textile components and other airdrop equipment. Uses and maintains machines and tools for fabrication, modification and repair to parachute and other airdrop equipment. Drop-tests troop-type personnel parachute to check proficiency.
(2) MOSC 92R2P. Performs duties in pacing, airdrop rigger, and airdrop equipment repair shown at the above skill level. Provides technical guidance and supervision to subordinate personnel. Maintains production reports and records. Inspects and classifies airdrop items. Performs initial and final inspection on all parachutes and airdrop textile component. Performs as inspector testers, pack-in-process inspector and as quality assurance personnel. Performs as malfunction officer at the drop zone. Diagnoses malfunctions occurring in airdrop equipment during airborne operations.
(3) MOSC 92R3P. Performs duties at preceding skill level. Supervises parachute pack, maintenance or airdrop sections. Directs section activities, schedules and assigns workload. Instructs personnel on job requirements, techniques and inspects work in progress. Inspects and certifies airdrop loads, airdrop equipment repair, and parachute packing. Inspects air items to ensure manufacture quality control. Controls and expedites coordination with airborne support activities. Assists in planning and coordinating training for standard and nonstandard rigging, sling loading, and airdrop procedures.
(4) MOSC 92R4P. Performs duties shown at preceding skill level. Supervises and provides technical guidance to subordinate personnel. Assists airdrop officer in planning, coordinating, requisitioning, receiving and storing equipment and supplies for airdrop. Coordinates with supporting Air Force and Army aviation elements. Provides technical direction and coordination for activities supporting routing and contingency missions. Maintains status on all jumps and airdrops to include schedules by G3 at division level. Prepares and submits required status reports. Maintains a reference library of current publication, regulations and SOP relating to airdrop and airdrop support. Participates in development and operational testing of airdrop equipment. Performs as the senior NCO in a separate detachment/unit engaged in parachute packing, maintenance and airdrop equipment rigging.
(5) MOSC 92R5P. Performs duties shown at preceding level of skill and provides technical guidance to subordinate personnel. Supervises operations of organizations performing airborne and resupply by airdrop missions. Supervises development and preparation of operations information, plans, maps, sketches, overlays, and related data to facilitate airborne operations. Advises on airborne operational matters and performs liaison between staff and supported personnel.', '15f6cd7274569241766c172fca46c72ce9e137074088bd743ef970bb58e2cd3f', 332, 332, null, 770, '2025-10-01', null, false, null),
  ('50169197-9857-5369-8674-14be8795d998', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Shower and Laundry specialist supervises or performs personnel laundry and shower operations.', '9cd9aa5db33ab9717306f32f0e75a382f111b30ae34160f1624db4bed5aff0db', 334, 334, null, 771, '2026-10-01', null, false, null),
  ('32a0590f-0720-5ca4-95f4-756268b54089', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Receives bulk, individual, or organizational laundry and reviews laundry lists for accuracy of bundle count or contents of individual laundry bag. Separates, marks washable and un- washable items. Operates mobile laundry system, shower units, light duty sewing machines and associated equipment.', 'e694e8ea11c8bb82f5e68abf05a4721e43fe49665b6164590b4dbe0ed1ae4b21', 334, 334, null, 772, '2026-10-01', null, false, 1),
  ('a30f84b4-2903-5209-bd6d-4d3e2581c28b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties of the preceding level of skill and provides technical guidance to junior grade personnel. Supervises establishment of shower and laundry. Supervises marking, classifying, and washing operations. Supervises, laundry and shower equipment. Estimates supply requirement, request supplies, and supervises receipt, storage, and issue of supplies, and equipment.', '69299b5ffd41b033774e7864e428022b3d938815d7c6f43ae78b6bcbe99f3eb5', 334, 334, null, 773, '2026-10-01', null, true, 2),
  ('b473b675-278c-5916-9f19-4746fcadb724', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding level of skill and provides technical guidance to lower grade personnel. Plans shower reconnaissance operations and organize reconnaissance teams for selection of operational sites. Determines personnel requirements and supervises training program. Prepares and develops cost and manpower estimates. Prepares facility layout. Establishes quality control standards. Maintains records of cost data and expenditures.', 'e36b7f1df4804ed6c971f060e68ddfba9f13d8b40635dc02d466ce397b99cd91', 334, 334, null, 774, '2026-10-01', null, true, 3),
  ('04fb2964-b434-5a4d-b037-65954004417e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs supervisory duties in preceding level of skills. Determines requirements and adequacy of shower and laundry and prepares operational plan to meet requirements. Provides technical guidance to lower grade personnel. Establishes, evaluates, and monitors unit training and preventive maintenance programs. Consolidate production reports and schedules. Coordinates operating requirements of subordinate units with major subordinate units.', 'de581e793a136753b665dbd7a0f67791a3b0f1b6f96045e8582783fcd10c26e1', 334, 334, null, 775, '2026-10-01', null, true, 4),
  ('83a9ec0d-4164-5631-a5ad-53cabf019036', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs supervisory duties shown in preceding levels of skills. Performs duties as quality assurance representative for all shower/laundry and clothing repair functions. Provides technical guidance to junior grade personnel. Develops countermeasure policies, plan, doctrine, and operating procedures. Assists commander and staff officers in appraisal of intelligence, operations, and training procedures.', 'fb0afab545c536f0f7f702f24744dfcd11893c653cb30f9fd8b897c70d6aa9ed', 334, 334, null, 776, '2026-10-01', null, true, 5),
  ('a34b9f34-ce9f-593d-be65-8336735130b6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Shower/Laundry Specialist is responsible for operating and maintaining shower and laundry facilities, including hospital laundry systems, to provide essential hygiene services and support unit morale by performing laundry services.', 'a91d74a07b0e7b9dcf012cfa7fa96b114261a92b568cb6c5ec0b41de094d163e', 335, 335, null, 777, '2025-10-01', '2026-10-01', false, null),
  ('f6680ba7-dca2-5295-9988-7eb803036712', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operate and maintain basic laundry and shower equipment, following established procedures. Receive, sort, and wash laundry, ensuring proper cleaning and sanitation. Distribute clean laundry to designated personnel. Prepare and maintain shower facilities, ensuring cleanliness and hygiene. Assist with inventory management of laundry supplies and chemicals. Follow safety protocols when handling chemicals and operating equipment.', 'e12577845417c39d558c07988e187d01e2a44722358e92d314dce7f600fdd79d', 335, 335, null, 778, '2025-10-01', '2026-10-01', false, 1),
  ('1c70ea6c-70bf-50a6-bb78-745dceed7bb2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise preventative maintenance checks and services on laundry and shower equipment. Troubleshoot minor equipment malfunctions, performing basic repairs. Supervise laundry and shower operations, ensure quality control and efficiency. Manage laundry and supply inventories, order replacements as needed. Maintain records of laundry and shower usage, reporting discrepancies.', '5f3f096d05b1e931c832bc2315055301cbcf7075caf8334751b6fb1f99b682a3', 335, 335, null, 779, '2025-10-01', '2026-10-01', false, 2),
  ('fd3edd5d-627d-5490-923f-02b43c6469f1', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise and train personnel in laundry and shower operations, enforcing standards. Supervise operator maintenance and repairs on laundry and shower systems. Analyze equipment performance, identifying and resolving operational issues. Manage the flow of laundry and supplies, optimizing efficiency and minimizing waste. Inspect facilities for sanitation and hygiene, implementing corrective actions.', '1540130695681a7708ebc5dcb81d1be1053d8f01bc8363f8a83fbbba5de7f80d', 335, 335, null, 780, '2025-10-01', '2026-10-01', false, 3),
  ('1a39f30e-6a81-59a8-a9d6-09fd8f30b629', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Manage all aspects of shower and laundry facilities, including personnel, equipment, and resources. Develop and implement operational plans, ensuring effective support for units. Oversee quality control programs, maintaining compliance with health and sanitation standards. Coordinate with other units to provide laundry and shower services during deployments and exercises. Analyze data and prepare reports on facility operations and resource utilization.', 'd45985e8d9aeb329af7e5b3370367b811d1bd559809a17caa93220e7f4a84223', 335, 335, null, 781, '2025-10-01', '2026-10-01', false, 4),
  ('1fd4cc17-b21e-5731-bf01-86666451cca4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92S', 'Shower and Laundry Specialist (S&L SPC)', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Develop and implement comprehensive laundry and shower support plans at theater or major command level. Advise commanders on logistical requirements and resource allocation for laundry and hygiene services. Evaluate and improve operational procedures, incorporating best practices and new technologies. Manage large-scale laundry and shower operations, overseeing multiple facilities and personnel. Conduct inspections and audits to ensure compliance with regulations and standards. Research and recommend solutions for complex laundry and hygiene challenges.', '4f7eef5b43e466136a30d29ad8fe862fdbc9893c9f669a576e969d024b0b3a27', 335, 335, null, 782, '2025-10-01', '2026-10-01', false, 5),
  ('6d97b51d-bb87-5a02-996d-d86bd1da7d8e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92W', 'Water Treatment Specialist (Water Trmt SPC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Water Treatment Specialist is primarily responsible for supervising and installing water purification equipment, ensuring clean water storage and availability, and performing water quality tests to detect potential contaminants. They also inspect facilities and food suppliers for disease-causing agents, germs, and environmental hazards. In Field Hospitals, they serve as laundry equipment operators, overseeing the sanitary operation of laundry facilities to maintain health and hygiene standards, safeguarding public health and preventing the spread of waterborne diseases.', '487823c885941d485e2c5157652935221934e1fcfc749c5c9b78544110b23f0a', 336, 336, null, 783, '2025-10-01', null, false, null),
  ('828b4f2c-4ad9-5265-b205-70070b235ce8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92W', 'Water Treatment Specialist (Water Trmt SPC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Collect and test water samples, following established procedures. Operate and maintain basic water purification equipment, assisting with setup and breakdown. Monitor water quality indicators, reporting deviations to supervisors. Maintain records of testing results and equipment maintenance. Follow safety protocols while handling chemicals and operating equipment. Support overall facility operations and sanitation efforts. Assist with basic laundry facility operations.', 'e499e061fe2144cdd06575b7945d72281cc252dc167e8ad79bea355a1f86a2e7', 336, 336, null, 784, '2025-10-01', null, false, 1),
  ('8f44c8b9-ab58-50cc-8712-9f3122d047b6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92W', 'Water Treatment Specialist (Water Trmt SPC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Purify water using various treatment methods, ensuring potable water standards. Operate and perform preventative maintenance on a wider range of water treatment equipment. Analyze water samples, interpret results and adjust treatment processes. Supervise small teams in water purification tasks, providing guidance and training. Inspect facilities and food suppliers for basic sanitation concerns. Maintain inventory of chemicals and supplies, managing stock levels. Operate laundry equipment facilities, ensuring sanitary operation.', '57e6bf992fea964d1cfc1a9131c24057177f928be8076403e8277b5866b75bd5', 336, 336, null, 785, '2025-10-01', null, false, 2),
  ('38f91313-5c6f-5b89-9e1c-c5bba854d410', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92W', 'Water Treatment Specialist (Water Trmt SPC)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise water purification operations, ensuring quality control and compliance with regulations. Direct water reconnaissance efforts, identifying and developing new water sources. Troubleshoot and repair complex water treatment equipment malfunctions. Train and mentor junior soldiers in water treatment procedures. Analyze water quality data, prepare reports and recommendations. Manage operation and quality control of water supply, storage, distribution, and purification activities at battalion/brigade level. Employ CBRN detection and purification techniques to ensure water sources are free from chemical, biological, radiological, and nuclear contamination.', '0bcff300d9122a7696182e55724ce7c1233ebb6fadacd226b5f0229e0dbac0a3', 336, 336, null, 786, '2025-10-01', null, false, 3),
  ('2e03647a-099c-59e3-bc0c-a64a23072e18', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92W', 'Water Treatment Specialist (Water Trmt SPC)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Manage all aspects of water treatment facilities, including personnel, equipment, and resources. Develop and implement water treatment plans, adapting to changing conditions. Advise commanders on water supply issues, providing technical expertise. Direct water reconnaissance and water point development for division, corps, and echelons above corps. Oversee quality control programs, maintaining compliance with standards. Furnish reports to higher headquarters. Develop area water supply and treatment plans and supervise operation. Perform staff and advisory duties related to water and laundry operations.', 'e46b9e7c095bcfc840d450822e64cb9561f875786eda68fbf77c9d4b3e4666b9', 336, 336, null, 787, '2025-10-01', null, false, 4),
  ('30caf861-6bed-5059-840f-d73e21a9a116', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Y', 'Unit Supply Specialist (Unit Supply SPEC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The unit supply specialist supervises or performs duties involving request, receipt, storage, issue, accountability and the preservation of individual, organizational installation, facilities and expendable/durable property and equipment. Operating and maintaining the Global Combat Support System (GCSS-Army) an automated supply system for accounting of organizational and installation property and equipment.', '5e2c904f17b938a5579d7d50ef90cb08d21b8d28fadce31b501a8be0f308f380', 337, 337, null, 788, '2026-10-01', null, false, null),
  ('2e8f535f-8c99-52a5-8461-f0068420c1ef', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Y', 'Unit Supply Specialist (Unit Supply SPEC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Receives, inspects inventories, loads unloads, segregates, stores, issues, delivers and turns-in organization and installation property and equipment. Operates the GCSS-Army unit level computer. Prepares all unit/organizational supply documentation. Maintains the automated supply system for accounting of organizational property and equipment. Issues and receives small arms. Secures and controls weapons, ammunition, and sensitive items in security areas. Schedules and performs preventive and organizational maintenance on weapons and sensitive items.', 'fee1aff4afd3d09bbdfccea90ea3c11c40350aa2d4d3e17f8b02a79d35d815f9', 337, 337, null, 789, '2026-10-01', null, false, 1),
  ('fedc15d3-7aea-5f68-b654-dca849519c0d', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Y', 'Unit Supply Specialist (Unit Supply SPEC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at preceding level of skill and provides technical guidance to lower grade personnel. Inspects completed transactions/work for accuracy and compliance with established policy and procedures. Coordinates property and equipment activities. Reviews and annotates changes to the unit material condition status report. Validates/posts transactions to organizational and installation property records and updates/maintains supporting document files. Determines required method of relief from responsibility for lost, damaged and destroyed property/equipment items.', '17b2d5427a457f21a74c8f76fb5a5989e005f08eaa194b98376b1a52c9d0906f', 337, 337, null, 790, '2026-10-01', null, true, 2),
  ('b2ab79c6-8419-5266-801e-5fcfdf5b73ff', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Y', 'Unit Supply Specialist (Unit Supply SPEC)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown at preceding level or skill and provides guidance to lower grade personnel. Directs supply personnel in establishing property and inventory control management functions IAW current policy/procedure directives. Maintain property and equipment under GCSS-Army. Review daily and monthly records of all property and equipment transactions including petroleum products, unit/organizational basic/combat loads and operating supplies. Reconcile all local purchase transactions for fiscal/property accounting. Ensure weapons/sensitive item inventories are conducted IAW current regulatory procedure. Provide technical assistance to unit/organizational equipment and records parts specialist (92A). Assist and advise supply officer and company commander.', '8c2361eacd46d00f9e00444da7e235d23ba2be819a0235c4bbc94db614607a02', 337, 337, null, 791, '2026-10-01', null, true, 3),
  ('1d945518-a6ec-5ba4-af5a-660dd5ab175a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Y', 'Unit Supply Specialist (Unit Supply SPEC)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs supervisory and management duties shown at preceding level of skill. Analyzes statistical data and reports to ascertain trends, conformance to standards and directives and efficiency of operations. Oversee and maintain logistical data provided by the GCSS-Army automated system. Coordinate logistical activities with other staff elements supply and service and motor transport units. Performs duty as a Contracting Officers Technical Representative (COTR). Conducts assistance visits to subordinate elements. Develops and executes training programs.', '4ac581a132a027128391390d94b74d4326398c41821138b133da2002469498fa', 337, 337, null, 792, '2026-10-01', null, true, 4),
  ('4b334128-6696-508a-8b21-ec4e2b805d40', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Y', 'Unit Supply Specialist (Unit Supply SPC)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The 92Y Unit Supply Specialist is responsible for managing and maintaining unit supplies and equipment, including receiving, storing, and issuing supplies, maintaining accurate inventory records and reporting discrepancies. They process requests, coordinate with logistics teams, and maintain unit supply records, ensuring timely and efficient delivery of supplies and equipment. They provide customer service to unit personnel, participate in unit deployments, prepare and load supplies and equipment for transport, playing a critical role in ensuring units have the necessary resources to perform their missions effectively.', '0c263fbd6832cebbd213ba19edf77b4904cd626670cc672163f2c6fcec47e795', 339, 339, null, 793, '2025-10-01', '2026-10-01', false, null),
  ('a3afb794-7971-59bd-81fe-6f1cc0bda254', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Y', 'Unit Supply Specialist (Unit Supply SPC)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Receive, inspect, and store organizational supplies and equipment, verifying quantities and condition. Issue supplies to authorized personnel, maintaining accurate records of transactions. Organize and maintain storage areas, ensuring accessibility and security. Perform basic ordering, inventory control, reporting shortages or discrepancies using the automated supply system. Follow established procedures for handling and disposing of waste materials. Assist with packing, crating, and shipping of supplies. Secures and controls weapon parts, sensitive items in secure areas.', 'a837e281478bb1c697a95282c9bbf6a99d6cd0c51eae006a6ca34f2cb646b802', 339, 339, null, 794, '2025-10-01', '2026-10-01', false, 1),
  ('adfe8c49-039a-5922-b9c3-499a7bc03505', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Y', 'Unit Supply Specialist (Unit Supply SPC)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Order and procure supplies using automated systems, ensuring timely delivery. Manage and maintain stock levels, anticipating future needs and minimizing shortages. Schedule and conduct periodic inventories, reconciling discrepancies and adjusting records. Prepare and process documentation for supply transactions, maintaining accountability. Operate material handling equipment, safely moving supplies and equipment. Assist with the preparation of reports on supply status and usage.', 'a673a6c78f63831e97a8fc7d94ea37211a5f32fd16eeea5c9a4acc7a4c87ce59', 339, 339, null, 795, '2025-10-01', '2026-10-01', false, 2),
  ('533891fb-5dfc-5c4b-9dd6-3e11ff82f6c3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Y', 'Unit Supply Specialist (Unit Supply SPC)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervise supply operations, coordinating the flow of materials and equipment. Analyze supply requirements, forecasting needs and optimizing stock levels. Manage and maintain automated supply systems, ensuring data accuracy. Train and mentor junior supply personnel provide guidance and support. Resolve supply discrepancies, investigating issues and implementing corrective actions. Prepare detailed reports on supply status, usage, and expenditures. Assists and advises the supply officer and company commander.', 'e4c162c4e2698d084d445d1cb77ac5e5826337d1c14bb95de2466cf849eceee2', 339, 339, null, 796, '2025-10-01', '2026-10-01', false, 3),
  ('09cd1d0f-412a-5aef-9b0b-4c24c5df64bf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Y', 'Unit Supply Specialist (Unit Supply SPC)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Manage all aspects of unit supply operations, including budgeting and resource allocation. Develop and implement supply plans, aligning with operational requirements. Advise commanders on supply matters, providing expert recommendations. Oversee the receipt, storage, issue, and disposal of all supplies and equipment. Conduct comprehensive audits of supply accounts, ensuring accountability and compliance. Coordinate with external agencies to procure specialized items and resolve complex supply issues. Train and mentor junior supply personnel provide guidance and support.', 'dde89d0d6df601d69fc40e4124704f1dd48a5ccef747fc9a7cec5bed94e4f7d4', 339, 339, null, 797, '2025-10-01', '2026-10-01', false, 4),
  ('66914d55-5f3f-5f98-8572-6cd6a64bebc8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Z', 'Senior Noncommissioned Logistician', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The senior noncommissioned logistician supervises Soldiers engaged in supply and services, materiel, petroleum, fatality and culinary management, aerial delivery operations, shower and laundry, water treatment and logistics operations. They performed these duties in a multifunctional logistics environment and the senior noncommissioned logistician must be qualified in one of the following seven MOS (92A, 92Y, 92F, 92G, 92M, 92R, and 92S) at the grade SFC.', '455d8e3187d13bd33736876a78cbe5f4cc2981066487252026e3c4ab96088c6e', 340, 340, null, 798, '2026-10-01', null, false, null),
  ('f9b801b3-1b75-51d1-b87e-edf4706aa4bf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Z', 'Senior Noncommissioned Logistician', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Senior noncommissioned logistician Master Sergeant (MSG) supervises duties in preceding skill levels and supervises operations of organizations performing supply and logistics related service operations such as decontamination, transportation, and property disposal operations. They supervise the planning of all classes of supply requirements in support of Army operations based on the operational environment. Supervises open and covered storage, receiving, classification, issue materiel handling, supply locator systems, facility safety and supply security operations. Supervise management of materiel support functions in stock control and accounting, procurement, inventory control and item financial management. Supervises development and preparation of operations information, plans, maps, sketches, overlays and related data to employment supply and service organizations. Analyzes reports on supply and service support operations. Performs duties as petroleum quality assurance representative. Assists command and staff officers in appraisals of petroleum and water operations. Develop, coordinate, implement, advise, and evaluate command food service programs. Monitor requests for food items and equipment. Develop and analyze menus and coordinates menu substitutions. Evaluate operation of garrison and field kitchens, food service training facilities and maintenance of equipment. Survey individual preferences, food preparation and food conservation. Prepare reports, studies, and briefings on food service operations. Supervises fatality management activities, provides technical and administrative support on graves registration matters, acquisition of land for temporary cemeteries, equipment requirements for mortuaries, and recovery/evacuation procedures. Supervises operations of organizations performing airborne and resupply by airdrop missions. Supervises development and preparation of operations information, plans, maps, sketches, overlays, and related data to facilitate airborne operations. Advises on airborne operational matters and performs liaison between staff and supported personnel. Performs duties as quality assurance representative for all shower/laundry and clothing repair functions. Provides technical guidance to junior grade personnel. Develops countermeasure policies, plan, doctrine, and operating procedures. Supervises development and preparation of operations, information, plans, maps, sketches, overlays, and related data to employ all logistical (supply & service organizations) in Army, Joint, Interagency, Intergovernmental, and multi- national operational forces in support of worldwide land and contingency operations. Contributes to subordinate and staff development and operations of the GCSS-Army automated system, equipment review, salvage, demilitarization, and unit/organizational and repair parts supply procedures within the operational area. Perform liaison between joint and allied staff and supported personnel to improve effectiveness of all support activities.', '0c51ae6d9c5e9020ac5dc07a6aff420cd4dfa40f3aab39acc2bf88e0abfbb3c3', 340, 340, null, 799, '2026-10-01', null, true, 5),
  ('3fe060fb-145c-5b4a-96af-9ef8f27817d4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Z', 'Senior Noncommissioned Logistician', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The senior noncommissioned logistician Sergeant Major (SGM) serves as the principal NCO of logistics support operations and performs supervisory duties shown in preceding level of skills. They provide technical guidance to subordinate personnel and advise senior leaders on logistical operations. They are the senior enlisted advisor to Commanders, Directors, and Chiefs of Departments and staff agencies on all matters pertaining to enlisted personnel. The senior noncommissioned logistician Sergeant Major (SGM) must be knowledgeable in all operations of organizations performing logistics related service operations. Must be able to plan, coordinate and supervise activities pertaining to unit organization, training, tactical and technical operations. Success in this MOS requires demonstrated expertise in a variety of progressive assignments including leadership, key billet, and staff positions at the strategic, operational, and tactical levels.', '687cb3484f1c225f1fc6b0b7566e119153fe08f6901bcf652ddaa75dc4965e5a', 340, 340, null, 800, '2026-10-01', null, true, 6),
  ('4a6db2f9-7f2b-58d2-a955-ec259ac5d8ee', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Z', 'Senior Noncommissioned Logistician', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The senior noncommissioned logistician supervises Soldiers engaged in supply and services, materiel, petroleum, fatality and culinary management, aerial delivery operations, shower and laundry, water treatment and logistics operations. They performed these duties in a multifunctional logistics environment.', 'ee7340fac5605337487bb8ad46090c3e9070b5aa8c052a7c83667c4d2d222f32', 342, 342, null, 801, '2025-10-01', '2026-10-01', false, null),
  ('e832256a-2b8b-5a5d-b8a5-f512ffd0b908', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Z', 'Senior Noncommissioned Logistician', 'rank_duties', 'E-8', null, 'Skill level 5 (E-8)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Senior Noncommissioned Logistician Master Sergeant (MSG) (MOS 92A, 92F, 92W and 92Y) shape and execute comprehensive logistical strategies at the brigade or higher echelon level, directly impacting mission success. Develop and refine logistical doctrine, policies, and procedures, influencing Army- wide standards. Advise commanders and staff on all facets of logistics, including supply, maintenance, transportation, water management, and financial resource allocation. Direct the synchronization of logistical efforts across multiple units and organizations, ensuring seamless support. Manage and oversee substantial budgets, optimizing resource utilization and maximizing return on investment. Mentor and develop subordinate logistical leaders, fostering a culture of continuous improvement and professional excellence. Represent the command in high-level logistical forums, collaborating with interagency partners and allied forces. Anticipate future logistical challenges, proactively developing innovative solutions and mitigating potential risks. Conduct strategic assessments of logistical capabilities, identifying areas for enhancement and modernization. Champion the integration of emerging technologies and best practices to optimize logistical efficiency and effectiveness.', '59a6088bd70dafd8c73e3e882ad9b0feb6b85896288a26a92ca26b0cded61e98', 342, 342, null, 802, '2025-10-01', '2026-10-01', false, 5),
  ('d6a76bfc-5f1a-5cea-9b34-5e277434ad58', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '92Z', 'Senior Noncommissioned Logistician', 'rank_duties', 'E-9', null, 'Skill level 6 (E-9)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Senior Noncommissioned Logistician Sergeant Major (SGM) (MOSs 92Z5O, 92G5O, 92M5O, 92R5P, and 92S5O) envisions and implements the overarching logistical strategy for a division, corps, or theater-level command, directly enabling sustained operations. Advise the commanding general, directors and staff on all logistical matters, provide critical insights and recommendations. Direct and synchronize the efforts of multiple logistical brigades and battalions, ensuring seamless support across a vast area of responsibility. Develop and enforce logistical policies, standards, and procedures, maintain accountability and maximizing efficiency. Manage budget and allocate resources strategically to meet evolving operational needs. Mentor and develop logistical leaders, fostering a culture of excellence and preparing them for future opportunities. Represent the command at the highest levels, collaborating with interagency partners, allied nations, and civilian authorities. Anticipate and mitigate logistical risks, proactively addressing potential disruptions to supply chains and support networks. Employ innovation and the adoption of cutting-edge technologies to transform logistical capabilities. Serve as the principal logistical authority, shaping the future of Army logistics and ensuring readiness for any contingency.', '95a3e90009e9f11f8f977848808aabbe8268aa09a1fcb04702ddea7022bae062', 342, 342, null, 803, '2025-10-01', '2026-10-01', false, 6),
  ('df4c0447-7270-5b06-9b8b-069fae539c34', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94A', 'Land Combat Electronic Missile System Repairer', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The land combat electronic missile system repairer supervises or performs field level maintenance on the TOW and Dragon missile systems, the Bradley Fighting Vehicle System (BFVS) and Javelin system.', 'e750549c15057412c2aa04d13a47775bc9f7b4cba8de404f7e3afbf9c1489153', 343, 343, null, 804, '2024-06-01', null, false, null),
  ('d733830d-ede0-584f-94f2-88e66a53377e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94A', 'Land Combat Electronic Missile System Repairer', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform quality control measures. Inspects, tests, adjusts components to specific tolerances. Determines shortcomings and malfunctions in electronic, electrical, mechanical, pneumatic, optical, and electromechanical assemblies, sub-assemblies, modules and circuit elements, with common and system special design test equipment. Repair unserviceable items by removing and replacing defective components and parts. Repair unserviceable optical and infrared components by aligning, adjusting, removing and replacing defective modules and assemblies. Determine serviceability and disposition of defective assemblies, subassemblies, and parts. Performs maintenance adjustments and repairs on job related tools and equipment. Prepare maintenance and supply forms and reports. Serve on inspection and maintenance teams.', 'f00892fdec0f2eef2eba801922c72635f76e1c7341370dd92867cea03a1965bd', 343, 343, null, 805, '2024-06-01', null, false, 1),
  ('e7dab7b3-d20b-51c7-8a07-8293798a7ba5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94A', 'Land Combat Electronic Missile System Repairer', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and supervises duties in preceding skill level and provides technical guidance to junior grade personnel in the accomplishment of their duties. Perform quality control measures. Installs equipment modifications and provides technical assistance to supported units.', '9e98d325fb258d8289d33ad97df622fff571bd282a7aa2de049f4b9d8ae3d699', 343, 343, null, 806, '2024-06-01', null, true, 2),
  ('4b442af9-6ea6-5b90-9523-859156804ab8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94A', 'Land Combat Electronic Missile System Repairer', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill levels. Establishes workloads and repair priorities; organizes work schedules, assigns duties, instructs subordinates in work techniques, and procedures for receipt, storage, inspection, testing, and repair of equipment. Implements quality control/quality assurance measures and performs initial and final inspection of equipment maintenance. Performs administrative functions in establishing and maintaining maintenance records.', '0c5bf2b8025853da570264c052049ac6e5de5695afbe0bdc6d0b06727fdc86cb', 343, 343, null, 807, '2024-06-01', null, true, 3),
  ('716dc25c-2866-5b5e-8cff-7806f62edca9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94D', 'Air Traffic Control Equipment Repairer (ATC Equip Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The ATC equipment repairer performs or supervises field level maintenance and installation of ATC communication systems, navigational aid systems (NAVAIDS), and landing systems.', 'e30fb978440f4fa41d84ca1625bceac7f45a70fdb4b3f6bddfe646d67d77d7f7', 344, 344, null, 808, '2024-06-01', null, false, null),
  ('88bc797f-2b36-55e9-919c-362ab50e89d6', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94D', 'Air Traffic Control Equipment Repairer (ATC Equip Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Uses Test, Measurement, and Diagnostic Equipment (TMDE), Test Program Sets (TPS), and Interactive Electronic Technical Manuals (IETM) to determine the cause and location of malfunctions, extent of faults, and category of maintenance required. Inspects equipment for faults and completeness. Tests equipment to determine operational condition. Troubleshoots to determine location and extent of equipment faults. Repairs equipment by adjusting, aligning, repairing, or replacing defective components. Tests repaired equipment to ensure compliance with technical specifications. Evacuates equipment and components to higher level repair activities based on the Maintenance Allocation Chart (MAC). Prepares appropriate maintenance forms and records. Logs maintenance in accordance with The Army Maintenance Management System (TAMMS). Prepares ATC equipment for Federal Aviation Administration (FAA) flight inspections. Maintains authorized spare parts, supply stock, tool lists, technical manuals, and instructional material. Perform preventive maintenance checks and services (PMCS) on TMDE, vehicles, and power generators.', 'f24349d7b83a54c8705f6244132bfc17f76b5b10e6af43965a6f6afe18da31c3', 344, 344, null, 809, '2024-06-01', null, false, 1),
  ('2998daa6-5a1f-5ce7-b2e0-fa6835f6f1bf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94D', 'Air Traffic Control Equipment Repairer (ATC Equip Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. Performs maintenance duties that are more complex and beyond the scope and experience of those encountered by the skill level one repairer. Supervises and leads teams of ATC equipment repairers. Provides technical assistance to both subordinates and supported users. Supervises the operation and proper use of TMDE. Schedules and performs user maintenance on TMDE, tools, and special test equipment. Performs final or quality control inspection of repaired equipment and maintenance documents. Provides shop supervisor with equipment repair status, priorities, and necessity for bench stock resupply. Maintains maintenance facility technical library.', '91528057b2401552f279811b7dc1d3dc6b75ad327f66e68f1ad3ce7716054b90', 344, 344, null, 810, '2024-06-01', null, true, 2),
  ('002bacc3-95d7-5aeb-a248-52125c142cc4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94D', 'Air Traffic Control Equipment Repairer (ATC Equip Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. Performs maintenance duties that are more complex and beyond the scope and experience of those encountered by the skill level two repairer. Supervises and leads sections of ATC equipment repairers. Establishes work load, work schedules, and repair priorities. Assigns priority of work for job requests. Supervises final or quality control inspection of repaired equipment and maintenance documents. Supervises calibration and shop safety programs. Serves as principal maintenance NCO in an ATC company, platoon or section.', '5a2744d252cb450346bd3fd50af414b1e42fa025a599c366b253cb03f69bd44f', 344, 344, null, 811, '2024-06-01', null, true, 3),
  ('8a7e4378-fa6e-5853-a38c-bfb6a4870b81', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94D', 'Air Traffic Control Equipment Repairer (ATC Equip Rep)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. Manages maintenance facilities and leads platoons. Manages calibration, quality assurance, and quality control programs for maintenance facilities. Coordinates for maintenance and repair of ATC equipment. Provides input to unit systems status reports. Maintains applicable administrative and maintenance files and inspects TAMMS and repair parts records. Recommends Prescribed Load List (PLL), shop stock, and bench stock changes. Manages supply operations for maintenance facilities. Coordinates with organizations and contractors for maintenance support and assistance. Ensures regulatory compliance with Department of Defense (DoD) and national level directives governing Information Assurance (IA) policies and procedures. Prepares technical reports on ATC equipment.', '5a9bbc6329044a5e722962c2f462e39d59618651962391d9df12419209602a59', 344, 344, null, 812, '2024-06-01', null, true, 4),
  ('b806cf9b-5b91-5113-8e66-809a4f8d7ca4', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94E', 'Radio Equipment Repairer', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The radio equipment repairer performs or supervises field level maintenance on radio receivers, transmitters, and associated equipment.', '011a45b8eb10ed1e09d5ad207cf9b12608f0622cfe6e3d238f60aa8955fcc057', 346, 346, null, 813, '2025-10-01', null, false, null),
  ('e43c0c9a-bbd1-5488-9a99-90d5944f27cf', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94E', 'Radio Equipment Repairer', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Use Test, Measurement, and Diagnostic Equipment (TMDE), Test Program Sets (TPS), and Interactive Electronic Technical Manuals (IETM) to determine the cause and location of malfunctions, extent of faults, and category of maintenance required. Inspect equipment for faults, and completeness. Test equipment to determine operational condition. Troubleshoot to determine location, and extent of equipment faults. Repair equipment by adjusting, aligning, repairing, or replacing defective components. Tests repaired equipment to ensure compliance with technical specifications. Evacuates equipment and components to higher level repair activities based on the Maintenance Allocation Chart (MAC). Prepares appropriate maintenance forms and records. Logs maintenance in accordance with The Army Maintenance Management System (TAMMS). Maintain authorized spare parts, supply stock, tool lists, technical manuals, and instructional material. Perform preventive maintenance checks and services (PMCS) on TMDE, vehicles, and power generators.', '176facd790901557caa4ad6dc2c81eec9002a98beade66af8f58089d56a4d9e7', 346, 346, null, 814, '2025-10-01', null, false, 1),
  ('1831482c-f092-54e4-8f6a-50b4f2d85db8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94E', 'Radio Equipment Repairer', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill level. Perform maintenance duties that are more complex and beyond the scope and experience of those encountered by the skill level one repairer. Provide technical assistance to both subordinates and supported users. Supervise the operation and proper use of TMDE. Schedules and performs user maintenance on TMDE, tools, and special test equipment. Perform final or quality control inspection of repaired equipment and maintenance documents. Provides shop supervisor with equipment repair status, priorities, and necessity for bench stock resupply. Maintain maintenance facility technical library. Controls and accounts for COMSEC/CCI within the repair facility.', 'ba830e24490a54e4b9a2df4658247ffb58eeced8a47eddc8231ad94d11bbc3c9', 346, 346, null, 815, '2025-10-01', null, true, 2),
  ('fbee8a71-40ef-5bbd-b471-60e76dfd22db', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94E', 'Radio Equipment Repairer', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill level. Performs maintenance duties that are more complex and beyond the scope and experience of those encountered by the skill level two repairer. Supervises and leads sections or squads of electronic repairers. Establishes workload, work schedules, and repair priorities. Assign priority of work for job requests. Supervise final or quality control inspection of repaired equipment and maintenance documents. Supervise calibration and shop safety programs. Ensures repair functions comply with Army and NSA specifications and policies.', 'fe705b5782831015e86061a603e93651f27ba73b85cda6ffcb905e78de090d8b', 346, 346, null, 816, '2025-10-01', null, true, 3),
  ('23e7d152-8772-589a-8cfe-1db35309e6a0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94F', 'Computer/Detection Systems Repairer (Comp/Det Sys Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The computer/detection systems repairer performs or supervises field level maintenance and repair on microcomputers and electromechanical telecommunications equipment, Field Artillery (FA) digital devices, Global Positioning System (GPS) receivers, switchboards, telephones, associated wire instruments/equipment, night vision devices/equipment, laser and fiber optic systems, mine detection and dispensing systems, battlefield illumination devices, electronic azimuth determining devices, and nuclear, biological, and chemical (NBC) warning and measuring devices.', '102cd6692c66c679d0eab628268e872aa3b0d560ef1d803f19321f683e7ba717', 348, 348, null, 817, '2025-10-01', null, false, null),
  ('fa12a75d-68f8-57a0-882e-a150714f22f9', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94F', 'Computer/Detection Systems Repairer (Comp/Det Sys Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Use Test, Measurement, and Diagnostic Equipment (TMDE), Test Program Sets (TPS), and Interactive Electronic Technical Manuals (IETM) to determine the cause and location of malfunctions, extent of faults, and category of maintenance required. Inspect equipment for faults and completeness. Test equipment to determine operational condition. Troubleshoot to determine location and extent of equipment faults. Repair equipment by adjusting, aligning, repairing, or replacing defective components. Tests repaired items to ensure compliance with technical specifications. Evacuates equipment and components to higher level repair activities based on the Maintenance Allocation Chart (MAC). Prepares appropriate maintenance forms and records. Logs maintenance in accordance with The Army Maintenance Management System (TAMMS). Maintain authorized spare parts, supply stock, tool lists, technical manuals, and instructional materials. Perform preventive maintenance checks and services (PMCS) on TMDE, vehicles, and power generators.', 'e1eb968b7633390a27db07b0dfbc71bc1f84b9d7c368b2a68f94e46bfdb9a226', 348, 348, null, 818, '2025-10-01', null, false, 1),
  ('7288a768-1555-5013-adc0-9e77cff0fc77', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94F', 'Computer/Detection Systems Repairer (Comp/Det Sys Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill level. Perform maintenance duties that are more complex and beyond the scope and experience of those encountered by the skill level one repairer. Provide technical assistance to both subordinates and supported users. Supervise the operation and proper use of TMDE. Schedules and performs user maintenance on TMDE, tools, and special test equipment. Perform final or quality control inspection of repaired equipment and maintenance documents. Provides shop supervisor with equipment repair status, priorities, and necessity for bench stock resupply. Maintains maintenance facility technical library.', '64ee8b500116fd9c0fed3f2837317931d5be7a75fb0c1cc2731db72a0db6801d', 348, 348, null, 819, '2025-10-01', null, true, 2),
  ('0e41e58c-229d-5509-8346-69f2f671074a', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94F', 'Computer/Detection Systems Repairer (Comp/Det Sys Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill level. Perform maintenance duties that are more complex and beyond the scope and experience of those encountered by the skill level two repairers. Supervises and leads sections or squads of electronic repairers. Establishes workload, work schedules, and repair priorities. Assign priority of work for job requests. Supervise final or quality control inspection of repaired equipment and maintenance documents. Supervise calibration and shop safety programs.', '5c5e6ad4c7e4bc1e7a917d132248a66385cfa65bcfacfb7d65643ad91fe5747e', 348, 348, null, 820, '2025-10-01', null, true, 3),
  ('58530013-21d4-5e00-bb4f-ee6d28415382', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94H', 'Test, Measurement, and Diagnostic Equipment (TMDE) Maintenance Support Specialist (TMDE Maint Spt Sp)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The TMDE maintenance support specialist performs and supervises duties involving the calibration and repair of general purpose TMDE, selected special purpose TMDE, Radiation Detecting, Indicating, and Computing (RADIAC) equipment, calibration standards and accessories. Operate TMDE and calibration standards. Operates and performs preventive maintenance and checks and services (PMCS) on assigned vehicles and equipment. Installs, operates and performs PMCS on power generators.', 'e481e964666f6ed18fddca777257a900e8d763a0b9d7ca80f948f3dbdefb376f', 350, 350, null, 821, '2024-06-01', null, false, null),
  ('b21a13a6-041d-5090-acf8-3699abcd00a5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94H', 'Test, Measurement, and Diagnostic Equipment (TMDE) Maintenance Support Specialist (TMDE Maint Spt Sp)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Operates and performs calibration by alignment and adjustment of electronic and mechanical components by comparing measurements of the unit under test to a known standard traceable to the National Institute of Standards and Technology (NIST). Repairs general purpose and selected special purpose TMDE to component level by removing and replacing defective components. Perform field and sustainment level maintenance on calibration standards and calibration accessories. Operates and performs PMCS on vehicles and generators. Performs special regulatory requirements associated with the calibration, maintenance and repair of RADIAC equipment.', '4d38a6e2141a87f0442a590e79197a2a33e7eaaeb05f3339b902f1f185875ea7', 350, 350, null, 822, '2024-06-01', null, false, 1),
  ('4a01df65-df86-5353-a0cd-733635b9f090', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94H', 'Test, Measurement, and Diagnostic Equipment (TMDE) Maintenance Support Specialist (TMDE Maint Spt Sp)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform all duties of skill level one. Provide technical assistance to skill level one. Performs cross checks of calibration standards through inter-comparison of team calibration standards. Perform Area TMDE Support Team (ATST) production control procedures. Receive, schedules and tracks equipment turned in for calibration or repair. Maintains maintenance records and files, and provides reports to supported units. Demonstrates proper maintenance and troubleshooting techniques to junior personnel. During split-based mode of operation: Supervises and establishes workload priorities within split section of an ATST; and coordinates with Sustainment Brigade and supported units for turn in and pick up of TMDE.', 'c6e85842ddfa536742d45a27ef1c6e4c1f04f9f050b5a5af0194a581ddea1709', 350, 350, null, 823, '2024-06-01', null, false, 2),
  ('2a44b04f-bd7f-50d1-8bf0-54025deda9a3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94H', 'Test, Measurement, and Diagnostic Equipment (TMDE) Maintenance Support Specialist (TMDE Maint Spt Sp)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises and performs all duties of skill levels one and two. As team chief and senior NCO on an ATST, supervises and manages TMDE calibration and repair support field and sustainment level maintenance for all supported organizations. Maintains hand receipt for ATST. Develops and implements standard operating procedures related to shop safety and TMDE calibration and repair. Coordinates with Sustainment Brigade and supported units for turn in and pick up of TMDE. Direct procedures for receipt, storage, inspection, testing, and repair of items. Establishes priorities within the ATST and distributes workload to the team. Responsible for ensuring that re-certification of team calibration standards is accomplished by the Area Calibration Laboratory. Develops and directs the ATST quality assurance, quality control (QA/QC) program, performs duties as ATST QA/QC inspector, and implements quality control procedures. Oversees maintenance records and calibration reports within the ATST and provides reports to higher headquarters to include Sustainment Brigade and the U.S. Army TMDE Activity (USATA). Ensures all procedures and records pertaining to radiation safety, and the calibration program, are implemented and maintained in accordance with U.S. code, Federal, and Army regulations. Organizes and conducts on the job training (OJT) programs. Demonstrate proper maintenance and troubleshooting techniques. Enforce proper work practices. Prepares maintenance reports and develops load plans. Coordinates the movement of ATST radioactive source and supervises the calibration and repair support of RADIAC equipment. Acts as the local radiation protection officer (LRPO) and performs custodial duties for the unit''s radioactive calibration source.', 'e35abced297bfd504839728c9393fe36492665d785635e6ae63ef3d91f79dd1d', 350, 350, null, 824, '2024-06-01', null, false, 3),
  ('8bd9114c-e216-545e-86c3-799e71e84178', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94M', 'Radar Repairer (Radar Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The radar repairer performs or supervises field level maintenance on SENTINEL (Ground Based Sensor) and FIREFINDER radar electronic assemblies and associated equipment. Performs or supervises field level maintenance on ground surveillance radar, associated equipment and meteorological equipment.', 'a7481074813338c729ab3151828df32c05a49518b7689a5c14136a4d463ad99d', 352, 352, null, 825, '2024-06-01', null, false, null),
  ('53c90a9d-4ea2-549d-bfb0-8938a1ad6d15', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94M', 'Radar Repairer (Radar Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Troubleshoots radar and associated equipment assemblies, subassemblies, modular and circuit elements with common and system peculiar test equipment for deficiencies and malfunctions. Repairs, removes, and/or replaces defective components and parts. Tests repaired system to ensure compliance with technical specifications. Inspects, tests, and adjusts system components and test equipment to specific tolerances. Determine serviceability and disposition of radar systems assemblies, subassemblies, and parts. Performs initial, in-process, on-site technical and quality control inspections. Prepares and maintains equipment logs, equipment modification and utilization records, exchange tags, and calibration data cards.', '796c83a545efbcb19d389e0e2df9d17b0b4b06edc79fb979cfa4da5f555c2c52', 352, 352, null, 826, '2024-06-01', null, false, 1),
  ('d32ca670-ba68-5085-bfd2-2440af92240b', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94M', 'Radar Repairer (Radar Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level and provides technical guidance to junior grade personnel. Provides technical assistance to supported units. Install equipment modifications. Complete maintenance and supply forms. Perform initial and final checkout and inspection of designated system items, assemblies, and subassemblies. Calibrate radar, organizational maintenance, and antenna alignment test sets.', '3d65537fd24f7cd6c489c1fb7cb1283276c351b056506298a378090ee397fe71', 352, 352, null, 827, '2024-06-01', null, true, 2),
  ('b0f6a2cb-7b08-55df-b60d-3ae7e2b6e747', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94M', 'Radar Repairer (Radar Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and supervises duties shown in preceding skill level. Establish workload and repair priorities. Recommend procedures for receipt, storage, inspection, testing, and repair of SENTINEL, FIREFINDER, Surveillance radar and associated equipment. Determines faulty work practices and demonstrates proper maintenance and trouble shooting techniques. Organizes and conducts OJT programs. Implement quality control measures. Establishes and maintains maintenance records. Prepare maintenance reports. Advise supervisors on operational and maintenance matters.', 'b10d6d1e7b38bb5c5407da95b2e3b5c0a97472fd0fb26697efcc98f5c7dae058', 352, 352, null, 828, '2024-06-01', null, true, 3),
  ('3288c3e9-3e83-537e-9cd3-d715042513ed', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94P', 'Multiple Launch Rocket System (MLRS) Repairer (MLRS Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The MLRS repairer supervises or performs field maintenance on multiple launch rocket system (MLRS) M270, M270A1, and High Mobility Artillery Rocket System (HIMARS), self-propelled launcher-loader (SPLL) (less carrier), launcher pod/container (LP/C) trainer, and test support group.', '0ec8a1a230547524bce866e46f979b179518c0d09a0503a23023a96588ae49fd', 353, 353, null, 829, '2025-10-01', null, false, null),
  ('5e576827-732f-5d79-8c25-f2c07a298901', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94P', 'Multiple Launch Rocket System (MLRS) Repairer (MLRS Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Troubleshoot SPLL and the launcher loader module (LLM) electrical, electronic, mechanical assemblies, modules and interconnecting cables to isolate malfunctions. Replaces or repairs electrical, hydraulic and mechanical assemblies, modules, and cables determined to be faulty. Uses breakout boxes and built in test equipment (BITE) for fault isolation and verification or adjustment of electrical assemblies and modules of LLM. Repairs, replaces chassis mounted components on units under test. Operate system cable tester. Perform unit maintenance on system peculiar test, training, and ancillary equipment. Assist automatic test equipment (ATE) operator in fault isolating LLM electronic modules and assemblies to component level at organizational level. Prepares and maintains equipment logs, equipment modification and utilization records, exchange logs, and calibration data cards. Completes maintenance and supply forms and records.', '7cf42bad11e43c1ab243721e217bc544a48cfa4601e8cb1787556420ce7cc74a', 353, 353, null, 830, '2025-10-01', null, false, 1),
  ('12ec320d-ee7a-56d0-9b12-a456d01c1909', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94P', 'Multiple Launch Rocket System (MLRS) Repairer (MLRS Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding level of skill. Supervises junior grade Soldiers and provides technical guidance to Soldiers in the accomplishment of their duties. Provides technical assistance to supported units.', '50f0c4e1ff1bc0b73d92d2b69b8db12160d21cc6f01062e32c473a948fb45e88', 353, 353, null, 831, '2025-10-01', null, true, 2),
  ('a47efc95-19b6-597b-8749-90168b3bfd14', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94P', 'Multiple Launch Rocket System (MLRS) Repairer (MLRS Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Supervises subordinate MLRS repairers engaged in support maintenance activities. Supervise inspection and maintenance teams. Perform as maintenance quality assurance and quality control (QA/QC) inspector, and implements quality control measures. Perform initial, work-in-process, final and on-site technical and quality control inspections. Monitors activities associated with maintenance of MLRS for potential problem areas and recommends improved procedures, if required. Identifies faulty work practices and demonstrates proper maintenance techniques. Organizes and conducts OJT programs.', '86fe52db31ddbe76379ed8ee2e8a22076bbbd9019a3d82ab86c8bfcca3e56bdf', 353, 353, null, 832, '2025-10-01', null, false, 3),
  ('16e136f4-1def-5d8a-9973-3e7223910e34', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94R', 'Avionics and Survivability Equipment Repairer (Avionics/Surv Eq Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The avionics and survivability equipment repairer performs field level maintenance on avionic navigation flight control systems, stabilization systems, equipment which operates using radar principles, and aircraft survivability equipment.', '2ece442983161ed1ea556d0368da0aa147deb8fe66e39dbaa4a1dfe92aec175f', 354, 354, null, 833, '2025-10-01', null, false, null),
  ('9e6b1f24-a362-51f3-bd4c-990d4492d190', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94R', 'Avionics and Survivability Equipment Repairer (Avionics/Surv Eq Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Uses Test, Measurement, and Diagnostic Equipment (TMDE), Test Program Sets (TPS), and Interactive Electronic Technical Manuals (IETM) to determine the cause and location of malfunctions, extent of faults, and category of maintenance required. Inspects equipment for faults and completeness. Tests equipment to determine operational condition. Troubleshoots to determine location and extent of equipment faults. Repairs equipment by adjusting, aligning, repairing, or replacing defective components. Tests repaired equipment to ensure compliance with technical specifications. Evacuates equipment and components to higher level repair activities based on the Maintenance Allocation Chart (MAC). Prepares appropriate maintenance forms and records. Logs maintenance in accordance with The Army Maintenance Management System (TAMMS). Maintains authorized spare parts, supply stock, tool lists, technical manuals, and instructional material. Perform preventive maintenance checks and services (PMCS) on TMDE, vehicles, and power generators.', '00f1728c354d82b49042755437c8a1f02775bb527ed235637551808bc10bfb17', 354, 354, null, 834, '2025-10-01', null, false, 1),
  ('12bda20d-e7d3-57d4-8051-1d6552288073', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94R', 'Avionics and Survivability Equipment Repairer (Avionics/Surv Eq Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. Performs maintenance duties that are more complex and beyond the scope and experience of those encountered by the skill level one repairer. Provides technical assistance to both subordinates and supported users. Supervises the operation and proper use of TMDE. Schedules and performs user maintenance on TMDE, tools, and special test equipment. Performs final or quality control inspection of repaired equipment and maintenance documents. Provides shop supervisor with equipment repair status, priorities, and necessity for bench stock re-supply. Maintain maintenance facility technical library.', '99fc985e0f8316bb9cbcd4c4731d93474f7ffb7457dab43a17e2660619dd2798', 354, 354, null, 835, '2025-10-01', null, true, 2),
  ('6713edec-bd10-5bbe-a87b-ba37a4958d55', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94R', 'Avionics and Survivability Equipment Repairer (Avionics/Surv Eq Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding skill level. Performs maintenance duties that are more complex and beyond the scope and experience of those encountered by the skill level two repairer. Supervises and leads sections or squads of electronic repairers. Establishes workload, work schedules, and repair priorities. Assigns priority of work for job requests. Supervises final or quality control inspection of repaired equipment and maintenance documents. Supervise calibration and shop safety programs.', '6b3327f8fab8ad64eaf451a8164972db5b7d46f59c4e9378631165a2c1269186', 354, 354, null, 836, '2025-10-01', null, true, 3),
  ('77df4dc0-4d09-5d74-8111-5695556c31cd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94S', 'Patriot System Repairer (Patriot Sys Rep)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Patriot system repairer performs or supervises field maintenance on the Patriot missile system, associated equipment and trainers.', '8dc63c3f6d531f950b9440e2b7ff1738a5f402a4ccbf5cac40114e9f77d3fe79', 356, 356, null, 837, '2025-10-01', null, false, null),
  ('0f6429b8-aa6a-5f2f-8ce3-ebba6b6c4413', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94S', 'Patriot System Repairer (Patriot Sys Rep)', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs field maintenance on the Patriot Information and Coordination Central (ICC), Engagement Control Station (ECS), Radar Set (RS), Antenna Mast Group (AMG), Launching Station (LS) and Communications Relay Group (CRG). Performs tests and adjusts components to specific tolerances and determines shortcomings and malfunctions in electronic assemblies, subassemblies, modules and circuit elements with common and system peculiar test equipment. Isolates malfunctions using automatic and semi-automatic program maintenance diagnostic software, unit self test and built in test equipment (BITE). Repairs unserviceable items by removing and replacing defective components. Operates and performs unit level maintenance on standard and system peculiar test equipment. Performs quality control measures. Completes maintenance and supply forms. Provides technical assistance to supported units.', '76831926c27b1226990b15f0b601075f9a3df94fa6a4a72168b3f362b319582f', 356, 356, null, 838, '2025-10-01', null, false, 1),
  ('e0e99356-a7ae-534f-8776-ebdb7bbe8ee3', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94S', 'Patriot System Repairer (Patriot Sys Rep)', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs field maintenance on the Patriot Information and Coordination Central (ICC), Engagement Control Station (ECS), Radar Set (RS), Antenna Mast Group (AMG), Launching Station (LS) and Communications Relay Group (CRG). Performs tests and adjusts components to specific tolerances and determines shortcomings and malfunctions in electronic assemblies, subassemblies, modules and circuit elements with common and system peculiar test equipment. Isolates malfunctions using automatic and semi-automatic program maintenance diagnostic software, unit self test and built in test equipment (BITE). Develops specialized computer software tests to evaluate suspected faults. Isolates system interface malfunctions. Determines serviceability and disposition of defective assemblies, subassemblies, modules and circuit elements. Repairs unserviceable items by removing and replacing defective components. Operates and performs field level maintenance on standard and system peculiar test equipment. Performs quality control measures and serves on maintenance and inspection teams. Completes maintenance and supply forms. Provides technical assistance to supported units.', '89381b96050c5defcca7cf16a431865fd193724b907daeda5aaaa3511e22003a', 356, 356, null, 839, '2025-10-01', null, false, 2),
  ('1f73ad29-d7c9-5da0-b435-fc4da73f0bb0', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94S', 'Patriot System Repairer (Patriot Sys Rep)', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties shown in preceding level of skill and provides technical guidance to junior grade personnel in the performance of their duties. Performs initial, in process and final type inspections of designated system items and their assemblies, subassemblies, modules and circuit elements. Performs as maintenance technical inspector.', 'e428b2f947ed1c4ee9fc197b1db646f724587f58e73a3eaa914e4a52acb5d884', 356, 356, null, 840, '2025-10-01', null, true, 3),
  ('1432f17b-e85b-595e-98b5-fac68df5aa56', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94S', 'Patriot System Repairer (Patriot Sys Rep)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs and supervises duties performed at preceding levels of skill. Implements quality control measures, determines faulty work practices and demonstrates proper maintenance and troubleshooting techniques. Establishes workloads and repair priorities. Establishes and maintains maintenance records. Supervises maintenance and inspection teams. Instructs junior grade personnel in the technical aspects of the Patriot system. Prepares maintenance and supply forms.', '1d2859e259f3879b06c03dbbdc5edd9ccf64ecd2ca50b6c1df2331d8727648dc', 356, 356, null, 841, '2025-10-01', null, true, 4),
  ('8011e7f2-de31-5287-80bf-ad563a6947e5', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94T', 'Short Range Air Defense System Repairer', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Short Range Air Defense System Repairer supervises, performs and inspects field maintenance on Avenger system and associated components (less carrier and communications).', '43499985b412a430c5859de0ccf1d91743dccfea09225d1c0ba36d8918e84a48', 358, 358, null, 842, '2025-10-01', null, false, null),
  ('1585356f-3283-5a32-862f-9d524b4ecaa8', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94T', 'Short Range Air Defense System Repairer', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform quality control measures. Perform maintenance adjustments on test equipment. Serves on maintenance and inspection teams. Inspects, tests, and adjusts components to specific tolerances. Determines shortcomings and malfunctions in electronic, electrical and cryogenic assemblies, modules and circuit elements using system associated equipment. Removes and replaces defective line replaceable units (LRU), including interconnecting cables. Determine serviceability, disposition of assemblies, subassemblies, and parts. Removes and installs servomotor/Azimuth Gear Assembly. Prepares maintenance and supply forms.', '1b8b02a867d59511d02a89c02478ef6aacd3c50a5d9d89dfe0581ca98aded048', 358, 358, null, 843, '2025-10-01', null, false, 1),
  ('bd2b0642-6449-5324-bf19-4888af546580', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94T', 'Short Range Air Defense System Repairer', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill level, supervises junior grade Soldiers, and provides technical guidance to the Soldiers in the accomplishment of their duties. Provides technical assistance to supported units. Install equipment modifications.', '5b63288332c10a73bd87193b4b21670f6d3b9d380b318299f1b763273a804475', 358, 358, null, 844, '2025-10-01', null, true, 2),
  ('ab7e826c-6be1-5465-b0c4-d31105067681', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94T', 'Short Range Air Defense System Repairer', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs duties in preceding skill levels, supervises junior grade Soldiers, and provides technical guidance to the Soldiers in the accomplishment of their duties. Establish workload and repair priorities. Recommend procedures for receipt, storage, inspection, testing, and repair of the Short Range Air Defense system and its components. Implement quality control measures. Maintains maintenance records and prepares maintenance reports.', '7626d9fd68040faf5d9ab69f98c5a5809c7c029ed3eb99d428ab84c25ebbfa4b', 358, 358, null, 845, '2025-10-01', null, true, 3),
  ('efb9fd15-4cd3-52e7-93f9-ec4306235a15', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94W', 'Electronic Maintenance Supervisor (Elect Maint Supv)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The electronic maintenance supervisor supervises, monitors, and directs the electronic maintenance mission of the US Army. The electronic maintenance supervisor performs and supervises field level maintenance on all Army standard electronic equipment, systems, and associated devices.', '4d3eac2c9c133f6e832f6b0f2d743897bc2990e1a059898cbeea434f0a7db389', 359, 359, null, 846, null, null, false, null),
  ('69070212-84f4-5a50-ad8e-bdd2f1295e5e', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94W', 'Electronic Maintenance Supervisor (Elect Maint Supv)', 'rank_duties', 'E-7', null, 'Skill level 4 (E-7)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Manages maintenance facilities, to include Area TMDE Support Teams and facilities, and leads platoons. Supervises and develops configuration management policies and procedures. Manages calibration, quality assurance, and quality control programs for maintenance facilities. Coordinates with supported units for maintenance and repair of electronic equipment. Provides input to unit systems status reports. Maintains applicable administrative and maintenance files and inspects TAMMS and repair parts records. Recommends Prescribed Load List (PLL), shop stock, and bench stock changes. Manages supply operations for maintenance facilities. Coordinates with organizations and contractors for maintenance support and assistance. Ensures regulatory compliance with Department of Defense (DoD) and national level directives governing Information Assurance (IA) policies and procedures. Ensures all repair functions comply with Army and National Security Agency (NSA) specifications and policies.', '0d07e21993430558229840824e921d1e1c34ed68451a84e7f58e1f0ce9e2dca5', 359, 359, null, 847, null, null, false, 4),
  ('0f298b04-d1d2-5236-aaac-b277b8225cfd', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94Y', 'Automatic Test Systems Operator/Maintainer', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The Automatic Test Systems Operator/Maintainer operates, performs, and supervises field maintenance on the Next Generation Automatic Test System (NGATS), Direct Support Electrical Test System (DSETS), and Base Shop Test Facility (BSTF), AN/TSM-191. Performs field level electronic maintenance, adjustments, tests, fault isolation, and repairs of supported system line replaceable units (LRU), shop replaceable units (SRU), test program sets (TPS) and performs maintenance on combat vehicles, Infantry and Artillery fire control systems and equipment, and related test equipment. Operates and performs preventive maintenance checks and services (PMCS) on assigned vehicles and power generators.', '380a2aa53a9ff877d9066abe6af790c8c9c99919a596c5ae8e65acee6ba016eb', 360, 360, null, 848, null, null, false, null),
  ('ff372ec2-9ae4-5ae8-98e6-9a50c9e5b400', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94Y', 'Automatic Test Systems Operator/Maintainer', 'rank_duties', 'E-1..E-4', null, 'Skill level 1 (E-1..E-4)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Performs march order and emplacement of the BSTF, installs supported weapon system test program sets, initiates unit under test (UUT) procedures, isolates UUT/BSTF/NGATS/DSETS printed circuit board or component malfunctions, replaces defective parts/components and performs UUT/BSTF/NGSATS/DSETS alignments and adjustments. Performs NGATS, DSETS, and BSTF preventive maintenance checks and services (PMCS) and operational checks. Operates and performs PMCS on assigned vehicles and power generators.', '39678c6d91f881030620dca32f63ae39ef445df9bc2423f9b8873dd5aae5af4a', 360, 360, null, 849, null, null, false, 1),
  ('5105a477-8664-534e-8114-d9c7b2f2ba95', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94Y', 'Automatic Test Systems Operator/Maintainer', 'rank_duties', 'E-5', null, 'Skill level 2 (E-5)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill level. Supervises junior grade Soldiers and provides technical guidance to the Soldiers in the accomplishment of their duties. Installs BSTF/NGATS/DSETS equipment modifications, prepares maintenance and supply forms and records, and provides technical assistance for corrective maintenance procedures.', 'be56c056a007eb61eb347b5f35ed09417445ab5112a79b71da1cc5e09e31e29d', 360, 360, null, 850, null, null, true, 2),
  ('384743c9-2e40-5356-8e9c-9c8104f8a3f2', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94Y', 'Automatic Test Systems Operator/Maintainer', 'rank_duties', 'E-6', null, 'Skill level 3 (E-6)', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'Perform duties shown in preceding skill levels. Establish workload and repair priorities. Recommend procedures for receipt, storage, inspection, testing and repair of items. Organizes and conducts on the job training (OJT) programs. Demonstrate proper maintenance and troubleshooting techniques. Determine faulty work practices. Prepare maintenance reports.', 'bc630132428ca3523a8662d5fbc32c0ae4d20ffe28d25f5cecfcee125eb497cb', 360, 360, null, 851, null, null, true, 3),
  ('153e96d3-7e34-571c-b5da-d5ab578a42db', '02d64a4e-2798-564f-95fb-4d9f2b83ec25', 'Army', 'enlisted', '94Z', 'Senior Electronic Maintenance Supervisor (Sr Elect Maint Supv)', 'general_duties', null, null, 'Major duties', 'DA PAM 611-21, ch. 10 (enlisted MOS specifications)', 'The senior electronic maintenance supervisor plans and directs electronic maintenance operations at all levels of command and echelons of the Army. Performs electronic maintenance staff functions. Provides technical advice to commanders and staff concerning Army electronic maintenance and electronic logistic support matters. Writes directives, policies and procedures which establishes Army electronic maintenance requirements.', '1b3ca950ac464357b507641c2f21552dbe75ce937d08907ec797a1cb1a935392', 361, 361, null, 852, null, null, false, null);
